# ---------------------------------------------------------------------------
# Bridge: process_rss
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  process RSS read using the standard library only.

The bridge reports its own resident set size to Prometheus
(`clarus_bridge_memory_usage_bytes`). That was the only use of a third-party
dependency, so the read is done here instead: the bridge then installs with
pure-Python packages only, which is what a single-file, offline deployment
needs.

Every platform helper returns 0 on any error. A scrape therefore never fails:
the gauge simply stays at 0, which is visibly wrong rather than accidentally
plausible.
"""

import os
import sys

_IS_WINDOWS = sys.platform == "win32"
_IS_MACOS = sys.platform == "darwin"

def _rss_linux():
    """VmRSS from /proc/self/status, in bytes.

    VmRSS is reported in kB by the kernel; the suffix is stripped rather than
    assumed so the value stays correct if the kernel ever changes units.
    """
    try:
        with open("/proc/self/status", "r", encoding="ascii", errors="replace") as fh:
            for line in fh:
                if line.startswith("VmRSS:"):
                    fields = line.split()
                    if len(fields) >= 2:
                        return int(fields[1]) * 1024
                    return 0
    except (OSError, ValueError):
        return 0
    return 0

def _rss_macos():
    """Resident set size via ps(1), in bytes.

    `ps -o rss=` prints kB with no header, which is the cheapest portable
    answer on macOS without linking a native API.
    """
    try:
        import subprocess

        out = subprocess.run(
            ["ps", "-o", "rss=", "-p", str(os.getpid())],
            capture_output=True,
            text=True,
            timeout=5,
        )
        return int(out.stdout.strip()) * 1024
    except (OSError, ValueError, subprocess.SubprocessError):
        return 0

def _rss_windows():
    """Working set via psapi through ctypes, in bytes.

    Deliberately not `wmic`: it is deprecated and removed on Windows 11 24H2
    and later, so that path would silently report 0 on current systems.
    GetProcessMemoryInfo fills a PROCESS_MEMORY_COUNTERS struct; its first
    member is cb (the struct size), and WorkingSetSize is the third.
    """
    try:
        import ctypes
        from ctypes import wintypes

        class PROCESS_MEMORY_COUNTERS(ctypes.Structure):
            _fields_ = [
                ("cb", wintypes.DWORD),
                ("PageFaultCount", wintypes.DWORD),
                ("PeakWorkingSetSize", ctypes.c_size_t),
                ("WorkingSetSize", ctypes.c_size_t),
                ("QuotaPeakPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t),
                ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                ("PagefileUsage", ctypes.c_size_t),
                ("PeakPagefileUsage", ctypes.c_size_t),
            ]

        counters = PROCESS_MEMORY_COUNTERS()
        counters.cb = ctypes.sizeof(PROCESS_MEMORY_COUNTERS)

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        psapi = ctypes.WinDLL("psapi", use_last_error=True)

        # Pseudo-handle for the calling process: no OpenProcess call, so no
        # handle to leak and nothing to cache between scrapes. The return type
        # must be declared: it defaults to a 32-bit int, which truncates the
        # HANDLE value and makes GetProcessMemoryInfo fail with
        # ERROR_INVALID_HANDLE (6).
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE
        psapi.GetProcessMemoryInfo.argtypes = [
            wintypes.HANDLE,
            ctypes.POINTER(PROCESS_MEMORY_COUNTERS),
            wintypes.DWORD,
        ]
        psapi.GetProcessMemoryInfo.restype = wintypes.BOOL
        handle = kernel32.GetCurrentProcess()
        ok = psapi.GetProcessMemoryInfo(
            handle,
            ctypes.byref(counters),
            ctypes.sizeof(PROCESS_MEMORY_COUNTERS),
        )
        if not ok:
            return 0
        return int(counters.WorkingSetSize)
    except (OSError, AttributeError, ValueError):
        return 0

def get_process_rss_bytes():
    """Return this process's resident set size in bytes, or 0 on failure."""
    if _IS_WINDOWS:
        return _rss_windows()
    if _IS_MACOS:
        return _rss_macos()
    return _rss_linux()

# ---------------------------------------------------------------------------
# Bridge: protocol
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  DIMSE protocol mappings and helpers.

Defines QIDO-RS <-> DICOM tag mappings, C-FIND keyword conversion,
N-ACTION request/response builders, JSON-to-Dataset converters,
and shared DIMSE status <-> human-readable text (PS3.7 sec.C.4).
"""

from pydicom import Dataset
from pydicom.dataelem import DataElement
from pydicom.multival import MultiValue
from pydicom.sequence import Sequence
from pydicom.uid import (
    ExplicitVRLittleEndian,
    ImplicitVRLittleEndian,
    RLELossless,
)

# ---------------------------------------------------------------------------
# Shared by main.py and cmove.py - defined ONCE here so the bundled output
# cannot shadow one definition with another.
# 1. EVRLE FIRST: with 4.80 first, a native-only viewer whose preferred
#    transfer syntax is EVRLE rejected the (DX, 4.70) fallback association
#    and every image went through transcode; with EVRLE first it accepted
#    the fallback (field measurement: passthrough=5, transcoded=0,
#    refetched=0, about 1 s). Wire note: negotiation is acceptor-driven -
#    a standard DIMSE acceptor picks the first TS of ITS OWN supported list
#    that appears in the proposal (pynetdicom presentation.py
#    negotiate_as_acceptor), so a 4.80-capable viewer still negotiates 4.80
#    on the main association and stored 4.80 instances send as-is,
#    unaffected by the order. The proposal order matters only for
#    order-sensitive viewers.
#    Some viewers reject the (CT, 4.80) fallback in BOTH orders (a limit of
#    their JPEG-LS decoder) - the bridge refetches such instances, and the
#    per-job rejection cache (handlers/cmove.py) prevents repeated doomed
#    association attempts.
# 2. Trim: JPEGLossless (4.57) and JPEGBaseline8Bit (4.50) are never
#    stored and never produced by the server, and no viewer ever selected
#    them; a viewer that did would still get images via the per-(class, TS)
#    fallback association.
#    Keep 4.70 (the stored corpus uses it).
# ---------------------------------------------------------------------------
JPEGLS_LOSSLESS_TS = "1.2.840.10008.1.2.4.80"
# Canonical proposal order for C-MOVE outbound multi-context negotiation
# Uncompressed family first, then compressed in
# the DICOM transfer-syntax taxonomy order - RLE, JPEG lossless, JPEG-LS,
# JPEG lossy, JPEG 2000, MPEG. Deterministic output is the goal (the
# standard, PS3.8 7.1.1.13, is silent on proposer order). EVRLE and IVRLE
# are NEVER dropped during budget trimming (they are the refetch targets).
_CANONICAL_TS = [
    ExplicitVRLittleEndian,  # uncompressed
    ImplicitVRLittleEndian,  # uncompressed
    "1.2.840.10008.1.2.5",  # RLE Lossless
    "1.2.840.10008.1.2.4.57",  # JPEG Lossless (Process 14 SV1 non-hierarchical)
    "1.2.840.10008.1.2.4.70",  # JPEG Lossless SV1 first-order
    JPEGLS_LOSSLESS_TS,  # 4.80 JPEG-LS Lossless
    "1.2.840.10008.1.2.4.81",  # 4.81 JPEG-LS Near-Lossless
    "1.2.840.10008.1.2.4.50",  # 4.50 JPEG Baseline
    "1.2.840.10008.1.2.4.51",  # 4.51 JPEG Extended
    "1.2.840.10008.1.2.4.90",  # 4.90 JPEG 2000 Lossless
    "1.2.840.10008.1.2.4.91",  # 4.91 JPEG 2000
    "1.2.840.10008.1.2.4.92",  # 4.92 JPEG 2000 Part 2
]

def canonical_ts_sort_key(ts_uid):
    """Ordering key for transfer-syntax UIDs in canonical proposer order.

    Unknown UIDs sort to the END (kept, just after every known TS) so a
    stored TS we don't recognise still gets proposed after the standard
    family, never dropped silently. Deterministic (nginx-way).
    """
    try:
        return _CANONICAL_TS.index(ts_uid)
    except ValueError:
        return len(_CANONICAL_TS)

IMAGE_TS = [
    ExplicitVRLittleEndian,  # EVRLE first (31.08 owner experiment, accepted)
    JPEGLS_LOSSLESS_TS,  # 4.80 (T87) - still negotiated by 4.80-capable viewers (acceptor-driven)
    ImplicitVRLittleEndian,  # Weasis SCP needs this, but EVRLE preferred
    "1.2.840.10008.1.2.4.70",  # P14.1 (JPEG Lossless SV1) - stored ELDICOM corpus
]
NON_IMAGE_TS = [ExplicitVRLittleEndian, ImplicitVRLittleEndian]

# ---------------------------------------------------------------------------
# Incoming C-STORE: some viewers export LOCAL files as-is in their original
# TS. Offering only IMAGE_TS on the SCP side made such a sender get every
# context REJECTED and report "Total size 0 B" (bridge log: association
# accepted, released with no C-STORE; a probe against a live peer proved the
# rejects). The SCP side has NO fallback mechanism - a rejected context is a
# failed export. The bridge never decodes incoming pixels (store bytes ->
# STOW), so the incoming list mirrors exactly what the server can ingest:
# the transcode announceable set plus the two native uncompressed TS. The
# SCU proposal keeps its narrower list above.
# Order: uncompressed first - acceptor-driven negotiation picks the first
# supported match when a sender offers several TS per context.
# ---------------------------------------------------------------------------
IMAGE_TS_INCOMING = [
    ExplicitVRLittleEndian,  # native
    ImplicitVRLittleEndian,  # native
    JPEGLS_LOSSLESS_TS,  # 4.80 JPEG-LS Lossless (server CAPS)
    "1.2.840.10008.1.2.4.70",  # 4.70 JPEG Lossless SV1 (server CAPS)
    "1.2.840.10008.1.2.4.50",  # 4.50 JPEG Baseline (server CAPS; field US scanner)
    RLELossless,  # 4.1.2.5 RLE (server CAPS; field US)
    "1.2.840.10008.1.2.4.81",  # 4.81 JPEG-LS Near-Lossless (server CAPS)
    "1.2.840.10008.1.2.4.90",  # 4.90 JPEG 2000 Lossless (server CAPS)
    "1.2.840.10008.1.2.4.91",  # 4.91 JPEG 2000 (server CAPS)
]

# ---------------------------------------------------------------------------
# Shared: DIMSE status -> human-readable text (PS3.7 sec.C.4)
# Used by C-STORE, C-MOVE, C-FIND, N-ACTION handlers.
# Defined ONCE here to avoid bundle duplicate-definition shadowing.
# ---------------------------------------------------------------------------
_DIMSE_STATUS_TEXT = {
    0x0000: "Success",
    0x0001: "Warning - SOP Class not supported",
    0x0116: "Warning - Attribute Value Out of Range",
    0x0118: "Class-Instance Conflict",
    0xA700: "Out of Resources",
    0xA701: "Out of Resources - Unable to calculate number of matches",
    0xA702: "Out of Resources - Unable to perform sub-operations",
    0xA801: "SOP Class Not Supported",
    0xA900: "Error - Identifier Does Not Match SOP Class",
    0xAA00: "Error - Nonexistent",
    0xB000: "Warning - Sub-operations Complete, One or More Failures",
    0xC000: "Processing Failure",
    0xC001: "Processing Failure - Cannot Understand",
    0xC002: "Processing Failure - Cannot Perform",
    0xFE00: "Cancel - Matching Terminated Due to Cancel Request",
}

def _dimse_status_name(code):
    """Return human-readable DIMSE status string for a status code."""
    if code is None:
        return "None"
    if not isinstance(code, int):
        try:
            code = int(code)
        except (TypeError, ValueError):
            return f"0x{code:04X}" if hasattr(code, "__int__") else str(code)
    text = _DIMSE_STATUS_TEXT.get(code)
    return f"0x{code:04X} ({text})" if text else f"0x{code:04X}"

# SOP Class UIDs for C-FIND dispatching
PATIENT_ROOT_UID = "1.2.840.10008.5.1.4.1.2.1.1"
STUDY_ROOT_UID = "1.2.840.10008.5.1.4.1.2.2.1"
MWL_UID = "1.2.840.10008.5.1.4.31"

# QIDO JSON key -> (DICOM tag group, element, VR, keyword)
QIDO_KEY_TO_TAG = {
    "00080005": (0x0008, 0x0005, "CS", "SpecificCharacterSet"),
    "00080020": (0x0008, 0x0020, "DA", "StudyDate"),
    "00080030": (0x0008, 0x0030, "TM", "StudyTime"),
    "00080050": (0x0008, 0x0050, "SH", "AccessionNumber"),
    "00080060": (0x0008, 0x0060, "CS", "Modality"),
    "00080061": (0x0008, 0x0061, "CS", "ModalitiesInStudy"),
    "00080090": (0x0008, 0x0090, "PN", "ReferringPhysicianName"),
    "00081030": (0x0008, 0x1030, "LO", "StudyDescription"),
    "00100010": (0x0010, 0x0010, "PN", "PatientName"),
    "00100020": (0x0010, 0x0020, "LO", "PatientID"),
    "00100030": (0x0010, 0x0030, "DA", "PatientBirthDate"),
    "00100040": (0x0010, 0x0040, "CS", "PatientSex"),
    "0020000D": (0x0020, 0x000D, "UI", "StudyInstanceUID"),
    "00200010": (0x0020, 0x0010, "SH", "StudyID"),
    "00201206": (0x0020, 0x1206, "IS", "NumberOfStudyRelatedSeries"),
    "00201208": (0x0020, 0x1208, "IS", "NumberOfStudyRelatedInstances"),
}

# C-FIND Study Root, SERIES level: the query keys the server accepts ONLY
# on the series level. Everything else mapped by C_FIND_TO_QIDO is a
# study-level key (the server rejects series keys on /studies with 400).
_SERIES_ONLY_QIDO_PARAMS = frozenset(
    {
        "SeriesInstanceUID",
        "SeriesNumber",
        "SeriesDate",
        "SeriesTime",
        "SeriesDescription",
    }
)

# Series-level QIDO JSON key -> (DICOM tag group, element, VR, keyword).
#
# Verified against the LIVE server 31.08 (GET /studies/{study}/series,
# fieldtest 8024) and the server's write_series_json render
# (crates/clarus-core/src/query/json.rs): series rows carry
# SeriesDate (0008,0021), SeriesTime (0008,0031), Modality, StationName
# (0008,1010), SeriesDescription (0008,103E), BodyPartExamined (0018,0015),
# SeriesInstanceUID (0020,000E), SeriesNumber (0020,0011), Laterality
# (0020,0060), NumberOfSeriesRelatedInstances (0020,1209).
#
# DELIBERATE omissions:
# - 0008,0005 SpecificCharacterSet: the series render always emits
#   "ISO_IR 100"; the converter forces ISO_IR 192 (UTF-8) first so
#   Cyrillic PatientName/StationName survives. Mapping it would let the
#   ISO_IR 100 overwrite the UTF-8 charset.
# - PatientName / PatientID / StudyInstanceUID: the server series render
#   does NOT emit them (confirmed live). They are injected from the study
#   row by _json_to_dataset_series.
QIDO_SERIES_KEY_TO_TAG = {
    "00080021": (0x0008, 0x0021, "DA", "SeriesDate"),
    "00080031": (0x0008, 0x0031, "TM", "SeriesTime"),
    "00080060": (0x0008, 0x0060, "CS", "Modality"),
    "00081010": (0x0008, 0x1010, "SH", "StationName"),
    "0008103E": (0x0008, 0x103E, "LO", "SeriesDescription"),
    "00180015": (0x0018, 0x0015, "CS", "BodyPartExamined"),
    "0020000E": (0x0020, 0x000E, "UI", "SeriesInstanceUID"),
    "00200011": (0x0020, 0x0011, "IS", "SeriesNumber"),
    "00200060": (0x0020, 0x0060, "CS", "Laterality"),
    "00201209": (0x0020, 0x1209, "IS", "NumberOfSeriesRelatedInstances"),
}

# Study-level identity attributes injected into a series C-FIND dataset
# from the owning study row (keyword -> tag). The server's series JSON
# carries none of them.
_STUDY_IDENTITY_ATTRS = {
    "PatientName": (0x0010, 0x0010),
    "PatientID": (0x0010, 0x0020),
    "StudyInstanceUID": (0x0020, 0x000D),
}

# C-FIND keyword -> QIDO query parameter.
#
# PS3.4 Study Root (C.6.2.1.2) REQUIRED matching keys: StudyDate, StudyTime,
# AccessionNumber, PatientName, PatientID, StudyInstanceUID, StudyID: all
# mapped. Optional keys the server filters on (PS3.18 8.3.3-1) are mapped too,
# incl. ModalitiesInStudy (0008,0061) - Weasis sends this, NOT Modality, in
# Study Root queries. Keys absent from the table are silently dropped, so a
# missing entry here = "match all" server-side (the field modality-filter bug).
C_FIND_TO_QIDO = {
    "PatientName": "PatientName",
    "PatientID": "PatientID",
    "PatientBirthDate": "PatientBirthDate",
    "PatientSex": "PatientSex",
    "StudyDate": "StudyDate",
    "StudyTime": "StudyTime",
    "AccessionNumber": "AccessionNumber",
    "StudyID": "StudyID",
    "StudyInstanceUID": "StudyInstanceUID",
    "Modality": "Modality",
    "ModalitiesInStudy": "ModalitiesInStudy",
    "StudyDescription": "StudyDescription",
    "ReferringPhysicianName": "ReferringPhysicianName",
    "PerformingPhysicianName": "PerformingPhysicianName",
    "NameOfPhysiciansReadingStudy": "NameOfPhysiciansReadingStudy",
    "SeriesInstanceUID": "SeriesInstanceUID",
    "SeriesNumber": "SeriesNumber",
    "SeriesDate": "SeriesDate",
    "SeriesTime": "SeriesTime",
    "SeriesDescription": "SeriesDescription",
    "SOPInstanceUID": "SOPInstanceUID",
}

def _extract_request_keywords(ds):
    """Extract keyword set from a pydicom Dataset (excludes SQ elements)."""
    keywords = set()
    for elem in ds:
        if elem.VR != "SQ" and elem.keyword:
            keywords.add(elem.keyword)
    return keywords

def _iter_mwl_request_elements(ds):
    """Yield the C-FIND MWL identifier elements, top level and SPS item.

    A conformant MWL request carries its SPS matching and return keys INSIDE
    the single item of (0040,0100) Scheduled Procedure Step Sequence - that is
    where (0040,0001) ScheduledStationAETitle and (0040,0009) SPS ID live
    (PS3.4 Table K.6-1). A flat request that puts them at the top level is also
    accepted: older senders do it and the standard's sequence matching is
    satisfied either way.

    Top-level elements come first, so a value stated both ways resolves to the
    top-level one.
    """
    for elem in ds:
        if elem.VR != "SQ":
            yield elem
    for elem in ds:
        if elem.VR != "SQ" or elem.keyword != "ScheduledProcedureStepSequence":
            continue
        items = elem.value or []
        if not items:
            continue
        # Single Item only (Table K.6-1). A sender that breaks the rule gets
        # its first item read rather than an error: the response is one row per
        # SPS, and there is exactly one SPS to answer for.
        for item in items[:1]:
            for sub in item:
                if sub.VR != "SQ":
                    yield sub

def _extract_mwl_request_keywords(ds):
    """Request keywords for an MWL C-FIND: top level PLUS the (0040,0100) item.

    A modality asks for an Optional key by naming it in the identifier, and the
    SPS-level keys it may ask for live inside the sequence. Flat top-level
    keywords are kept too, so both request shapes work.
    """
    keywords = set()
    for elem in _iter_mwl_request_elements(ds):
        if elem.keyword:
            keywords.add(elem.keyword)
    return keywords

def _build_qido_params(ds):
    """Build QIDO-RS query parameters from a pydicom Dataset.

    Maps C-FIND keywords to QIDO query parameters.
    None and empty-after-strip values are skipped for ALL VRs (DICOMweb:
    absent parameter = match all). Field bug 31.08: an empty IS
    (SeriesNumber) decoded by pydicom to None was stringified to "None"
    and sent to the server, which answered 400.
    Non-empty values pass through as-is (server handles DICOM `*`/`?`
    wildcards).
    """
    params = {}
    for elem in ds:
        if elem.VR == "SQ":
            continue
        keyword = elem.keyword
        if keyword in C_FIND_TO_QIDO:
            if elem.value is None:
                continue
            # Multi-valued matching (a MultiValue) is a LIST of alternatives:
            # `str()` on one produces "['CT', 'MR']", which the server reads as
            # a single unmatched value and answers with zero matches. PS3.18
            # 10.6 defines the query syntax as comma-separated, so the
            # alternatives are joined that way.
            if isinstance(elem.value, (list, tuple, MultiValue)):
                val = ",".join(str(item).strip() for item in elem.value if item)
            else:
                val = str(elem.value).strip()
            # Skip empty values  -  DICOMweb convention: absent = match all
            if val:
                params[C_FIND_TO_QIDO[keyword]] = val
    return params

def _split_qido_params(ds):
    """Split a C-FIND identifier into (study_params, series_params).

    Server contract (qido_pure.rs foreign_keys, 31.08):
    - GET /studies rejects series-only keys with 400;
    - GET /studies/{study}/series accepts ONLY series keys + Modality
      (PatientName/PatientID/StudyInstanceUID are foreign there).
    Modality is legal at BOTH levels; it goes to the SERIES step only:
    the study-level Modality filter matches the study's first-series
    modality (documented server deviation) and could wrongly exclude a
    study whose later series carries the modality.
    """
    all_params = _build_qido_params(ds)
    study_params = {}
    series_params = {}
    for key, val in all_params.items():
        if key in _SERIES_ONLY_QIDO_PARAMS or key == "Modality":
            series_params[key] = val
        else:
            study_params[key] = val
    return study_params, series_params

# MWL (Modality Worklist) <-> UPS-RS workitem DICOMweb JSON keys.
#
# PS3.4 2026d Table K.6-1: the Modality Worklist Information Model is a FLAT,
# NON-OBJECT model - it has no SOP Common attributes, so SOP Instance UID
# (0008,0018) has no place in a response. The modality's identity for a
# Scheduled Procedure Step is (0040,0009) SPS ID plus (0040,1001) Requested
# Procedure ID, and the SPS attributes themselves live INSIDE the single item
# of (0040,0100) Scheduled Procedure Step Sequence:
#
#   "The Scheduled Procedure Step Sequence shall contain only a single Item."
#
# RETURN keys are emitted whenever the source has a value, whether the modality
# asked or not. OPTIONAL keys are emitted ONLY when the modality requested them
# (PS3.4 C.4.1.1.3.2), which is how a modality says "give me this key".
#
# Sources are the server's workitem render (handlers/ups/json.rs). The keys the
# server does not render simply produce nothing - an absent Return key, not a
# fabricated one. This is a documented VENDOR mapping: no normative DICOM or
# IHE mapping from UPS workitems to a DIMSE MWL response exists, so the derived
# identifiers below are the bridge's own, declared in
# dimse-bridge-conformance-statement.md.

# Top level. PatientName/PatientID are Return keys (Type 1) at identifier
# level; the rest are Optional and request-gated.
MWL_RETURN_TOP = {
    "00100010": (0x0010, 0x0010, "PN", "PatientName"),
    "00100020": (0x0010, 0x0020, "LO", "PatientID"),
}

MWL_OPTIONAL_TOP = {
    "00080050": (0x0008, 0x0050, "SH", "AccessionNumber"),
    "0020000D": (0x0020, 0x000D, "UI", "StudyInstanceUID"),
    "00321032": (0x0032, 0x1032, "PN", "RequestingPhysician"),
}

# The two Optional top-level keys whose UPS source moved into a sequence: the
# study and the accession are carried by (0040,A370) Referenced Request
# Sequence (PS3.4 Table CC.2.5-3). The bare top-level tag is a fallback for a
# server that still emits it (and the (0040,4021) Input Information Sequence
# names the study too), so a row is rendered whether the source is old or new.
MWL_OPTIONAL_TOP_SEQ = {
    "0020000D": ("0040A370", "0020000D"),
    "00080050": ("0040A370", "00080050"),
}

# The station source that moved into a sequence, resolved BEFORE the flat fill
# runs: UPS carries the station in (0040,4025) Scheduled Station Name Code
# Sequence, whose Code Value is the AE Title (PS3.4 Table CC.2.5-3; AIW-I
# 4.81.4.1.2.1 Table 4.81.4.1.2.1-3). The emitted MWL element stays
# (0040,0001) ScheduledStationAETitle, because that is the attribute Table
# K.6-1 defines for the DIMSE side - only the SOURCE changes.
MWL_STATION_SEQ = ("00404025", "00080100")

# Inside the single item of (0040,0100) Scheduled Procedure Step Sequence.
MWL_RETURN_SPS = {
    "00400001": (0x0040, 0x0001, "AE", "ScheduledStationAETitle"),
    "00400002": (0x0040, 0x0002, "DA", "ScheduledProcedureStepStartDate"),
    "00400003": (0x0040, 0x0003, "TM", "ScheduledProcedureStepStartTime"),
    # (0008,0060) Modality is a Return key Type 1 in MWL. UPS itself has no
    # Modality attribute (PS3.4 Table CC.2.5-3); the server renders the input
    # study's Modality as a documented vendor extension, and the bridge maps it
    # here. While a deployment's server does not render it, the key is simply
    # absent for every workitem - which is the same shape as any other absent
    # Return key, not a special case.
    "00080060": (0x0008, 0x0060, "CS", "Modality"),
}

MWL_OPTIONAL_SPS = {
    "00400010": (0x0040, 0x0010, "SH", "ScheduledStationName"),
}

# (0074,1200) ScheduledProcedureStepPriority is deliberately NOT here: it is an
# attribute of the UPS Scheduled Procedure Step Module (PS3.3 C.30.1) and has
# no row in Table K.6-1, so it must not appear in an MWL response.
#
# (0040,0006) ScheduledPerformingPhysicianName is a Return key Type 2 with no
# UPS source. Type 2 permits absence, so it is omitted rather than invented.

# SPS ID (0040,0009) / Requested Procedure ID (0040,1001) are derived, not
# mapped: see _mwl_sps_id / _mwl_rp_id.
MWL_SPS_ID_LEN = 16

# C-FIND MWL match keyword -> UPS-RS workitems query parameter.
# Only the keys the server's workitem search actually filters on (ups/types.rs
# parse_form_query / StoreFilter): station_aet, modality, patient_id,
# workitem_uid, workflow_state. Other MWL keys are NOT filterable server-side
# -> absent parameter = match all (DICOMweb convention).
MWL_TO_UPS_PARAM = {
    "ScheduledStationAETitle": "00404025.00080100",
    "Modality": "00080060",
    "PatientID": "00100020",
    "StudyInstanceUID": "0020000D",
    "ProcedureStepState": "00741000",
}

def _build_mwl_params(ds):
    """Build UPS-RS workitems query params from a C-FIND MWL request Dataset.

    Reads the matching keys from BOTH the top level and the item of
    (0040,0100) Scheduled Procedure Step Sequence, because that is where a
    conformant MWL request puts them. A nested-only request used to yield an
    empty dict - i.e. match-all - so the modality's station filter silently
    returned every workitem on the server.

    Maps only the keys the server's workitem search filters on; empty values
    are skipped (absent = match all, the DICOMweb convention). Returns a dict
    (possibly empty).
    """
    params = {}
    for elem in _iter_mwl_request_elements(ds):
        keyword = elem.keyword
        if keyword not in MWL_TO_UPS_PARAM:
            continue
        param = MWL_TO_UPS_PARAM[keyword]
        if param in params:
            # Already stated at an earlier level (top level precedes the SPS
            # item). First statement wins, so the resolution does not depend on
            # element order inside the sequence.
            continue
        # PS3.18 10.6: the query syntax is comma-separated for a list of
        # alternatives, and `str()` on a MultiValue yields "['CT', 'MR']" -
        # which the server reads as one unmatched value. An element with no
        # value is skipped rather than sent as the text "None".
        if elem.value is None:
            continue
        if isinstance(elem.value, (list, tuple, MultiValue)):
            val = ",".join(str(item).strip() for item in elem.value if item)
        else:
            val = str(elem.value).strip()
        if val:
            params[param] = val
    return params

def _safe_add_new(ds, group, elem, vr, val):
    """Add element to Dataset; fall back to direct assignment if tag exists (BR-014)."""
    try:
        ds.add_new((group, elem), vr, val)
    except ValueError:
        ds[(group, elem)] = DataElement((group, elem), vr, val)

def _json_add_vr(ds, group, elem, vr, raw_first):
    """Add one DICOMweb JSON value to `ds` under the element's VR (CMP-005).

    The single place a JSON value becomes a pydicom element, shared by the
    QIDO and MWL converters so the two cannot drift on VR handling. Returns
    True when the element was added.
    """
    try:
        if vr == "PN":
            # Person Name: prefer the Alphabetic component.
            if isinstance(raw_first, dict):
                val = raw_first.get("Alphabetic", "")
            else:
                val = str(raw_first)
        elif vr == "IS":
            val = int(raw_first)
        elif vr == "TM":
            # Time: normalize the display "HH:MM:SS" form to the canonical
            # DICOM "HHMMSS.FFFFFF" (PS3.5 6.2). pydicom logs
            # "Invalid value for VR TM: '11:25:01'" when a colon form is
            # constructed (field noise on every C-FIND); stripping the
            # colons keeps the attribute valid and warning-free.
            val = str(raw_first).replace(":", "")
        else:
            # CS, UI, LO, SH, DA - plain string. CS may arrive as a list.
            val = str(raw_first)
    except (TypeError, ValueError, IndexError):
        return False
    _safe_add_new(ds, group, elem, vr, val)
    return True

def _json_map_to_dataset(json_obj, keymap):
    """Convert a DICOMweb JSON object to a pydicom Dataset (shared core).

    Handles VR-aware parsing for PN/IS/CS/UI/LO/SH/DA/TM (CMP-005).

    The C-FIND response re-emits the 16 mapped attributes on every row;
    PS3.4 C.4.1.1.3.2 says the response shall not contain attributes that
    were not in the request or specified in that section - this is a
    deliberate, viewer-tolerated deviation (documented in the DIMSE bridge
    conformance statement).
    """
    ds = Dataset()
    # PS3.5 6.1.2: SpecificCharacterSet MUST be the first element.
    # ISO_IR 192 (UTF-8) is ALWAYS set, deliberately (documented in the DIMSE
    # bridge conformance statement): without it pydicom defaults to iso8859 /
    # Latin-1 and replaces Cyrillic PN/LO with '????' in RadiAnt/MicroDICOM.
    # The charset covers Cyrillic and all other scripts in the bridge rows.
    ds.SpecificCharacterSet = "ISO_IR 192"

    for json_key, value in json_obj.items():
        if json_key not in keymap:
            continue
        group, elem, vr, dicom_keyword = keymap[json_key]
        raw_value = value.get("Value", []) if isinstance(value, dict) else []
        if not raw_value:
            # Zero-length delta (documented in the DIMSE bridge conformance
            # statement): an attribute that is present but EMPTY is dropped,
            # i.e. the attribute is ABSENT from the row, NOT emitted as a
            # zero-length value. PS3.4 C.4.1.1.3.2 note 2 would require a
            # zero-length attribute; we deliberately do not do that (keeps
            # the rows minimal and is tolerated by all viewers).
            continue
        _json_add_vr(ds, group, elem, vr, raw_value[0])
    return ds

def _json_to_dataset(json_obj, request_keywords):
    """QIDO-RS study JSON -> pydicom Dataset (13/13 QIDO attributes)."""
    return _json_map_to_dataset(json_obj, QIDO_KEY_TO_TAG)

def _json_first_value(json_obj, key):
    """First DICOMweb JSON Value entry for `key` ('' when absent).

    PN values arrive as {"Alphabetic": ...} objects; everything else as
    plain strings/numbers.
    """
    attr = json_obj.get(key) or {}
    values = attr.get("Value") or []
    if not values:
        return ""
    first = values[0]
    if isinstance(first, dict):
        return str(first.get("Alphabetic", ""))
    return str(first)

def _json_seq_first_value(json_obj, seq_key, item_key):
    """First value of `item_key` inside the FIRST item of sequence `seq_key`.

    The UPS workitem render carries the study and the accession through
    (0040,A370) Referenced Request Sequence (PS3.4 Table CC.2.5-3), so a
    consumer that wants the input study reads it there. '' when the sequence,
    the item or the tag is absent.
    """
    seq = json_obj.get(seq_key) or {}
    items = seq.get("Value") or []
    if not items or not isinstance(items[0], dict):
        return ""
    return _json_first_value(items[0], item_key)

def _json_workitem_study_uid(json_obj):
    """The input study UID of a UPS workitem JSON, from either carriage.

    (0040,A370) Referenced Request Sequence is the standard carriage and is
    read first; the bare top-level (0020,000D) is the fallback for a server
    (or a stored row) that still emits it, and the (0040,4021) Input
    Information Sequence is the last resort. The three name one fact.
    """
    study = _json_seq_first_value(json_obj, "0040A370", "0020000D")
    if study:
        return study
    study = _json_first_value(json_obj, "0020000D")
    if study:
        return study
    return _json_seq_first_value(json_obj, "00404021", "0020000D")

def _json_to_dataset_series(json_obj, request_keywords, study_json=None):
    """QIDO-RS series JSON -> pydicom Dataset (31.08 series-level C-FIND).

    The series C-FIND dataset MUST carry series attributes (0020,000E,
    0020,0011, 0008,0060, ...) - viewers drop rows without them. The
    server's series render omits PatientName/PatientID/StudyInstanceUID
    (confirmed live 31.08), so when the owning study row (`study_json`)
    is given, those three are injected from it.
    """
    ds = _json_map_to_dataset(json_obj, QIDO_SERIES_KEY_TO_TAG)
    if study_json:
        study_ds = _json_map_to_dataset(study_json, QIDO_KEY_TO_TAG)
        for group, elem in _STUDY_IDENTITY_ATTRS.values():
            ident_elem = study_ds.get((group, elem))
            if ident_elem is not None:
                _safe_add_new(ds, group, elem, ident_elem.VR, ident_elem.value)
    return ds

def _mwl_tail(value):
    """Last MWL_SPS_ID_LEN characters of an identifier, or '' when too short.

    Both identifiers below live in VR SH (16 characters). A UPS workitem UID is
    `2.25.<decimal u128>` (up to 43 characters), so it cannot be carried
    verbatim; the tail is used instead. This is a DERIVATION into an
    identifier's own scoped namespace, not a truncation of a value the modality
    must round-trip: a modality only needs a stable handle to couple MPPS to
    the step, and SPS ID is scoped by the Requested Procedure (PS3.3 C.4.10).
    """
    text = str(value or "").strip()
    if len(text) < MWL_SPS_ID_LEN:
        return ""
    return text[-MWL_SPS_ID_LEN:]

def _mwl_sps_id(workitem_uid):
    """(0040,0009) Scheduled Procedure Step ID, derived from the workitem UID.

    The MWL model has no SOP Instance UID (PS3.4 Table K.6-1), so the workitem
    UID has no legal home; its tail is the honest, deterministic stand-in.
    """
    return _mwl_tail(workitem_uid)

def _mwl_rp_id(study_instance_uid):
    """(0040,1001) Requested Procedure ID, derived from the study UID.

    Empty when the workitem names no study: there is no Requested Procedure
    without one, so nothing is emitted.
    """
    return _mwl_tail(study_instance_uid)

def _mwl_fill_start_datetime(sps, json_obj):
    """Fill (0040,0002)/(0040,0003) from (0040,4005) when the pair is missing.

    Both are Return keys Type 1 in MWL, but the UPS workitem carries the single
    DT attribute (0040,4005) ScheduledProcedureStepStartDateTime instead. Split
    it: the first 8 characters are the date, the next 6 the time. Only fields
    that are still absent are filled, so an explicit DA/TM pair wins.
    """
    if (
        "ScheduledProcedureStepStartDate" in sps
        and "ScheduledProcedureStepStartTime" in sps
    ):
        return
    dt = _json_first_value(json_obj, "00404005")
    if not dt:
        return
    digits = str(dt).strip()
    if len(digits) < 8:
        return
    date_part = digits[:8]
    time_part = digits[8:14]
    if "ScheduledProcedureStepStartDate" not in sps and date_part.isdigit():
        _safe_add_new(sps, 0x0040, 0x0002, "DA", date_part)
    if (
        "ScheduledProcedureStepStartTime" not in sps
        and len(time_part) == 6
        and time_part.isdigit()
    ):
        _safe_add_new(sps, 0x0040, 0x0003, "TM", time_part)

def _json_to_dataset_mwl(json_obj, request_keywords):
    """UPS-RS workitem JSON -> pydicom MWL Dataset, in the standard's shape.

    PS3.4 Table K.6-1: one row per Scheduled Procedure Step, with
    PatientName/PatientID at identifier level and the SPS attributes inside the
    single item of (0040,0100) Scheduled Procedure Step Sequence.

    Emission rules:
      - Return keys (MWL_RETURN_TOP, MWL_RETURN_SPS) whenever the source has a
        value, whether the modality asked or not.
      - Optional keys (MWL_OPTIONAL_TOP, MWL_OPTIONAL_SPS) ONLY when the
        modality named them in the identifier (PS3.4 C.4.1.1.3.2).

    The two derived identifiers have no source to map from:
      - (0040,0009) SPS ID       <- the workitem UID's tail
      - (0040,1001) RP ID        <- the input study UID's tail
    See _mwl_sps_id / _mwl_rp_id for why the tail and not the whole value.
    """
    ds = Dataset()
    # PS3.5 6.1.2: SpecificCharacterSet MUST be the first element.
    # ISO_IR 192 (UTF-8) is ALWAYS set, deliberately (documented in the DIMSE
    # bridge conformance statement): without it pydicom defaults to iso8859 /
    # Latin-1 and replaces Cyrillic PN/LO with '????' in RadiAnt/MicroDICOM.
    ds.SpecificCharacterSet = "ISO_IR 192"

    sps = Dataset()

    def fill(target, keymap, source, always):
        """Copy mapped values from `source` into `target` under `keymap`."""
        for json_key, (group, elem, vr, keyword) in keymap.items():
            if not always and keyword not in request_keywords:
                continue
            value = source.get(json_key)
            if not isinstance(value, dict):
                continue
            raw_value = value.get("Value") or []
            if not raw_value:
                # Present but EMPTY is dropped, not emitted zero-length: an
                # attribute with no value is absent from the row (documented
                # deviation, PS3.4 C.4.1.1.3.2 note 2 would allow zero-length).
                continue
            _json_add_vr(target, group, elem, vr, raw_value[0])

    # Identifier level: the two Return keys, then the request-gated Optional
    # ones. The study and the accession live in the Referenced Request
    # Sequence on a current server, so their values are resolved through that
    # (with the bare tag and the Input Information Sequence as fallbacks)
    # before the flat fill runs.
    fill(ds, MWL_RETURN_TOP, json_obj, always=True)
    optional_source = dict(json_obj)
    for flat_key, (seq_key, item_key) in MWL_OPTIONAL_TOP_SEQ.items():
        # `0020000D` is resolved even when the flat tag is present: the bare
        # tag and the Referenced Request Sequence must name the SAME study as
        # the derived RP ID, and `_json_workitem_study_uid` is the one place
        # that decides which value wins. Skipping the resolution when the bare
        # tag exists let the two disagree - and an empty bare tag silently
        # dropped StudyInstanceUID while leaving the RP ID derived from it.
        if flat_key == "0020000D":
            value = _json_workitem_study_uid(json_obj)
        else:
            if flat_key in optional_source:
                continue
            value = _json_seq_first_value(
                json_obj, seq_key, item_key
            ) or _json_first_value(json_obj, flat_key)
        if value:
            optional_source[flat_key] = {"vr": "UI", "Value": [value]}
    fill(ds, MWL_OPTIONAL_TOP, optional_source, always=False)

    # SPS level: the Return keys, then the request-gated Optional ones. The
    # station is resolved through its sequence first, so the flat fill below
    # reads a value that came from (0040,4025) Code Value without the return
    # key map having to know about sequences.
    sps_source = dict(json_obj)
    station = _json_seq_first_value(json_obj, *MWL_STATION_SEQ)
    if station:
        sps_source["00400001"] = {"vr": "AE", "Value": [station]}
    fill(sps, MWL_RETURN_SPS, sps_source, always=True)
    fill(sps, MWL_OPTIONAL_SPS, json_obj, always=False)

    # (0040,0002)/(0040,0003) Start Date/Time are Return keys Type 1. A
    # workitem created by the 2709 UPS Update path carries only (0040,4005)
    # ScheduledProcedureStepStartDateTime (VR DT); split it into the DA/TM
    # pair rather than leaving two Return keys empty. With neither source, the
    # pair is honestly absent - a step with no start time cannot produce one.
    _mwl_fill_start_datetime(sps, json_obj)

    # (0040,0009) SPS ID: the handle the modality couples MPPS to.
    sps_id = _mwl_sps_id(_json_first_value(json_obj, "00080018"))
    if sps_id:
        _safe_add_new(sps, 0x0040, 0x0009, "SH", sps_id)

    # (0040,0007) SPS Description is Optional: the modality must ask for it.
    # Source is (0074,1204) Procedure Step Label, the human-readable label.
    if "ScheduledProcedureStepDescription" in request_keywords:
        label = _json_first_value(json_obj, "00741204")
        if label:
            _safe_add_new(sps, 0x0040, 0x0007, "LO", label)

    if len(sps) > 0:
        ds.ScheduledProcedureStepSequence = Sequence([sps])

    # (0040,1001) Requested Procedure ID is Optional, and derived from the
    # input study. No study -> no Requested Procedure, so nothing is emitted.
    # The study is read from the Referenced Request Sequence first (the
    # standard carriage), with the bare tag and the Input Information
    # Sequence as fallbacks.
    if "RequestedProcedureID" in request_keywords:
        rp_id = _mwl_rp_id(_json_workitem_study_uid(json_obj))
        if rp_id:
            _safe_add_new(ds, 0x0040, 0x1001, "SH", rp_id)

    return ds

# ---------------------------------------------------------------------------
# N-ACTION protocol helpers
# ---------------------------------------------------------------------------
def _parse_n_action_rq(event):
    """Parse N-ACTION-RQ dataset.

    Returns (transaction_uid, [(sop_class_uid, sop_instance_uid), ...]).
    Raises ValueError if TransactionUID (0008,1195) is missing.
    """
    # pynetdicom N-ACTION-RQ: dataset is in .dataset or fallback to .action_information
    try:
        ds = event.dataset
    except AttributeError:
        ds = (
            event.action_information
            if hasattr(event, "action_information")
            else Dataset()
        )
    tx_uid = getattr(ds, "TransactionUID", None)
    if not tx_uid or str(tx_uid).strip() == "":
        raise ValueError("N-ACTION-RQ: missing TransactionUID (0008,1195)")
    tx_uid = str(tx_uid)

    sop_list = []
    ref_seq = getattr(ds, "ReferencedSOPSequence", None)
    if ref_seq:
        for item in ref_seq:
            sop_class = str(getattr(item, "ReferencedSOPClassUID", ""))
            sop_uid = str(getattr(item, "ReferencedSOPInstanceUID", ""))
            if sop_uid.strip():
                sop_list.append((sop_class, sop_uid))

    return tx_uid, sop_list

def _build_n_action_rsp(tx_uid, verified_sops, failed_sops):
    """Build N-ACTION-RSP pydicom Dataset.

    verified_sops: list of (sop_class_uid, sop_instance_uid)
    failed_sops:   list of (sop_class_uid, sop_instance_uid, failure_reason)
    """
    rsp = Dataset()
    rsp.TransactionUID = tx_uid

    if verified_sops:
        success_seq = []
        for sop_class, sop_uid in verified_sops:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            success_seq.append(item)
        rsp.ReferencedSOPSequence = success_seq

    if failed_sops:
        failed_seq = []
        for sop_class, sop_uid, reason in failed_sops:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            item.FailureReason = reason
            failed_seq.append(item)
        rsp.FailedSOPSequence = failed_seq

    return rsp

# ---------------------------------------------------------------------------
# Bridge: registry
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  SOP Class and Printer registries.

YAML-driven SOP class acceptance. 11 built-in fallback classes.
Printer registry for C-PRINT (P22c).
"""

import logging

# ---------------------------------------------------------------------------
# _parse_simple_yaml  -  minimal YAML subset parser (0 dependencies)
# ---------------------------------------------------------------------------
def _parse_simple_yaml(path):
    """Parse a minimal YAML subset: top-level key with nested dicts of name/accept.

    Only handles the exact format used by sop_classes.yaml and printers.yaml.
    No dependencies. Replaces PyYAML (~500 KB).
    """
    result = {}
    current_section = None
    current_uid = None
    current_entry = {}

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            # Skip empty lines and comments
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue

            # Count leading spaces for indentation
            indent = len(line) - len(line.lstrip())

            if indent == 0 and stripped.endswith(":"):
                # Top-level section: "sop_classes:" or "printers:"
                current_section = stripped[:-1].strip()
                result[current_section] = {}
            elif indent == 2 and stripped.endswith(":"):
                # UID/name key: "  1.2.840...:"
                current_uid = stripped[:-1].strip().strip("\"'")
                current_entry = {}
                if current_section:
                    result[current_section][current_uid] = current_entry
            elif indent == 4 and ":" in stripped:
                # Key: value: "    name: CT Image Storage"
                key, _, value = stripped.partition(":")
                key = key.strip()
                # An inline comment is documentation, not part of the value:
                # `accept: false  # retired vendor` must stay a boolean, and a
                # quoted value must compare without its quotes. Without the
                # strip the comparison below sees "false  # retired vendor" and
                # stores a truthy string, so a class marked as not accepted is
                # accepted anyway.
                value = value.split("#", 1)[0].strip().strip("\"'")
                if value.lower() == "true":
                    current_entry[key] = True
                elif value.lower() == "false":
                    current_entry[key] = False
                else:
                    current_entry[key] = value

    return result

# ---------------------------------------------------------------------------
# Bridge: SOP Class Registry  -  YAML-driven, no code changes needed
# ---------------------------------------------------------------------------
def _load_sop_registry(yaml_path="sop_classes.yaml"):
    """Load SOP class registry from YAML file (BR-009: no PyYAML dependency).

    Returns dict[uid -> dict] with keys: name, accept.
    Falls back to built-in defaults if YAML is missing or unparseable.
    """
    try:
        data = _parse_simple_yaml(yaml_path)
        registry = data.get("sop_classes", {}) if data else {}
        if registry:
            logging.info(
                "[SOP-REG] Loaded %d SOP classes from %s", len(registry), yaml_path
            )
            return registry
    except FileNotFoundError:
        logging.info("[SOP-REG] Using built-in SOP defaults (no custom %s)", yaml_path)
    except Exception as e:
        logging.info(
            "[SOP-REG] Using built-in SOP defaults: %s parse error - %s", yaml_path, e
        )

    return _BUILTIN_SOP_CLASSES()

def _BUILTIN_SOP_CLASSES():
    """Return 11 built-in SOP classes  -  always available, no dependencies (CMP-006).

    Includes 3 legacy Retired classes still in active use on pre-2006 equipment:
    - MG For Processing (Retired): replaced by 1.2.840.10008.5.1.4.1.1.1.2.1
    - US Multi-frame (Retired): replaced by 1.2.840.10008.5.1.4.1.1.6.1
    - NM (Retired): replaced by 1.2.840.10008.5.1.4.1.1.20
    """
    return {
        "1.2.840.10008.1.1": {"name": "Verification", "accept": True},
        "1.2.840.10008.5.1.4.1.1.2": {"name": "CT Image Storage", "accept": True},
        "1.2.840.10008.5.1.4.1.1.4": {"name": "MR Image Storage", "accept": True},
        "1.2.840.10008.5.1.4.1.1.1": {
            "name": "Computed Radiography Image Storage",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.1.1": {
            "name": "Digital X-Ray Image Storage - For Presentation",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.1.2": {
            "name": "Digital Mammography X-Ray Image Storage - For Presentation",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.7": {
            "name": "Secondary Capture Image Storage",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.6.1": {
            "name": "Ultrasound Image Storage",
            "accept": True,
        },
        # Legacy Retired (pre-2006 equipment still in active use)
        "1.2.840.10008.5.1.4.1.1.1.2.1": {
            "name": "Digital Mammography X-Ray - For Processing (Retired)",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.3": {
            "name": "Ultrasound Multi-frame Image Storage (Retired)",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.5": {
            "name": "Nuclear Medicine Image Storage (Retired)",
            "accept": True,
        },
    }

def _is_sop_accepted(sop_registry, context_uid):
    """Check if a SOP class UID is accepted by the Bridge.

    Args:
        sop_registry: dict from _load_sop_registry()
        context_uid: pynetdicom UID string (e.g. '1.2.840.10008.5.1.4.1.1.2')

    Returns:
        True if the SOP class is in registry and accept=True.
    """
    info = sop_registry.get(context_uid)
    if info and info.get("accept", False):
        return True
    return False

def _get_sop_registry_uids(sop_registry):
    """Return list of accepted SOP class UID strings from registry."""
    return [uid for uid, info in sop_registry.items() if info.get("accept", False)]

# ---------------------------------------------------------------------------
# Bridge: C-PRINT printer registry loader
# ---------------------------------------------------------------------------
def _load_printer_registry(yaml_path="printers.yaml"):
    """Load printer registry from YAML file (BR-009: no PyYAML dependency).

    Returns dict[str -> dict] with keys: name, host, port, aet, driver.
    Falls back to empty dict if YAML is missing.
    """
    try:
        data = _parse_simple_yaml(yaml_path)
        registry = data.get("printers", {}) if data else {}
        if registry:
            logging.info(
                "[PRINT-REG] Loaded %d printers from %s", len(registry), yaml_path
            )
            return registry
    except FileNotFoundError:
        logging.debug("[PRINT-REG] No custom printers.yaml - C-PRINT disabled")
    except Exception as e:
        logging.info("[PRINT-REG] Printers config parse error - %s: %s", yaml_path, e)

    return {}

# ---------------------------------------------------------------------------
# Bridge: sop_index
# ---------------------------------------------------------------------------

"""SOP Instance UID index  -  filesystem-backed key-value store.

nginx-way: one JSON file per SOP UID. Directory = index.
No SQLite. No locks. No busy_timeout.
"""

import json
import logging
import os
import time

class SopIndexManager:
    """Filesystem-backed index: SOPInstanceUID -> (StudyInstanceUID, SeriesInstanceUID).

    Layout:
        sop_index/{sop_uid}.json -> {"study_uid": "...", "series_uid": "...",
                                     "ts": ..., "is_verified": false}

    Populated at C-STORE time after successful STOW-RS (HTTP 200/201/202).
    Looked up at N-ACTION time to verify Storage Commitment.
    """

    def __init__(self, index_dir):
        """index_dir: path to sop_index directory (created if absent)."""
        self._dir = index_dir
        os.makedirs(self._dir, exist_ok=True)

    def _path(self, sop_uid):
        safe = sop_uid.replace("\x00", "_").replace("/", "_").replace("\\", "_")
        return os.path.join(self._dir, f"{safe}.json")

    def insert_sop(self, sop_uid, study_uid, series_uid):
        """Insert or replace a SOP entry. Idempotent."""
        data = {
            "study_uid": study_uid,
            "series_uid": series_uid,
            "ts": int(time.time()),
            "is_verified": False,
        }
        path = self._path(sop_uid)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f)
            f.flush()
        os.replace(tmp, path)

    def lookup_sop(self, sop_uid):
        """Look up a SOP UID. Returns dict or None."""
        path = self._path(sop_uid)
        if not os.path.isfile(path):
            return None
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logging.warning("[SOP-INDEX] Corrupt %s: %s", path, e)
            return None

    def mark_verified(self, sop_uid):
        """Mark a SOP as verified after successful N-ACTION check."""
        entry = self.lookup_sop(sop_uid)
        if entry is None:
            return
        entry["is_verified"] = True
        path = self._path(sop_uid)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(entry, f)
            f.flush()
        os.replace(tmp, path)

    def cleanup(self, max_age_seconds=86400):
        """Remove entries older than max_age_seconds (default: 24h)."""
        cutoff = time.time() - max_age_seconds
        removed = 0
        try:
            for name in os.listdir(self._dir):
                if not name.endswith(".json"):
                    continue
                path = os.path.join(self._dir, name)
                try:
                    if os.path.getmtime(path) < cutoff:
                        os.unlink(path)
                        removed += 1
                except OSError:
                    pass
        except OSError:
            pass
        if removed > 0:
            logging.info("[SOP-INDEX] Cleaned %d entries", removed)

    def count(self):
        """Return total number of entries."""
        try:
            return sum(1 for n in os.listdir(self._dir) if n.endswith(".json"))
        except OSError:
            return 0

    def close(self):
        """No-op on filesystem."""

# ---------------------------------------------------------------------------
# Bridge: streaming
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  streaming multipart parser (P10: Content-Length-based framing).

Contains _stream_multipart_instances (yields DICOM parts from streaming
multipart/related response). Parts within the spill threshold stay fully in
memory; larger parts spill the excess into a system temp file (W3, 0209).

P10: replaced boundary-searching state machine with Content-Length-based
framing. Boundary is used ONLY for verification, not for finding part
boundaries. This eliminates false boundary matches in binary pixel data.
"""

import logging
import os
import tempfile
from collections import namedtuple

# Defence in depth: prevent unbounded buffer growth on malformed multipart
MAX_BUFFER_SIZE = 100 * 1024 * 1024  # 100 MB

# Parts above this size are yielded as SpilledPart - the first
# SPILL_THRESHOLD body bytes stay in memory, the excess streams into a temp
# file. Injectable per call via the spill_threshold parameter (tests), never
# monkeypatched.
SPILL_THRESHOLD = 16 * 1024 * 1024  # 16 MB

# Yield element for an oversized part. `head` carries the first
# spill_threshold body bytes (kept in memory), `path` points at a temp file
# holding the rest. Namedtuple over (is_path, payload) tuples: attribute
# access beats indexed nested tuples at the two call sites (parser + loop).
SpilledPart = namedtuple("SpilledPart", "head path")

# DICOM magic bytes at offset 128 (PS3.10 sec.7.1)
DICM_MAGIC = b"DICM"
DICM_OFFSET = 128
DICM_MIN_SIZE = 132  # 128 + 4 magic bytes

# ---------------------------------------------------------------------------
# P10 B2: DICOM magic bytes verification (defence in depth)
# ---------------------------------------------------------------------------
def _is_valid_dicom(data: bytes) -> bool:
    """Check DICOM magic bytes ('DICM' at offset 128). PS3.10 sec.7.1."""
    if len(data) < DICM_MIN_SIZE:
        return False
    return data[DICM_OFFSET : DICM_OFFSET + 4] == DICM_MAGIC

# ---------------------------------------------------------------------------
# P10 B1: Content-Length extraction from MIME part headers
# ---------------------------------------------------------------------------
def _parse_content_length(headers_bytes: bytes) -> int | None:
    """Extract Content-Length from MIME part headers.

    Returns int or None if header is missing or malformed.
    """
    for line in headers_bytes.split(b"\r\n"):
        if line.lower().startswith(b"content-length:"):
            try:
                return int(line.split(b":", 1)[1].strip())
            except (ValueError, IndexError):
                return None
    return None

def _parse_part_transfer_syntax(headers_bytes: bytes) -> str | None:
    """Extract the `transfer-syntax=` parameter from the part's
    Content-Type header (3008 stored-first: the server names the ACTUAL
    syntax of the part bytes). Handles quoted and unquoted values and
    other parameters before/after. Returns None when absent.
    """
    for line in headers_bytes.split(b"\r\n"):
        if not line.lower().startswith(b"content-type:"):
            continue
        for part in line.split(b";")[1:]:
            kv = part.strip()
            if not kv.lower().startswith(b"transfer-syntax="):
                continue
            value = kv.split(b"=", 1)[1].strip().strip(b'"')
            value = value.decode("ascii", "replace").strip()
            return value or None
        return None
    return None

# ---------------------------------------------------------------------------
# P10 B1: Content-Length-based streaming multipart parser
# ---------------------------------------------------------------------------
def _stream_multipart_instances(
    response, chunk_size=65536, spill_threshold=SPILL_THRESHOLD
):
    """Generator: yield (part, part_index, part_ts) from streaming multipart response.

    part_ts is the `transfer-syntax=` parameter of the part's Content-Type
    header (None when the server did not emit it - old server builds). The
    bridge reads it first in the actual_ts resolution chain, so the send
    loop never trusts a DICOM parser for the stored syntax.

    P10: Content-Length-based framing. Boundary is used ONLY for verification.
    Each MIME part MUST include Content-Length header (fail closed if missing).

    Protocol on the wire (from Clarus Server S1):
        --BOUNDARY\\r\\n
        Content-Type: application/dicom\\r\\n
        Content-Length: N\\r\\n
        \\r\\n
        <N bytes DICOM>
        \\r\\n--BOUNDARY\\r\\n
        ... next part ...
        \\r\\n--BOUNDARY--\\r\\n

    Args:
        response: requests.Response with stream=True
        chunk_size: read buffer size (default 64KB)
        spill_threshold: body bytes kept in memory per part (default 16 MB)

    Yields:
        (part, part_index, part_ts)  -  part is the raw DICOM body as bytes
        (the whole part fit in memory) or SpilledPart(head, path) when the
        part exceeded spill_threshold. The head carries the first
        spill_threshold bytes - enough for the DICM magic check and the
        whole file meta group the send loop reads.

    Raises:
        ValueError: if buffer exceeds MAX_BUFFER_SIZE, boundary missing,
                    or Content-Length missing (fail closed)
    """
    # Extract boundary from Content-Type header
    content_type = response.headers.get("Content-Type", "")
    boundary = None
    for param in content_type.split(";"):
        param = param.strip()
        if param.startswith("boundary="):
            boundary = param.split("=", 1)[1].strip().strip('"')
            break
    if not boundary:
        raise ValueError("Multipart: no boundary in Content-Type header")

    # Wire-format delimiters (as sent by Clarus Server S1/S2)
    boundary_bytes = ("--" + boundary).encode("ascii")
    first_delimiter = boundary_bytes + b"\r\n"  # --BOUNDARY\r\n
    # PS3.18 sec.8.7.2: each part body is followed by CRLF, then the next boundary.
    # Content-Length may or may not include this trailing CRLF. Handle both:
    #   Case A (CRLF in Content-Length): <body>\r\n--BOUNDARY\r\n
    #   Case B (CRLF outside):          <body>\r\n\r\n--BOUNDARY\r\n
    next_delimiter = b"\r\n" + boundary_bytes + b"\r\n"  # \r\n--BOUNDARY\r\n
    next_delimiter_alt = (
        b"\r\n\r\n" + boundary_bytes + b"\r\n"
    )  # \r\n\r\n--BOUNDARY\r\n
    final_delimiter = b"\r\n" + boundary_bytes + b"--"  # \r\n--BOUNDARY--
    final_delimiter_alt = b"\r\n\r\n" + boundary_bytes + b"--"  # \r\n\r\n--BOUNDARY--
    len_next_delimiter = len(next_delimiter)
    len_next_delimiter_alt = len(next_delimiter_alt)

    buffer = b""
    part_index = 0
    preamble_skipped = False
    # W3 (0209) spill state for the oversized part currently being received.
    spill_file = None  # open temp file, None when no spill is active
    spill_path = None  # spill_file.name while active
    spill_written = 0  # body bytes already written to the file
    spill_total = 0  # Content-Length of the spilled part
    spill_body_start = 0  # buffer offset where the part body begins

    try:
        for chunk in response.iter_content(chunk_size=chunk_size):
            if not chunk:
                continue
            if spill_file is None:
                buffer += chunk
            else:
                # W3: cap the in-memory head at spill_threshold, stream the
                # body overflow to the temp file and keep only the framing
                # bytes (trailing CRLF + next delimiter) in the buffer - it
                # stays bounded no matter how large the part is.
                avail = len(buffer) - spill_body_start
                missing = spill_total - spill_written - avail
                to_head = min(spill_threshold - avail, len(chunk))
                buffer += chunk[:to_head]
                to_file = min(len(chunk) - to_head, missing - to_head)
                if to_file > 0:
                    spill_file.write(chunk[to_head : to_head + to_file])
                    spill_written += to_file
                buffer += chunk[to_head + to_file :]

            # Defence in depth: prevent unbounded growth. W3 note: with a
            # spill active the in-memory buffer is capped at spill_threshold
            # bytes, so this check is inert for the head of an oversized
            # part; it remains the guard for malformed streams (broken
            # framing never completes a part, nothing is ever consumed).
            if len(buffer) > MAX_BUFFER_SIZE:
                raise ValueError(
                    f"Multipart buffer exceeded {MAX_BUFFER_SIZE} bytes "
                    "- possible malformed response"
                )

            while True:
                # -- Phase 0: skip preamble, find first boundary ---------
                if not preamble_skipped:
                    idx = buffer.find(first_delimiter)
                    if idx == -1:
                        break  # Wait for more data
                    buffer = buffer[idx + len(first_delimiter) :]
                    preamble_skipped = True
                    # Continue to Phase 1 (don't break  -  headers follow immediately)

                # -- Phase 1: parse part headers -------------------------
                header_end = buffer.find(b"\r\n\r\n")
                if header_end == -1:
                    break  # Wait for complete headers

                # Defence: empty headers (header_end == 0) means the \r\n\r\n
                # at buffer start is a trailing CRLF from previous part body,
                # NOT the start of a new part. Check for closing delimiter.
                if header_end == 0:
                    if buffer.startswith(final_delimiter_alt):
                        return  # Clean finish (trailing CRLF + closing delimiter)
                    if buffer.startswith(next_delimiter_alt):
                        buffer = buffer[len_next_delimiter_alt:]
                        continue  # Next part (trailing CRLF + next delimiter)
                    # Not a delimiter  -  break and wait for more data
                    break

                headers_bytes = buffer[:header_end]
                body_start = header_end + 4  # Skip \r\n\r\n

                # P10: Content-Length is MANDATORY (S1  -  server provides it)
                content_length = _parse_content_length(headers_bytes)
                if content_length is None:
                    raise ValueError(
                        f"[STREAM] Part {part_index}: missing Content-Length "
                        "- server must provide Content-Length per MIME part (P10 S1). "
                        "Boundary-based framing is unsafe for binary DICOM data."
                    )
                # 3008 stored-first: per-part transfer-syntax parameter.
                part_ts = _parse_part_transfer_syntax(headers_bytes)

                # W3: parts above the threshold spill to a temp file.
                if spill_file is None and content_length > spill_threshold:
                    spill_file = tempfile.NamedTemporaryFile(
                        prefix="clbridge_spill_",
                        suffix=".part",
                        delete=False,
                    )
                    spill_path = spill_file.name
                    spill_written = 0
                    spill_total = content_length
                    spill_body_start = body_start
                    # The current chunk may already carry body bytes past
                    # the threshold - drain exactly the body overflow to the
                    # file; framing bytes (trailing CRLF + delimiter) stay
                    # in the buffer for Phase 4.
                    body_end = body_start + content_length
                    overflow = buffer[body_start + spill_threshold : body_end]
                    if overflow:
                        spill_file.write(overflow)
                        spill_written += len(overflow)
                    buffer = buffer[: body_start + spill_threshold] + buffer[body_end:]

                # -- Phase 2: extract DICOM body by length ---------------
                body_end = body_start + content_length
                if spill_file is None:
                    if len(buffer) < body_end:
                        break  # Wait for complete body
                    part = buffer[body_start:body_end]
                    buffer = buffer[body_end:]
                    check = part
                else:
                    # Head capped in memory, the excess already on disk.
                    if (len(buffer) - body_start) + spill_written < content_length:
                        break  # Wait for complete body
                    part = SpilledPart(
                        buffer[body_start : body_start + spill_threshold],
                        spill_path,
                    )
                    buffer = buffer[body_start + spill_threshold :]
                    spill_file.close()
                    spill_file = None
                    spill_path = None
                    spill_written = 0
                    check = part.head

                # -- Phase 3: yield DICOM body (Content-Length is authoritative) -
                body_valid = _is_valid_dicom(check)
                if body_valid:
                    yield (part, part_index, part_ts)
                    part_index += 1
                else:
                    if isinstance(part, SpilledPart):
                        # No consumer will ever see this part - drop the file.
                        try:
                            os.unlink(part.path)
                        except OSError:
                            pass
                    logging.warning(
                        "[STREAM] Part %d: invalid DICOM (no magic bytes), skipping",
                        part_index,
                    )

                # -- Phase 4: skip past next delimiter -----------------
                # Content-Length is authoritative  -  body already extracted.
                # Just find and skip the delimiter between parts.
                if buffer.startswith(final_delimiter):
                    return  # Clean finish
                if buffer.startswith(final_delimiter_alt):
                    return  # Clean finish (CRLF outside Content-Length)

                if buffer.startswith(next_delimiter):
                    buffer = buffer[len_next_delimiter:]
                    continue  # Next part
                if buffer.startswith(next_delimiter_alt):
                    buffer = buffer[len_next_delimiter_alt:]
                    continue  # Next part (CRLF outside Content-Length)

                # Delimiter not in buffer yet  -  wait for next HTTP chunk
                break

        # -- Flush: stream ended without final delimiter ----------------
        # W3: with a spill still active the oversized part never completed -
        # never yield a truncated head, let the finally drop the file.
        if preamble_skipped and len(buffer) > 0 and spill_file is None:
            # Try to extract one last part from remaining buffer
            header_end = buffer.find(b"\r\n\r\n")
            if header_end != -1:
                headers_bytes = buffer[:header_end]
                body_start = header_end + 4
                content_length = _parse_content_length(headers_bytes)
                part_ts = _parse_part_transfer_syntax(headers_bytes)
                if (
                    content_length is not None
                    and len(buffer) >= body_start + content_length
                ):
                    dicom_body = buffer[body_start : body_start + content_length]
                    if _is_valid_dicom(dicom_body):
                        yield (dicom_body, part_index, part_ts)
                elif content_length is None:
                    # Fallback: use whatever is left as body (no Content-Length header).
                    # Some non-standard DICOMweb implementations omit Content-Length.
                    body = buffer[body_start:].rstrip(b"\r\n")
                    if body and _is_valid_dicom(body):
                        yield (body, part_index, part_ts)
    finally:
        # W3: never leak a spill file - a truncated stream, a fatal parse
        # error or an early consumer exit all land here. A completed part
        # resets spill_file before it is yielded, so only the part that was
        # still being received is cleaned up here.
        if spill_file is not None:
            try:
                spill_file.close()
            except OSError:
                pass
            try:
                os.unlink(spill_path)
            except OSError:
                pass

# ---------------------------------------------------------------------------
# Bridge: utils
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  core utilities: shutdown signal, logging, dataset measurement.

Contains graceful shutdown event, signal handler, logging setup with rotation,
and C-STORE dataset size measurement.
"""

import hashlib
import hmac
import io
import logging
import os
import signal
import sys
import tempfile
import threading
import time
from logging.handlers import RotatingFileHandler

from pydicom import dcmwrite
from pydicom.uid import ImplicitVRLittleEndian

# ---------------------------------------------------------------------------
# Bridge: graceful shutdown event  -  checked by all handlers
# ---------------------------------------------------------------------------
_shutdown_requested = threading.Event()

# : PID file path for duplicate instance detection cleanup
_pid_path = None  # Set by main.py after successful startup checks

def set_pid_path(path: str) -> None:
    """Set PID file path (called by main.py after startup checks)."""
    global _pid_path
    _pid_path = path

def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT/SIGBREAK  -  initiate graceful shutdown (BR-007).

    nginx-way: signal handler does ONE thing  -  sets the shutdown flag.
    The ShutdownMonitor thread (started in main.py) bridges this flag
    to pynetdicom's event loop by calling ae.shutdown() from a regular
    thread context, which is safe (not async-signal-restricted).
    """
    sig_name = signal.Signals(signum).name
    logging.info("Received %s, initiating graceful shutdown...", sig_name)
    _shutdown_requested.set()
    # That's it. Nothing else. No timers, no os._exit, no file I/O.
    # ShutdownMonitor thread handles the rest.

# ---------------------------------------------------------------------------
# Bridge: configure logging with optional rotation
# ---------------------------------------------------------------------------
def _setup_logging(log_level="INFO", log_file=None):
    """Configure root logger with console handler and optional file handler.

    Log rotation: 10 MB x 3 backups (always on when log_file is set).
    """
    level = getattr(logging, log_level.upper(), logging.INFO)
    fmt = logging.Formatter(
        "%(asctime)s [%(levelname)s] %(message)s",
        datefmt="%Y-%m-%dT%H:%M:%S",
    )

    root_logger = logging.getLogger()
    root_logger.setLevel(level)
    root_logger.handlers.clear()

    # -- Suppress library noise  -  : libraries keep quiet --
    # urllib3/requests log every HTTP request at INFO (432 lines of "201 Created"
    # for a 432-slice upload). pynetdicom/pydicom dump tracebacks.
    # Below WARNING, library output is noise  -  admin doesn't need it.
    for lib in ("urllib3", "requests", "httpx", "httpcore", "pydicom", "pynetdicom"):
        logging.getLogger(lib).setLevel(logging.WARNING)

    # -- Console: UTF-8 with error replacement  -  never crash on non-cp1251 chars --
    # Chinese patient names, Norwegian AE titles, DICOM UIDs with special chars  -
    # Windows console may be cp1251, but log messages come in UTF-8.
    # reconfigure() makes stderr replace unencodable chars with '?' instead of crashing.
    console_stream = sys.stderr
    try:
        console_stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass  # Python < 3.7 or non-TTY  -  fall through to raw stderr
    console = logging.StreamHandler(console_stream)
    console.setFormatter(fmt)
    root_logger.addHandler(console)

    if log_file:
        # Auto-create the parent directory (e.g. logs/) so a fresh host does not
        # fail on a missing path.
        log_dir = os.path.dirname(os.path.abspath(log_file))
        os.makedirs(log_dir, exist_ok=True)
        max_bytes = 10 * 1024 * 1024  # 10 MB
        file_handler = RotatingFileHandler(
            log_file,
            maxBytes=max_bytes,
            backupCount=3,
            encoding="utf-8",
        )
        file_handler.setFormatter(fmt)
        root_logger.addHandler(file_handler)
        logging.info("Logging to file: %s (10 MB x 3 rotations)", log_file)

# ---------------------------------------------------------------------------
# Bridge: C-STORE size limit measurement
# ---------------------------------------------------------------------------
def _measure_dataset_bytes(dataset, event=None):
    """Return dataset size in bytes.

    Prefers pynetdicom's raw DataSet if available (no extra serialization).
    Falls back to dcmwrite() into BytesIO buffer.

    pynetdicom hands large payloads over as a stream (BytesIO) rather than
    bytes, and a stream has no len(); the size of such a payload is its
    remaining length, so seek to the end and restore the position. Without
    this the size of every large C-STORE would be reported as unmeasurable.
    """
    # Bridge: try raw request data first (fast path, BR-001)
    if event is not None:
        raw = getattr(event.request, "DataSet", None)
        if raw is not None:
            try:
                return len(raw)
            except TypeError:
                # A stream: measure by seeking, then restore the read
                # position so the caller can still consume the payload.
                pos = raw.tell()
                size = raw.seek(0, io.SEEK_END)
                raw.seek(pos)
                return size
    # Bridge: fallback  -  serialize to measure (slow path, BR-001)
    buf = io.BytesIO()
    # Ensure bare Datasets (e.g. from tests) have encoding context
    if not hasattr(dataset, "is_implicit_VR") or dataset.is_implicit_VR is None:
        dataset.is_implicit_VR = True
        dataset.is_little_endian = True
    # Populate minimal file_meta to satisfy pydicom validator
    if not hasattr(dataset, "file_meta") or not dataset.file_meta:
        from pydicom import Dataset as DcmDs

        dataset.file_meta = DcmDs()
    fm = dataset.file_meta
    if not getattr(fm, "MediaStorageSOPClassUID", None):
        fm.MediaStorageSOPClassUID = (
            getattr(dataset, "SOPClassUID", "1.2.840.10008.5.1.4.1.1.7")
            or "1.2.840.10008.5.1.4.1.1.7"
        )
    if not getattr(fm, "MediaStorageSOPInstanceUID", None):
        fm.MediaStorageSOPInstanceUID = (
            getattr(dataset, "SOPInstanceUID", "1.2.826.0.1.3680043.8.498.1")
            or "1.2.826.0.1.3680043.8.498.1"
        )
    if not getattr(fm, "TransferSyntaxUID", None):
        fm.TransferSyntaxUID = ImplicitVRLittleEndian
    dcmwrite(buf, dataset, enforce_file_format=True)
    return len(buf.getvalue())

# ---------------------------------------------------------------------------
# Bridge: PatientName masking - no PHI in logs.
# ---------------------------------------------------------------------------
def mask_patient_name(name: str) -> str:
    """Mask PatientName for 152-FZ: Ivanov -> I....v, Smith -> S...h."""
    if not name:
        return "***"
    n = len(name)
    if n <= 1:
        return "***"
    if n == 2:
        return name[0] + "."
    return name[0] + "." * min(n - 2, 4) + name[-1]

def mask_patient_id(patient_id: str) -> str:
    """Mask PatientID for the logs with a keyed HMAC token (152-FZ).

    A national/MRN identifier has no safe first/last mask (its prefix is
    site-coded), so the log carries a stable 12-hex token instead of the raw
    value. The study UID logged next to it remains the correlation key.

    The token is HMAC-SHA256 under a per-install secret, not a bare digest.
    Patient IDs are low entropy by design - a few digits, often with a
    site prefix - so an unkeyed SHA-256 of one is reversible by enumeration:
    anyone holding a log line hashes candidates until one matches, in
    seconds, and the log stops being anonymised. The secret is what makes
    that search impossible without the key file.

    Correlating two lines needs the same secret, so the key persists next to
    the outbox and is created once on first use. Deleting it yields a NEW
    key, and every token written afterwards differs from the ones already in
    the log: old lines keep their own tokens and no longer join to new ones.
    That affects log correlation ONLY - forwarding is unaffected, because the
    outbox carries the raw PatientID, not this token.
    """
    if not patient_id:
        return "***"
    key = _mask_key()
    return hmac.new(key, patient_id.encode("utf-8"), hashlib.sha256).hexdigest()[:12]

#: Per-install masking key, read once. `None` = not yet loaded.
_mask_key_cache = None

def _outbox_root() -> str:
    """The configured outbox directory, resolved the same way main.py resolves
    it (relative paths are relative to the config file). Falls back to the
    default so a unit-test import does not depend on startup order."""
    configured = os.environ.get("CLBRIDGE_OUTBOX_DIR")
    if configured:
        return configured
    return os.path.join(os.getcwd(), "clbridge", "outbox")

def set_mask_key_dir(path: str) -> None:
    """Point the masking key at `path` (called by main.py once the outbox
    directory is resolved). Clears the cache so the next call reloads."""
    global _mask_key_cache, _mask_key_dir_override
    _mask_key_dir_override = path
    _mask_key_cache = None

#: Explicit override set by main.py; empty means "derive from the outbox".
_mask_key_dir_override = ""

#: Serialises the load-or-create sequence between THREADS of this process.
#: The `O_EXCL` create already arbitrates between processes; two threads in
#: one process would otherwise both miss the cache and both run the repair
#: branch over the same file. `RLock` because the recursion is not expected:
#: a plain `Lock` would be enough today, and a nested call in the future must
#: not deadlock the whole process over a log line.
_mask_key_lock = threading.RLock()

#: A published key is 32 random bytes (256 bits); anything shorter is a
#: truncated file or a half-written one, never a key. The length is the
#: contract the winner writes and the loser accepts, so both sides agree.
_MASK_KEY_BYTES = 32

#: How many times a loser re-reads a file it found too short before giving
#: up. The winner's window is one `os.replace` - microseconds - so three
#: attempts with a 10 ms backoff cover an arbitrarily slow scheduler without
#: turning a broken file into an infinite wait.
_MASK_KEY_READ_ATTEMPTS = 3
_MASK_KEY_READ_PAUSE_S = 0.01

def _publish_key(path: str, key: bytes) -> None:
    """Write `key` to `path` so no reader can ever observe a partial file.

    A create-then-write publishes the NAME before the BYTES: a concurrent
    reader sees an empty file, and an empty HMAC key is as good as no key at
    all - the token becomes an unkeyed digest of a low-entropy patient id,
    reversible by enumeration. Writing to a temporary sibling and `os.replace`
    onto the final name makes the publication atomic on POSIX and on Windows,
    so a reader opens either the old file or the complete new one.
    """
    fd, tmp_path = tempfile.mkstemp(
        prefix=".patient_id_mask.", dir=os.path.dirname(path)
    )
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(key)
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

def _read_key(path: str) -> bytes:
    """Read a published key, retrying while it is still too short."""
    for attempt in range(_MASK_KEY_READ_ATTEMPTS):
        try:
            with open(path, "rb") as handle:
                key = handle.read()
        except FileNotFoundError:
            key = b""
        if len(key) >= _MASK_KEY_BYTES:
            return key
        if attempt + 1 < _MASK_KEY_READ_ATTEMPTS:
            time.sleep(_MASK_KEY_READ_PAUSE_S)
    return key

def _mask_key() -> bytes:
    """Load the per-install masking key, creating or repairing it as needed.

    Three cases, and they are genuinely different:

    * ABSENT - create it exclusively (`O_EXCL`). Two processes starting at the
      same moment must not both write a key with one silently winning: the
      loser re-reads what the winner wrote, so both end up with the same key.
    * PRESENT and long enough - use it. This is the normal path.
    * PRESENT but too short - the file is truncated or was never a key. It has
      to be REPLACED, which the exclusive-create path cannot do: `O_EXCL`
      fails on an existing file, and re-reading it would hand back the same
      unusable bytes while the log claimed otherwise. The replacement is
      therefore an in-place truncating write.

    A missing key is created rather than treated as an error: the first log
    line of a fresh install must already be masked, and refusing to log it
    would trade a privacy leak for an outage. An UNREADABLE key (permissions,
    a directory in its place) is logged and not fatal - tokens then stop being
    stable across restarts, which is visible and recoverable, whereas a crash
    at startup is not.
    """
    global _mask_key_cache
    if _mask_key_cache is not None:
        return _mask_key_cache
    with _mask_key_lock:
        if _mask_key_cache is not None:
            return _mask_key_cache
        key = _load_or_create_key()
        _mask_key_cache = key
        return key

def _load_or_create_key() -> bytes:
    """The load-or-repair sequence behind `_mask_key`, run under the lock."""
    root = _mask_key_dir_override or _outbox_root()
    path = os.path.join(root, ".patient_id_mask.key")

    try:
        with open(path, "rb") as handle:
            existing = handle.read()
    except FileNotFoundError:
        existing = None
    except OSError as exc:
        logging.error(
            "[MASK] cannot read the patient-id key at %s (%s); "
            "log tokens are not stable across restarts",
            path,
            exc,
        )
        return os.urandom(_MASK_KEY_BYTES)

    if existing is not None and len(existing) >= _MASK_KEY_BYTES:
        return existing

    key = os.urandom(_MASK_KEY_BYTES)
    try:
        os.makedirs(root, exist_ok=True)
        if existing is None:
            # Absent. The exclusive create decides a race between processes,
            # and its only role is to name one winner: the bytes are then
            # published by rename, so no reader ever sees the empty file the
            # create leaves behind.
            try:
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            except FileExistsError:
                # Another process won. Its file is authoritative; it is read
                # back with a length check, because the winner's rename makes a
                # short read impossible and a half-written file must never be
                # adopted as a key.
                adopted = _read_key(path)
                if len(adopted) >= _MASK_KEY_BYTES:
                    return adopted
                # The winner is mid-publication or gone; publishing ours is
                # still the best repair, and it is atomic for every reader.
                _publish_key(path, key)
                return key
            os.close(fd)
        else:
            # Present but unusable: it cannot be trusted and `O_EXCL` would
            # refuse to fix it, so it is replaced. The length is reported
            # because a short key is a symptom worth seeing.
            logging.warning(
                "[MASK] key file %s is short (%d bytes); replacing it",
                path,
                len(existing),
            )
        _publish_key(path, key)
    except OSError as exc:
        logging.error(
            "[MASK] cannot persist the patient-id key at %s (%s); "
            "log tokens are not stable across restarts",
            path,
            exc,
        )
    return key

# ---------------------------------------------------------------------------
# Bridge: validation
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  DICOM tag validation and coercion (FR-001).

Bridge sanitizes empty DICOM Type 2 fields (PatientID, PatientName)
BEFORE sending to the server. Records all modifications in
Original Attributes Sequence (0400,0561)  -  the bridge's audit trail.

Server also validates independently  -  two levels of protection.
"""

import hashlib
import secrets
import time

from pydicom.dataset import Dataset
from pydicom.sequence import Sequence

def generate_patient_id(prefix="AUTOPAT_"):
    """Generate unique PatientID: AUTOPAT_YYYYMMDD_HHMMSS_RRRRR.

    Fallback for when StudyInstanceUID is unavailable.
    Prefer generate_patient_id_from_study() for deterministic grouping.
    Uses timestamp + secrets for uniqueness across concurrent C-STORE calls.
    """
    ts = time.strftime("%Y%m%d_%H%M%S")
    rnd = secrets.token_hex(4)  # 8 hex chars  -  sufficient entropy for fallback
    return f"{prefix}{ts}_{rnd}"

def generate_patient_id_from_study(study_uid, prefix="AUTOPAT_"):
    """Generate deterministic PatientID from StudyInstanceUID.

    # All SOPs in one study must map to the same PatientID, otherwise the
    # DICOMweb hierarchy would split a single study across patients.
    SHA-256 truncated to 12 hex chars -> collision probability < 2^-48.
    Deterministic -> same StudyUID always produces same PatientID.
    """
    h = hashlib.sha256(study_uid.encode()).hexdigest()[:12].upper()
    return f"{prefix}{h}"

def generate_patient_name(prefix="Anonymous^"):
    """Generate DICOM PatientName in PN format: Anonymous^Generated.

    Fallback when StudyInstanceUID is unavailable.
    """
    return f"{prefix}Generated"

def generate_patient_name_from_study(study_uid, prefix="Anonymous^"):
    """Generate deterministic PatientName from StudyInstanceUID.

    Format: Anonymous^A1B2C3  -  unique per study, minimal.
    """
    h = hashlib.sha256(study_uid.encode()).hexdigest()[:6].upper()
    return f"{prefix}{h}"

def record_modification(
    ds,
    tag,
    old_value,
    reason="COERCE",
    modifying_operator=None,
    modifying_system=None,
):
    """Write modification to Original Attributes Sequence (0400,0561).

    DICOM PS3.3 C.12.1: Original Attributes Sequence records what was changed,
    by whom, when, and why. Bridge is the single point of audit  -  server does
    NOT write this tag.

    Structure:
      OriginalAttributesSequence (0400,0561)
        Item:
          AttributeModificationDateTime (0400,0562)
          ModifyingSystem (0400,0563)
          ModifyingOperator (0400,0566)  -  who made the change (Type 2)
          ReasonForModification (0400,0565)
          ModifiedAttributesSequence (0400,0550)
            Item: the actual changed tag with its OLD value

    Args:
        ds: pydicom Dataset (modified in-place)
        tag: DICOM tag tuple, e.g. (0x0010, 0x0020)
        old_value: original value before modification
        reason: DICOM CID 7050 code (COERCE, CORRECT, etc.)
        modifying_operator: who made the change (DIMSE AE Title for C-STORE, else "DIMSE")
        modifying_system: (0400,0563) system that applied the change - the
            bridge's configured AE title. PS3.3 C.12.1 wants the system
            identified, so the caller supplies it; a literal here would
            disagree with the AE title the bridge actually associates under.
    """
    from datetime import datetime

    from pydicom.dataelem import DataElement

    if not modifying_system:
        # (0400,0563) is Type 1 (PS3.3 C.12.1). An empty value would be a
        # malformed audit entry, and a silent default would hide the miswiring
        # that caused it - refuse the write instead.
        raise ValueError("modifying_system is required for ModifyingSystem (0400,0563)")

    # -- Original Attributes Sequence item (who/when/why) --
    # DICOM PS3.3 Table C.12.1.1.9-1: Original Attributes Macro
    attr_item = Dataset()
    attr_item.SourceOfPreviousValues = ""  # (0400,0564) Type 2  -  may be empty
    attr_item.AttributeModificationDateTime = datetime.now().strftime(
        "%Y%m%d%H%M%S"
    )  # (0400,0562) Type 1
    attr_item.ModifyingSystem = modifying_system  # (0400,0563) Type 1
    attr_item.ReasonForTheAttributeModification = (
        reason  # (0400,0565) Type 1  -  CID 7050: COERCE
    )
    # (0400,0566) ModifyingOperator  -  who (Type 2). Not in pydicom data dict
    # (pydicom doesn't know this private-ish tag), so use add_new() to avoid
    # "Camel case attribute" warnings.
    attr_item.add_new((0x0400, 0x0566), "PN", modifying_operator or "DIMSE")

    # -- ModifiedAttributesSequence (0400,0550)  -  WHAT was changed --
    # Type 1. Single Item containing the modified tag with its OLD value.
    # Preserve VR from original element, fallback to LO (Long String).
    vr = ds[tag].VR if tag in ds else "LO"
    mod_attr = Dataset()
    mod_attr[tag] = DataElement(tag, vr, old_value or "")
    mod_seq = Sequence()
    mod_seq.append(mod_attr)
    attr_item.ModifiedAttributesSequence = mod_seq

    # Add to main dataset
    if (0x0400, 0x0561) not in ds:
        ds.OriginalAttributesSequence = Sequence()
    ds.OriginalAttributesSequence.append(attr_item)

def sanitize_dataset(
    ds,
    fix_patient_id=True,
    fix_patient_name=True,
    id_prefix="AUTOPAT_",
    name_prefix="Anonymous^",
    write_audit=True,
    study_uid=None,
    modifying_system=None,
):
    """Sanitize empty DICOM Type 2 fields. Returns list of modifications.

    Args:
        ds: pydicom Dataset (modified in-place)
        fix_patient_id: generate PatientID if empty
        fix_patient_name: generate PatientName if empty
        id_prefix: prefix for generated PatientID
        name_prefix: prefix for generated PatientName
        write_audit: if True, record modification in (0400,0561) now.
                     If False, skip  -  caller must apply record_modification later
                     (used to defer audit trail writing off C-STORE hot-path).
        study_uid: if provided, generates deterministic PatientID/Name from
                   StudyInstanceUID. All SOPs in the same study get the same
                   PatientID  -  preserving the DICOM patient-study relationship
                   and preventing SQLite performance degradation.
        modifying_system: (0400,0563) value for the audit entry - the bridge's
                   configured AE title, threaded to record_modification().

    Returns:
        list of (tag, old_value, new_value) tuples for logging
    """
    if write_audit and not modifying_system:
        # Validated BEFORE any field is overwritten: mutating first and failing
        # inside record_modification would leave the dataset changed with no
        # audit entry carrying the original empty value, so a caller retrying
        # with a valid title would record a false "old" value.
        raise ValueError("modifying_system is required for ModifyingSystem (0400,0563)")

    modifications = []

    # PatientID (0010,0020)  -  Type 2
    pid = ds.get((0x0010, 0x0020))
    if not pid or not pid.value:
        # Two values with different jobs: the log tuple needs a readable
        # placeholder, while the audit entry records what the attribute
        # ACTUALLY held - the empty string for an absent or empty Type 2 field
        # (PS3.3 C.2.2). Recording "(empty)" in the Modified Attributes
        # Sequence would state a value the attribute never had.
        old = str(pid.value) if (pid and pid.value) else ""
        logged = old or "(empty)"
        if fix_patient_id:
            if study_uid:
                new_id = generate_patient_id_from_study(study_uid, id_prefix)
            else:
                new_id = generate_patient_id(id_prefix)
            ds.PatientID = new_id
            if write_audit:
                record_modification(
                    ds, (0x0010, 0x0020), old, modifying_system=modifying_system
                )
            modifications.append(((0x0010, 0x0020), logged, new_id))
        else:
            raise ValueError("PatientID is empty and fix_patient_id is disabled")

    # PatientName (0010,0010)  -  Type 2
    pname = ds.get((0x0010, 0x0010))
    if not pname or not pname.value:
        old = str(pname.value) if (pname and pname.value) else ""
        logged = old or "(empty)"
        if fix_patient_name:
            if study_uid:
                new_name = generate_patient_name_from_study(study_uid, name_prefix)
            else:
                new_name = generate_patient_name(name_prefix)
            ds.PatientName = new_name
            if write_audit:
                record_modification(
                    ds, (0x0010, 0x0010), old, modifying_system=modifying_system
                )
            modifications.append(((0x0010, 0x0010), logged, new_name))
        else:
            raise ValueError("PatientName is empty and fix_patient_name is disabled")

    return modifications

