# Bridge: 
# ---------------------------------------------------------------------------
# Clarus Bridge  -  clean_code package (development only).
# This file is NOT included in the bundle (bundle.py concatenates .py files directly).
# It exists so that Pylance and IDEs can resolve `from clean_code.xxx import ...` imports.

# ---------------------------------------------------------------------------
# Bridge: handlers
