# Bridge: move_jobs
# ---------------------------------------------------------------------------

"""Clarus Bridge - C-MOVE job queue and SCP target registry (BR-007).

MoveJobManager: SQLite-backed C-MOVE job queue with SCP target auto-registration.
Thread-safe via SharedDb: one connection, one lock.
Survives bridge restarts.

Known limitations:
- C-MOVE-CANCEL not supported. Client can close association;
  Bridge finishes the current job (data won't be lost).
- No duplicate SOP check before re-send after restart.
- Double I/O: temp-file -> read -> send (streaming future).
"""

import ipaddress
import logging
import threading
import time

# ---------------------------------------------------------------------------
# DB Migration helpers (subnet support, composite keys)
# ---------------------------------------------------------------------------
def _migrate_move_jobs(conn):
    """Add target_host/target_port columns if missing (pre-existing DBs)."""
    cols = {r[1] for r in conn.execute("PRAGMA table_info('move_jobs')").fetchall()}
    if "target_host" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN target_host TEXT NOT NULL DEFAULT ''"
        )
    if "target_port" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN target_port INTEGER NOT NULL DEFAULT 0"
        )
    # (0008,0058) Failed SOP Instance UID List - newline-joined UIDs of
    # the slices that failed transfer in this job (PS3.4 C.4.2.1.4.2). The
    # C-MOVE reactor reads it to put the list on the final Failed/Cancel/
    # Warning C-MOVE-RSP Identifier.
    if "failed_sops" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN failed_sops TEXT NOT NULL DEFAULT ''"
        )
    # Per-association expose flag: 1 when this job was requested over the
    # Expose Rejected Instances AE. Carried on the job because the C-MOVE
    # worker threads are long-lived and outlive the association that queued
    # the work, so it cannot be read from the event when the job runs.
    if "expose_rejected" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN expose_rejected INTEGER NOT NULL DEFAULT 0"
        )

def _migrate_scp_targets(conn):
    """Migrate scp_targets from single PK (ae_title) to composite (ae_title, host).

    Preserves existing data. Idempotent  -  safe to run multiple times.
    """
    # Check if old schema (ae_title as sole PK) exists
    cols = {r[1] for r in conn.execute("PRAGMA table_info('scp_targets')").fetchall()}
    if not cols:
        # Table doesn't exist yet  -  create with v2 schema
        conn.execute(
            "CREATE TABLE IF NOT EXISTS scp_targets ("
            "  ae_title TEXT NOT NULL,"
            "  host TEXT NOT NULL,"
            "  port INTEGER NOT NULL DEFAULT 104,"
            "  last_seen INTEGER NOT NULL,"
            "  consecutive_failures INTEGER DEFAULT 0,"
            "  PRIMARY KEY (ae_title, host)"
            ")"
        )
        return

    # Check if already migrated: composite PK present.
    # SQLite PRAGMA table_info doesn't directly show composite PK.
    # Check by trying to insert a duplicate (ae, host)  -  if UNIQUE constraint
    # fails on (ae_title) alone, we're on old schema.
    # Simpler: check if 'host' is part of PK by looking at the CREATE TABLE sql
    create_sql = conn.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='scp_targets'"
    ).fetchone()
    if create_sql and "PRIMARY KEY (ae_title, host)" in create_sql[0]:
        return  # Already v2

    # Migrate: create v2, copy data, drop v1, rename
    conn.execute(
        "CREATE TABLE scp_targets_v2 ("
        "  ae_title TEXT NOT NULL,"
        "  host TEXT NOT NULL,"
        "  port INTEGER NOT NULL DEFAULT 104,"
        "  last_seen INTEGER NOT NULL,"
        "  consecutive_failures INTEGER DEFAULT 0,"
        "  PRIMARY KEY (ae_title, host)"
        ")"
    )
    conn.execute(
        "INSERT OR IGNORE INTO scp_targets_v2"
        " SELECT ae_title, host, port, last_seen, consecutive_failures"
        " FROM scp_targets"
    )
    conn.execute("DROP TABLE scp_targets")
    conn.execute("ALTER TABLE scp_targets_v2 RENAME TO scp_targets")

# ---------------------------------------------------------------------------
# Bridge: C-MOVE job queue and SCP target registry
# ---------------------------------------------------------------------------
class MoveJobManager:
    """SQLite-backed C-MOVE job queue with SCP target auto-registration.

    Thread-safe via SharedDb  -  "one connection, one lock".
    Survives bridge restarts.

    Known limitations:
    - C-MOVE-CANCEL not supported. Client can close association;
      Bridge finishes the current job (data won't be lost).
    - No duplicate SOP check before re-send after restart.
    - Double I/O: temp-file -> read -> send (streaming future).
    """

    def __init__(self, shared_db, max_workers=2, scp_remove_failures=3):
        """shared_db: SharedDb instance (NOT raw sqlite3.Connection).

        Uses SharedDb.locked() for ALL DB operations - no own lock.
        One connection, one lock: a single serialized writer avoids both lock
        ordering bugs and SQLite busy-handler tuning.

        scp_remove_failures: consecutive-failure threshold for the auto-remove
        of an auto-registered SCP peer (CM-006). Fixed constant 3 (fed from
        `_SCP_FAILURES_BEFORE_REMOVE` in main.py); there is no config knob.
        """
        self._db = shared_db  # SharedDb, NOT sqlite3.Connection
        self._cond = (
            threading.Condition()
        )  # notify workers (own cond, not on SharedDb lock)
        self.max_workers = max_workers
        self.scp_remove_failures = max(1, int(scp_remove_failures or 3))
        self._cancel_callbacks = {}  # job_id -> callable
        self._last_peers_reload = 0.0  # timestamp of last peers reload
        self.lazyload_peers_interval = (
            30  # seconds between peers.conf reloads (0 = every call)
        )

        with self._db.locked() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS move_jobs ("
                "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  study_uid TEXT NOT NULL,"
                "  move_dest_ae TEXT NOT NULL,"
                "  target_host TEXT NOT NULL DEFAULT '',"
                "  target_port INTEGER NOT NULL DEFAULT 0,"
                "  status TEXT NOT NULL DEFAULT 'pending',"
                "  total_instances INTEGER DEFAULT 0,"
                "  completed_instances INTEGER DEFAULT 0,"
                "  failed_instances INTEGER DEFAULT 0,"
                "  error_message TEXT,"
                "  failed_sops TEXT NOT NULL DEFAULT '',"
                "  created_at INTEGER NOT NULL,"
                "  updated_at INTEGER NOT NULL,"
                "  attempts INTEGER DEFAULT 0,"
                "  expose_rejected INTEGER NOT NULL DEFAULT 0"
                ")"
            )
            # Migration: add target_host/target_port columns if missing (pre-existing DBs)
            _migrate_move_jobs(conn)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_move_jobs_status ON move_jobs(status)"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_move_jobs_created ON move_jobs(created_at)"
            )
            # scp_targets v2: composite primary key (ae_title, host) for subnet support
            _migrate_scp_targets(conn)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_scp_targets_ae ON scp_targets(ae_title)"
            )
            conn.commit()

    # --- move_jobs CRUD ---

    def create_job(
        self,
        study_uid,
        move_dest_ae,
        target_host="",
        target_port=0,
        expose_rejected=False,
    ):
        """Create a new pending C-MOVE job. Returns job id.

        target_host/target_port: resolved Move Destination address.
        Stored so worker doesn't need to re-resolve (subnet support).
        expose_rejected: the job was queued over the QA AE; the worker queries
        the configured `[dicomweb] qa_url` endpoint instead of `clarus_url`.
        Stored because the worker outlives the association.
        """
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "INSERT INTO move_jobs"
                " (study_uid, move_dest_ae, target_host, target_port,"
                "  status, created_at, updated_at, expose_rejected)"
                " VALUES (?, ?, ?, ?, 'pending', ?, ?, ?)",
                (
                    study_uid,
                    move_dest_ae,
                    target_host,
                    target_port,
                    now,
                    now,
                    1 if expose_rejected else 0,
                ),
            )
            conn.commit()
            with self._cond:
                self._cond.notify()  # wake one waiting worker
            return cur.lastrowid

    def count_pending(self):
        """Number of jobs in the 'pending' state (drain gauge).

        Read-only and cheap (one indexed COUNT); never raises, so a metrics
        scrape cannot be broken by a busy/locked database - returns 0 instead.
        """
        try:
            with self._db.locked() as conn:
                row = conn.execute(
                    "SELECT COUNT(*) FROM move_jobs WHERE status = 'pending'"
                ).fetchone()
            return int(row[0]) if row else 0
        except Exception:
            return 0

    def pick_pending_job(self, timeout=5.0):
        """Atomically pick one pending job.

        Returns dict or None.
        """
        while True:
            with self._db.locked() as conn:
                rows = conn.execute(
                    "SELECT id, study_uid, move_dest_ae, attempts,"
                    " target_host, target_port"
                    " FROM move_jobs WHERE status = 'pending'"
                    " ORDER BY created_at ASC"
                ).fetchall()

            if len(rows) == 0:
                with self._cond:
                    notified = self._cond.wait(timeout=timeout)
                if not notified:
                    return None
                continue

            row = rows[0]
            job_id = row[0]
            now = int(time.time())
            with self._db.locked() as conn:
                row2 = conn.execute(
                    "SELECT id, study_uid, move_dest_ae, attempts,"
                    " target_host, target_port, expose_rejected"
                    " FROM move_jobs WHERE status = 'pending' AND id = ?",
                    (job_id,),
                ).fetchone()
                if not row2:
                    continue  # Another worker claimed it

                conn.execute(
                    "UPDATE move_jobs SET status = 'in_progress',"
                    " updated_at = ?, attempts = attempts + 1"
                    " WHERE id = ?",
                    (now, job_id),
                )
                conn.commit()
                return {
                    "id": job_id,
                    "study_uid": row2[1],
                    "move_dest_ae": row2[2],
                    "attempts": row2[3],
                    "target_host": row2[4],
                    "target_port": row2[5],
                    # The worker outlives the association that queued the job,
                    # so which base URL to stream from has to come from the
                    # row. Omitting it here silently sent every QA job to
                    # clarus_url, i.e. the sequester was never lifted.
                    "expose_rejected": int(row2[6] or 0),
                }

    def update_job_progress(self, job_id, completed, failed, total):
        """Update job progress counters (CM-005)."""
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET completed_instances = ?,"
                " failed_instances = ?, total_instances = ?,"
                " updated_at = ? WHERE id = ?",
                (completed, failed, total, now, job_id),
            )
            conn.commit()

    def get_job_progress(self, job_id):
        """Return (completed, total, status) for a job. Used by C-MOVE generator for 0xFF00 polling."""
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT completed_instances, total_instances, status"
                " FROM move_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                return (0, 0, "unknown")
            return (row[0], row[1], row[2])

    def set_job_failed_sops(self, job_id, uids):
        """Record the (0008,0058) Failed SOP Instance UID List for a job.

        newline-joined UIDs of the slices that were attempted but not
        delivered. Read back by the C-MOVE generator so the final
        Failed/Cancel/Warning C-MOVE-RSP Identifier carries the list
        (PS3.4 C.4.2.1.4.2). Call once at job end.
        """
        text = "\n".join(u for u in (uids or []) if u)
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET failed_sops = ?, updated_at = ? WHERE id = ?",
                (text, now, job_id),
            )
            conn.commit()

    def get_job_failed_sops(self, job_id):
        """Return the (0008,0058) Failed SOP Instance UID list for a job."""
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT failed_sops FROM move_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
        if not row or not row[0]:
            return []
        return [u for u in str(row[0]).split("\n") if u]

    def finish_job(self, job_id, success=True, error_message=None):
        """Mark job as success or failed. A terminal row is never rewritten.

        Two wakers can finish the same job - the poll reactor on timeout and
        the worker when it reaches the end of the instance list - and the last
        writer would otherwise decide the outcome. A row that already says
        `failed` must not turn into `success` (or the reverse), because the
        viewer was already told the first verdict and the counter was already
        incremented for it.

        Returns True when THIS call moved the row to a terminal status, False
        when another waker had already finished it. The caller must use that
        answer before counting the outcome: a second waker that counts its own
        call double-counts a job that only finished once.
        """
        status = "success" if success else "failed"
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "UPDATE move_jobs SET status = ?, error_message = ?,"
                " updated_at = ? WHERE id = ?"
                " AND status NOT IN ('success', 'failed')",
                (status, error_message or "", now, job_id),
            )
            conn.commit()
            return cur.rowcount > 0

    def reset_job_to_pending(self, job_id, reason=""):
        """Reset an in_progress job back to pending (viewer busy, retry later)."""
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET status = 'pending', error_message = ?,"
                " updated_at = ? WHERE id = ?",
                (reason, now, job_id),
            )
            conn.commit()
        with self._cond:
            self._cond.notify()  # Wake a worker to process the reset job (after fail_timeout)

    def recover_in_progress_jobs(self):
        """On startup: reset all in_progress jobs to pending (CM-007)."""
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "UPDATE move_jobs SET status = 'pending', updated_at = ?"
                " WHERE status = 'in_progress'",
                (now,),
            )
            conn.commit()
            return cur.rowcount

    def cleanup_old_jobs(self, max_age_seconds=86400):
        """Remove success/failed jobs older than max_age_seconds (default 24h) (CM-008)."""
        with self._db.locked() as conn:
            cutoff = int(time.time()) - max_age_seconds
            conn.execute(
                "DELETE FROM move_jobs WHERE status IN ('success', 'failed')"
                " AND updated_at < ?",
                (cutoff,),
            )
            conn.commit()

    # --- scp_targets CRUD ---

    def register_peer(self, ae_title, host, port=104):
        """Register or update a manually configured peer from peers.conf.

        Composite key (ae_title, host)  -  supports multiple entries per AE
        (exact IP + CIDR subnet, or multiple subnets).
        Non-CIDR (exact IP) entries: only ONE per AE title  -  re-registration
        with a different host replaces the old one. CIDR entries coexist.
        """
        now = int(time.time())
        with self._db.locked() as conn:
            # Non-CIDR host: delete any existing non-CIDR entry for this AE
            # so re-registration with a different IP replaces the old one.
            if "/" not in host:
                conn.execute(
                    "DELETE FROM scp_targets"
                    " WHERE ae_title = ? AND host NOT LIKE '%/%'",
                    (ae_title,),
                )
            conn.execute(
                "INSERT OR REPLACE INTO scp_targets"
                " (ae_title, host, port, last_seen, consecutive_failures)"
                " VALUES (?, ?, ?, ?, 0)",
                (ae_title, host, port, now),
            )
            conn.commit()
        logging.info(
            "[PEER] Registered %s at %s:%d",
            ae_title,
            host,
            port,
        )

    # --- SCP peer lookup with subnet support --------------------

    def lookup_scp(self, ae_title, client_ip=None):
        """Look up SCP peer by AE Title, with optional IP subnet matching.

        Args:
            ae_title: Move Destination AE Title.
            client_ip: IP address of the requesting SCU (for subnet matching).
                If None, returns first exact-match (non-CIDR) entry.

        Returns:
            (host, port) tuple or None.

        Subnet matching (CIDR):
            peers.conf supports: WEASIS_AE  192.168.1.0/24  11113
            When client_ip falls within the subnet, returns the CIDR host
            (e.g. "192.168.1.0/24") and port. Caller uses the PORT for
            association; the HOST is informational (routed via client_ip).
        """
        with self._db.locked() as conn:
            rows = conn.execute(
                "SELECT host, port FROM scp_targets WHERE ae_title = ?",
                (ae_title,),
            ).fetchall()

        if not rows:
            return None

        if client_ip is None:
            # No IP  -  return first exact (non-CIDR) match, else first entry
            for host, port in rows:
                if "/" not in host:
                    return (host, port)
            return (rows[0][0], rows[0][1])

        # IP provided  -  match against subnets
        try:
            client = ipaddress.ip_address(client_ip)
        except ValueError:
            # Invalid IP string  -  fall back to exact match
            for host, port in rows:
                if "/" not in host:
                    return (host, port)
            return None

        # Priority 1: exact IP match (non-CIDR)
        for host, port in rows:
            if "/" not in host and host == client_ip:
                return (host, port)

        # Priority 2: CIDR subnet match
        for host, port in rows:
            if "/" in host:
                try:
                    network = ipaddress.ip_network(host, strict=False)
                    if client in network:
                        return (host, port)
                except ValueError:
                    continue

        return None

    def reload_peers_from_file(self, peers_file):
        """Reload peers from peers.conf into scp_targets table.

        Respects lazyload_peers_interval. Composite key (ae_title, host)
         -  multiple entries per AE (CIDR + exact) are preserved.
        """
        if self.lazyload_peers_interval > 0:
            elapsed = time.time() - self._last_peers_reload
            if elapsed < self.lazyload_peers_interval:
                return 0

        self._last_peers_reload = time.time()
        new_count = 0
        seen = set()
        with self._db.locked() as conn:
            for ae_title, host, port in parse_peers_conf(peers_file):
                seen.add((ae_title, host))
                row = conn.execute(
                    "SELECT host, port FROM scp_targets"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                ).fetchone()
                existing = (row[0], row[1]) if row else None
                if existing is None or existing != (host, port):
                    now = int(time.time())
                    conn.execute(
                        "INSERT OR REPLACE INTO scp_targets"
                        " (ae_title, host, port, last_seen, consecutive_failures)"
                        " VALUES (?, ?, ?, ?, 0)",
                        (ae_title, host, port, now),
                    )
                    new_count += 1
            # A peer removed from peers.conf is gone from the operator's view,
            # so routing to the stale row was a destination the config no
            # longer names. Deleting by (ae_title, host) keeps a peer that is
            # still listed under a different port.
            stale = [
                (ae, host)
                for ae, host in conn.execute("SELECT ae_title, host FROM scp_targets")
                if (ae, host) not in seen
            ]
            for ae, host in stale:
                conn.execute(
                    "DELETE FROM scp_targets WHERE ae_title = ? AND host = ?",
                    (ae, host),
                )
            if stale:
                logging.info(
                    "[PEER] Removed %d peer(s) no longer in %s",
                    len(stale),
                    peers_file,
                )
            conn.commit()
        if new_count:
            logging.info(
                "[PEER] Reloaded %d new/updated peer(s) from %s", new_count, peers_file
            )
        return new_count

    # --- scp failure tracking ---

    def record_scp_failure(self, ae_title, host=None):
        """Record a failure to reach SCP.

        Auto-remove after 3 consecutive failures (CM-006).
        If host is provided, only updates that specific entry (subnet-safe).
        """
        with self._db.locked() as conn:
            if host:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures ="
                    " consecutive_failures + 1"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                )
                row = conn.execute(
                    "SELECT consecutive_failures FROM scp_targets"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                ).fetchone()
                if row and row[0] >= self.scp_remove_failures:
                    conn.execute(
                        "DELETE FROM scp_targets" " WHERE ae_title = ? AND host = ?",
                        (ae_title, host),
                    )
                    logging.warning(
                        "[SCP] Removed %s@%s after %d consecutive failures",
                        ae_title,
                        host,
                        self.scp_remove_failures,
                    )
            else:
                # Backward compat: update all entries for this AE
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures ="
                    " consecutive_failures + 1 WHERE ae_title = ?",
                    (ae_title,),
                )
                # Check and auto-remove entries with >= N failures
                conn.execute(
                    "DELETE FROM scp_targets"
                    " WHERE ae_title = ? AND consecutive_failures >= ?",
                    (ae_title, self.scp_remove_failures),
                )
            conn.commit()

    def record_scp_success(self, ae_title, host=None):
        """Reset failure counter on successful connection (CM-006).
        If host is provided, only resets that specific entry (subnet-safe).
        """
        with self._db.locked() as conn:
            if host:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures = 0"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                )
            else:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures = 0"
                    " WHERE ae_title = ?",
                    (ae_title,),
                )
            conn.commit()

    def close(self):
        """no-op  -  SharedDb owns the connection, closed in main()."""

    # --- C-MOVE-CANCEL support ---

    def set_job_cancel_callback(self, job_id, callback):
        """Store cancel callback for a job (BR-012)."""
        self._cancel_callbacks[job_id] = callback

    def is_job_cancelled(self, job_id):
        """Check if job was cancelled by SCU (BR-012)."""
        cb = self._cancel_callbacks.get(job_id)
        if cb:
            try:
                return cb()
            except Exception:
                return False
        return False

    def clear_job_callback(self, job_id):
        """Remove cancel callback after job completes (BR-012)."""
        self._cancel_callbacks.pop(job_id, None)

# ---------------------------------------------------------------------------
# Bridge: assoc_tracker
# ---------------------------------------------------------------------------

"""DIMSE Association Tracker  -  nginx-way.

Tracks active DICOM associations: AE title, IP, studies received, instance counts.
Used by C-STORE handler and association event handlers to provide
administrator-visible INFO logs without per-SOP spam.

Thread-safe via threading.Lock. Cleanup on association release.
"""

import logging
import threading

# -- Association info ----------------------------------------------------

class AssocInfo:
    """Per-association tracking state."""

    __slots__ = ("address", "ae_title", "instance_count", "studies")

    def __init__(self, ae_title: str, address: str):
        self.ae_title = ae_title
        self.address = address
        # studies: dict[study_uid -> {'patient_id': str, 'modality': str, 'count': int}]
        self.studies: dict[str, dict] = {}
        self.instance_count = 0

# Global registry: association_id -> AssocInfo
_assoc_registry: dict[int, AssocInfo] = {}
_assoc_lock = threading.Lock()

# -- Public API ----------------------------------------------------------

def register_assoc_accepted(assoc_id: int, ae_title: str, address: str) -> None:
    """Register a new DICOM association. Logs INFO on first connection.

    Called from evt.EVT_ACCEPTED handler.
    """
    with _assoc_lock:
        if assoc_id in _assoc_registry:
            return  # Already registered (should not happen)
        _assoc_registry[assoc_id] = AssocInfo(ae_title, address)

    # Counter is bumped outside the lock: prometheus_client objects are
    # already thread-safe and this is not on the C-STORE hot path.
    try:
        associations_total.labels(role="from", ae=ae_label(ae_title)).inc()
    except Exception:
        pass

    # : log outside lock to avoid holding it during I/O.
    # Mask AE title if it looks like a hostname (long, noisy).
    ae_display = ae_title if len(ae_title) <= 16 else ae_title[:16]
    logging.info(
        "[DIMSE] Association accepted: AE=%s from %s",
        ae_display,
        address,
    )

def register_assoc_released(assoc_id: int) -> None:
    """Release association and log summary.

    Called from evt.EVT_RELEASED or evt.EVT_ABORTED handler.
    """
    with _assoc_lock:
        info = _assoc_registry.pop(assoc_id, None)

    if info is None:
        return

    studies_count = len(info.studies)
    instances = info.instance_count
    ae = info.ae_title[:16] if len(info.ae_title) > 16 else info.ae_title

    if studies_count == 0:
        # NOTE: fires for EVERY association, including C-MOVE/C-FIND ones
        # that never carry C-STORE. "(no instances received)" is accurate
        # for all operation types (field: "no C-STORE received" read like
        # the bridge expected a C-STORE on a C-MOVE association).
        logging.info(
            "[DIMSE] Association released: AE=%s (no instances received)",
            ae,
        )
        return

    # Build study summary: "CTx432, SRx2" (ASCII only  -  cp1251-safe)
    study_parts = []
    for study_uid, sinfo in info.studies.items():
        mod = sinfo.get("modality", "??")
        cnt = sinfo.get("count", 0)
        study_parts.append(f"{mod}x{cnt}")

    logging.info(
        "[DIMSE] Association released: AE=%s studies=%d instances=%d [%s]",
        ae,
        studies_count,
        instances,
        ", ".join(study_parts),
    )

def record_cstore(
    assoc_id: int, study_uid: str, patient_id: str, modality: str
) -> bool:
    """Record a C-STORE instance in the association tracker.

    Returns True if this is the FIRST instance for this study_uid
    (caller should log INFO about new study).
    """
    if not study_uid:
        return False

    with _assoc_lock:
        info = _assoc_registry.get(assoc_id)
        if info is None:
            return False  # Association not tracked (should not happen)

        info.instance_count += 1

        if study_uid not in info.studies:
            info.studies[study_uid] = {
                "patient_id": patient_id or "?",
                "modality": modality or "??",
                "count": 1,
            }
            return True  # First instance of this study
        else:
            info.studies[study_uid]["count"] += 1
            return False  # Already tracking this study

# ---------------------------------------------------------------------------
# Bridge: commit_tracker
# ---------------------------------------------------------------------------

"""CommitTracker - async Storage Commitment resolution (N-EVENT-REPORT, Stage 2).

nginx-way: N-ACTION is fire-and-forget. A background worker resolves each
commitment batch once ALL referenced SOPs are stored OR the hard deadline
(default 300s) passes; unconfirmed SOPs at deadline are reported as failures
(EventTypeID=2) so the modality keeps its local copy.

Backpressure is structural (single worker, fire-and-forget dispatch inside the
DIMSE reactor) - no cap / 0xA700 is introduced.

Decoupled via three injected callables so this module is unit-testable without
  a live DICOM/HTTP environment:
  verify(sop_class, sop_uid) -> bool    stored/confirmed?
  report(host, port, ae, tx_uid, event_type, ok, failed)
  resolve(job) -> None                  how the batch becomes a verdict

The third is what the 2409 migration adds. It defaults to the local
heuristic this module has always used (unconfirmed SOPs -> 0x0110), so the
default is byte-for-byte today's behaviour; true-mode supplies a callable
that asks the ORIGIN once and reports the origin's own verdict verbatim.
"""

import json
import logging
import threading
import time

DEFAULT_DEADLINE_SEC = 300.0
DEFAULT_RESOLVE_INTERVAL = 5.0

# Failure Reason (0008,1197) for an SOP never confirmed by the deadline:
# 0110H Processing Failure (PS3.3 C.14.1.1). 0111H is not an enumerated
# Failure Reason - it exists only as an N-CREATE status in PS3.7.
REASON_UNCONFIRMED = 0x0110

def _pair(item):
    """One `(sop_class, sop_uid)` tuple from a persisted JSON pair.

    A tuple, not a list: `pending` is a SET of these, so the elements have to
    be hashable, and the comparison against `job.sops` (built from tuples)
    would otherwise never match.
    """
    sop_class, sop_uid = item
    return (sop_class, sop_uid)

class CommitJob:
    """One N-ACTION Storage Commitment batch awaiting resolution."""

    __slots__ = (
        "calling_ae",
        "deadline",
        "host",
        "pending",
        "pending_persisted",
        "port",
        "sops",
        "tx_uid",
    )

    def __init__(self, tx_uid, calling_ae, host, port, sops, deadline):
        self.tx_uid = tx_uid
        self.calling_ae = calling_ae
        self.host = host
        self.port = port
        self.sops = list(sops)  # [(sop_class, sop_uid), ...]
        self.pending = set(sops)  # not-yet-confirmed (cls, uid)
        self.deadline = deadline
        # Size of `pending` as last written to the store. Starts equal to the
        # live set so a freshly registered batch is not rewritten on the first
        # tick for no reason.
        self.pending_persisted = len(self.pending)

class CommitTracker:
    """Tracks commitment batches; resolves and reports them asynchronously.

    Persistence (M7): a batch registered by an N-ACTION is a promise to the
    modality that an N-EVENT-REPORT will follow, and PS3.4 J.3.3.1 makes that
    report the result. Holding the promise only in `_jobs` meant a restart
    lost every outstanding batch: the transaction UID stayed active on the
    modality's side forever and the commitment never resolved. The jobs are
    therefore mirrored into a SQLite table, the same store the C-MOVE state
    machine already uses (`move_jobs.db`, via `SharedDb.locked()`), and a
    tracker constructed with a `db` reloads the pending rows before its loop
    starts.

    The dict stays the working set: it is what `_tick` iterates and what the
    tests inspect, and a row only exists to survive a process restart.
    """

    def __init__(
        self,
        verify,
        report,
        resolve=None,
        interval=DEFAULT_RESOLVE_INTERVAL,
        deadline_sec=DEFAULT_DEADLINE_SEC,
        shutdown=None,
        now=time.time,
        db=None,
    ):
        self._verify = verify  # verify(sop_class, sop_uid) -> bool
        self._report = report  # report(...)
        # resolve(job) -> None; None keeps the local heuristic below. The
        # callable owns sending the N-EVENT-REPORT for its batch.
        self._resolve_fn = resolve
        self._interval = interval
        self._deadline_sec = deadline_sec
        self._jobs = {}
        self._lock = threading.Lock()
        self._stop = shutdown if shutdown is not None else threading.Event()
        self._now = now  # injectable clock for tests
        self._db = db
        if db is not None:
            self._create_schema()
            self._reload()

    # ---- persistence -----------------------------------------------------

    def _create_schema(self):
        """Create the batch table.

        `pending` is stored as JSON rather than as a second table: the column
        is read and written whole, never queried by SOP, and a normalised
        table would add a join and a row-set to keep consistent for no
        question anyone asks. `sops` is stored whole too - the report needs
        the COMPLETE referenced set (J.3.3.1.2), so a batch is never resolved
        from a partial list.
        """
        with self._db.locked() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS commit_jobs ("
                "  tx_uid TEXT PRIMARY KEY,"
                "  calling_ae TEXT NOT NULL,"
                "  host TEXT NOT NULL,"
                "  port INTEGER NOT NULL,"
                "  sops TEXT NOT NULL,"  # JSON [[cls, uid], ...]
                "  pending TEXT NOT NULL,"  # JSON [[cls, uid], ...]
                "  deadline REAL NOT NULL"
                ")"
            )
            conn.commit()

    def _reload(self):
        """Restore the pending batches left by a previous process.

        Rows are restored verbatim, INCLUDING their original deadline: a
        batch whose deadline passed while the bridge was down is resolved on
        the first tick, which is the correct answer - the modality is still
        waiting, and "everything unconfirmed by then" is what the deadline
        means. Rewriting the deadline on reload would extend a promise the
        SCP already made.
        """
        restored = 0
        with self._db.locked() as conn:
            rows = conn.execute(
                "SELECT tx_uid, calling_ae, host, port, sops, pending, deadline"
                " FROM commit_jobs"
            ).fetchall()
        for tx_uid, calling_ae, host, port, sops, pending, deadline in rows:
            try:
                sop_pairs = [_pair(item) for item in json.loads(sops)]
                pending_pairs = {_pair(item) for item in json.loads(pending)}
                job = CommitJob(
                    tx_uid,
                    calling_ae,
                    host,
                    int(port),
                    sop_pairs,
                    float(deadline),
                )
                job.pending = pending_pairs
                job.pending_persisted = len(pending_pairs)
            except (ValueError, TypeError) as e:
                # A row that cannot be read is not a reason to refuse the
                # whole reload: the other batches are still deliverable, and
                # this one is named in the log rather than silently dropped.
                logging.error(
                    "[COMMIT] tx=%s: unreadable persisted batch (%s) - skipped",
                    tx_uid,
                    e,
                )
                continue
            self._jobs[tx_uid] = job
            restored += 1
        if restored:
            logging.warning(
                "[COMMIT] recovered %d outstanding batch(es) from the previous "
                "session; the modality is still waiting for their verdicts",
                restored,
            )

    def _persist(self, job):
        if self._db is None:
            return
        with self._db.locked() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO commit_jobs"
                " (tx_uid, calling_ae, host, port, sops, pending, deadline)"
                " VALUES (?, ?, ?, ?, ?, ?, ?)",
                (
                    job.tx_uid,
                    job.calling_ae,
                    job.host,
                    int(job.port),
                    json.dumps([list(item) for item in job.sops]),
                    json.dumps(sorted(list(item) for item in job.pending)),
                    float(job.deadline),
                ),
            )
            conn.commit()

    def _forget(self, tx_uid):
        if self._db is None:
            return
        with self._db.locked() as conn:
            conn.execute("DELETE FROM commit_jobs WHERE tx_uid = ?", (tx_uid,))
            conn.commit()

    def register(self, tx_uid, calling_ae, host, port, sops):
        """Register an N-ACTION batch for async resolution. Fire-and-forget."""
        deadline = self._now() + self._deadline_sec
        job = CommitJob(tx_uid, calling_ae, host, port, sops, deadline)
        with self._lock:
            self._jobs[tx_uid] = job
        self._persist(job)

    # ---- resolution ------------------------------------------------------

    def _resolve(self, job):
        """Send one N-EVENT-REPORT for the batch.

        The mode branch is here, at the single point where a batch becomes a
        verdict: a supplied `resolve` callable owns the whole resolution
        (true-mode asks the origin and reports its answer), and the default
        is the local heuristic that has always run.

        Returns True when the verdict was delivered. A failed delivery must NOT
        retire the job: the modality was never told the outcome, so discarding
        it lost the commitment silently (PS3.4 J.3.3.1 - the N-EVENT-REPORT IS
        the result).
        """
        if self._resolve_fn is not None:
            try:
                self._resolve_fn(job)
                return True
            except Exception as e:
                logging.error("[COMMIT] resolve for tx=%s failed: %s", job.tx_uid, e)
                return False

        ok = []
        failed = []
        for sop_class, sop_uid in job.sops:
            if (sop_class, sop_uid) in job.pending:
                failed.append((sop_class, sop_uid, REASON_UNCONFIRMED))
            else:
                ok.append((sop_class, sop_uid))
        event_type = 1 if not failed else 2  # success / complete-with-failures
        # The verdict counters belong here, not in the handler: this is where
        # a SOP actually acquires a verdict. The handler answers 0x0000
        # without checking anything (PS3.4 J.3.2), so counting there would
        # report a verdict the bridge had no evidence for at that instant.
        try:
            if ok:
                naction_total.labels(verdict="success").inc(len(ok))
            if failed:
                naction_total.labels(verdict="failed").inc(len(failed))
        except Exception:
            pass
        try:
            delivered = self._report(
                job.host, job.port, job.calling_ae, job.tx_uid, event_type, ok, failed
            )
        except Exception as e:
            logging.error("[COMMIT] report for tx=%s failed: %s", job.tx_uid, e)
            return False
        return delivered is not False

    def _tick(self):
        with self._lock:
            jobs = list(self._jobs.values())
        now = self._now()
        for job in jobs:
            for sop_item in list(job.pending):
                sop_class, sop_uid = sop_item
                try:
                    if self._verify(sop_class, sop_uid):
                        job.pending.discard(sop_item)
                except Exception as e:
                    logging.warning("[COMMIT] verify %s error: %s", sop_uid, e)
            if not job.pending or now >= job.deadline:
                # Retire the job only once its verdict was actually delivered:
                # dropping it after a failed N-EVENT-REPORT lost the outcome
                # the modality was waiting for.
                if self._resolve(job):
                    with self._lock:
                        self._jobs.pop(job.tx_uid, None)
                    # Drop the row only after the verdict left the process:
                    # a row deleted before the report would lose the batch on
                    # a crash between the two, which is the failure this
                    # persistence exists to prevent.
                    self._forget(job.tx_uid)
                else:
                    logging.warning(
                        "[COMMIT] tx=%s kept for another attempt: the verdict "
                        "was not delivered",
                        job.tx_uid,
                    )
            elif self._db is not None:
                # Confirmations shrink `job.pending` and that set is what a
                # restart reads back. Rewriting the row on EVERY tick would put
                # a commit on the tracker's own timer for a batch that may sit
                # for the full deadline; the row is written when the set
                # actually shrank, which is the only state change here that a
                # restart can observe.
                if len(job.pending) != job.pending_persisted:
                    job.pending_persisted = len(job.pending)
                    self._persist(job)

    # ---- lifecycle -------------------------------------------------------

    def run(self):
        """Background loop; resolve batches on an interval. Blocks until close."""
        while not self._stop.is_set():
            try:
                self._tick()
            except Exception as e:
                logging.error("[COMMIT] tick error: %s", e)
            self._stop.wait(self._interval)

    def pending_count(self):
        with self._lock:
            return len(self._jobs)

    def close(self):
        self._stop.set()

# ---------------------------------------------------------------------------
# Bridge: http_helpers
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  HTTP helpers: retry, QIDO/WADO/STOW requests (BR-005).

Contains _http_retry (exponential backoff + jitter),
_qido_request, _wado_metadata_request, stow_single_instance, and
_http_status_to_dimse (BR-011).

Auth is handled by nginx reverse proxy  -  no Basic Auth in application code.
"""

import io
import json
import logging
import time
import uuid
from urllib.parse import urlsplit, urlunsplit

import httpx
from pydicom import dcmwrite
from pydicom.uid import ExplicitVRLittleEndian

# ---------------------------------------------------------------------------
# 2908: single source of the DICOMweb base URL (clarus_url refactor)
# ---------------------------------------------------------------------------
RETRY_AFTER_MIN_SEC = 5
RETRY_AFTER_MAX_SEC = 300
RETRY_AFTER_DEFAULT_SEC = 30

def dicomweb_base(clarus_url):
    """Return the normalized DICOMweb base URL (no trailing slash).

    Single source for EVERY DICOMweb URL the bridge builds. Config
    validation (clean_code.config.validate_clarus_url) already rejects
    bad schemes and strips the trailing slash; this re-strips for
    defense in depth.
    """
    return clarus_url.rstrip("/")

def dicomweb_origin(clarus_url):
    """Return scheme://netloc of clarus_url (health probe lives at root)."""
    parts = urlsplit(clarus_url)
    return urlunsplit((parts.scheme, parts.netloc, "", "", ""))

def service_base_url(clarus_url, qa_url, qa_view):
    """Pick the DICOMweb base URL for this request.

    `qa_view` is true for associations accepted by the QA AE. AIRA 57.2.1
    defines the expose mechanism as "a webservice endpoint specifically
    configured to provide access to hidden instances", i.e. a separate base
    URL the deployment chooses - NOT a query parameter. Selecting the base URL
    keeps the bridge usable against any DICOMweb server: a server that
    publishes a QA endpoint works, and one that would need a vendor-specific
    parameter is simply pointed at its own endpoint instead.

    Falls back to `clarus_url` when no QA endpoint is configured, so a bridge
    with `expose_port` set but no `qa_url` never silently queries an empty
    base - the caller has already refused to start the QA AE in that case.
    """
    if qa_view and qa_url:
        return dicomweb_base(qa_url)
    return dicomweb_base(clarus_url)

def retry_after_seconds(headers, default=RETRY_AFTER_DEFAULT_SEC):
    """Parse the Retry-After header (seconds or HTTP-date), clamp to [5, 300].

    Garbage / absent header -> fixed 30 s default. HTTP-date values are
    treated conservatively as the default (no clock math in the bridge).
    """
    try:
        value = int(str(headers.get("Retry-After", "")).strip())
    except (ValueError, TypeError, AttributeError):
        return default
    return max(RETRY_AFTER_MIN_SEC, min(RETRY_AFTER_MAX_SEC, value))

# ---------------------------------------------------------------------------
# Bridge: simple retry with fixed backoff (like Orthanc)
# ---------------------------------------------------------------------------
def _http_retry(request_func, max_retries=3, delay=2.0):
    """Execute HTTP request with fixed backoff  -  3 attempts, 2s delay.

    Retry on: 429, 5xx, timeouts, connection errors.
    No retry on: 4xx except 429 (client errors are permanent).

    Returns httpx.Response, including the final 5xx; raises the last
    transport exception (timeout / connection error).
    """
    last_exception = None

    for attempt in range(max_retries + 1):
        try:
            resp = request_func()
            if resp.status_code == 429:
                if attempt < max_retries:
                    stow_retries.inc()
                    time.sleep(delay)
                    continue
                return resp
            if resp.status_code == 507:
                # 507 Insufficient Storage: NO retry inside _http_retry.
                # Return immediately; the outbox worker applies Retry-After
                # backpressure (clamped 5..300 s) and keeps files pending.
                return resp
            if 400 <= resp.status_code < 500:
                return resp
            if resp.status_code < 500:
                return resp
            logging.warning(
                "[RETRY] HTTP %d on attempt %d/%d",
                resp.status_code,
                attempt + 1,
                max_retries + 1,
            )
            # Final 5xx: return the response so the caller's
            # raise_for_status() / _http_status_to_dimse maps it (5xx ->
            # 0xA700 transient), not a bare Exception that escapes C-FIND
            # generators and mis-maps to fatal.
            if attempt == max_retries:
                return resp
        except (httpx.TimeoutException, httpx.ConnectError) as e:
            logging.warning(
                "[RETRY] %s on attempt %d/%d: %s",
                type(e).__name__,
                attempt + 1,
                max_retries + 1,
                e,
            )
            last_exception = e
        except httpx.TransportError as e:
            # Every other transport failure - a reset mid-response, a read
            # timeout, a truncated body - is equally transient and equally
            # retryable. Letting those escape aborted the batch on the first
            # hiccup while the two named subclasses were retried.
            logging.warning(
                "[RETRY] transport %s on attempt %d/%d: %s",
                type(e).__name__,
                attempt + 1,
                max_retries + 1,
                e,
            )
            last_exception = e

        if attempt < max_retries:
            stow_retries.inc()
            time.sleep(delay)

    raise last_exception or Exception("Max retries exceeded")

# ---------------------------------------------------------------------------
# Bridge: QIDO-RS with retry
# ---------------------------------------------------------------------------
def _qido_request(url, params, http_timeout=30, limit=None, offset=0, tls=None):
    """QIDO-RS GET with retry wrapper. Auth by nginx.

    Args:
        limit: if set, adds ?limit=N&offset=M to request (server-side pagination).
        offset: pagination offset, only used when limit is set.
        tls: optional (cert_path, key_path) tuple for mTLS. verify always on.

    The QA view is chosen by the CALLER through the base URL (see
    `qa_base_url`), not by a query parameter: the bridge is a universal
    DICOMweb client, so it must not depend on any one server's private
    parameter for this.
    """
    if limit is not None:
        params = dict(params)
        params["limit"] = str(limit)
        params["offset"] = str(offset)

    def _do_qido():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.get(
                url,
                params=params,
                headers={"Accept": "application/dicom+json"},
            )
        finally:
            client.close()

    resp = _http_retry(_do_qido)
    resp.raise_for_status()
    # PS3.18 10.6: a search with no matches may answer 204 No Content, which
    # carries no body at all. `json()` on it raises ValueError, and the C-FIND
    # callers only catch httpx errors - a no-match search would surface as a
    # tooling failure instead of an empty result set. The same applies to an
    # intermediary that answers 200 with an empty or non-JSON body.
    if resp.status_code == 204 or not resp.content:
        return []
    try:
        body = resp.json()
    except ValueError:
        logging.warning(
            "[QIDO] %s answered 200 with a body that is not JSON "
            "(%d bytes); treating it as no matches",
            url,
            len(resp.content),
        )
        return []
    return body if isinstance(body, list) else []

# ---------------------------------------------------------------------------
# Bridge: WADO-RS metadata lookup with retry
# ---------------------------------------------------------------------------
def _wado_metadata_request(url, http_timeout=30, tls=None):
    """WADO-RS metadata GET with retry wrapper. Auth by nginx."""

    def _do_wado():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.get(
                url,
                headers={"Accept": "application/dicom+json"},
            )
        finally:
            client.close()

    return _http_retry(_do_wado)

# ---------------------------------------------------------------------------
# 2409: Storage Commitment (PS3.18 13.4/13.5) - POST commit, GET check
# ---------------------------------------------------------------------------
# DICOM JSON keys (Annex J.2), the same ones the server's commitment_pure
# module defines. Only the INSTANCE form of the Referenced SOP Sequence is
# used here: the bridge always has SOP Instance UIDs to commit.
_STC_REFERENCED_SOP_SEQUENCE = "00081199"
_STC_FAILED_SOP_SEQUENCE = "00081198"
_STC_FAILURE_REASON = "00081197"
_STC_REFERENCED_SOP_CLASS_UID = "00081150"
_STC_REFERENCED_SOP_INSTANCE_UID = "00081155"

# The only FailureReason values PS3.3 C.14.1.1 enumerates for the attribute.
# The server emits a subset of these; the table is total so a future server-
# side addition can never push a non-enumerated code onto the DIMSE wire.
_STC_NO_SUCH_SOP = 0x0112
_STC_PROCESSING_FAILURE = 0x0110
_STC_RESOURCE_LIMITATION = 0x0213

_STC_REASON_MAP = {
    "0110": _STC_PROCESSING_FAILURE,
    "0112": _STC_NO_SUCH_SOP,
    "0213": _STC_RESOURCE_LIMITATION,
}

# Sentinel on the return value for "the origin has no Commit resource".
# The caller logs the misconfiguration WARN; there is deliberately NO
# fallback to the local path (a silent fallback would mask the wrong knob
# forever).
STC_NO_RESOURCE = "no_commit_resource"

def _stc_commit_request(clarus_url, tx_uid, sop_list, http_timeout=30, tls=None):
    """POST one Storage Commitment request and map the verdict.

    Returns ``(committed, failed, sentinel)``:

      committed: [(sop_class, sop_uid)]            - the origin committed these
      failed:    [(sop_class, sop_uid, reason_int)] - enumerated C.14.1.1 codes
      sentinel:  None, or STC_NO_RESOURCE when the origin answered 404/405

    409 (duplicate Transaction UID) replays the stored verdict through ONE
    GET of the same path. Every other non-200 outcome maps to "all failed
    0x0110" - the bridge reports what it knows, it never guesses.

    ``sop_list`` is [(sop_class_uid, sop_instance_uid), ...]; the body is the
    INSTANCE form of the Referenced SOP Sequence (commitment_pure.py).
    """
    base = dicomweb_base(clarus_url)
    url = f"{base}/commitment-requests/{tx_uid}"

    items = []
    for sop_class, sop_uid in sop_list:
        items.append(
            {
                _STC_REFERENCED_SOP_CLASS_UID: {"vr": "UI", "Value": [sop_class]},
                _STC_REFERENCED_SOP_INSTANCE_UID: {"vr": "UI", "Value": [sop_uid]},
            }
        )
    body = {_STC_REFERENCED_SOP_SEQUENCE: {"vr": "SQ", "Value": items}}

    def _do_commit():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.post(
                url,
                json=body,
                headers={
                    "Accept": "application/dicom+json",
                    "Content-Type": "application/dicom+json",
                },
            )
        finally:
            client.close()

    try:
        resp = _http_retry(_do_commit)
    except Exception as e:
        # Retry budget spent on a transport failure or a 5xx.
        logging.warning("[STC] commit tx=%s failed: %s", tx_uid, e)
        return [], _all_failed(sop_list), None

    status = resp.status_code

    if status in (404, 405):
        logging.warning(
            "[STC] origin answers %d on commitment-requests; set "
            "storage_commitment_presence=false for this origin",
            status,
        )
        return [], _all_failed(sop_list), STC_NO_RESOURCE

    if status == 409:
        # The Transaction UID was already committed: the verdict is stored,
        # not re-derived. ONE GET, and an idempotent answer is reported.
        return _stc_check_request(clarus_url, tx_uid, sop_list, http_timeout, tls=tls)

    if status != 200:
        logging.warning(
            "[STC] commit tx=%s: HTTP %d -> all failed 0x0110 (%s)",
            tx_uid,
            status,
            resp.text[:200],
        )
        return [], _all_failed(sop_list), None

    try:
        payload = resp.json()
    except Exception as e:
        logging.warning("[STC] commit tx=%s: unparsable body (%s)", tx_uid, e)
        return [], _all_failed(sop_list), None

    return _stc_map_verdict(payload, sop_list, tx_uid)

def _stc_check_request(clarus_url, tx_uid, sop_list, http_timeout=30, tls=None):
    """GET the stored verdict for a Transaction UID (PS3.18 13.5).

    Used for the 409 replay path: the origin already has a verdict for this
    Transaction UID and re-committing must not change it. A 404 (the result
    was swept by retention) is every SOP failed 0x0110.
    """
    base = dicomweb_base(clarus_url)
    url = f"{base}/commitment-requests/{tx_uid}"

    def _do_check():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.get(url, headers={"Accept": "application/dicom+json"})
        finally:
            client.close()

    try:
        resp = _http_retry(_do_check)
    except Exception as e:
        logging.warning("[STC] check tx=%s failed: %s", tx_uid, e)
        return [], _all_failed(sop_list), None

    if resp.status_code in (404, 405):
        logging.warning(
            "[STC] check tx=%s: HTTP %d (result not stored) -> all failed 0x0110",
            tx_uid,
            resp.status_code,
        )
        return [], _all_failed(sop_list), None

    if resp.status_code != 200:
        logging.warning(
            "[STC] check tx=%s: HTTP %d -> all failed 0x0110",
            tx_uid,
            resp.status_code,
        )
        return [], _all_failed(sop_list), None

    try:
        payload = resp.json()
    except Exception as e:
        logging.warning("[STC] check tx=%s: unparsable body (%s)", tx_uid, e)
        return [], _all_failed(sop_list), None

    return _stc_map_verdict(payload, sop_list, tx_uid)

def _all_failed(sop_list):
    """Every SOP failed with the general processing failure code."""
    return [
        (sop_class, sop_uid, _STC_PROCESSING_FAILURE) for sop_class, sop_uid in sop_list
    ]

def _stc_map_verdict(payload, sop_list, tx_uid):
    """Map a Commit/Check 200 body onto (committed, failed, None).

    Committed SOPs come from ReferencedSOPSequence (0008,1199); failed ones
    from FailedSOPSequence (0008,1198) with FailureReason (0008,1197) read as
    a STRING (DICOM JSON renders numeric VRs as strings). A SOP absent from
    BOTH sequences is a protocol defect of the origin and is reported as
    failed 0x0110 - the bridge reports, it does not guess.
    """
    committed = []
    failed = []
    seen = set()

    for item in _stc_sequence_items(payload, _STC_REFERENCED_SOP_SEQUENCE):
        pair = _stc_pair(item)
        if pair is None:
            continue
        seen.add(_stc_key(pair))
        committed.append(pair)

    for item in _stc_sequence_items(payload, _STC_FAILED_SOP_SEQUENCE):
        pair = _stc_pair(item)
        if pair is None:
            continue
        reason = _stc_reason(item)
        seen.add(_stc_key(pair))
        failed.append((pair[0], pair[1], reason))

    for sop_class, sop_uid in sop_list:
        if (str(sop_class), str(sop_uid)) not in seen:
            logging.warning(
                "[STC] tx=%s: SOP %s is in neither response sequence -> 0x0110",
                tx_uid,
                sop_uid,
            )
            failed.append((sop_class, sop_uid, _STC_PROCESSING_FAILURE))

    return committed, failed, None

def _stc_sequence_items(payload, tag):
    """The Value items of one sequence tag, or [] when absent/malformed."""
    if not isinstance(payload, dict):
        return []
    seq = payload.get(tag)
    if not isinstance(seq, dict):
        return []
    items = seq.get("Value")
    if not isinstance(items, list):
        return []
    return [item for item in items if isinstance(item, dict)]

def _stc_pair(item):
    """(sop_class, sop_uid) from one sequence item, or None when incomplete."""
    sop_class = _stc_single(item, _STC_REFERENCED_SOP_CLASS_UID)
    sop_uid = _stc_single(item, _STC_REFERENCED_SOP_INSTANCE_UID)
    if sop_class is None or sop_uid is None:
        return None
    return (sop_class, sop_uid)

def _stc_single(item, tag):
    """One string out of a DICOM JSON element's Value list."""
    element = item.get(tag)
    if not isinstance(element, dict):
        return None
    values = element.get("Value")
    if not isinstance(values, list) or not values:
        return None
    return str(values[0])

def _stc_key(pair):
    return (str(pair[0]), str(pair[1]))

def _stc_reason(item):
    """FailureReason as a DIMSE code; anything unenumerated is 0x0110."""
    raw = _stc_single(item, _STC_FAILURE_REASON)
    if raw is None:
        return _STC_PROCESSING_FAILURE
    return _STC_REASON_MAP.get(str(raw).strip(), _STC_PROCESSING_FAILURE)

# ---------------------------------------------------------------------------
# Bridge: HTTP status -> DIMSE status mapping
# ---------------------------------------------------------------------------
def _http_status_to_dimse(http_status):
    """Map HTTP status code to DIMSE (status, description) tuple (BR-011).

    Transient errors (0xA700)  -  bridge should retry with backoff.
    Fatal errors (0xC000)  -  bridge should NOT retry.
    Success (0x0000)  -  delivered.
    """
    # -- Transient errors (retryable) --
    TRANSIENT = {
        429: "Too Many Requests - rate limited, retry after delay",
        500: "Internal Server Error - server malfunction",
        502: "Bad Gateway - storage backend error",
        503: "Service Unavailable - server busy or down",
        504: "Gateway Timeout - database operation timed out",
        507: "Insufficient Storage - disk full on server",
    }
    if http_status in TRANSIENT:
        return (0xA700, http_status, TRANSIENT[http_status])

    # -- Fatal errors (do NOT retry) --
    FATAL = {
        400: "Bad Request - invalid DICOM data",
        401: "Unauthorized - check Clarus credentials",
        403: "Forbidden - insufficient permissions",
        404: "Not Found - study/series/instance missing",
        405: "Method Not Allowed - wrong HTTP method",
        406: "Not Acceptable - unsupported Transfer Syntax",
        409: "Conflict - SOP Instance UID conflict",  # Note: 409 succeeds for idempotent delivery
        413: "Payload Too Large - dataset exceeds server limit",
        415: "Unsupported Media Type - wrong Content-Type",
        416: "Range Not Satisfiable - invalid byte range",
        422: "Unprocessable Content - DICOM validation failed",
    }
    if http_status in FATAL:
        return (0xC000, http_status, FATAL[http_status])

    # -- Success codes --
    if 200 <= http_status < 300:
        return (0x0000, http_status, "OK")

    # -- Unknown  -  conservative: treat as transient for safety --
    if 500 <= http_status < 600:
        return (0xA700, http_status, f"Unknown server error HTTP {http_status}")
    return (0xC000, http_status, f"Unexpected HTTP {http_status}")

# ---------------------------------------------------------------------------
# Bridge: STOW-RS response parser  -  detect per-SOP failures
# ---------------------------------------------------------------------------
def _parse_stow_failures_all(response_text):
    """Parse STOW-RS JSON for ALL failed SOPs (0008,1198 Failed SOP Sequence).

    Server returns HTTP 202 even when individual SOPs in a batch fail.
    Returns a list of {"sop_uid": str, "reason": str}; empty when none failed.
    """
    try:
        body = json.loads(response_text)
    except (json.JSONDecodeError, TypeError):
        return []

    failed_seq = body.get("00081198")
    if not failed_seq:
        return []

    items = failed_seq.get("Value", [])
    if not items:
        return []

    failures = []
    for item in items:
        # 00081197 = Failure Reason (US, numeric code)
        failure_code_tag = item.get("00081197", {})
        codes = failure_code_tag.get("Value", [])
        failure_code = codes[0] if codes else "?"

        # 00000902 = Error Comment (LO, human-readable)
        error_comment_tag = item.get("00000902", {})
        comments = error_comment_tag.get("Value", [])
        error_comment = comments[0] if comments else "Unknown reason"

        # 00081155 = Referenced SOP Instance UID (PS3.18 sec.10.5.2.1)
        ref_sop_tag = item.get("00081155", {})
        ref_sops = ref_sop_tag.get("Value", [])
        ref_sop = ref_sops[0] if ref_sops else "?"

        failures.append(
            {
                "sop_uid": ref_sop,
                "reason": f"[code={failure_code}] {error_comment}",
            }
        )
    return failures

def _parse_stow_failures(response_text, sop_instance_uid):
    """Parse STOW-RS JSON response for the FIRST Failed SOP (batch-compatible).

    Server returns HTTP 202 even when individual SOPs fail.
    Returns dict {"sop_uid", "reason"} if rejected, None if accepted.
    """
    failures = _parse_stow_failures_all(response_text)
    if not failures:
        return None
    return failures[0]

def _ensure_stow_ts(dataset):
    """Ensure dataset has file_meta.TransferSyntaxUID for dcmwrite.

    pynetdicom may strip file_meta from network-received datasets (BR-020).
    Only needed when re-serializing (modified instances). Raw pass-through
    (raw_bytes != None) keeps the original bytes and never reaches here.
    Note: pydicom Dataset.__getattr__ raises AttributeError, not returns None.
    """
    try:
        _ = dataset.file_meta.TransferSyntaxUID
    except AttributeError:
        from pydicom.dataset import FileMetaDataset

        dataset.file_meta = FileMetaDataset()
        dataset.file_meta.TransferSyntaxUID = ExplicitVRLittleEndian

def stow_single_instance(
    dataset, clarus_url, http_timeout=30, raw_bytes=None, client=None, tls=None
):
    """STOW-RS single instance with retry (BR-002). Auth by nginx.

    Args:
        clarus_url: DICOMweb base URL (single knob, 2908). Trailing slash
            is stripped by dicomweb_base().
        raw_bytes: if provided, use these EXACT bytes as DICOM payload.
            Bypasses dcmwrite  -  preserves byte-identical content for CAS dedup.
            When None, dataset is re-serialized via dcmwrite (modified instance).
        client: optional pre-created httpx.Client for connection reuse.
            When None, creates and closes a new Client per call.
            P30: use a persistent Client for Keep-Alive (x2 throughput).
        tls: optional (cert_path, key_path) tuple for mTLS. verify is
            ALWAYS on (httpx default)  -  no knob to disable it.

    Returns: (dimse_status, http_status, msg).
    """
    # ensure file_meta TransferSyntaxUID before any dcmwrite re-serialization.
    if raw_bytes is None:
        _ensure_stow_ts(dataset)

    # P8: raw pass-through  -  use exact bytes when no modifications were applied.
    # This preserves byte-identical content for CAS dedup (avoids dcmwrite
    # re-serialization which changes File Meta Information, tag ordering, padding).
    if raw_bytes is not None:
        dicom_bytes = raw_bytes
    else:
        buf = io.BytesIO()
        dcmwrite(buf, dataset, enforce_file_format=True)
        dicom_bytes = buf.getvalue()

    boundary = f"BOUNDARY_{uuid.uuid4().hex[:16]}"
    body = (
        (f"--{boundary}\r\nContent-Type: application/dicom\r\n\r\n").encode("ascii")
        + dicom_bytes
        + (f"\r\n--{boundary}--\r\n").encode("ascii")
    )

    # P8: httpx with total timeout  -  prevents indefinite hangs on TCP accept.
    # requests(timeout=30) only covers connect+read, not total elapsed time.
    # httpx.Timeout(N) covers the entire request lifecycle.
    total_timeout = http_timeout + 10
    base = dicomweb_base(clarus_url)
    stow_url = f"{base}/studies"

    # P30: Keep-Alive  -  reuse client for connection persistence (x2 throughput).
    # Without Keep-Alive: TCP-handshake (~30-100ms) on every slice.
    # With Keep-Alive: one handshake for the entire queue drain.
    def _do_stow():
        if client is not None:
            # Persistent client  -  connection reuse via Keep-Alive
            return client.post(
                stow_url,
                content=body,
                headers={
                    "Content-Type": (
                        f'multipart/related; type="application/dicom"; '
                        f"boundary={boundary}"
                    ),
                    "Accept": "application/dicom+json",
                },
            )
        # Fallback: create+close client per request (backward compat)
        _c = httpx.Client(timeout=httpx.Timeout(total_timeout), cert=tls)
        try:
            return _c.post(
                stow_url,
                content=body,
                headers={
                    "Content-Type": (
                        f'multipart/related; type="application/dicom"; '
                        f"boundary={boundary}"
                    ),
                    "Accept": "application/dicom+json",
                },
            )
        finally:
            _c.close()

    try:
        resp = _http_retry(_do_stow)
        # Bridge: STOW requests counter by HTTP status
        stow_requests.labels(status=str(resp.status_code)).inc()
        sop_uid = str(getattr(dataset, "SOPInstanceUID", "?"))

        if resp.status_code in (200, 201, 202):
            # Bridge: parse STOW-RS JSON for per-SOP failures
            rejection = _parse_stow_failures(resp.text, sop_uid)
            if rejection:
                logging.error(
                    "[STOW-RS] Server rejected SOP %s: %s - check clarus-server logs",
                    rejection["sop_uid"],
                    rejection["reason"],
                )
                return (0xA700, resp.status_code, rejection["reason"])

            logging.debug("-> STOW-RS: %d OK (SOP: %s)", resp.status_code, sop_uid)
            return (0x0000, resp.status_code, "OK")

        # Disk full
        if resp.status_code == 507:
            backoff = retry_after_seconds(resp.headers)
            logging.error(
                "-> STOW-RS: 507 DISK FULL (retry after %ss)",
                backoff,
            )
            return (0xA700, 507, f"Disk full - retry after {backoff}s")

        # use _http_status_to_dimse for all non-2xx responses
        return _http_status_to_dimse(resp.status_code)
    except httpx.ConnectError:
        logging.warning("-> STOW-RS: CONNECTION REFUSED")
        stow_requests.labels(status="error").inc()
        return (0xA700, None, "Connection refused")
    except httpx.TimeoutException:
        logging.warning("-> STOW-RS: TOTAL TIMEOUT after %.0fs", total_timeout)
        stow_requests.labels(status="error").inc()
        return (0xA700, None, "Total timeout")
    except Exception as e:
        logging.warning("-> STOW-RS: ERROR (%s)", e)
        logging.debug("-> STOW-RS: Full traceback follows:", exc_info=True)
        stow_requests.labels(status="error").inc()
        return (0xC000, None, str(e))

def stow_batch_instances(payloads, clarus_url, http_timeout=30, client=None, tls=None):
    """STOW-RS batch  -  N instances in ONE multipart/related request.

    One POST per study-batch (fieldtest: 1063 POSTs -> ~20). P8 raw
    pass-through per part: byte-identical content for CAS dedup, no
    dcmwrite re-serialization unless the instance was modified.

    Args:
        payloads: list of (sop_uid, ds, raw_bytes).
            raw_bytes: exact bytes (None -> re-serialize modified ds).
        clarus_url: DICOMweb base URL (single knob, 2908).
        client: optional pre-created httpx.Client (Keep-Alive, P30).
        tls: optional (cert_path, key_path) tuple for mTLS.

    Returns: (results, retry_after) tuple.
        results: per-SOP list, in payload order:
            [(sop_uid, dimse_status, http_status, msg), ...]
            dimse_status mirrors stow_single_instance (0x0000 / 0xA700 / 0xC000).
        retry_after: seconds to pause on HTTP 507 (clamped 5..300), or None.
    """
    if not payloads:
        return [], None

    boundary = f"BOUNDARY_{uuid.uuid4().hex[:16]}"
    total_timeout = http_timeout + 10
    base = dicomweb_base(clarus_url)
    stow_url = f"{base}/studies"

    body = bytearray()
    for sop_uid, ds, raw_bytes in payloads:
        if raw_bytes is None:
            _ensure_stow_ts(ds)
            buf = io.BytesIO()
            dcmwrite(buf, ds, enforce_file_format=True)
            dicom_bytes = buf.getvalue()
        else:
            dicom_bytes = raw_bytes
        body += b"--" + boundary.encode("ascii") + b"\r\n"
        body += b"Content-Type: application/dicom\r\n\r\n"
        body += dicom_bytes
        body += b"\r\n"
    body += b"--" + boundary.encode("ascii") + b"--\r\n"

    headers = {
        "Content-Type": (
            f'multipart/related; type="application/dicom"; ' f"boundary={boundary}"
        ),
        "Accept": "application/dicom+json",
    }

    def _do_stow():
        if client is not None:
            return client.post(
                stow_url,
                content=bytes(body),
                headers=headers,
            )
        _c = httpx.Client(timeout=httpx.Timeout(total_timeout), cert=tls)
        try:
            return _c.post(
                stow_url,
                content=bytes(body),
                headers=headers,
            )
        finally:
            _c.close()

    try:
        resp = _http_retry(_do_stow)
        stow_requests.labels(status=str(resp.status_code)).inc()

        if resp.status_code in (200, 201, 202):
            # Per-SOP outcome: server may reject a subset (0008,1198) in a 2xx.
            failed = _parse_stow_failures_all(resp.text)
            failed_by_uid = {f["sop_uid"]: f["reason"] for f in failed}
            sent = {uid for uid, _ds, _raw in payloads}
            # PS3.18 10.5: a rejection the server reported for a SOP the client
            # did not send means the two sides disagree about the batch. Marking
            # every sent SOP as delivered would claim a success nobody stated,
            # so the whole batch is retried.
            unmatched = [f for f in failed if f["sop_uid"] not in sent]
            if unmatched:
                logging.error(
                    "[STOW-RS] Server rejected %d SOP(s) not in this batch - "
                    "whole batch retried",
                    len(unmatched),
                )
                return [
                    (uid, 0xA700, resp.status_code, "Unmatched failure response")
                    for uid in sent
                ], None
            results = []
            for sop_uid, ds, raw_bytes in payloads:
                if sop_uid in failed_by_uid:
                    results.append(
                        (sop_uid, 0xA700, resp.status_code, failed_by_uid[sop_uid])
                    )
                else:
                    results.append((sop_uid, 0x0000, resp.status_code, "OK"))
            if failed:
                logging.error(
                    "[STOW-RS] Batch: %d/%d SOPs rejected by server - "
                    "will re-send individually on retry",
                    len(failed),
                    len(payloads),
                )
            return results, None

        # / Disk full  -  whole batch retryable.
        # 2908: _http_retry does NOT retry 507; backoff comes from the
        # Retry-After header (clamped 5..300 s, default 30 s). The outbox
        # worker pauses and keeps the files pending.
        if resp.status_code == 507:
            backoff = retry_after_seconds(resp.headers)
            logging.error(
                "-> STOW-RS: 507 DISK FULL (retry after %ss)",
                backoff,
            )
            msg = f"Disk full - retry after {backoff}s"
            return [(uid, 0xA700, 507, msg) for uid, _, _ in payloads], backoff

        # non-2xx  -  whole batch shares one outcome.
        dimse_status, _, msg = _http_status_to_dimse(resp.status_code)
        return (
            [(uid, dimse_status, resp.status_code, msg) for uid, _, _ in payloads],
            None,
        )
    except httpx.ConnectError:
        logging.warning("-> STOW-RS: CONNECTION REFUSED")
        stow_requests.labels(status="error").inc()
        return [
            (uid, 0xA700, None, "Connection refused") for uid, _, _ in payloads
        ], None
    except httpx.TimeoutException:
        logging.warning("-> STOW-RS: TOTAL TIMEOUT after %.0fs", total_timeout)
        stow_requests.labels(status="error").inc()
        return [(uid, 0xA700, None, "Total timeout") for uid, _, _ in payloads], None
    except Exception as e:
        logging.warning("-> STOW-RS: ERROR (%s)", e)
        logging.debug("-> STOW-RS: Full traceback follows:", exc_info=True)
        stow_requests.labels(status="error").inc()
        return [(uid, 0xC000, None, str(e)) for uid, _, _ in payloads], None

# ---------------------------------------------------------------------------
# Bridge: outbox
# ---------------------------------------------------------------------------

"""Outbox Queue  -  filesystem-backed reliable DICOM persistence + delivery.

nginx-way: directories = queue state. Atomic os.rename = state transition.
No SQLite. No WAL. No busy_timeout. No _write_lock.

Layout:
    outbox/
      pending/       <- items waiting for first attempt or retry
        {uid}.dcm    <- DICOM blob (atomic write: .tmp -> os.replace)
        {uid}.meta   <- {"created_at": ..., "retry_count": 0, "next_retry_at": ..., "last_error": "..."}
        {uid}.mods   <- audit trail sidecar (FR-001), optional
      in_progress/   <- atomic claim: os.rename from pending/
      done/          <- only when cleanup=False (retain for audit)
      undelivered/   <- max retries exhausted (manual intervention)

Guarantees:
  - Atomic claim: os.rename(pending/x.*, in_progress/x.*)  -  only ONE worker succeeds
  - Crash-safe: recover_stuck() moves in_progress/* back to pending/ on startup
  - Idempotent: enqueue checks if {uid}.dcm already exists in any dir -> skip
  - No duplicate delivery: exactly one in_progress/ at a time

Thread safety:
  - enqueue(): concurrent-safe via atomic os.replace (no shared state)
  - dequeue(): os.rename is atomic on same filesystem  -  collision -> skip, try next
  - Single worker (KISS)  -  no multi-worker contention in practice
"""

import json
import logging
import os
import shutil
import threading
import time

from pydicom import dcmread, dcmwrite
from pydicom.dataset import FileMetaDataset
from pydicom.uid import ExplicitVRLittleEndian

# How often the worker checks for stuck items (crashed during delivery).
STUCK_ITEM_CHECK_INTERVAL = 60.0  # seconds

# Items stuck in in_progress/ longer than this -> recovered.
STUCK_ITEM_TIMEOUT = 300.0  # 5 minutes

def _ensure_file_meta(dataset):
    """Ensure dataset has a valid FileMetaDataset with TransferSyntaxUID.

    ALWAYS moves stray (0002,eeee) group elements out of the DIMSE dataset
    body into file_meta - pydicom rejects a write that leaves (0002,eeee)
    inline ("must be in a FileMetaDataset instance", Weasis C-STORE 0xA700).
    A tag already present in file_meta is NOT overwritten, so the negotiated
    TransferSyntaxUID from event.file_meta (C-STORE path sets ds.file_meta)
    always wins. Preserves upstream TS when present (cltranscode inserts
    (0002,0010) into DIMSE datasets). Falls back to ExplicitVRLittleEndian.
    """
    if (
        hasattr(dataset, "file_meta")
        and isinstance(dataset.file_meta, FileMetaDataset)
        and dataset.file_meta
    ):
        file_meta = dataset.file_meta
    else:
        file_meta = FileMetaDataset()
        dataset.file_meta = file_meta

    group_0002_tags = [tag for tag in dataset._dict if (tag >> 16) == 0x0002]
    for tag in group_0002_tags:
        elem = dataset[tag]
        if tag not in file_meta:
            file_meta.add(elem)
        del dataset[tag]

    if hasattr(file_meta, "TransferSyntaxUID") and file_meta.TransferSyntaxUID:
        return
    # A dataset without TS info is suspicious -
    # say it loud instead of silently corrupting compressed pixel data.
    logging.warning(
        "[OUTBOX] SOP %s has no TransferSyntaxUID - defaulting to "
        "ExplicitVRLittleEndian (compressed instances MUST pass the "
        "negotiated TS via event.file_meta)",
        str(getattr(dataset, "SOPInstanceUID", "?")),
    )
    file_meta.TransferSyntaxUID = ExplicitVRLittleEndian

class OutboxQueue:
    """Filesystem-backed outbox  -  directories + atomic rename = queue."""

    def __init__(
        self,
        outbox_dir,
        max_queue=20000,
        max_retries=10,
        cleanup=True,
        retry_interval=0,
        pending_gauge=None,
        undelivered_total=None,
    ):
        self._dir = outbox_dir
        self.max_queue = max_queue
        self.MAX_RETRIES = max_retries
        self.cleanup = cleanup
        self.retry_interval = retry_interval

        # 0409 forwarder: this OutboxQueue backs BOTH the primary STOW drain
        # and (as a second instance) the best-effort forward channel. The
        # pending gauge tells the metric layer WHICH queue is reporting, so the
        # two never clobber each other. Default None = primary (outbox_pending).
        self._pending_gauge = (
            pending_gauge if pending_gauge is not None else outbox_pending
        )
        self._undelivered_total = undelivered_total

        # Subdirectories
        self._pending = os.path.join(self._dir, "pending")
        self._in_progress = os.path.join(self._dir, "in_progress")
        self._done = os.path.join(self._dir, "done")
        self._undelivered = os.path.join(self._dir, "undelivered")

        for d in [self._pending, self._in_progress, self._done, self._undelivered]:
            os.makedirs(d, exist_ok=True)

        # In-memory pending counter (avoids os.listdir on hot C-STORE path).
        self._pending_count = 0
        self._pending_lock = threading.Lock()

        # Sync from what's already on disk (survives restart).
        self._sync_pending_count()

    def _set_pending_gauge(self):
        """Push the in-memory pending count to this queue's Prometheus gauge.

        0409: routed through self._pending_gauge so the primary STOW queue and
        the forward queue each report to their own metric (isolation).
        """
        try:
            self._pending_gauge.set(self._pending_count)
        except Exception:
            pass

    # -- path helpers --------------------------------------------------

    def _safe_uid(self, sop_uid):
        return sop_uid.replace("\x00", "_").replace("/", "_").replace("\\", "_")

    def _dcm_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.dcm")

    def _meta_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.meta")

    def _mods_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.mods")

    # -- atomic file write ---------------------------------------------

    @staticmethod
    def _atomic_write(path, data, binary=False):
        """Write data atomically: tmp -> flush -> os.replace."""
        tmp = path + ".tmp"
        mode = "wb" if binary else "w"
        encoding = None if binary else "utf-8"
        with open(tmp, mode, encoding=encoding) as f:
            f.write(data)
            f.flush()
        os.replace(tmp, path)

    # -- modifications sidecar -----------------------------------------

    def _write_mods_sidecar(self, sop_uid, modifications):
        """Write FR-001 audit trail sidecar (best-effort)."""
        try:
            mods_json = []
            for tag, old_val, new_val in modifications:
                mods_json.append(
                    {
                        "tag": [tag[0], tag[1]],
                        "old": old_val,
                        "new": new_val,
                    }
                )
            self._atomic_write(
                self._mods_path(self._pending, sop_uid),
                json.dumps(mods_json),
            )
        except Exception as e:
            logging.warning("[OUTBOX] Failed to write .mods for %s: %s", sop_uid, e)

    @staticmethod
    def read_mods_sidecar(blob_path):
        """Read modifications sidecar for a blob file. Returns None if absent."""
        if not blob_path.endswith(".dcm"):
            return None
        mods_path = blob_path[:-4] + ".mods"
        if not os.path.isfile(mods_path):
            return None
        try:
            with open(mods_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None

    @staticmethod
    def delete_mods_sidecar(blob_path):
        """Delete a modifications sidecar (best-effort)."""
        if not blob_path.endswith(".dcm"):
            return
        mods_path = blob_path[:-4] + ".mods"
        try:
            os.unlink(mods_path)
        except OSError:
            pass

    # -- core operations -----------------------------------------------

    def enqueue(self, dataset, modifications=None):
        """Persist DICOM instance to outbox. Thread-safe, atomic writes.

        Order: .dcm -> .mods -> .meta (LAST). Orphan .dcm without .meta =
        safe to ignore on startup (recover_stuck skips them).

        Returns True (inserted), False (error), or "duplicate" (already in queue).
        """
        t0 = time.time()
        sop_uid = str(getattr(dataset, "SOPInstanceUID", ""))
        if not sop_uid:
            logging.error("[OUTBOX] Dataset has no SOPInstanceUID - cannot enqueue")
            return False

        # Check if already in any queue directory (dedup).
        for d in [self._pending, self._in_progress, self._done]:
            if os.path.isfile(self._dcm_path(d, sop_uid)):
                logging.info(
                    "[OUTBOX] SOP %s already in queue - duplicate, 0x0000", sop_uid
                )
                return "duplicate"

        dcm_path = self._dcm_path(self._pending, sop_uid)

        # Step 1: Write DICOM blob (atomic).
        _ensure_file_meta(dataset)
        try:
            tmp = dcm_path + ".tmp"
            dcmwrite(tmp, dataset, enforce_file_format=True)
            os.replace(tmp, dcm_path)
        except Exception as e:
            logging.error("[OUTBOX] Failed to write blob for %s: %s", sop_uid, e)
            try:
                os.unlink(dcm_path + ".tmp")
            except OSError:
                pass
            return False

        # Step 2: Write modifications sidecar (best-effort, BEFORE .meta).
        if modifications:
            self._write_mods_sidecar(sop_uid, modifications)

        # Step 3: Write metadata (LAST  -  signals "this item is ready").
        now = time.time()
        meta = {
            "created_at": now,
            "retry_count": 0,
            "next_retry_at": now,
            "last_error": None,
        }
        meta_path = self._meta_path(self._pending, sop_uid)
        self._atomic_write(meta_path, json.dumps(meta))

        with self._pending_lock:
            self._pending_count += 1
        self._set_pending_gauge()

        logging.debug("[OUTBOX] Enqueued SOP %s", sop_uid)

        elapsed = time.time() - t0
        try:
            outbox_enqueue_latency_seconds.observe(elapsed)
        except Exception:
            pass

        return True

    # -- forward channel (0409) ----------------------------------------

    @staticmethod
    def _inc_forward_dropped():
        """Increment the forward DROP counter (0409 best-effort mirror)."""
        try:

            forward_dropped_total.inc()
        except Exception:
            pass

    def _link_or_copy(self, src, dst):
        """Place src bytes at dst with ZERO extra disk usage when possible.

        0409 forwarder: the blob is already atomically written in the PRIMARY
        outbox. Rather than duplicating its bytes, try a hard link
        first (same filesystem -> no extra bytes). If that fails (cross-device
        EXDEV, archived fs, no hardlink support) fall back to a byte copy via
        tmp + os.replace (still atomic, still crash-safe).

        Returns True on success, False on failure.
        """
        try:
            os.link(src, dst)
            return True
        except OSError:
            pass
        try:
            tmp = dst + ".tmp"
            shutil.copyfile(src, tmp)
            os.replace(tmp, dst)
            return True
        except OSError:
            try:
                os.unlink(dst + ".tmp")
            except OSError:
                pass
            return False

    def enqueue_from_blob(self, blob_path, sop_uid, modifications=None):
        """Mirror an ALREADY-persisted primary blob into the forward queue.

        The forward channel is best-effort: it must NEVER change the C-STORE
        status the modality already received from the primary enqueue. Called
        from handle_c_store AFTER the primary enqueue returns True.

        Contract (identical ready-marker semantics to enqueue(), outbox.py):
          forward/<dir>/{uid}.dcm  <- hardlinked/copied primary pending blob
          forward/<dir>/{uid}.mods <- audit sidecar (optional)
          forward/<dir>/{uid}.meta <- written LAST = "this item is ready"

        Returns:
          True       -> blob placed in forward/pending
          "duplicate"-> already mirrored (idempotent re-C-STORE)
          "full"     -> forward queue at max_queue (dropped + counter)
          False      -> placement failed (dropped + counter)

        The caller ignores return for the modality status, but logs/drops.
        """
        if not sop_uid or not blob_path or not os.path.isfile(blob_path):
            self._inc_forward_dropped()
            return False

        # Dedup: already mirrored in forward/pending or in_progress -> nothing
        # to do (re-C-STORE of the same SOP, or a leftover from a crash).
        for d in [self._pending, self._in_progress]:
            if os.path.isfile(self._dcm_path(d, sop_uid)):
                logging.debug(
                    "[OUTBOX] SOP %s already in forward queue - duplicate",
                    sop_uid,
                )
                return "duplicate"

        # Queue-full: drop-newest (best-effort, never backpressure primary).
        if self.max_queue and self._pending_count >= self.max_queue:
            logging.warning(
                "[OUTBOX] Forward queue full (%d) - dropping %s "
                "(primary 0x0000 unchanged)",
                self.max_queue,
                sop_uid,
            )
            self._inc_forward_dropped()
            return "full"

        dcm_path = self._dcm_path(self._pending, sop_uid)

        # Step 1: hardlink/copy the primary blob into forward/pending.
        #
        # The primary worker can claim and remove this blob at any moment: the
        # primary enqueue that produced it returns before the worker runs, so
        # the `isfile` check above races the delivery. One retry covers the
        # window where the file is present but briefly unavailable; a second
        # failure means the item really is gone, which the primary channel has
        # already accounted for.
        if not self._link_or_copy(blob_path, dcm_path):
            if os.path.isfile(blob_path) and self._link_or_copy(blob_path, dcm_path):
                pass
            else:
                logging.error(
                    "[OUTBOX] Forward enqueue failed to place blob for %s "
                    "(primary 0x0000 unchanged)",
                    sop_uid,
                )
                self._inc_forward_dropped()
                return False

        # Step 2: audit sidecar (best-effort, BEFORE .meta).
        if modifications:
            self._write_mods_sidecar(sop_uid, modifications)

        # Step 3: metadata LAST  -  signals "this item is ready" to the worker.
        now = time.time()
        meta = {
            "created_at": now,
            "retry_count": 0,
            "next_retry_at": now,
            "last_error": None,
        }
        meta_path = self._meta_path(self._pending, sop_uid)
        self._atomic_write(meta_path, json.dumps(meta))

        with self._pending_lock:
            self._pending_count += 1
        self._set_pending_gauge()

        logging.debug("[OUTBOX] Forward-enqueued SOP %s", sop_uid)
        return True

    def dequeue(self):
        """Atomically claim the oldest ready SOP.

        Scans pending/*.meta for items with next_retry_at <= now.
        os.rename from pending/ to in_progress/  -  atomic claim.
        On collision -> skip, try next.

        Returns (sop_uid, ds, blob_path, raw_bytes) 4-tuple,
        or (None, None, None, None) if queue is empty.
        """
        now = time.time()
        sop_uid = None

        try:
            names = os.listdir(self._pending)
        except OSError:
            return (None, None, None, None)

        # Find first ready item.
        for name in names:
            if not name.endswith(".meta"):
                continue
            uid = name[:-5]  # strip .meta
            meta_path = self._meta_path(self._pending, uid)

            try:
                with open(meta_path, "r", encoding="utf-8") as f:
                    meta = json.load(f)
            except (json.JSONDecodeError, OSError):
                continue

            next_retry = meta.get("next_retry_at", 0)
            retry_count = meta.get("retry_count", 0)
            if next_retry > now or retry_count >= self.MAX_RETRIES:
                continue

            # Atomic claim: move ALL files for this UID to in_progress/.
            dcm = self._dcm_path(self._pending, uid)
            mods = self._mods_path(self._pending, uid)

            try:
                os.rename(dcm, self._dcm_path(self._in_progress, uid))
                if os.path.isfile(mods):
                    os.rename(mods, self._mods_path(self._in_progress, uid))
                os.rename(meta_path, self._meta_path(self._in_progress, uid))
                sop_uid = uid
                break
            except OSError:
                # Another worker claimed it (or file removed)  -  skip.
                continue

        if sop_uid is None:
            return (None, None, None, None)

        # Read DICOM from claimed file.
        blob_path = self._dcm_path(self._in_progress, sop_uid)
        try:
            # Lazy parse (OPT-1): a full Dataset (incl. pixels) is needed ONLY
            # when the blob carries a .mods audit sidecar - the drain then
            # re-serializes it (stow re-write must keep PixelData). The
            # unmodified majority is delivered as raw_bytes passthrough; the
            # header-only parse (stop_before_pixels) still yields every field
            # the drain needs for study bucketing, stats and logging without
            # walking the bulky pixel element.
            modified = os.path.isfile(self._mods_path(self._in_progress, sop_uid))
            if modified:
                ds = dcmread(blob_path)
            else:
                ds = dcmread(blob_path, stop_before_pixels=True)
            with open(blob_path, "rb") as f:
                raw_bytes = f.read()
            return (sop_uid, ds, blob_path, raw_bytes)
        except Exception as e:
            logging.error("[OUTBOX] Failed to read blob %s: %s", blob_path, e)
            self.mark_failed(sop_uid, f"Blob read error: {e}")
            retries = self._get_retry_count(sop_uid)
            if retries >= self.MAX_RETRIES:
                self.move_to_undelivered(sop_uid)
            return (None, None, None, None)

    # -- delivery status -----------------------------------------------

    def mark_delivered(self, sop_uid):
        """Mark SOP as successfully delivered."""
        # Find which dir the SOP is in (normally in_progress/, but allow pending/ for test flexibility).
        dir_ = self._in_progress
        if not os.path.isfile(self._dcm_path(dir_, sop_uid)):
            dir_ = self._pending
        dcm = self._dcm_path(dir_, sop_uid)
        meta = self._meta_path(dir_, sop_uid)
        mods = self._mods_path(dir_, sop_uid)

        if self.cleanup:
            for p in [dcm, meta, mods]:
                try:
                    os.unlink(p)
                except OSError:
                    pass
        else:
            for p in [dcm, meta]:
                dst = p.replace(dir_, self._done)
                try:
                    os.rename(p, dst)
                except OSError:
                    pass
            if os.path.isfile(mods):
                try:
                    os.rename(mods, self._mods_path(self._done, sop_uid))
                except OSError:
                    pass

        with self._pending_lock:
            self._pending_count = max(0, self._pending_count - 1)
        self._set_pending_gauge()
        logging.debug("[OUTBOX] Delivered SOP %s", sop_uid)

    def delivered(self, sop_uid):
        """True when this SOP is no longer waiting for delivery anywhere.

        The bridge's own delivery state is the durable fact and the ONLY
        readiness signal: the server ACKs a STOW-RS only after durable
        persist, so "not in this queue any more" means the origin has it.
        A C-STORE that was never enqueued (a modality re-request, a restart
        with cleanup on) also reads as delivered, which is correct: the
        bridge is not holding it, so nothing local stands between the SOP
        and the origin's verdict.

        Read-side only - the worker is the single writer of this state.
        Checks undelivered/ FIRST: a SOP that exhausted its retries must
        never read as delivered.
        """
        if os.path.isfile(self._dcm_path(self._undelivered, sop_uid)):
            return False
        for dir_ in (self._pending, self._in_progress):
            if os.path.isfile(self._dcm_path(dir_, sop_uid)):
                return False
        return True

    def mark_failed(self, sop_uid, error):
        """Mark delivery as failed. Retry with backoff.

        Works on items in pending/ or in_progress/. Updates .meta
        with retry_count and next_retry_at. If already in pending/,
        just updates .meta in place (no rename needed).
        Only calls move_to_undelivered when retry_count >= MAX_RETRIES.
        """
        # Find which dir the SOP is in.
        dir_ = self._in_progress
        if not os.path.isfile(self._dcm_path(dir_, sop_uid)):
            dir_ = self._pending
        meta_path = self._meta_path(dir_, sop_uid)

        retry_count = self._get_retry_count(sop_uid) + 1
        if self.retry_interval == 0:
            delay = min(2**retry_count, 120)
        else:
            delay = self.retry_interval
        next_retry = time.time() + delay

        meta = {
            "created_at": time.time(),
            "retry_count": retry_count,
            "next_retry_at": next_retry,
            "last_error": str(error)[:200],
        }

        # Atomic update of .meta.
        tmp = meta_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(meta, f)
            f.flush()
        os.replace(tmp, meta_path)

        # If in in_progress/, move back to pending/.
        if dir_ == self._in_progress:
            dcm = self._dcm_path(self._in_progress, sop_uid)
            mods = self._mods_path(self._in_progress, sop_uid)
            try:
                os.rename(dcm, self._dcm_path(self._pending, sop_uid))
                if os.path.isfile(mods):
                    os.rename(mods, self._mods_path(self._pending, sop_uid))
                os.rename(meta_path, self._meta_path(self._pending, sop_uid))
            except OSError as e:
                logging.error(
                    "[OUTBOX] Failed to move %s back to pending: %s", sop_uid, e
                )

        if retry_count >= self.MAX_RETRIES:
            logging.error(
                "[OUTBOX] SOP %s: max retries (%d) exceeded - needs manual intervention",
                sop_uid,
                self.MAX_RETRIES,
            )
            self.move_to_undelivered(sop_uid)
        else:
            logging.warning(
                "[OUTBOX] SOP %s: delivery failed (retry %d/%d): %s",
                sop_uid,
                retry_count,
                self.MAX_RETRIES,
                error,
            )

    def requeue(self, sop_uid, reason):
        """Move a claimed item back to pending/ WITHOUT bumping retry count.

        2908: used for 507 Insufficient Storage backpressure. The item is
        NOT a failed delivery - it stays pending (retry_count unchanged),
        only last_error is recorded for diagnostics.
        """
        dcm = self._dcm_path(self._in_progress, sop_uid)
        if not os.path.isfile(dcm):
            return
        mods = self._mods_path(self._in_progress, sop_uid)
        meta_path = self._meta_path(self._in_progress, sop_uid)
        try:
            os.rename(dcm, self._dcm_path(self._pending, sop_uid))
            if os.path.isfile(mods):
                os.rename(mods, self._mods_path(self._pending, sop_uid))
            os.rename(meta_path, self._meta_path(self._pending, sop_uid))
        except OSError as e:
            logging.error(
                "[OUTBOX] Failed to requeue %s back to pending: %s",
                sop_uid,
                e,
            )
            return

        # Update last_error only - retry_count stays (507 is not a failure).
        try:
            meta_target = self._meta_path(self._pending, sop_uid)
            with open(meta_target, "r", encoding="utf-8") as f:
                meta = json.load(f)
            meta["last_error"] = str(reason)[:200]
            self._atomic_write(meta_target, json.dumps(meta))
        except (OSError, json.JSONDecodeError):
            pass
        logging.warning(
            "[OUTBOX] SOP %s requeued to pending (no retry bump): %s",
            sop_uid,
            reason,
        )

    def move_to_undelivered(self, sop_uid):
        """Move exhausted-retry SOP to undelivered/  -  manual intervention needed."""

        # 0409: forward queue increments its own counter, not the primary's.
        undelivered_counter = (
            self._undelivered_total
            if self._undelivered_total is not None
            else outbox_undelivered_total
        )

        dcm = self._dcm_path(self._pending, sop_uid)
        # Also check in_progress (edge case: max retries hit during in-flight failure).
        if not os.path.isfile(dcm):
            dcm = self._dcm_path(self._in_progress, sop_uid)
        dst = self._dcm_path(self._undelivered, sop_uid)

        try:
            shutil.move(dcm, dst)
            logging.critical("[OUTBOX] SOP %s moved to UNDELIVERED: %s", sop_uid, dst)
        except OSError as e:
            logging.critical(
                "[OUTBOX] Failed to move %s to undelivered: %s", sop_uid, e
            )

        # Clean up .meta and .mods.
        for dir_ in [self._pending, self._in_progress]:
            for p in [self._meta_path(dir_, sop_uid), self._mods_path(dir_, sop_uid)]:
                try:
                    os.unlink(p)
                except OSError:
                    pass

        with self._pending_lock:
            self._pending_count = max(0, self._pending_count - 1)
        self._set_pending_gauge()
        try:
            undelivered_counter.inc()
        except Exception:
            pass

    # -- recovery ------------------------------------------------------

    def recover_stuck(self):
        """Move stuck in_progress/ items back to pending/. Called at startup and periodically.

        Two categories:
          1. in_progress/ files with mtime older than STUCK_ITEM_TIMEOUT -> back to pending/
          2. pending/ items with retry_count >= MAX_RETRIES -> move to undelivered/
        """
        now = time.time()
        cutoff = now - STUCK_ITEM_TIMEOUT
        recovered = 0
        undelivered_count = 0

        # Category 1: stuck in_progress -> pending.
        try:
            for name in os.listdir(self._in_progress):
                if not name.endswith(".dcm"):
                    continue
                uid = name[:-4]
                dcm_path = os.path.join(self._in_progress, name)
                try:
                    if os.path.getmtime(dcm_path) < cutoff:
                        for ext in [".dcm", ".meta", ".mods"]:
                            src = os.path.join(self._in_progress, uid + ext)
                            dst = os.path.join(self._pending, uid + ext)
                            if os.path.isfile(src):
                                os.rename(src, dst)
                        recovered += 1
                except OSError:
                    pass
        except OSError:
            pass

        # Category 1b: orphan .dcm files in pending/ without .meta (crashed before metadata write).
        # Create a .meta so dequeue() can find them.
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".dcm"):
                    continue
                uid = name[:-4]
                meta_path = self._meta_path(self._pending, uid)
                if not os.path.isfile(meta_path):
                    now_ts = time.time()
                    meta = {
                        "created_at": now_ts,
                        "retry_count": 0,
                        "next_retry_at": now_ts,
                        "last_error": None,
                    }
                    self._atomic_write(meta_path, json.dumps(meta))
                    recovered += 1
                    logging.info("[OUTBOX] Created .meta for orphan %s", uid)
        except OSError:
            pass

        if recovered > 0:
            logging.warning(
                "[OUTBOX] Recovered %d stuck in_progress item(s)", recovered
            )

        # Category 2: max-retry items -> undelivered.
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".meta"):
                    continue
                uid = name[:-5]
                meta_path = os.path.join(self._pending, name)
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        meta = json.load(f)
                except (json.JSONDecodeError, OSError):
                    continue
                if meta.get("retry_count", 0) >= self.MAX_RETRIES:
                    dcm = self._dcm_path(self._pending, uid)
                    if os.path.isfile(dcm):
                        self.move_to_undelivered(uid)
                        undelivered_count += 1
        except OSError:
            pass

        if undelivered_count > 0:
            logging.warning(
                "[OUTBOX] Moved %d max-retry item(s) to undelivered", undelivered_count
            )

        # Sync in-memory counter from FS.
        self._sync_pending_count()

        return (recovered, undelivered_count)

    # -- query helpers -------------------------------------------------

    def pending_count(self):
        """Return approximate pending count (in-memory, O(1))."""
        with self._pending_lock:
            return self._pending_count

    def _sync_pending_count(self):
        """Recalculate pending count from FS (startup / recovery only)."""
        try:
            count = sum(1 for n in os.listdir(self._pending) if n.endswith(".dcm"))
        except OSError:
            count = 0
        with self._pending_lock:
            self._pending_count = count
        self._set_pending_gauge()
        return count

    def next_retry_wait_sec(self):
        """Return seconds until the next SOP is ready for retry, or 5.0 if empty.

        Scans pending/*.meta to find min next_retry_at. O(n) on <=1000 files  -  fine.
        """
        now = time.time()
        earliest = None
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".meta"):
                    continue
                meta_path = os.path.join(self._pending, name)
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        meta = json.load(f)
                except (json.JSONDecodeError, OSError):
                    continue
                retry_count = meta.get("retry_count", 0)
                next_retry = meta.get("next_retry_at", 0)
                if retry_count < self.MAX_RETRIES and next_retry > now:
                    if earliest is None or next_retry < earliest:
                        earliest = next_retry
        except OSError:
            pass

        if earliest is not None:
            wait = earliest - now
            return max(0.1, min(wait, 5.0))
        return 5.0

    def _get_retry_count(self, sop_uid):
        """Return current retry count for a SOP."""
        for dir_ in [self._pending, self._in_progress]:
            meta_path = self._meta_path(dir_, sop_uid)
            if os.path.isfile(meta_path):
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        return json.load(f).get("retry_count", 0)
                except (json.JSONDecodeError, OSError):
                    pass
        return 0

    def close(self):
        """No-op on filesystem."""

# ---------------------------------------------------------------------------
# Bridge: http_server
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  HTTP handler for /print, /metrics, /health, /version.

BridgeHTTPHandler: POST /print (C-PRINT), GET /metrics (Prometheus), GET /health,
GET /version (build identification).
Includes JSON->DICOM Dataset converter and factory for dependency injection (MAJ-003).
"""

import base64
import json
import logging
from http.server import BaseHTTPRequestHandler

from prometheus_client import generate_latest
from pydicom import Dataset
from pydicom.datadict import keyword_dict

# Short git revision of the commit the bundle was generated from. bundle.py
# rewrites this line when it assembles clbridge.py; in the source tree the
# value is the placeholder, which is also the honest answer for a bundle cut
# outside a repository.
BUNDLE_STAMP = "1303ccd9"

# ---------------------------------------------------------------------------
# Bridge: JSON -> DICOM Dataset converter for C-PRINT
# ---------------------------------------------------------------------------
def _json_print_to_dataset(json_dict):
    """Convert JSON dict of DICOM tags to pydicom Dataset.

    Keys can be:
        - DICOM tag hex string (e.g. "00100010" -> PatientName)
        - DICOM keyword (e.g. "PatientName")
    """
    ds = Dataset()
    for key, value in json_dict.items():
        # Try hex tag
        if len(key) == 8 and all(c in "0123456789ABCDEFabcdef" for c in key):
            group = int(key[0:4], 16)
            elem = int(key[4:8], 16)
        else:
            # Try keyword lookup
            tag_int = keyword_dict.get(key)
            if tag_int is None:
                logging.debug("[C-PRINT] Unknown DICOM keyword: %s", key)
                continue
            # keyword_dict values are ints like 0x00100010
            group = tag_int >> 16
            elem = tag_int & 0xFFFF

        # Handle nested dicts as sequences
        if isinstance(value, dict):
            item = _json_print_to_dataset(value)
            ds.add_new((group, elem), "SQ", [item])
        elif isinstance(value, list):
            # Could be VR mismatch; set raw
            ds.add_new((group, elem), "OB", value)
        else:
            ds.add_new((group, elem), "SH", str(value))  # default VR; may be overridden
    return ds

# ---------------------------------------------------------------------------
# Bridge: HTTP Bridge Handler  -  /print + /metrics, /health
# ---------------------------------------------------------------------------
class BridgeHTTPHandler(BaseHTTPRequestHandler):
    """HTTP handler for POST /print, GET /metrics, GET /health, GET /version.

    POST /print  -  receives print jobs from ClarityX.
        Request body: JSON with keys:
            printer_name (str): key in printers.yaml
            film_session (dict): DICOM Film Session attributes as JSON
            images (list[str]): base64-encoded DICOM Part 10 files
            calling_aet (str, optional): override AE Title
        Response: JSON PrintResult

    GET /metrics  -  Prometheus text format metrics.
    GET /health  -  liveness probe (200 OK), pure and fast.
    GET /version  -  build identification (version + generated-from revision).
    """

    # Dependencies injected via make_bridge_handler() factory  -  NO lazy imports in do_GET!
    driver_registry = {}
    printer_registry = {}
    bridge_ae_title = "CLARUS_BRIDGE"
    # BR-P31: cached references to avoid per-request imports (P2.10 bottleneck fix)
    _outbox_ref = None  # OutboxQueue  -  reliable persistence queue
    _health_checker_ref = None  # HealthChecker  -  real server health status
    _commit_tracker_ref = None  # CommitTracker  -  Storage Commitment batches
    _move_jobs_ref = None  # MoveJobManager  -  C-MOVE job table

    def do_GET(self):
        """Handle GET /metrics, GET /health and GET /version (P22d, P2.10).

        P2.10: /health is a PURE liveness probe  -  no imports, no queue checks,
        no health checker calls. Those are enforced at C-STORE level (handle_c_store).
        /health MUST return in <1ms to avoid serialization bottleneck in
        the single-threaded HTTP server (or thread pool starvation in
        ThreadingHTTPServer).
        """
        if self.path == "/metrics":
            # RSS comes straight from the OS and involves no handle to hold
            # open, so there is nothing to cache between scrapes. A failure
            # leaves the gauge at 0 rather than breaking the scrape.
            memory_usage.set(get_process_rss_bytes())

            # update Outbox queue metrics  -  use cached refs, NO imports
            try:
                _outbox = type(self)._outbox_ref
                if _outbox is not None:
                    outbox_pending.set(_outbox.pending_count())
            except Exception:
                pass

            # update queue-depth gauges  -  cached refs, no imports.
            # Every access is guarded: a broken tracker must not break a scrape.
            try:
                _ct = type(self)._commit_tracker_ref
                if _ct is not None:
                    _n = _ct.pending_count()
                    commit_batches_pending.set(_n)
                    naction_batches_pending.set(_n)
            except Exception:
                pass

            try:
                _mj = type(self)._move_jobs_ref
                if _mj is not None:
                    cmove_jobs_pending.set(_mj.count_pending())
            except Exception:
                pass

            # server_health from real HealthChecker, NOT outbox pending
            try:
                _hc = type(self)._health_checker_ref
                if _hc is not None:
                    server_health.set(1 if _hc.is_healthy() else 0)
            except Exception as e:
                logging.error("[METRICS] server_health update failed: %s", e)

            metrics_data = generate_latest()  # pyright: ignore[reportOptionalCall]
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; version=0.0.3; charset=utf-8")
            self.send_header("Content-Length", str(len(metrics_data)))
            self.end_headers()
            self.wfile.write(metrics_data)
        elif self.path == "/health":
            # P2.10: /health is a PURE liveness probe. No imports, no queue checks,
            # no health checker  -  just "is the HTTP server alive?".
            # Backpressure (queue%, server health) is enforced at C-STORE level.
            # This MUST be the fastest handler in the system.
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(b"OK")
        elif self.path == "/version":
            # Which bundle is running? Same weight as /health: a constant join,
            # no imports beyond the module constant.
            body = f"clbridge {VERSION} ({BUNDLE_STAMP})".encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self):
        if self.path != "/print":
            self.send_error(404, "Not Found")
            return

        # Validate Content-Type
        content_type = self.headers.get("Content-Type", "")
        if "application/json" not in content_type:
            self.send_error(400, "Expected application/json")
            return

        # Read body. A non-numeric or negative length is a malformed request,
        # not a reason to drop the connection without an answer: `int()` would
        # raise out of the handler, and a negative length passes the size
        # ceiling below while `read(-1)` blocks the worker on a body that never
        # ends.
        try:
            content_length = int(self.headers.get("Content-Length", 0))
        except (TypeError, ValueError):
            self._json_error(400, "Invalid Content-Length")
            return
        if content_length < 0:
            self._json_error(400, "Invalid Content-Length")
            return
        if content_length > 100 * 1024 * 1024:  # 100 MB limit
            self.send_error(413, "Payload too large")
            return
        body = self.rfile.read(content_length)

        try:
            request_data = json.loads(body)
        except json.JSONDecodeError as e:
            self._json_error(400, f"Invalid JSON: {e}")
            return
        # A syntactically valid array or scalar is still not a print request,
        # and `request_data.get` would raise AttributeError out of the handler.
        if not isinstance(request_data, dict):
            self._json_error(400, "Expected a JSON object")
            return

        printer_name = request_data.get("printer_name")
        if not printer_name:
            self._json_error(400, "Missing printer_name")
            return

        printer_cfg = self.printer_registry.get(printer_name)
        if not printer_cfg:
            self._json_error(404, f"Printer '{printer_name}' not found in registry")
            return

        # Decode film_session from JSON -> pydicom Dataset
        try:
            film_session = _json_print_to_dataset(request_data.get("film_session", {}))
        except Exception as e:
            self._json_error(400, f"Invalid film_session: {e}")
            return

        # Decode images from base64
        images = []
        for img_b64 in request_data.get("images", []):
            try:
                images.append(base64.b64decode(img_b64))
            except Exception as e:
                self._json_error(400, f"Invalid image base64: {e}")
                return

        # Get calling AE title
        calling_aet = request_data.get("calling_aet", self.bridge_ae_title)

        # Select driver
        driver_name = printer_cfg.get("driver", "generic_dicom")
        driver = self.driver_registry.get(driver_name)
        if not driver:
            self._json_error(500, f"Driver '{driver_name}' not registered")
            return

        # Execute print
        try:
            result = driver.print(
                film_session=film_session,
                images=images,
                printer_host=printer_cfg["host"],
                printer_port=printer_cfg["port"],
                calling_aet=calling_aet,
            )
            self._json_response(200 if result.is_success else 502, result)
        except Exception as e:
            logging.error("[C-PRINT] Print job failed: %s", e)
            logging.debug("[C-PRINT] Full traceback follows:", exc_info=True)
            self._json_error(500, f"Print failed: {e}")

    def _json_response(self, status_code, result):
        """Send JSON PrintResult."""
        body = json.dumps(
            {
                "job_id": result.job_id,
                "status": f"0x{result.status:04X}",
                "film_boxes_printed": result.film_boxes_printed,
                "failed_images": result.failed_images,
                "printer_message": result.printer_message,
            }
        ).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _json_error(self, status_code, message):
        """Send JSON error."""
        body = json.dumps({"error": message}).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format, *args):
        """Redirect HTTP server logs to Python logging."""
        logging.debug("[HTTP-BRIDGE] " + format % args)

# ---------------------------------------------------------------------------
# Bridge: factory for BridgeHTTPHandler with injected dependencies
# ---------------------------------------------------------------------------
def make_bridge_handler(
    driver_registry,
    printer_registry,
    bridge_ae_title,
    health_checker=None,
    outbox=None,
    commit_tracker=None,
    move_jobs=None,
):
    """Create BridgeHTTPHandler subclass with injected dependencies.

    P2.10: Injects bridge runtime dependencies (outbox, etc.)
    as class-level attributes so do_GET() never does lazy imports. This eliminates
    the per-request import lock contention that was serializing /health behind
    /metrics in the single-threaded HTTPServer.

    PH-007: health_checker is stored for real server_health gauge.
    """

    class _Handler(BridgeHTTPHandler):
        pass

    _Handler.driver_registry = driver_registry
    _Handler.printer_registry = printer_registry
    _Handler.bridge_ae_title = bridge_ae_title
    _Handler._outbox_ref = outbox
    _Handler._health_checker_ref = health_checker
    _Handler._commit_tracker_ref = commit_tracker
    _Handler._move_jobs_ref = move_jobs
    return _Handler

# ---------------------------------------------------------------------------
# Bridge: prefetch
# ---------------------------------------------------------------------------

"""Bounded FIFO prefetch for the C-MOVE read path (B1, 2508).

A reader thread pulls `(dicom_bytes, idx)` from a source generator and fills a
bounded queue; the sender drains it. Structural backpressure is the bounded
queue itself: the reader blocks when it is full, the sender when it is empty,
so memory is bounded by `max_parts` and the Clarus server leg stays busy while
the sender is blocked on C-STORE network I/O - raising end-to-end C-MOVE
toward the server ceiling (the serial pipeline left the server idle during
each C-STORE).
"""

import logging
import os
import queue
import threading

# Default queue depth: 4 parts (~20 MB for typical CT slices), FIFO.
# A module-level constant so production and tests observe the same value.
DEFAULT_PREFETCH_PARTS = 4

# Sentinel: the reader has finished (EOF) or hit a fatal error to surface.
_EOF = object()

class PartPrefetcher:
    """Bounded FIFO prefetch bridging a reader thread and the sender loop.

    Usage:
        pref = PartPrefetcher(_stream_multipart_instances(resp)).start()
        for dicom_bytes, idx in pref:
            ... send ...
        # On early exit (cancel / shutdown / fatal error):
        pref.stop()
    """

    def __init__(self, source, max_parts=DEFAULT_PREFETCH_PARTS):
        self._q = queue.Queue(maxsize=max_parts)
        self._source = source
        self._error = None
        self._stop = threading.Event()
        self._thread = threading.Thread(
            target=self._fill, name="cmove-prefetch", daemon=True
        )

    def _fill(self):
        try:
            for item in self._source:
                if self._stop.is_set():
                    # The item is already pulled from the source and will
                    # never be consumed - release a spilled part here, since
                    # the queue cannot show it to the drain.
                    self._discard(item)
                    break
                # Blocks when the queue is full - this is the backpressure.
                self._q.put(item)
                if self._stop.is_set():
                    # Paired with the check above: a stop that landed while
                    # we were blocked in put() is seen HERE, before the source
                    # is asked for one more item that nothing would consume.
                    break
        except Exception as e:  # surface a reader failure to the sender
            self._error = e
        finally:
            try:
                self._q.put(_EOF)
            except Exception:
                pass

    def start(self):
        """Start the reader thread. Returns self."""
        self._thread.start()
        return self

    def __iter__(self):
        """Yield `(dicom_bytes, idx)` as the reader produces them, in order."""
        while True:
            item = self._q.get()
            if item is _EOF:
                if self._error is not None:
                    raise self._error
                return
            yield item

    def _drain(self):
        """Discard queued items, unlinking any spilled part they carry."""
        while True:
            try:
                item = self._q.get_nowait()
            except queue.Empty:
                return
            self._discard(item)

    @staticmethod
    def _discard(item):
        """Unlink the temp file of a discarded, never-consumed part."""
        part = item[0] if isinstance(item, tuple) and item else None
        if isinstance(part, SpilledPart):
            try:
                os.unlink(part.path)
            except OSError:
                pass

    def stop(self):
        """Force the reader to finish and wait for it (non-fatal, idempotent).

        Called when the sender exits early (cancel / shutdown / fatal error).
        The reader may be blocked on `put` while the queue is full; draining
        the queue frees a slot so it can observe the stop flag and exit.
        A drained part that was spilled to disk is unlinked here: nothing
        downstream will ever consume it, so the temp file would otherwise
        stay behind (the parser drops only malformed parts, and the sender
        loop unlinks only the part it has already taken).

        Drained TWICE: the first pass frees the slot the reader is blocked on,
        and the reader then parks the part it was holding, so a pass that
        finished before that wake-up would miss it and leave its spill file
        behind. The second pass after the join catches exactly that item.
        """
        self._stop.set()
        self._drain()
        if self._thread.is_alive():
            self._thread.join(timeout=5.0)
            if self._thread.is_alive():
                logging.warning("[B1-prefetch] reader thread did not exit in 5s")
        self._drain()

# ---------------------------------------------------------------------------
# Bridge: health_checker
# ---------------------------------------------------------------------------

"""Clarus Bridge - DICOMweb Server Health Checker.

Background poller + pre-flight gate. Polls GET /health every N seconds
and updates a threading.Event. C-STORE handler reads the Event -
zero HTTP overhead on the hot path, proactive degradation.

Modes (from clbridge.conf [dicomweb] health_check_mode):
  "probe"  - background poll. On HTTP 404: server has no /health endpoint
             - disable checks until bridge restart (max compatibility).
  "always" - background poll every `interval` seconds. If server unhealthy,
             C-STORE immediately returns 0xA700 - no buffering, no waste.
             For Clarus: always use this mode.
  "never"  - skip health check entirely (max DICOMweb compatibility).

/health is NOT in PS3.18 - it's a Kubernetes liveness/readiness de-facto
standard. Non-K8s DICOMweb servers (Orthanc, dcm4che) don't have it.
"""

import logging
import threading
import time

import requests

class HealthChecker:
    """Background health-check of DICOMweb server + pre-flight gate.

    Background thread polls GET /health every `interval` seconds.
    Updates `_server_healthy` threading.Event proactively.
    C-STORE handler reads the Event via check_before_stow() -
    no HTTP on the hot path, bridge degrades before buffering.

    Thread-safe: check_before_stow() is lock-free (reads Event).
    Only the background poller writes state.
    """

    def __init__(
        self,
        clarus_url: str,
        mode: str = "probe",
        interval: float = 5.0,  # background poll interval (probe + always)
        http_timeout: float = 5.0,
        tls=None,
    ):
        if mode not in ("probe", "always", "never"):
            raise ValueError(
                f"health_check_mode must be 'probe'|'always'|'never', got '{mode}'"
            )
        self._clarus_url = clarus_url
        # /health lives at the server ROOT, not under /dicomweb (2908).
        self._health_url = f"{dicomweb_origin(clarus_url)}/health"
        self._tls = tls
        self._mode = mode
        self._interval = interval
        self._http_timeout = http_timeout

        # Proactive state (updated by background poller)
        self._server_healthy = threading.Event()
        self._server_healthy.set()  # Start optimistic - assume alive
        self._last_ok_time = time.monotonic()
        self._consecutive_failures = 0
        self._disabled_until_restart = False  # set on 404 in "probe" mode
        self._last_reason = ""

        # Background thread
        self._thread = None

    # --- Public API ---

    def is_healthy(self) -> bool:
        """Return True if server is currently considered healthy.

        Non-blocking snapshot - reads Event, no HTTP.
        """
        if self._mode == "never":
            return True
        if self._disabled_until_restart:
            return True  # Server has no /health - assume OK
        return self._server_healthy.is_set()

    def check_before_stow(self) -> tuple:
        """Pre-flight health gate. Call before each STOW-RS.

        Both "probe" and "always" use the background poller's Event.
        Lock-free: zero HTTP overhead on the C-STORE hot path.

        "never" mode: always OK.
        "probe" mode:  if 404 was detected, checks disabled (always OK).
        "always" mode: Event reflects server state; 0xA700 if unhealthy.

        Returns:
            (True, 0x0000, "")         - server healthy, proceed
            (False, 0xA700, reason)    - server unhealthy, reject with 0xA700
            (True, 0x0000, "disabled") - health check disabled (probe got 404)
        """
        if self._mode == "never":
            return (True, 0x0000, "")

        if self._disabled_until_restart:
            return (True, 0x0000, "disabled")

        # Lock-free Event read - updated by background poller.
        # Zero HTTP on the hot path, proactive degradation.
        if self._server_healthy.is_set():
            return (True, 0x0000, "")

        return (False, 0xA700, self._last_reason or "server unhealthy")

    def dead_seconds(self) -> float:
        """Return seconds since last successful health check (0 if healthy)."""
        if self._server_healthy.is_set():
            return 0.0
        return time.monotonic() - self._last_ok_time

    # --- Lifecycle ---

    def start(self):
        """Start background health-check thread.

        "always" mode: poller runs forever, never disables.
        "probe" mode:  poller runs until first 404, then disables.
        "never" mode:  no poller, no checks.
        """
        if self._mode == "never":
            logging.info("[HEALTH] Health check disabled (mode=never).")
            return

        # Both "probe" and "always" use background polling.
        # Probe auto-disables on 404 (non-Clarus servers without /health).
        # Always mode: stays enabled permanently (Clarus, Kubernetes -
        # /health endpoint is guaranteed to exist).
        self._thread = threading.Thread(
            target=self._run,
            name="health-checker",
            daemon=True,
        )
        self._thread.start()
        logging.info(
            "[HEALTH] Background poller started: GET %s "
            "every %.0fs, timeout=%.0fs, mode=%s",
            self._health_url,
            self._interval,
            self._http_timeout,
            self._mode,
        )

    def stop(self):
        """Stop background thread (no-op - daemon thread exits with process)."""
        # Daemon thread, no explicit stop needed

    # - Background Poller -

    def _run(self):
        """Background loop: poll /health, update Event."""

        url = self._health_url
        was_dead = False

        while not _shutdown_requested.is_set():
            try:
                resp = requests.get(url, timeout=self._http_timeout, cert=self._tls)
                if resp.status_code == 200:
                    self._on_healthy()
                    was_dead = False
                elif resp.status_code == 404 and self._mode == "probe":
                    # Server has no /health - disable checks permanently
                    self._disabled_until_restart = True
                    logging.warning(
                        "[HEALTH] Server returned 404 on /health - "
                        "health check disabled until bridge restart "
                        "(mode=probe). Server: %s",
                        self._clarus_url,
                    )
                    return  # Exit poller thread - nothing to poll
                else:
                    self._on_unhealthy(
                        f"Server returned HTTP {resp.status_code}",
                        was_dead,
                    )
                    was_dead = True
            except requests.exceptions.Timeout:
                self._on_unhealthy(
                    f"/health timeout after {self._http_timeout}s",
                    was_dead,
                )
                was_dead = True
            except requests.exceptions.ConnectionError as e:
                self._on_unhealthy(f"Connection refused: {e}", was_dead)
                was_dead = True
            except Exception as e:
                self._on_unhealthy(f"/health error: {e}", was_dead)
                was_dead = True

            time.sleep(self._interval)

    def _on_healthy(self):
        """Called when /health returns 200."""
        if not self._server_healthy.is_set():
            downtime = time.monotonic() - self._last_ok_time
            logging.warning(
                "[HEALTH] Server recovered after %.0fs downtime",
                downtime,
            )
        self._server_healthy.set()
        self._consecutive_failures = 0
        self._last_ok_time = time.monotonic()
        self._last_reason = ""

    def _on_unhealthy(self, reason: str, was_dead: bool):
        """Called when /health fails."""
        self._server_healthy.clear()
        self._consecutive_failures += 1
        self._last_reason = reason
        if not was_dead:
            logging.warning(
                "[HEALTH] Check #%d failed: %s - bridge degraded, "
                "C-STORE will return 0xA700",
                self._consecutive_failures,
                reason,
            )
        elif self._consecutive_failures % 12 == 0:
            # Periodic reminder every ~60s (12 * 5s interval)
            dead_for = time.monotonic() - self._last_ok_time
            logging.error(
                "[HEALTH] Server still dead after %.0fs " "(check #%d): %s",
                dead_for,
                self._consecutive_failures,
                reason,
            )

# ---------------------------------------------------------------------------
# Bridge: handlers/cfind
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-FIND handler: dispatches to Patient/Study Root or MWL.

CRIT-002: extracted common _handle_qido_search() to eliminate ~60 lines of duplication.
"""

import logging
from urllib.parse import quote

import httpx

# ---------------------------------------------------------------------------
# Bridge: C-FIND handler with response limit + timeout
# ---------------------------------------------------------------------------
def _stamp_cfind_response(event, row_ds):
    """Echo (0008,0052) QueryRetrieveLevel and add (0008,0054)
    RetrieveAETitle on every C-FIND response row (01.09 Orthanc-control
    finding: MicroDicom's series panel keys rows by the RESPONSE
    QueryRetrieveLevel; Orthanc puts both on every row and the panel
    renders there). Spec-legal: PS3.4 C.4.1 - the response identifier
    shall contain the attributes of the request identifier; the SCP's
    AE title is a standard C-FIND response attribute.
    """
    level = (
        str(getattr(event.identifier, "QueryRetrieveLevel", "") or "").strip().upper()
        or "STUDY"
    )
    if "QueryRetrieveLevel" not in row_ds:
        row_ds.QueryRetrieveLevel = level
    bridge_ae = (
        getattr(
            getattr(getattr(event, "assoc", None), "acceptor", None), "ae_title", ""
        )
        or ""
    )
    if bridge_ae and "RetrieveAETitle" not in row_ds:
        row_ds.RetrieveAETitle = bridge_ae

def _cfind_shape(ds):
    """Privacy-safe C-FIND query shape for diagnostics (31.08 field
    debugging): attribute NAMES with a '*' marker when the value contains
    a wildcard star, plus QueryRetrieveLevel and SpecificCharacterSet.
    NO attribute values are logged (PHI discipline, access-journal rule).
    """
    keys = []
    for elem in ds:
        if elem.VR == "SQ" or not elem.keyword:
            continue
        val = elem.value
        if val is None or str(val).strip() == "":
            continue
        keys.append(elem.keyword + ("*" if "*" in str(val) else ""))
    level = str(getattr(ds, "QueryRetrieveLevel", "") or "")
    charset = str(getattr(ds, "SpecificCharacterSet", "") or "")
    return (
        f"level={level or '-'} keys={','.join(keys) or '-'} "
        f"charset={charset or '-'}"
    )

def handle_c_find(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Dispatch C-FIND to Patient Root, Study Root, or MWL models.

    `expose_rejected` is a property of the AE that accepted this association,
    not of the message: the QA AE sets it, every other AE leaves it False. It
    selects `qa_url` (the backend QA webservice endpoint) as the DICOMweb base
    instead of `clarus_url`; no query parameter is added, so the bridge works
    against any server that publishes such an endpoint.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        yield 0xC000, None
        return

    model_uid = event.context.abstract_syntax
    calling_ae = event.assoc.requestor.ae_title
    logging.info("[DIMSE] C-FIND from %s -> model: %s", calling_ae, model_uid)
    logging.info("[C-FIND-DEBUG] AE=%s %s", calling_ae, _cfind_shape(event.identifier))

    if model_uid == PATIENT_ROOT_UID:
        yield from _handle_patient_root(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
    elif model_uid == STUDY_ROOT_UID:
        yield from _handle_study_root(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
    elif model_uid == MWL_UID:
        # MWL is a worklist: rejected instances are stored studies, never
        # scheduled procedures, so the QA AE has nothing to change here.
        yield from _handle_mwl(
            event, clarus_url, verbose, max_responses, http_timeout, tls
        )
    else:
        yield 0xA900, None

# ---------------------------------------------------------------------------
# CRIT-002: Common QIDO-RS search handler (eliminates ~60 lines of duplication)
# ---------------------------------------------------------------------------
# 31.08 honest error logging: HTTP status errors log the actual status and
# URL (with PHI values masked, like the access journal);
# "connection failed" is reserved for TRANSPORT errors. 4xx is never
# retried (_http_retry) - a 400 here means the bridge sent a bad query.
#
# PS3.18 Table 6.7.1-1: every query key here can carry patient data, not just
# PatientName - PatientID, the accession number and the description fields all
# identify a person. Masking one key left the rest in the journal.
_MASKED_LOG_KEYS = frozenset(
    key.lower()
    for key in (
        "PatientName",
        "PatientID",
        "OtherPatientIDs",
        "PatientBirthDate",
        "PatientSex",
        "PatientAddress",
        "PatientTelephoneNumbers",
        "AccessionNumber",
        "StudyDescription",
        "SeriesDescription",
        "InstitutionName",
        "ReferringPhysicianName",
        "PerformingPhysicianName",
        "RequestingPhysician",
        "AdmittingDiagnosesDescription",
        "StudyID",
    )
)
# The same keys by tag, for a caller that passed numeric tags.
_MASKED_LOG_TAGS = frozenset(
    tag
    for tag in (
        "00100010",
        "00100020",
        "00100022",
        "00100030",
        "00100040",
        "00101040",
        "00102154",
        "00080050",
        "00081030",
        "0008103E",
        "00080080",
        "00080090",
        "00081050",
        "00081060",
        "00081080",
        "00200010",
    )
)

def _masked_query(params):
    """Render QIDO params for logging with every PHI value masked as ***.

    The key is URL-decoded and lower-cased before the lookup: a query string
    may spell `patientname` or percent-encode the tag, and an exact-match
    comparison against the canonical spelling would let those through.
    """
    from urllib.parse import unquote

    parts = []
    for key in sorted(params):
        bare = unquote(str(key)).strip().lower().replace(",", "")
        if bare in _MASKED_LOG_KEYS or bare in _MASKED_LOG_TAGS:
            parts.append(f"{key}=***")
        else:
            parts.append(f"{key}={params[key]}")
    return "&".join(parts)

def _handle_qido_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout,
    default_param,
    log_label,
    url_path="studies",
    json_to_ds=_json_to_dataset,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Common C-FIND handler: QIDO-RS search -> DIMSE Pending responses.

    Args:
        default_param: default search value if no params extracted
            (e.g. {"PatientName": "*"} for Patient Root,
             {"StudyDescription": "*"} for Study Root)
        log_label: label for find_responses metric ('study' or 'mwl')
        url_path: DICOMweb resource path ("studies" or "workitems")
        json_to_ds: DICOMweb JSON -> Dataset converter (QIDO-study for
            "studies", MWL/UPS for "workitems")
    """
    ds = event.identifier
    # MWL requests carry their SPS-level keys inside (0040,0100), so the MWL
    # path needs keywords from the sequence item too. QIDO keeps the flat
    # extraction: its identifier carries no SPS sequence, and recursing would
    # only add noise to its keyword set.
    if url_path == "workitems":
        request_keywords = _extract_mwl_request_keywords(ds)
    else:
        request_keywords = _extract_request_keywords(ds)
    # Diagnostics ( 23.08): the bridge used to drop unmapped keywords
    # silently, which hid the modality-filter field bug behind "show all".
    logging.info(
        "[C-FIND] %s keywords: %s",
        log_label,
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    if url_path == "workitems":
        # MWL: params already formed by caller, skip _build_qido_params
        params = default_param
    else:
        params = _build_qido_params(ds)
        if not params:
            params = default_param
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    url = f"{base}/{url_path}"
    # One row beyond the limit keeps the local truncation guard reachable: a
    # server told exactly max_responses cannot prove there was more
    # (PS3.4 Table C.4.1-1: B001 means further matches exist).
    qido_limit = max_responses + 1 if max_responses else None
    try:
        results = _qido_request(
            url,
            params,
            http_timeout,
            limit=qido_limit,
            tls=tls,
        )
        if not isinstance(results, list):
            results = []
    except httpx.HTTPStatusError as exc:
        # 31.08 honest log: a 400 here is the BRIDGE's fault (bad query,
        # e.g. series keys on the study level) - never a "connection
        # failure". The response body is not logged (may echo the query).
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            url,
            _masked_query(params),
        )
        yield 0xC000, None
        return
    except httpx.HTTPError:
        # Transport errors only: ReadError / ConnectError / Timeout.
        logging.warning("[C-FIND] QIDO error: connection failed")
        yield 0xC000, None
        return

    count = 0
    truncated = False
    for result in results:
        # Bridge: C-FIND response limit guard
        if max_responses and count >= max_responses:
            truncated = True
            logging.warning(
                "[C-FIND] Response limit reached (%d). "
                "Results truncated. Total available: %d.",
                max_responses,
                len(results),
            )
            break
        # Bridge: all responses sent with Pending status
        row_ds = json_to_ds(result, request_keywords)
        if url_path != "workitems":
            _stamp_cfind_response(event, row_ds)
        yield 0xFF00, row_ds
        count += 1

    # Bridge: final status when truncated  -  0xB001 (Warning).
    # PS3.4 Table C.4.1-1: "Matching terminated due to number of matches
    # encountered. Subsequent request may return additional matches."
    # This is a STANDARD C-FIND status. Every DIMSE-compatible viewer
    # (Weasis, MicroDICOM, Orthanc) is required to handle it.
    # pynetdicom knows this status  -  no "Unknown status" warning.
    # Bridge: count C-FIND responses sent. The counter is incremented BEFORE
    # the final yield: the SCP stops iterating a generator as soon as it reads
    # a non-Pending status, so anything after that yield never runs and the
    # metric would always report zero.
    find_responses.labels(type=log_label).inc(count)
    if truncated:
        yield 0xB001, None
    else:
        yield 0x0000, None

def _handle_patient_root(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND Patient Root -> QIDO-RS studies."""
    yield from _handle_qido_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        {},
        "study",
        tls=tls,
        expose_rejected=expose_rejected,
        qa_url=qa_url,
    )

def _handle_study_root(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND Study Root -> QIDO-RS.

    STUDY level (or level absent): GET /studies - unchanged.
    SERIES level (31.08, MicroDicom series search): two-step search
    (study -> per-study series), see _handle_series_search.
    IMAGE level is NOT implemented - out of scope, documented in the
    report; such a query falls through to the study-level path and the
    server answers 400 for the foreign SOPInstanceUID key (honest log).
    """
    level = (
        str(getattr(event.identifier, "QueryRetrieveLevel", "") or "").strip().upper()
    )
    if level == "SERIES":
        yield from _handle_series_search(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    yield from _handle_qido_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        {},
        "study",
        tls=tls,
        expose_rejected=expose_rejected,
        qa_url=qa_url,
    )

def _handle_series_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Study Root C-FIND at SERIES level: two-step QIDO search (31.08).

    Step a: GET /studies with the study-level keys -> study rows (identity:
    StudyInstanceUID + PatientName/PatientID for enrichment).
    Step b: per study, GET /studies/{study}/series with the series-level
    keys (+ Modality) -> series rows.

    Rows from all studies merge into ONE 0xFF00 stream; max_responses
    applies to the TOTAL (0xB001 truncation preserved). An empty step (a)
    yields an empty result (0x0000), not an error.
    """
    ds = event.identifier
    request_keywords = _extract_request_keywords(ds)
    logging.info(
        "[C-FIND] series keywords: %s",
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    study_params, series_params = _split_qido_params(ds)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    # One row beyond the limit keeps the local truncation guard reachable
    # (PS3.4 Table C.4.1-1: B001 means further matches exist).
    qido_limit = max_responses + 1 if max_responses else None

    # ---- step a: studies ----
    studies_url = f"{base}/studies"
    try:
        study_rows = _qido_request(
            studies_url,
            study_params,
            http_timeout,
            limit=qido_limit,
            tls=tls,
        )
        if not isinstance(study_rows, list):
            study_rows = []
    except httpx.HTTPStatusError as exc:
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            studies_url,
            _masked_query(study_params),
        )
        yield 0xC000, None
        return
    except httpx.HTTPError:
        logging.warning("[C-FIND] QIDO error: connection failed")
        yield 0xC000, None
        return

    study_by_uid = {}
    for row in study_rows:
        study_uid = _json_first_value(row, "0020000D")
        if study_uid:
            study_by_uid[study_uid] = row
    # The study step asking for one row more than the caller's limit is how a
    # cap is DETECTED: if that many studies came back, there are more studies
    # than this search can walk. Their series were never fetched, so the answer
    # is already incomplete before step (b) produces a single row - and a
    # transfer that reported 0x0000 ("complete, no matches") while matches sit
    # beyond the cap tells the SCU the study set is empty when it is not.
    study_cap_hit = qido_limit is not None and len(study_rows) >= qido_limit
    if not study_by_uid:
        # Empty step (a) -> empty result, per the prompt.
        yield 0x0000, None
        return

    # ---- step b: per-study series ----
    count = 0
    truncated = False
    for study_uid, study_row in study_by_uid.items():
        if max_responses and count >= max_responses:
            truncated = True
            logging.warning(
                "[C-FIND] Response limit reached (%d). Results truncated.",
                max_responses,
            )
            break
        series_url = f"{base}/studies/{quote(study_uid, safe='')}/series"
        try:
            series_rows = _qido_request(
                series_url,
                dict(series_params),
                http_timeout,
                limit=qido_limit,
                tls=tls,
            )
            if not isinstance(series_rows, list):
                series_rows = []
        except httpx.HTTPStatusError as exc:
            logging.warning(
                "[C-FIND] QIDO HTTP %d: %s?%s",
                exc.response.status_code,
                series_url,
                _masked_query(series_params),
            )
            yield 0xC000, None
            return
        except httpx.HTTPError:
            logging.warning("[C-FIND] QIDO error: connection failed")
            yield 0xC000, None
            return
        for row in series_rows:
            if max_responses and count >= max_responses:
                truncated = True
                logging.warning(
                    "[C-FIND] Response limit reached (%d). " "Results truncated.",
                    max_responses,
                )
                break
            row_ds = _json_to_dataset_series(
                row,
                request_keywords,
                study_row,
            )
            _stamp_cfind_response(event, row_ds)
            yield 0xFF00, row_ds
            count += 1
        if truncated:
            break

    # Counted before the terminal yield for the same reason as the study
    # handler: nothing after a non-Pending status is ever executed.
    find_responses.labels(type="series").inc(count)
    if truncated or study_cap_hit:
        yield 0xB001, None
    else:
        yield 0x0000, None

def _handle_mwl(event, clarus_url, verbose, max_responses, http_timeout=30, tls=None):
    """C-FIND MWL -> UPS-RS workitems (Stage 3: real MWL key mapping).

    Query: maps the modality's MWL matching keys to the workitem query params
    the server filters on (station_aet, modality, patient_id, workitem_uid,
    workflow_state). Response: converts the workitem DICOMweb JSON back to MWL
    attributes (scheduled procedure step + patient) so the modality sees a
    complete worklist entry.
    """
    params = _build_mwl_params(event.identifier)
    yield from _handle_qido_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        params,
        "mwl",
        url_path="workitems",
        json_to_ds=_json_to_dataset_mwl,
        tls=tls,
    )

# ---------------------------------------------------------------------------
# Bridge: handlers/cstore
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-STORE and C-ECHO handlers.

handle_c_store: C-STORE -> STOW-RS forwarding with size validation,
cp1251 charset fix, and SOP indexing.
handle_c_echo: Verification.
"""

import logging
import os
import struct
import threading
import time

# ---------------------------------------------------------------------------
# Backpressure: limit concurrent C-STORE handlers (like nginx worker_connections)
# ---------------------------------------------------------------------------
# Prevents pynetdicom thread pool exhaustion under extreme load.
# When all slots are busy, new associations get DIMSE 0xA700 (Out of Resources)
#  -  modalities are REQUIRED by DICOM standard to retry.
# Default: max(4, cpu_count). Configurable via [advanced] max_concurrent_cstore.
_MAX_CONCURRENT_CSTORE = max(4, (os.cpu_count() or 2))
_cstore_semaphore = threading.Semaphore(_MAX_CONCURRENT_CSTORE)

def set_max_concurrent_cstore(n: int) -> None:
    """Set max concurrent C-STORE handlers (called from config parsing)."""
    global _MAX_CONCURRENT_CSTORE, _cstore_semaphore
    _MAX_CONCURRENT_CSTORE = n
    _cstore_semaphore = threading.Semaphore(n)

# ---------------------------------------------------------------------------
# PROD-HARDENING: Unified backpressure  -  single function for outbox
# ---------------------------------------------------------------------------
def _check_backpressure(pending, max_queue):
    """Unified adaptive backpressure with hysteresis.

    Returns DIMSE status:
      <70%  -> 0x0000  (Success, no delay)
      70-90% -> 0x0000 (rate-limit, linear 0-200ms)
      90-95% -> 0xA700  (Out of Resources)
      >=95%  -> 0xC000  (Cannot Perform)

    Args:
        pending: Current queue depth (integer count).
        max_queue: Maximum queue capacity (integer count).
    """
    max_q = max_queue if max_queue > 0 else 5000
    ratio = pending / max_q if max_q > 0 else 0.0

    if ratio >= 0.95:
        logging.critical(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - CRITICAL, returning 0xC000",
            pending,
            max_q,
            ratio * 100,
        )
        return 0xC000  # Cannot Perform
    elif ratio >= 0.90:
        logging.error(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - returning 0xA700",
            pending,
            max_q,
            ratio * 100,
        )
        return 0xA700  # Out of Resources
    elif ratio >= 0.70:
        # Soft rate-limit: linear delay 0-200ms between 70% and 90%
        delay = 0.2 * (ratio - 0.70) / (0.90 - 0.70)
        time.sleep(delay)
        logging.warning(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - rate-limit delay %.0fms",
            pending,
            max_q,
            ratio * 100,
            delay * 1000,
        )
    # <70%  -  no delay, no reject

    return 0x0000  # Success

# ---------------------------------------------------------------------------
# Unified pre-stow admission gate
# ---------------------------------------------------------------------------
class _AdmissionController:
    """Single admission decision for C-STORE (health + backpressure).

    Replaces the two independent checks (health_checker + _check_backpressure)
    with one pre-flight gate. Priorities:
      1. Server dead >= 30s  -> PARK (0x0000) when store_forward=on, else 0xC000.
      2. degraded  (< 30s)   -> 0xA700 (both modes; hysteresis)
      3. backpressure        -> 0xC000 (>=95%) / 0xA700 (90-95%) /
                                rate-limit (70-90%), else 0x0000.
         (>=95% disk limit overrides parking ALWAYS.)

    store_forward: on -> a dead>=30s C-STORE is parked (0x0000; blob already
    atomically on disk before ACK), off -> 0xC000 (Cannot Perform, not transient).

    One place decides "can we take a new C-STORE". Mode
    (never/probe-disabled) handling is preserved via HealthChecker.
    """

    DEAD_SECONDS_FATAL = 30.0

    def __init__(self, outbox=None, health_checker=None, store_forward=False):
        self._outbox = outbox
        self._health = health_checker
        self._store_forward = store_forward

    def check(self):
        """Return (dimse_status, reason). 0x0000 = admit."""
        if self._health is not None:
            healthy, status, reason = self._health.check_before_stow()
            if not healthy:
                dead = self._health.dead_seconds()
                if dead >= self.DEAD_SECONDS_FATAL:
                    if self._store_forward:
                        logging.warning(
                            "[ADMISSION] Server dead %.0fs, store_forward=on "
                            "- parked (0x0000; blob on disk)",
                            dead,
                        )
                        # Parking: accept; backpressure below may still reject.
                    else:
                        logging.error(
                            "[ADMISSION] Server dead for %.0fs -> 0xC000 "
                            "(Cannot Perform)",
                            dead,
                        )
                        return 0xC000, reason or "server dead"
                else:
                    logging.warning(
                        "[ADMISSION] Server degraded for %.0fs -> 0xA700",
                        dead,
                    )
                    return status, reason or "server degraded"

        if self._outbox is not None:
            bp = _check_backpressure(
                self._outbox.pending_count(),
                self._outbox.max_queue,
            )
            if bp != 0x0000:
                return bp, "queue backpressure"

        return 0x0000, ""

# ---------------------------------------------------------------------------
# Bridge: cp1251 mojibake fixer for old Russian X-ray machines
# ---------------------------------------------------------------------------

# Module-level Cyrillic character set for mojibake detection (DRY-001).
# Defined once at import time, not re-created per C-STORE call.
# Using frozenset  -  immutable + hashable, no runtime cost on each call.
_CYRILLIC_BLOCK = frozenset(
    "АБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ" "абвгдежзийклмнопрстуфхцчшщъыьэюяё№"
)

def _fix_cp1251_krakozyabry(ds):
    """Detect and fix cp1251 mojibake in DICOM text fields.

    Problem: Old Russian X-ray machines encode PatientName/StudyDescription
    in Windows-1251 (cp1251) but either omit SpecificCharacterSet (0008,0005)
    or set it to ISO_IR 100 (Latin-1). pydicom then decodes the bytes as
    Latin-1, producing garbled text like "ÐŸÐµÑ‚Ñ€Ð¾Ð²" instead of "Петров".

    This function reverses the incorrect Latin-1 -> bytes step and re-decodes
    as cp1251. If the field was already valid UTF-8, it is left untouched.

    Strategy:
    1. Check if SpecificCharacterSet is missing or ISO_IR 100.
    2. For each target field: encode back to Latin-1 bytes -> decode as cp1251.
    3. If the result differs from original -> replace.
    4. Set SpecificCharacterSet to ISO_IR 192 (UTF-8) for Clarus Server.
    """
    charset = getattr(ds, "SpecificCharacterSet", None)
    if charset is not None:
        cs = str(charset).strip()
        if cs and cs not in ("", "ISO_IR 100", "ISO 2022 IR 100"):
            charset_conversions.labels(from_encoding="utf8").inc()
            return ds

    fields_to_fix = [
        "PatientName",
        "PatientID",
        "InstitutionName",
        "StudyDescription",
        "SeriesDescription",
    ]

    # fix v2: heuristic to distinguish cp1251 mojibake from valid Latin-1.

    def _has_cyrillic_run(text, min_run=3):
        """Return True if text contains >=min_run consecutive Cyrillic chars."""
        run = 0
        for ch in text:
            if ch in _CYRILLIC_BLOCK:
                run += 1
                if run >= min_run:
                    return True
            else:
                run = 0
        return False

    # Short-name exception:
    # Korean surnames transcribed in Cyrillic (for example the 2-3 character
    # transliterations of Ho, Yu, Lee and Kim) are 1-4 chars, all Cyrillic, but
    # never form a >=3 run in isolation. Without this exception a radiology
    # department whose staff include Korean-Russian colleagues would see those
    # names garbled in the viewer.
    def _is_all_cyrillic(text):
        return (
            len(text) >= 1
            and len(text) <= 4
            and all(ch in _CYRILLIC_BLOCK for ch in text)
        )

    fixed_any = False
    for field in fields_to_fix:
        if field not in ds:
            continue
        element = ds.data_element(field)
        if element is None:
            continue
        value = element.value
        if not isinstance(value, (str, bytes)):
            try:
                value = str(value)
            except Exception:
                continue
        if not value:
            continue

        try:
            raw_bytes = value.encode("latin-1")
            fixed = raw_bytes.decode("cp1251", errors="replace")
        except (UnicodeEncodeError, UnicodeDecodeError, Exception):
            malformed_tags.inc()
            continue

        # Only accept the fix if the result contains >=3 consecutive Cyrillic
        # characters OR is a short all-Cyrillic name (1-4 chars, no long run).
        if (
            fixed != value
            and not _has_cyrillic_run(fixed, 3)
            and not _is_all_cyrillic(fixed)
        ):
            continue

        if fixed != value:
            element.value = fixed
            fixed_any = True
            if field == "PatientName":
                logging.debug(
                    "  [CP1251] Fixed %s: %s -> %s",
                    field,
                    mask_patient_name(str(value)),
                    mask_patient_name(str(fixed)),
                )
            elif field == "PatientID":
                # A modality's PatientID is the real identifier, not the
                # bridge's AUTOPAT_ placeholder: it goes through the keyed
                # token like every other log line that carries one.
                logging.debug(
                    "  [CP1251] Fixed %s: %s -> %s",
                    field,
                    mask_patient_id(str(value)),
                    mask_patient_id(str(fixed)),
                )
            else:
                logging.debug(
                    "  [CP1251] Fixed %s: %.40s → %.40s",
                    field,
                    str(value)[:40],
                    str(fixed)[:40],
                )

    if fixed_any:
        ds.SpecificCharacterSet = "ISO_IR 192"
        charset_conversions.labels(from_encoding="cp1251").inc()
        logging.info(
            "  [CP1251] Detected and fixed cp1251 mojibake in %s",
            mask_patient_name(str(ds.get("PatientName", "unknown"))),
        )
    else:
        charset_conversions.labels(from_encoding="latin1").inc()

    return ds

# ---------------------------------------------------------------------------
# Bridge: C-STORE handler with size limit
# ---------------------------------------------------------------------------
def handle_c_store(
    event,
    clarus_url,
    verbose,
    sop_index=None,
    max_store_bytes=0,
    http_timeout=30,
    sop_registry=None,
    outbox=None,
    health_checker=None,
    store_forward=False,
    fix_empty_patient_id=True,
    fix_empty_patient_name=True,
    bridge_id_prefix="AUTOPAT_",
    bridge_name_prefix="Anonymous^",
    tls=None,
    forward_outbox=None,
    bridge_ae_title="CLARUS_BRIDGE",
):
    """Handle C-STORE: validate, enqueue to OutboxQueue, return immediately.

    OutboxQueue guarantees eventual delivery. C-STORE returns 0x0000 Success
    as soon as the SOP is persisted in SQLite  -  the modality is free immediately.
    Background outbox workers drain the queue via STOW-RS.

    Args:
        outbox: OutboxQueue instance (required for reliable persistence).
                Falls back to sync STOW-RS if None (demo/testing mode).
        store_forward: when on, a dead>=30s server parks the C-STORE
                (0x0000) instead of 0xC000.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        return 0xC000  # Processing Failure

    # Backpressure: if all slots busy -> 0xA700 Out of Resources
    # Modality will retry  -  this is standard DICOM behavior (PS3.7 sec.C.4).
    # Like nginx worker_connections: accept only what you can process.
    if not _cstore_semaphore.acquire(blocking=False):
        logging.warning(
            "[C-STORE] Backpressure: all %d slots busy - rejecting with 0xA700",
            _MAX_CONCURRENT_CSTORE,
        )
        return 0xA700  # Out of Resources

    try:
        # Bridge: C-STORE counter
        cstore_requests.inc()
        start_time = time.monotonic()

        # Bridge: check SOP class acceptance via registry
        if sop_registry is not None:
            context_uid = event.context.abstract_syntax
            if not _is_sop_accepted(sop_registry, context_uid):
                logging.warning(
                    "[C-STORE] Rejected: SOP class %s not in registry or accept=false",
                    context_uid,
                )
                # 0x0122 "SOP Class not supported" (PS3.7 Annex C) - 0xA801 is
                # a C-MOVE code and does NOT exist in the C-STORE status table
                # (PS3.4 Table B.2-1 lists A7xx/A9xx/Cxxx/B000/B006/B007/0000).
                return 0x0122

        # pydicom may fail to parse corrupted dataset (e.g. broken
        # sequences from Explicit->Implicit VR conversion of non-pixel objects).
        # Don't kill the association  -  return C000 and let other slices through.
        try:
            ds = event.dataset
        except (OSError, struct.error) as e:
            logging.warning("[BUG-005] C-STORE parse error, returning C000: %s", e)
            return 0xC000

        # Attach the File Meta Information BEFORE any
        # re-serialization. event.file_meta carries the NEGOTIATED transfer
        # syntax of this C-STORE. Without it, _ensure_file_meta defaults to
        # ExplicitVRLittleEndian and a 4.70 instance is silently rewritten as
        # EVRLE with its encapsulated pixel stream intact - a corrupt hybrid
        # (found by the cstore_e2e test).
        try:
            ds.file_meta = event.file_meta
        except Exception as fm_err:
            logging.warning("[C-STORE] Cannot attach file_meta: %s", fm_err)

        sop_uid = str(getattr(ds, "SOPInstanceUID", ""))
        study_uid = str(getattr(ds, "StudyInstanceUID", ""))
        patient = str(getattr(ds, "PatientName", "unknown"))

        # Bridge: detect malformed tags  -  missing SOPInstanceUID
        if not sop_uid:
            malformed_tags.inc()

        # Bridge: C-STORE size limit guard. The size is measured in both
        # branches: with a limit it gates the store, without one it feeds the
        # rx byte counter.
        dataset_size = _measure_dataset_bytes(ds, event)
        if max_store_bytes > 0 and dataset_size > max_store_bytes:
            logging.warning(
                "[C-STORE] Rejected oversized dataset: %d bytes "
                "(limit: %d bytes) from %s",
                dataset_size,
                max_store_bytes,
                mask_patient_name(patient),
            )
            return 0xA700  # Out of Resources  -  Refused: Out of Resources

        # rx bytes: the accepted payload size, counted before persistence so a
        # later outbox failure cannot hide received traffic.
        if dataset_size > 0:
            try:
                bytes_total.labels(
                    direction="rx", peer=ae_label(event.assoc.requestor.ae_title)
                ).inc(dataset_size)
            except Exception:
                pass

        logging.debug(
            "[C-STORE] Received: %s (SOP: %s)", mask_patient_name(patient), sop_uid
        )
        logging.debug(
            "[C-STORE] %s SOP=%s StudyUID=%s Modality=%s",
            mask_patient_name(patient),
            sop_uid[:40] if sop_uid else "(none)",
            study_uid[:50] if study_uid else "(none)",
            str(getattr(ds, "Modality", "?")),
        )

        # Track C-STORE per association for INFO-level logging.
        # Admin sees: "CT-2 connected, receiving study 1.2.840... (CT, 437 instances)".
        # One line per new study, not per SOP.
        try:
            assoc_id = id(event.assoc)  # Python object ID  -  unique per connection
        except Exception:
            assoc_id = 0
        patient_id_raw = str(getattr(ds, "PatientID", "?"))
        modality = str(getattr(ds, "Modality", "??"))
        is_new_study = record_cstore(assoc_id, study_uid, patient_id_raw, modality)
        if is_new_study:
            logging.info(
                "[C-STORE] Receiving: study=%s patient=%s modality=%s",
                study_uid[:50] if study_uid else "?",
                mask_patient_id(patient_id_raw) if patient_id_raw else "?",
                modality,
            )

        # Unified pre-stow admission gate (health + backpressure).
        # Rejects early (: don't do heavy work if we won't accept).
        adm_status, adm_reason = _AdmissionController(
            outbox=outbox,
            health_checker=health_checker,
            store_forward=store_forward,
        ).check()
        if adm_status != 0x0000:
            logging.warning(
                "[C-STORE] Admission denied (%s): rejecting with 0x%04X",
                adm_reason or "?",
                adm_status,
            )
            return adm_status

        # Bridge: fix cp1251 mojibake before forwarding to Clarus Server
        ds = _fix_cp1251_krakozyabry(ds)

        # Sanitize empty DICOM Type 2 fields before outbox
        # Bridge fixes what it can, server validates independently  -  two layers of protection.
        # write_audit=False: audit trail (0400,0561) is deferred to outbox worker
        # to keep the C-STORE hot-path fast. Modifications metadata is passed
        # alongside the blob and applied by the worker before STOW-RS.
        # study_uid: deterministic PatientID from StudyInstanceUID.
        # All SOPs in the same study get the SAME PatientID  -  preserves DICOM
        # patient-study relationship and prevents SQLite single-patient overflow.
        try:
            mods = sanitize_dataset(
                ds,
                fix_patient_id=fix_empty_patient_id,
                fix_patient_name=fix_empty_patient_name,
                id_prefix=bridge_id_prefix,
                name_prefix=bridge_name_prefix,
                write_audit=False,
                study_uid=study_uid,
                modifying_system=bridge_ae_title,
            )
            if mods:
                for tag, old, new in mods:
                    # Mask PatientName in logs (Russian personal-data law 152-FZ); show
                    # PatientID as-is (it is generated, not PHI).
                    display_new = (
                        mask_patient_name(new) if tag == (0x0010, 0x0010) else new
                    )
                    logging.debug(
                        "Coerced %s: '%s' -> '%s' (audit trail deferred to worker)",
                        tag,
                        old,
                        display_new,
                    )
        except ValueError as e:
            logging.error("Validation failed: %s - returning 0xC000", e)
            return 0xC000

        # "Don't do heavy work on the hot path. Accept bytes -> return
        # Success -> done. Everything else happens in the background."

        # Bridge: async STOW-RS via OutboxQueue  -  reliable persistence + best-effort delivery
        # (backpressure is already enforced by the unified _AdmissionController above)
        if outbox is not None:
            # Outbox-based: persist to SQLite -> immediate 0x0000 Success
            ok = outbox.enqueue(ds, modifications=mods if mods else None)
            if ok == "duplicate":
                # Idempotent  -  SOP already in outbox, return SUCCESS
                logging.info(
                    "[C-STORE] SOP %s already in outbox (duplicate) - 0x0000 Success",
                    sop_uid,
                )
                return 0x0000  # Success  -  idempotent, already persisted
            if not ok:
                logging.error(
                    "[C-STORE] Outbox enqueue failed for %s (SOP: %s) - returning 0xA700",
                    mask_patient_name(patient),
                    sop_uid,
                )
                return 0xA700  # Out of Resources  -  transient, sender should retry

            status = 0x0000  # Success  -  SOP persisted in outbox, will be delivered

            # -- 0409 forwarder hook ----------------------------------
            # Best-effort DIMSE->DIMSE mirror to a SECOND (non-authoritative)
            # archive. Called ONLY after the PRIMARY enqueue returned True
            # (so a failed primary enqueue never touches the forward channel).
            # The forward channel can NEVER change `status`: whatever happens
            # here the modality already holds 0x0000 from the primary persist.
            if forward_outbox is not None:
                try:
                    # Blob is already atomically on disk in the primary outbox;
                    # hardlink (EXDEV fallback copy) it into forward/pending.
                    primary_blob = outbox._dcm_path(outbox._pending, sop_uid)
                    _ = forward_outbox.enqueue_from_blob(
                        primary_blob,
                        sop_uid,
                        modifications=mods if mods else None,
                    )
                    # Result is intentionally ignored: forward is best-effort.
                    # Dropped/full/failure are logged + counted inside
                    # enqueue_from_blob; the modality status stays 0x0000.
                except Exception as fwd_err:  # defensive: never touch status
                    logging.warning(
                        "[C-STORE] Forward enqueue raised %s for %s "
                        "(0x0000 unchanged)",
                        type(fwd_err).__name__,
                        sop_uid,
                    )
                    if hasattr(forward_outbox, "_inc_forward_dropped"):
                        forward_outbox._inc_forward_dropped()
        else:
            # Fallback: sync forwarding (no outbox, no legacy queue)
            logging.warning(
                "[C-STORE] No queue configured - falling back to sync forward"
            )
            status, http_status, reason = stow_single_instance(
                ds,
                clarus_url,
                http_timeout,
                tls=tls,
            )
            if status != 0x0000:
                logging.warning(
                    "[C-STORE] Rejected %s (SOP: %s): %s - %s",
                    mask_patient_name(patient),
                    sop_uid,
                    _dimse_status_name(status),
                    reason,
                )

        # Bridge: translation duration observation
        translation_duration.observe(time.monotonic() - start_time)

        return status
    finally:
        _cstore_semaphore.release()

# ---------------------------------------------------------------------------
# Bridge: C-ECHO handler
# ---------------------------------------------------------------------------
def handle_c_echo(event):
    """Handle C-ECHO (Verification)."""
    return 0x0000  # Success

# ---------------------------------------------------------------------------
# Bridge: handlers/naction
# ---------------------------------------------------------------------------

"""Clarus Bridge - N-ACTION handler (Storage Commitment).

handle_n_action: parses Storage Commitment Request, verifies SOPs via WADO-RS,
builds N-ACTION-RSP with success/failed SOP sequences, and registers the batch
in the CommitTracker for the async N-EVENT-REPORT (closes the
RSP->report loop).
"""

import logging

import httpx

# ---------------------------------------------------------------------------
# Per-SOP Storage Commitment confirmation (shared by sync RSP + async report)
# ---------------------------------------------------------------------------
def _sop_confirm(sop_uid, sop_index, clarus_url, http_timeout, tls=None):
    """Confirm one SOP is actually stored in Clarus. Returns DIMSE reason.

    0      - confirmed (in index AND WADO-RS metadata 200), also marks verified.
    0xC201 - not in index / not on server.
    0xC202 - server unavailable (timeout / connection refused).
    0xC210 - processing failure.
    """
    entry = sop_index.lookup_sop(sop_uid)
    if entry is None:
        return 0xC201

    study_uid = entry["study_uid"]
    series_uid = entry["series_uid"]
    base = dicomweb_base(clarus_url)
    url = (
        f"{base}/studies/{study_uid}"
        f"/series/{series_uid}/instances/{sop_uid}/metadata"
    )
    try:
        resp = _wado_metadata_request(url, http_timeout, tls=tls)
    except (httpx.TimeoutException, httpx.ConnectError):
        return 0xC202
    except Exception as e:
        logging.warning("  [N-ACTION] SOP %s: WADO error (%s)", sop_uid, e)
        return 0xC210

    if resp.status_code == 200:
        try:
            sop_index.mark_verified(sop_uid)
        except Exception:
            pass
        return 0
    logging.warning(
        "  [N-ACTION] SOP %s: WADO-RS HTTP %d -> not confirmed",
        sop_uid,
        resp.status_code,
    )
    return 0xC201

# ---------------------------------------------------------------------------
# N-ACTION handler (Storage Commitment)
# ---------------------------------------------------------------------------
def _register_commit(
    commit_tracker,
    tx_uid,
    calling_ae,
    sop_list,
    event,
    resolve_scp=None,
):
    """Register the batch so the async N-EVENT-REPORT can be pushed later.

    PS3.8: A-ASSOCIATE carries no listening port, and `requestor.port` is the
    EPHEMERAL SOURCE port of this very connection - pushing an N-EVENT-REPORT
    there always failed, because that socket is gone once the association
    closes. The destination port therefore comes from the peer config (the same
    lookup C-MOVE uses) and nowhere else. A peer that cannot be resolved is
    reported as skipped rather than guessed at.
    """
    requestor = getattr(getattr(event, "assoc", None), "requestor", None)
    address = getattr(requestor, "address", None)
    port_ = None
    if resolve_scp is not None and calling_ae and address:
        try:
            target = resolve_scp(calling_ae, address)
            if target:
                address, port_ = target[0], target[1]
        except Exception as e:
            logging.warning("[N-ACTION] resolve_scp for %s failed: %s", calling_ae, e)

    if address and port_:
        commit_tracker.register(tx_uid, calling_ae, address, int(port_), sop_list)
    else:
        logging.warning(
            "[N-ACTION] No requestor address/port for tx=%s - report skipped",
            tx_uid,
        )

def handle_n_action(
    event,
    clarus_url,
    verbose,
    sop_index,
    http_timeout=30,
    commit_tracker=None,
    resolve_scp=None,
    tls=None,
    stc_presence=False,
):
    """Handle N-ACTION-RQ (Storage Commitment Push Model, PS3.4 K.2).

    Two modes, selected once at startup by ``[dicomweb]
    storage_commitment_presence``:

    - ``stc_presence=False`` (default, today's behaviour): confirm each SOP
      against the local index + WADO-RS, build the RSP with provisional
      Success/Failed sequences, and register the batch for the async
      N-EVENT-REPORT.
    - ``stc_presence=True``: the ORIGIN owns commitment. The RSP is
      status-only 0x0000 (the standard's shape, J.3.2.1.3) - the verdict is
      not known yet, because the bridge's own STOW may still be queued - and
      the batch is registered so the tracker asks the origin ONCE when the
      bridge has delivered every SOP.

    Registers only when a commit_tracker is provided (fire-and-forget); the
    N-ACTION-RSP itself stays synchronous.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        return 0xC000, None

    # Validate action_type (1 = Storage Commitment Request).
    # 0x0122 "No such action" is part of the PS3.7 general-refusal set - a
    # clean refusal, NOT an implementation 0xC2xx code a modality is not
    # required to understand.
    action_type = getattr(event, "action_type", None)
    if action_type is not None and action_type != 1:
        logging.warning(
            "[N-ACTION] Unsupported action_type=%s (only type 1 supported)",
            action_type,
        )
        return 0x0122, None

    calling_ae = event.assoc.requestor.ae_title
    logging.debug("[DIMSE] N-ACTION from %s", calling_ae)

    try:
        naction_requests.inc()
    except Exception:
        pass

    try:
        tx_uid, sop_list = _parse_n_action_rq(event)
    except ValueError as e:
        # Unparsable request (e.g. missing TransactionUID) -> 0x0110
        # Processing Failure (the 0107/0110 class).
        logging.warning("[N-ACTION] Parse error: %s", e)
        return 0x0110, None
    except Exception as e:
        # 0x0213 Processing Failure (general-refusal set).
        logging.error("[N-ACTION] Unexpected parse error: %s", e)
        logging.debug("[N-ACTION] Full traceback follows:", exc_info=True)
        return 0x0213, None

    logging.info(
        "[N-ACTION] TransactionUID: %s, SOPs to verify: %d", tx_uid, len(sop_list)
    )

    # J.3.2: a successful N-ACTION-RSP says only that the SCP RECEIVED the
    # request; the per-SOP verdict travels in the N-EVENT-REPORT (J.3.3.1).
    # The RSP is therefore ALWAYS status-only 0x0000 here, and the verdict is
    # left entirely to the tracker, which probes asynchronously.
    #
    # Confirming every referenced SOP before answering meant one WADO
    # round-trip per instance inside the DIMSE reactor: a modality that sends
    # a 500-instance batch held its association open for tens of minutes
    # waiting for an acknowledgement that, by the standard, carries nothing.
    # A caller-supplied `sop_index` is no longer consulted here; the tracker's
    # `verify` callable is the one place that knows how a SOP is confirmed.
    rsp = None
    if stc_presence:
        # Origin-owned commitment. The verdict is not knowable here: the
        # bridge may still be holding some of these SOPs in its own outbox,
        # so any sequence content would be a guess. The tracker resolves the
        # batch against the origin once every SOP has been delivered (or the
        # deadline passes).
        logging.info(
            "[N-ACTION] tx=%s: origin STC mode - status-only RSP, "
            "%d SOP(s) registered for the origin's verdict",
            tx_uid,
            len(sop_list),
        )
    else:
        # Local heuristic. The tracker's `verify` (the SOP index + WADO-RS
        # path) decides per SOP on its own tick; this handler acknowledges
        # receipt and gets out of the way.
        #
        # The SOPs the RSP used to report as failures are NOT reported as
        # failures here: at this instant nothing has been checked, so a
        # 0x0110 for each of them would be a claim the bridge has no evidence
        # for. The N-EVENT-REPORT the tracker sends is where that verdict
        # legitimately appears.
        logging.info(
            "[N-ACTION] tx=%s: %d SOP(s) accepted for asynchronous "
            "verification (status-only RSP)",
            tx_uid,
            len(sop_list),
        )

    # Register the batch for the async N-EVENT-REPORT.
    if commit_tracker is not None and sop_list:
        _register_commit(
            commit_tracker,
            tx_uid,
            calling_ae,
            sop_list,
            event,
            resolve_scp=resolve_scp,
        )

    # A correctly-parsed request is ALWAYS acknowledged 0x0000 (J.3.2.1.4: no
    # service-class specific values; RSP only says "received / not handling").
    # In false-mode success, partial and total failure differ ONLY by the
    # content of the Success / Failed SOP sequences built above; in true-mode
    # `rsp` is None (status-only) and every per-SOP outcome travels in the
    # async N-EVENT-REPORT, which is untouched here.
    return 0x0000, rsp

def _display_reason(reason, sop_uid):
    """Log helper: emits per-SOP WADO failure line, returns the reason code."""
    if reason == 0xC202:
        logging.warning(
            "  [N-ACTION] SOP %s: WADO-RS UNAVAILABLE -> FAILED (0xC202)", sop_uid
        )
    elif reason == 0xC210:
        logging.warning(
            "  [N-ACTION] SOP %s: WADO-RS ERROR -> FAILED (0xC210)", sop_uid
        )
    else:
        logging.warning(
            "  [N-ACTION] SOP %s: NOT CONFIRMED -> FAILED (0xC201)", sop_uid
        )
    return reason

# ---------------------------------------------------------------------------
# Bridge: handlers/cmove
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-MOVE handler: WADO-RS streaming + C-STORE forwarding.

handle_c_move: accepts C-MOVE-RQ, creates job in queue, returns Pending.
_execute_cmove_job: streams study from Clarus, sends instances to target SCP.
_send_storage_commitment: pushes Storage Commitment N-ACTION after successful C-MOVE.

MAJ-002: _execute_cmove_job split into _associate_for_move() and _stream_and_send_study().
"""

import io
import json
import logging
import re
import shutil
import struct
import threading
import time
from urllib.parse import quote as _quote

# HTTP client + URL helpers for the R1 pre-flight (QIDO series lookup uses
# httpx via _qido_request; the per-series WADO metadata GET uses plain
# requests).
import httpx as _httpx
import requests
from pydicom import Dataset, dcmread
from pydicom.uid import (
    ExplicitVRLittleEndian,
    ImplicitVRLittleEndian,
    generate_uid,
)
from pynetdicom import AE
from pynetdicom.sop_class import (
    StorageCommitmentPushModel,
    Verification,
)

# TS-order constants (IMAGE_TS EVRLE-first etc.) live in clean_code.protocol
# (single definition - the bundle warns on duplicate module-level names).
# The main C-MOVE outbound association proposes each SOP class with its
# uncompressed family (EVRLE, IVRLE) first and then any stored/compressed
# transfer syntaxes from the pre-flight; negotiation is acceptor-driven, so a
# 4.80-capable viewer still negotiates 4.80 and a stored 4.80 sends as-is on
# the accepted 4.80 context.

# ---------------------------------------------------------------------------
# No probe/second association: the bridge NEVER opens one to a C-MOVE
# destination. The main association is the ONLY delivery association; a stored
# TS the viewer did not accept is either refetched on the MAIN association (if
# the server can produce an accepted TS) or fails honestly. There is no
# fallback/probe/reject-cache machinery. Retrying the main association is
# governed by the single outbound_assoc_attempts knob (PS3.8 9.1.4 Note 2
# leaves retry policy to the implementation).
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# simple bool to suppress pynetdicom noise during streaming/SC
# ---------------------------------------------------------------------------
_suppress_pynetdicom = False

class _SuppressPynetdicomFilter(logging.Filter):
    """Simple filter: suppress pynetdicom logs when _suppress_pynetdicom is True."""

    def filter(self, record):
        return not _suppress_pynetdicom

_pynetdicom_suppress = _SuppressPynetdicomFilter()
logging.getLogger("pynetdicom").addFilter(_pynetdicom_suppress)

# Enrich pynetdicom timeout messages with context: which timer,
# inbound/outbound, AE title, timeout value.
import pynetdicom.association as _assoc_module

_original_assoc_error = _assoc_module.LOGGER.error

def _patched_assoc_error(msg, *args, **kwargs):
    if msg == "Network timeout reached":
        msg = (
            "Network timeout reached (idle socket > network_timeout - "
            "check inbound_network_timeout / outbound_network_timeout in config)"
        )
    elif msg and "DIMSE timeout reached" in str(msg):
        msg = (
            "DIMSE timeout reached (no response to command within dimse_timeout - "
            "check inbound_dimse_timeout / outbound_dimse_timeout in config)"
        )
    _original_assoc_error(msg, *args, **kwargs)

_assoc_module.LOGGER.error = _patched_assoc_error

# ---------------------------------------------------------------------------
# Bridge: C-MOVE  -  extract MoveDestination from C-MOVE-RQ
# ---------------------------------------------------------------------------
def _parse_c_move_rq(event):
    """Extract StudyInstanceUID(s) and MoveDestination from C-MOVE-RQ.

    Returns (list_of_study_uids, move_dest_ae).
    Raises ValueError if StudyInstanceUID or MoveDestination is missing.

    MoveDestination (0000,0600) is a DIMSE command field, not an identifier
    element  -  accessed via event.move_destination in pynetdicom.

    A sender may put MULTIPLE StudyInstanceUIDs in a single C-MOVE-RQ.
    Discarding all but the first would silently drop studies, so every
    requested UID is processed.
    """
    move_dest = event.move_destination
    if not move_dest or str(move_dest).strip() == "":
        raise ValueError("C-MOVE-RQ: missing MoveDestination (0000,0600)")

    ds = event.identifier
    study_uid_raw = getattr(ds, "StudyInstanceUID", None)
    if not study_uid_raw or str(study_uid_raw).strip() == "":
        raise ValueError("C-MOVE-RQ: missing StudyInstanceUID (0020,000D)")

    # pynetdicom may return multi-valued StudyInstanceUID as list, tuple,
    # or pydicom MultiString (all iterable, none are str).
    # process ALL StudyInstanceUIDs in the request.
    if isinstance(study_uid_raw, str):
        study_uids = [str(study_uid_raw)]
    else:
        try:
            study_uids = [str(uid) for uid in list(study_uid_raw)]
        except (TypeError, IndexError):
            raise ValueError("C-MOVE-RQ: invalid StudyInstanceUID (0020,000D)")

    if not study_uids:
        raise ValueError("C-MOVE-RQ: empty StudyInstanceUID list")

    return study_uids, str(move_dest)

def _json_loads(payload):
    """json.loads over bytes/str - no new dependency, no external stream."""
    if isinstance(payload, (bytes, bytearray)):
        return json.loads(bytes(payload).decode("utf-8", "replace"))
    return json.loads(payload)

def split_multipart_parts(raw, boundary):
    """Split a multipart body into (headers_bytes, body_bytes) parts.

    Minimal, dependency-free (no python-multipart) parser for the PS3.18
    10.4.4 metadata response. `raw` is the bytes body; `boundary` is the
    Content-Type boundary parameter (already unquoted by the caller). A
    body of two consecutive boundaries (Preamble / Epilogue around the
    parts) is handled by dropping empty segments and lone boundary
    markers. Each returned part is (raw_header_bytes, raw_body_bytes) with
    the CRLFCRLF boundary removed. Returns [] on any structural failure.
    """
    try:
        if not raw or not boundary:
            return []
        if isinstance(raw, str):
            raw = raw.encode("utf-8")
        # Find every boundary line ("--boundary" as a whole line, i.e. on its
        # own line: preceded by CRLF or start-of-string; optionally followed
        # by "--" for the closing "--boundary--").
        delim = re.compile(
            rb"(?:\r\n|\r|\n|^)--" + re.escape(boundary.encode("utf-8")),
            re.MULTILINE,
        )
        # Content between two consecutive boundary lines is one part (headers
        # then a blank line then the body). The preamble before the first
        # boundary (often empty) is skipped.
        matches = list(delim.finditer(raw))
        parts = []
        for k in range(1, len(matches)):
            seg_start = matches[k - 1].end()
            seg_end = matches[k].start()
            # Drop an optional trailing CRLF that ends the previous segment
            # (it belongs to the boundary line break, not the part body).
            if raw[seg_start : seg_start + 2] == b"\r\n":
                seg_start += 2
            elif seg_start < len(raw) and raw[seg_start : seg_start + 1] == b"\n":
                seg_start += 1
            content = raw[seg_start:seg_end].rstrip(b"\r\n")
            # Skip empty segments (double boundaries / stray separators).
            if not content:
                continue
            sep = content.find(b"\r\n\r\n")
            if sep == -1:
                sep2 = content.find(b"\n\n")
                if sep2 == -1:
                    continue  # not a well-formed part (no header/body split)
                header_bytes = content[:sep2]
                body_bytes = content[sep2 + 2 :]
            else:
                header_bytes = content[:sep]
                body_bytes = content[sep + 4 :]
            parts.append((header_bytes, body_bytes))
        return parts
    except Exception:
        return []

# ---------------------------------------------------------------------------
# R1 pre-flight (0609): learn each class's stored TS BEFORE the association.
# Source: the standard per-instance metadata resource (PS3.18 10.4.4)
# /studies/{study}/series/{series}/metadata, whose elements ALWAYS carry
# (0002,0010) TransferSyntaxUID (and (0008,0016) SOPClassUID). Series are
# enumerated via QIDO-RS /studies/{study}/series.
# ---------------------------------------------------------------------------
# TTL cache of successful pre-flights (0609 field): a repeated C-MOVE of
# the same study skips the PS3.18 10.4.4 metadata walk (field: 2.3 s for a
# 432-instance series + parse, plus the association waits on it). Failures
# are NOT cached - the degrade path must retry. A new stored TS appearing
# inside the TTL window stays deliverable: such an instance misses its
# context and takes the legacy fallback path (spec R4 rule 3).
_PREFLIGHT_TTL_S = 120.0
_preflight_cache = {}  # study_uid -> (expires_monotonic, result dict)

# Entries expire on their own deadline, but nothing removed them, so a bridge
# serving many studies grew this dict without bound (each value also holds a
# set per SOP class). The cap is generous against the TTL: at the observed
# rate a full 120 s window holds a few hundred entries, and 1024 is well past
# that while still bounding memory.
_CACHE_MAX_ENTRIES = 1024

def _cache_evict(cache, now):
    """Drop expired entries, then the oldest until the cache fits the cap."""
    for key, value in list(cache.items()):
        if now >= value[0]:
            del cache[key]
    if len(cache) <= _CACHE_MAX_ENTRIES:
        return
    # Oldest-expiring first: those are the entries closest to being useless.
    for key, _value in sorted(cache.items(), key=lambda kv: kv[1][0])[
        : len(cache) - _CACHE_MAX_ENTRIES
    ]:
        del cache[key]

def _preflight_study_ts_by_class(
    study_uid,
    clarus_url,
    http_timeout=2.0,
    tls=None,
    budget_s=4.0,
    expose_rejected=False,
    qa_url="",
):
    """Return dict[sop_class -> set[stored transfer syntax UID]] for a
    C-MOVE study, or None when pre-flight cannot be completed.

    Used to shape the outbound association's per-TS contexts so the stored
    transfer syntax of every instance is PROPOSED and its acceptance is
    explicit at negotiation time (spec R1/R2). Failure is NEVER fatal: any
    error/timeout/404/over-budget returns None and the caller degrades to
    the fixed [EVRLE, IVRLE, 4.80, 4.70] proposal (today's behavior).

    1. QIDO series lookup /studies/{study}/series -> SeriesInstanceUIDs.
    2. Per series, WADO metadata /studies/{study}/series/{series}/metadata
       (Accept application/dicom+json) -> one JSON array; each element
       contributes (SOPClassUID from 00080016, TS from 00020010).

    The metadata resource is answered with the mandatory media type
    multipart/related; type="application/dicom+json" (PS3.18 10.4.4) - the
    single part is parsed; a plain application/dicom+json body is handled as
    before. Successful non-empty results are cached for _PREFLIGHT_TTL_S
    seconds.
    """
    _now = time.monotonic()
    # The cache key carries the expose mode: the two AEs see DIFFERENT instance
    # sets for the same study, so a shared entry would let a normal-AE job
    # propose contexts for instances it must not retrieve.
    _cache_key = (study_uid, bool(expose_rejected))
    _hit = _preflight_cache.get(_cache_key)
    if _hit is not None and _now < _hit[0]:
        logging.info(
            "[C-MOVE] pre-flight %s: cache hit (TTL %.0fs), %d class(es)",
            str(study_uid)[:50],
            _PREFLIGHT_TTL_S,
            len(_hit[1]),
        )
        return {k: set(v) for k, v in _hit[1].items()}
    _preflight_cache.pop(_cache_key, None)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    start = time.monotonic()

    def _over_budget():
        return (time.monotonic() - start) >= budget_s

    def _normalize_rows(value):
        """Coerce a parsed metadata JSON value into a list of instance dicts.

        Some deployments answer WADO metadata as a single JSON array of
        instance objects; others (PS3.18 Annex F allows either a single
        array or one object per multipart part) answer as one JSON
        object per instance per multipart part. Accept a list (extend) or a
        bare dict (one instance). Anything else yields nothing.
        """
        if isinstance(value, list):
            return [v for v in value if isinstance(v, dict)]
        if isinstance(value, dict):
            return [value]
        return []

    def _parse_metadata_body(content_type, raw):
        """Parse the metadata response body into a list of JSON dicts.

        PS3.18 8.9.3 + 10.4.4: metadata is conveyed as the mandatory
        multipart/related media type. Two conformant shapes occur in the
        field:
          * one part whose payload is a JSON array of instance objects, or
          * one JSON object per instance, one instance per multipart part.
        Both are parsed here: when content_type starts with multipart/related
        the raw body is split on the boundary and EVERY part's payload is
        parsed (each as an array -> extended, or a bare object -> appended);
        otherwise the whole body is parsed directly as JSON. Returns [] on
        any parse failure.
        """
        ct = content_type or ""
        if not ct.lower().startswith("multipart/related"):
            try:
                rows = raw.json() if hasattr(raw, "json") else _json_loads(raw)
                return _normalize_rows(rows)
            except Exception:
                return []
        # Extract the boundary parameter, e.g.
        #   boundary="18d3aa...".
        boundary = ""
        for piece in ct.split(";"):
            piece = piece.strip()
            if piece.lower().startswith("boundary="):
                boundary = piece[len("boundary=") :].strip().strip('"')
                break
        if not boundary:
            return []
        try:
            body_bytes = raw.content if hasattr(raw, "content") else raw
            parts = split_multipart_parts(body_bytes, boundary)
            if not parts:
                return []
            out = []
            for _headers, body in parts:
                try:
                    out.extend(_normalize_rows(_json_loads(body)))
                except Exception:
                    # A malformed part must not sink a good response: skip it.
                    continue
            return out
        except Exception:
            return []

    # 1. enumerate series (QIDO-RS, same shape the series C-FIND step-b uses).
    # `_qido_request` returns the parsed JSON list (or []); a 4xx raises an
    # httpx.HTTPStatusError which is a subclass of httpx.HTTPError.
    try:
        series_url = f"{base}/studies/{_quote(study_uid, safe='')}/series"
        series_rows = _qido_request(series_url, {}, http_timeout, limit=None, tls=tls)
        if not isinstance(series_rows, list):
            raise ValueError("series QIDO did not return a JSON list")
    except (_httpx.HTTPError, ValueError, KeyError, TypeError):
        logging.debug(
            "[C-MOVE] pre-flight: series QIDO for %s failed - no stored-TS "
            "contexts proposed",
            str(study_uid)[:50],
        )
        return None
    if _over_budget():
        return None

    series_uids = []
    for row in series_rows:
        if not isinstance(row, dict):
            continue
        suid = _json_first_value(row, "0020000E")
        if suid:
            series_uids.append(suid)
    if not series_uids:
        # Empty study (no series) - nothing to pre-liquidate; caller uses the
        # default proposal and the study stream will simply return 0 parts.
        return {}

    result = {}
    for suid in series_uids:
        if _over_budget():
            return None  # give up cleanly, degrade to default proposal
        meta_url = (
            f"{base}/studies/{_quote(study_uid, safe='')}"
            f"/series/{_quote(suid, safe='')}/metadata"
        )
        try:
            mresp = requests.get(
                meta_url,
                headers={"Accept": "application/dicom+json"},
                timeout=http_timeout,
                cert=tls,
            )
            mresp.raise_for_status()
            _mh = getattr(mresp, "headers", {}) or {}
            rows = _parse_metadata_body(
                _mh.get("Content-Type", ""),
                mresp,
            )
            if not rows:
                # add ONE debug line with the reason so a failing field
                # pre-flight is not silent.
                logging.debug(
                    "[C-MOVE] pre-flight: metadata for series %s: %d bytes, "
                    "content-type=%s - no JSON rows parsed",
                    str(suid)[:50],
                    len(mresp.content) if hasattr(mresp, "content") else -1,
                    _mh.get("Content-Type", "?"),
                )
                continue
        except Exception as _pref_exc:
            # Any series metadata failure -> abandon the whole pre-flight
            # (partial data could shape a wrong proposal).
            logging.debug(
                "[C-MOVE] pre-flight: metadata for series %s failed (%s) - "
                "no stored-TS contexts proposed",
                str(suid)[:50],
                _pref_exc,
            )
            return None
        for inst in rows:
            if not isinstance(inst, dict):
                continue
            sop_class = _json_first_value(inst, "00080016")
            ts_uid = _json_first_value(inst, "00020010")
            if sop_class and ts_uid:
                result.setdefault(sop_class, set()).add(ts_uid)
    # drop empty classes
    result = {k: v for k, v in result.items() if v}
    n_classes = len(result)
    n_ts = sum(len(v) for v in result.values())
    logging.info(
        "[C-MOVE] pre-flight %s: %d class(es), %d stored TS total "
        "(PS3.18 10.4.4 metadata)",
        str(study_uid)[:50],
        n_classes,
        n_ts,
    )
    if result:
        _preflight_cache[(study_uid, bool(expose_rejected))] = (
            time.monotonic() + _PREFLIGHT_TTL_S,
            {k: set(v) for k, v in result.items()},
        )
        _cache_evict(_preflight_cache, time.monotonic())
    return result

# ---------------------------------------------------------------------------
# _study_sop_uids - ordered, de-duplicated SOP instance UID list of a study
# (PS3.18 10.4.4 metadata): the authoritative UNDELIVERED tail for
# the (0008,0058) Failed SOP Instance UID List on a GIVE_UP / partial final is
# computed as (this list) minus (the UIDs actually delivered across all
# resume passes). Kept separate from `_preflight_study_ts_by_class` so the
# negotiation map and its tests are untouched. Returns the ordered list of
# SOP UIDs, or None when the study metadata cannot be enumerated (the worker
# then degrades to the per-attempt failed list).
# ---------------------------------------------------------------------------
_study_sop_uids_cache = {}  # study_uid -> (expires_monotonic, list[uid])

def _study_sop_uids(
    study_uid,
    clarus_url,
    http_timeout=2.0,
    tls=None,
    budget_s=4.0,
    expose_rejected=False,
    qa_url="",
):
    """Return ordered, de-duplicated SOP instance UID list of a study from
    the standard per-instance metadata resources (PS3.18 10.4.4), or None if
    the study cannot be enumerated (best effort; the caller degrades)."""

    def _normalize(value):
        if isinstance(value, list):
            return [v for v in value if isinstance(v, dict)]
        if isinstance(value, dict):
            return [value]
        return []

    def _parse_body(ct, raw):
        """Metadata body -> list of instance dicts (array part or object-per-
        part; mirrored from `_preflight_study_ts_by_class`)."""
        ctype = ct or ""
        try:
            if not ctype.lower().startswith("multipart/related"):
                rows = raw.json() if hasattr(raw, "json") else _json_loads(raw)
                return _normalize(rows)
            boundary = ""
            for piece in ctype.split(";"):
                piece = piece.strip()
                if piece.lower().startswith("boundary="):
                    boundary = piece[len("boundary=") :].strip().strip('"')
                    break
            if not boundary:
                return []
            body_bytes = raw.content if hasattr(raw, "content") else raw
            parts = split_multipart_parts(body_bytes, boundary)
            out = []
            for _h, body in parts:
                out.extend(_normalize(_json_loads(body)))
            return out
        except Exception:
            return []

    now = time.monotonic()
    hit = _study_sop_uids_cache.get((study_uid, bool(expose_rejected)))
    if hit is not None and now < hit[0]:
        return list(hit[1])
    _study_sop_uids_cache.pop((study_uid, bool(expose_rejected)), None)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    start = time.monotonic()

    def _over_budget():
        return (time.monotonic() - start) >= budget_s

    try:
        series_url = f"{base}/studies/{_quote(study_uid, safe='')}/series"
        series_rows = _qido_request(series_url, {}, http_timeout, limit=None, tls=tls)
    except Exception:
        return None
    series_uids = []
    if isinstance(series_rows, list):
        for row in series_rows:
            if isinstance(row, dict):
                s = _json_first_value(row, "0020000E")
                if s:
                    series_uids.append(s)
    if not series_uids:
        return []
    uids = []
    seen = set()
    for suid in series_uids:
        if _over_budget():
            return None
        meta_url = (
            f"{base}/studies/{_quote(study_uid, safe='')}"
            f"/series/{_quote(suid, safe='')}/metadata"
        )
        try:
            mresp = requests.get(
                meta_url,
                headers={"Accept": "application/dicom+json"},
                timeout=http_timeout,
                cert=tls,
            )
            mresp.raise_for_status()
            _mh = getattr(mresp, "headers", {}) or {}
            rows = _parse_body(_mh.get("Content-Type", ""), mresp)
        except Exception:
            return None
        for inst in rows:
            sop = _json_first_value(inst, "00080018")
            if sop and sop not in seen:
                seen.add(sop)
                uids.append(sop)
    if uids:
        _study_sop_uids_cache[(study_uid, bool(expose_rejected))] = (
            time.monotonic() + _PREFLIGHT_TTL_S,
            list(uids),
        )
        _cache_evict(_study_sop_uids_cache, time.monotonic())
    return uids

# ---------------------------------------------------------------------------
# (2608): self-delivery guard  -  is the target the bridge's own listener?
# ---------------------------------------------------------------------------
def _is_self_delivery_target(
    target_host, target_port, bridge_dimse_host, bridge_dimse_port
):
    """Return True if (target_host, target_port) is the bridge's own DIMSE listener.

    Loopback aliases (127.0.0.1, localhost, ::1) and bind-any addresses
    (0.0.0.0, ::) are treated as one endpoint: a peers.conf entry pointing
    at any alias with the bridge port would loop C-MOVE back into the
    bridge's own C-STORE SCP.
    """
    if bridge_dimse_port is None or target_port != bridge_dimse_port:
        return False
    if target_host is None:
        return False

    def _normalize(host):
        h = str(host).strip().lower()
        if h in ("0.0.0.0", "::", "[::]"):
            return "127.0.0.1"
        return h

    aliases = {"127.0.0.1", "localhost", "::1"}
    if bridge_dimse_host:
        aliases.add(_normalize(bridge_dimse_host))
    return _normalize(target_host) in aliases

def _failure_dataset(uids, error_comment=None):
    """Response-Identifier Data Set for a non-success C-MOVE-RSP final status.

    - (0008,0058) Failed SOP Instance UID List (UI, VM 1-n): the SOP instance
      UIDs that were attempted but not delivered - PS3.4 Table C.4-2 requires
      Cancel, Failure and Warning to contain it (PS3.4 C.4.2.1.4.2).
    - (0000,0902) Error Comment (LO): honest reason, carried on a Failure
      status when nothing conclusive was listed.

    Both elements use add_new (keyword-independent) so the command/data set
    round-trips regardless of pynetdicom property mapping.
    """
    ds = Dataset()
    if error_comment:
        try:
            ds.add_new((0x0000, 0x0902), "LO", str(error_comment)[:64])
        except Exception:
            pass
    if uids:
        try:
            ds.add_new((0x0008, 0x0058), "UI", [str(u) for u in uids])
        except Exception:
            pass
    return ds

# Bridge: C-MOVE handler  -  synchronous transfer with per-instance progress
def handle_c_move(
    event,
    move_jobs,
    peers_file,
    clarus_url,
    bridge_ae_title,
    http_timeout=30,
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    bridge_dimse_host=None,
    bridge_dimse_port=None,
    move_poll_timeout=600,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Handle C-MOVE-RQ: fire-and-forget dispatch + held reactor for the final.

    DICOM PS3.4 sec.C.4.2.2: the SCP shall have prior knowledge of the
    Move Destination AE Title and Presentation Address.

    Combo model (fire-and-forget + DB-polling for the final response):
    - jobs are created in SQLite; _cmove_worker pool streams in background
      (worker threads associate and send C-STORE, independently of reactor)
    - yield (addr, port) -> pynetdicom primes store_assoc
    - reactor is DELIBERATELY held: the generator polls job progress from
      the DB (0.5 s interval, bounded by move_poll_timeout) until every job
      is terminal, and only then emits the pending-count int + final status
    - success -> yield 0 (zero sub-operations): pynetdicom sends the final
      0000 immediately and opens no store_assoc
    - failure / cancel -> yield 1, then the honest final status (0xB000 or
      0xC000 / 0xFE00) with its (0008,0058) Identifier

    Pending C-MOVE-RSPs are optional (PS3.4 C.1.4) and the bridge does not
    send them: the final response is delayed until the transfer actually
    finishes (so its timing and statuses stay honest), and the final
    sub-operation counters reflect the sub-operations the DIMSE framework
    performed synchronously  -  which in this fire-and-forget model is zero.

    The reactor is freed only after the final response  -  NOT after dispatch:
    this protects SCUs that treat the final C-MOVE-RSP as "all stores done".

    Actual transfer runs in _cmove_worker thread pool.
    Real progress tracked via Prometheus metrics + job status.

    Self-delivery guard (2608): if the resolved Move Destination is the
    bridge's own DIMSE listener (host/port match incl. loopback aliases),
    the request is rejected with 0xA801 before any job is created.

    Poll timeout (2608): the progress poll is bounded by move_poll_timeout;
    on expiry unfinished jobs are finished as failed and 0xB000 is returned.
    """
    calling_ae = event.assoc.requestor.ae_title
    model_uid = str(event.context.abstract_syntax) if event.context else "?"

    # DEBUG: log full C-MOVE-RQ identifier to diagnose Weasis multi-study import
    ds = event.identifier
    patient_id = (
        str(getattr(ds, "PatientID", "")).strip() if hasattr(ds, "PatientID") else ""
    )
    study_uid = (
        str(getattr(ds, "StudyInstanceUID", "")).strip()
        if hasattr(ds, "StudyInstanceUID")
        else ""
    )
    logging.info(
        "[DIMSE] C-MOVE from %s model=%s PatientID=%s StudyUID=%s",
        calling_ae,
        model_uid,
        mask_patient_id(patient_id) if patient_id else "(none)",
        study_uid[:50] if study_uid else "(none)",
    )

    try:
        study_uids, move_dest_ae = _parse_c_move_rq(event)
    except ValueError as e:
        logging.warning("[C-MOVE] Parse error: %s", e)
        yield 0xC000, None
        return

    if peers_file:
        move_jobs.reload_peers_from_file(peers_file)

    calling_ip = event.assoc.requestor.address
    target = move_jobs.lookup_scp(move_dest_ae, client_ip=calling_ip)
    if target is None:
        logging.warning(
            "[C-MOVE] Unknown Move Destination: %s. Add '%s  <IP>:<port>' to peers.conf.",
            move_dest_ae,
            move_dest_ae,
        )
        yield 0xA801, None
        return

    target_host, target_port = target

    # P2 (2608): CIDR peers entries carry an informational host  -  the real
    # destination is the calling client itself (subnet match, PS3.4 sec.C.4.2.2).
    # Without substitution _associate_for_move would get the CIDR string and
    # silently fail to associate.
    if "/" in target_host:
        logging.info(
            "[C-MOVE] Move Destination %s: CIDR host %s is informational - "
            "routing via calling client IP %s.",
            move_dest_ae,
            target_host,
            calling_ip,
        )
        target_host = calling_ip

    # (2608): self-delivery guard  -  never C-STORE back into the bridge's
    # own DIMSE listener. Field incident: misconfigured peers.conf pointed
    # the Move Destination at the bridge itself; the bridge answered its own
    # C-STORE with success and the viewer received nothing.
    if _is_self_delivery_target(
        target_host, target_port, bridge_dimse_host, bridge_dimse_port
    ):
        logging.warning(
            "[C-MOVE] Move Destination %s resolves to the bridge itself "
            "(%s:%d) - rejecting with 0xA801 (self-delivery loop).",
            move_dest_ae,
            target_host,
            target_port,
        )
        yield 0xA801, None
        return

    if target_host != calling_ip:
        logging.warning(
            "[C-MOVE] IP MISMATCH: %s registered at %s but C-MOVE from %s.",
            move_dest_ae,
            target_host,
            calling_ip,
        )
        yield 0xA801, None
        return

    # create a job for EACH StudyInstanceUID in the request.
    # Weasis sends multiple StudyUIDs in one C-MOVE-RQ  -  process them all.
    job_ids = []
    for study_uid in study_uids:
        job_id = move_jobs.create_job(
            study_uid,
            move_dest_ae,
            target_host,
            target_port,
            expose_rejected=expose_rejected,
        )
        job_ids.append(job_id)
        logging.info(
            "[C-MOVE] Job #%d created for Study %s -> %s",
            job_id,
            study_uid,
            move_dest_ae,
        )

    logging.info(
        "[C-MOVE] Move Destination: %s -> %s:%d, Studies: %d (%s)",
        move_dest_ae,
        target_host,
        target_port,
        len(study_uids),
        ", ".join(study_uids),
    )

    # Set cancel callback on ALL jobs.
    #
    # `hasattr(event, "is_cancelled")` is NOT a harmless probe: on a
    # pynetdicom service event the name is a property that READS the
    # association's cancel state, and that read consumes a C-CANCEL already
    # received. Probing with it therefore discarded a cancel that arrived
    # before this point, and every later poll saw False. Presence is
    # decided on the TYPE, which never invokes the getter.
    #
    # The state is also LATCHED: one property read per poll writes True into a
    # holder both the poller and the worker read, so whichever of them asks
    # first cannot swallow the cancel out from under the other.
    class _CancelState:
        __slots__ = ("cancelled",)

        def __init__(self):
            self.cancelled = False

    _cancel_state = _CancelState()
    _has_cancel = getattr(type(event), "is_cancelled", None) is not None or (
        "is_cancelled" in getattr(event, "__dict__", {})
    )

    def _is_cancelled():
        # Read at most once per poll and remember a True: the property is
        # consumed by reading it, so a second reader in the same window would
        # otherwise see the state already drained.
        if _cancel_state.cancelled:
            return True
        if not _has_cancel:
            return False
        state = event.is_cancelled
        if state() if callable(state) else state:
            _cancel_state.cancelled = True
            return True
        return False

    for job_id in job_ids:
        move_jobs.set_job_cancel_callback(job_id, _is_cancelled)

    def _clear_callbacks():
        # The callback closes over `event` (and through it the association).
        # Leaving it in the registry keeps the whole request object alive for
        # the life of the process, so every cancel path drops it.
        for job_id in job_ids:
            move_jobs.clear_job_callback(job_id)

    # yield 1: (addr, port)  -  pynetdicom primes store_assoc
    yield (target_host, target_port)

    def _agg_failed_uids():
        """(0008,0058) material across all finished jobs (PS3.4 C.4.2.1.4.2)."""
        out = []
        for job_id in job_ids:
            getter = getattr(move_jobs, "get_job_failed_sops", None)
            if getter is None:
                continue
            try:
                for u in getter(job_id):
                    if u and u not in out:
                        out.append(u)
            except Exception:
                continue
        return out

    def _finish_jobs_cancelled():
        for job_id in job_ids:
            move_jobs.finish_job(
                job_id, success=False, error_message="Cancelled by SCU"
            )
            move_jobs_counter.labels(status="failed").inc()
        _clear_callbacks()

    # yield 2+: hold the DIMSE dialog (0.5 s DB poll, bounded by
    # move_poll_timeout) until every job is terminal  -  the final response is
    # not emitted until the transfer actually finishes. Pending C-MOVE-RSPs
    # are optional (PS3.4 C.1.4) and the bridge does not send them, so no
    # per-instance progress yield occurs; the pending-count int is emitted
    # only once the poll concludes.
    logging.info(
        "[C-MOVE] %d job(s) dispatched to worker (polling DB for progress)",
        len(job_ids),
    )

    # P3 (2608): bound the poll with an overall timeout. If a worker dies
    # between picking a job and finishing it, the viewer must get 0xB000
    # instead of a hung association.
    poll_started = time.monotonic()

    while True:
        if _is_cancelled():
            _finish_jobs_cancelled()
            # Non-empty sub-operation count so pynetdicom keeps the dialog
            # open for the Cancel status yield below.
            yield 1
            # PS3.4 Table C.4-2 FE00 Cancel; C.4.2.1.4.2: the Identifier
            # carries (0008,0058) Failed SOP Instance UID List (may be empty).
            yield 0xFE00, _failure_dataset(_agg_failed_uids())
            return

        # Aggregate terminal state across all jobs
        total_completed = 0
        all_finished = True
        any_failed = False
        for job_id in job_ids:
            completed, _total, status = move_jobs.get_job_progress(job_id)
            total_completed += completed
            if status not in ("success", "failed"):
                all_finished = False
            if status == "failed":
                any_failed = True

        if all_finished:
            if any_failed:
                # A terminal status carries NO sub-operations: the count is
                # what tells pynetdicom whether to open the move-destination
                # association before it reads the failure, and a non-zero
                # count there makes it associate once more - a failure of that
                # association then replaces the honest 0xB000/0xC000 with
                # 0xA801, and the (0008,0058) list never reaches the viewer.
                # `0` is the truthful count: nothing is still in flight.
                failed_uids = _agg_failed_uids()
                # Two yields, not one tuple: the reactor protocol is a bare
                # sub-operation count followed by (status, identifier), and a
                # bare 0 is the truthful count here.
                yield 0
                if total_completed == 0:
                    # Zero sub-operations completed: B000 ("Sub-operations
                    # Complete") would be a lie - say Failure (PS3.4 Table
                    # C.4-2, "Failed: Unable to process") with an honest
                    # Error Comment (PS3.4 C.4.2.1.4.2 Identifier).
                    comment = "Unable to process: no SOP instances delivered"
                    yield 0xC000, _failure_dataset(
                        failed_uids,
                        error_comment=comment,
                    )
                else:
                    # Partial: some sub-operations failed -> Warning (Table
                    # C.4-2) + (0008,0058) Failed SOP Instance UID List.
                    yield 0xB000, _failure_dataset(failed_uids)
            else:
                # All jobs succeeded: 0 sub-operations -> pynetdicom sends
                # the final 0000 immediately and opens NO store_assoc
                # (service_class.py:2136-2143 returns before the associate).
                yield 0
            _clear_callbacks()
            return

        # P3 (2608): poll timeout  -  finish unfinished jobs as failed, then
        # report the honest failure/warning. The reactor releases the
        # association after the final yields.
        if (
            move_poll_timeout is not None
            and time.monotonic() - poll_started >= move_poll_timeout
        ):
            timed_out_jobs = []
            for job_id in job_ids:
                _, _, job_status = move_jobs.get_job_progress(job_id)
                if job_status not in ("success", "failed"):
                    move_jobs.finish_job(
                        job_id, success=False, error_message="Move poll timeout"
                    )
                    move_jobs_counter.labels(status="failed").inc()
                    timed_out_jobs.append(job_id)
            # The worker streams instances and only finishes the job when it
            # runs out of them, so marking the row failed is not enough: it
            # would keep sending and then rewrite the row to success. The
            # cancel state is what the worker already polls per instance.
            _cancel_state.cancelled = True
            logging.warning(
                "[C-MOVE] Move poll timeout (%ds) expired: %d job(s) still "
                "unfinished (%s) - finished as failed, final status %s.",
                move_poll_timeout,
                len(timed_out_jobs),
                (
                    ", ".join(str(j) for j in timed_out_jobs)
                    if timed_out_jobs
                    else "(none)"
                ),
                "0xC000" if total_completed == 0 else "0xB000",
            )
            yield 0
            failed_uids = _agg_failed_uids()
            if total_completed == 0:
                # Nothing delivered before the poll timeout -> Failure, not a
                # "sub-operations complete" Warning (PS3.4 Table C.4-2).
                yield 0xC000, _failure_dataset(
                    failed_uids,
                    error_comment="Unable to process: no SOP instances delivered (move poll timeout)",
                )
            else:
                yield 0xB000, _failure_dataset(failed_uids)
            _clear_callbacks()
            return

        time.sleep(0.5)

# ---------------------------------------------------------------------------
# Bridge: Storage Commitment push after C-MOVE (CMP-008)
# ---------------------------------------------------------------------------
def _send_storage_commitment(
    move_dest_ae, target_host, target_port, sop_list, bridge_ae_title
):
    """Send N-ACTION Storage Commitment Request to move destination AE.

    Args:
        move_dest_ae: AE Title of the move destination (SCU)
        target_host: IP/hostname of the move destination
        target_port: port of the move destination
        sop_list: list of (sop_class_uid, sop_instance_uid) tuples
        bridge_ae_title: Bridge's own AE Title

    Returns:
        True if commitment request was sent successfully.
    """
    logging.info(
        "[C-MOVE-COMMIT] Sending Storage Commitment to %s@%s:%d for %d SOPs",
        move_dest_ae,
        target_host,
        target_port,
        len(sop_list),
    )

    ae = AE(ae_title=bridge_ae_title)
    # Storage Commitment is optional (PS3.4 sec.C.4.2.5). Fast-fail ACSE:
    # if viewer doesn't respond in 3s, it doesn't support SC. Don't
    # waste 10s on a feature that most viewers don't implement.
    ae.network_timeout = 5
    ae.acse_timeout = 3
    ae.dimse_timeout = 30
    ae.add_requested_context(StorageCommitmentPushModel)
    ae.add_requested_context(
        Verification
    )  # Fallback: allows association even if no SC support

    # suppress pynetdicom's "No accepted presentation contexts" ERROR  -
    # it's normal for SCPs that don't support Storage Commitment.
    global _suppress_pynetdicom
    _suppress_pynetdicom = True
    try:
        assoc = ae.associate(target_host, target_port, ae_title=move_dest_ae)
    finally:
        _suppress_pynetdicom = False

    if not assoc.is_established:
        logging.info(
            "[C-MOVE-COMMIT] SCP %s:%d unavailable - skipping Storage Commitment",
            target_host,
            target_port,
        )
        return False

    sc_accepted = any(
        str(ctx.abstract_syntax) == StorageCommitmentPushModel
        for ctx in assoc.accepted_contexts
    )
    if not sc_accepted:
        logging.info(
            "[C-MOVE-COMMIT] SCP %s does not support Storage Commitment - skipping",
            move_dest_ae,
        )
        _release_or_abort(assoc, timeout=2.0)
        return False

    try:
        # Build N-ACTION request dataset
        ds = Dataset()
        ds.TransactionUID = generate_uid()

        ref_seq = []
        for sop_class, sop_uid in sop_list:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            ref_seq.append(item)
        ds.ReferencedSOPSequence = ref_seq

        # Send N-ACTION with action type 1 (Storage Commitment Request)
        # pynetdicom 3.x signature: send_n_action(dataset, action_type, class_uid,
        #   meta_uid=None, instance_uid=None)
        # action_type=1 (PS3.4 sec.J.3.1), class_uid=StorageCommitmentPushModel.
        status, response = assoc.send_n_action(
            ds,
            1,  # action_type: Storage Commitment Request (PS3.4 sec.J.3.1)
            StorageCommitmentPushModel,
            instance_uid=ds.TransactionUID,
        )

        if status:
            status_code = status.Status if hasattr(status, "Status") else status
            if status_code == 0x0000:
                logging.info(
                    "[C-MOVE-COMMIT] %s: Storage Commitment %s.",
                    move_dest_ae,
                    _dimse_status_name(status_code),
                )
            else:
                # Any SC failure is non-fatal: the move already succeeded and
                # Storage Commitment is optional (PS3.4 C.4.2.5).
                logging.info(
                    "[C-MOVE-COMMIT] %s: Storage Commitment %s. "
                    "Non-fatal (SC optional, PS3.4 C.4.2.5).",
                    move_dest_ae,
                    _dimse_status_name(status_code),
                )
            return True
        else:
            logging.warning(
                "[C-MOVE-COMMIT] N-ACTION no status returned for %s",
                move_dest_ae,
            )
            return False
    except Exception as e:
        logging.warning(
            "[C-MOVE-COMMIT] N-ACTION failed for %s: %s",
            move_dest_ae,
            e,
        )
        return False
    finally:
        _release_or_abort(assoc, timeout=2.0)

# ---------------------------------------------------------------------------
# Lazy-load Clarus capabilities (GET /dicomweb) at first C-MOVE.
# Don't query at startup  -  server may not be running yet.
# Query on first use, cache result, fall back to defaults if unreachable.
# ---------------------------------------------------------------------------
_TS_NAMES = {
    "1.2.840.10008.1.2": "Implicit VR Little Endian",
    "1.2.840.10008.1.2.1": "Explicit VR Little Endian",
    "1.2.840.10008.1.2.1.99": "Deflated Explicit VR Little Endian",
    "1.2.840.10008.1.2.2": "Explicit VR Big Endian",
    "1.2.840.10008.1.2.4.50": "JPEG Baseline",
    "1.2.840.10008.1.2.4.51": "JPEG Extended",
    "1.2.840.10008.1.2.4.57": "JPEG Lossless SV1",
    "1.2.840.10008.1.2.4.70": "JPEG Lossless SV1 (first-order)",
    "1.2.840.10008.1.2.4.80": "JPEG-LS Lossless",
    "1.2.840.10008.1.2.4.81": "JPEG-LS Near-Lossless",
    "1.2.840.10008.1.2.4.90": "JPEG 2000 Lossless",
    "1.2.840.10008.1.2.4.91": "JPEG 2000",
    "1.2.840.10008.1.2.4.92": "JPEG 2000 Part 2",
    "1.2.840.10008.1.2.5": "RLE Lossless",
}

def _ts_name(uid):
    """Human-readable transfer syntax name for CAPS logging.

    Was a NameError before: the helper was called but never defined, so the
    whole caps fetch died and the bridge always fell back to passthrough.
    """
    return _TS_NAMES.get(uid, uid)

def _get_clarus_transfer_syntaxes(clarus_url, timeout=5.0, tls=None):
    """Query Clarus /dicomweb for transfer syntax capabilities.

    Result is cached in the function's closure after first success.

    IMPORTANT: CAPS announces only encode-capable
    transcode-target codecs. An empty CAPS means "no transcoding available,
    request without ?transferSyntax=, receive stored bytes as-is."
    Bridge MUST NOT invent capabilities the server doesn't claim.

    NB: "MUST NOT invent" applies to *compressed*
    transcode targets - we never refetch to a compressed TS the server did
    not announce. It does NOT exclude EVRLE: a transcode-capable server is
    expected to be able to return the standard default EVRLE representation
    (PS3.18 8.7.3.1), so `_pick_refetch_ts` adds EVRLE on its own when
    `server_ts_list` is non-empty. On a no-transcode server (this list empty)
    nothing - including EVRLE - is invented or requested.

    Args:
        clarus_url: Clarus DICOMweb base URL (single knob, 2908).
        timeout: HTTP request timeout in seconds.
        tls: optional (cert_path, key_path) tuple for mTLS.

    Returns:
        List of transfer syntax UID strings (empty if server can't transcode).
    """
    cache_key = clarus_url
    if not hasattr(_get_clarus_transfer_syntaxes, "cache"):
        _get_clarus_transfer_syntaxes.cache = {}
    cache = _get_clarus_transfer_syntaxes.cache
    cached_entry = cache.get(cache_key)
    if cached_entry:
        ts_list, cached_at = cached_entry
        if time.time() - cached_at < 60:
            return ts_list

    ts_list = []
    base = dicomweb_base(clarus_url)
    try:
        resp = requests.get(
            base,
            timeout=timeout,
            cert=tls,
        )
        resp.raise_for_status()
        caps = resp.json()
        tc_list = caps.get("transferCapabilities")
        if tc_list:
            for tc in tc_list:
                ts_list.extend(tc.get("transferSyntaxUid", []))
            ts_list = sorted(set(ts_list))
            logging.info(
                "[CAPS] %s -> %d transfer syntax(es):",
                base,
                len(ts_list),
            )
            for ts in ts_list:
                logging.info("[CAPS]   %s", _ts_name(ts))
        elif tc_list is not None:
            # Empty array []  -  server honestly reports: no transcoding.
            logging.info(
                "[CAPS] Server %s: empty transferCapabilities - "
                "passthrough mode (no transcoding, bridge will not request ?transferSyntax=)",
                clarus_url,
            )
        else:
            # null/absent  -  treat as empty (no transcode).
            logging.info(
                "[CAPS] Server %s: no transferCapabilities field - " "passthrough mode",
                clarus_url,
            )
    except Exception as e:
        logging.warning(
            "[CAPS] Clarus %s unreachable: %s - assuming passthrough mode",
            clarus_url,
            e,
        )
        ts_list = []

    _get_clarus_transfer_syntaxes.cache[cache_key] = (ts_list, time.time())
    return ts_list

# ---------------------------------------------------------------------------
# _associate_for_move  -  establish C-STORE association with target SCP
# ---------------------------------------------------------------------------
def _is_image_sop(sop_uid, sop_registry=None):
    """Check sop_registry for the non_image flag, fall back to the prefix
    heuristic. Non-image SOPs (SR/PR/RTSTRUCT) are always sent as-is."""
    if sop_registry and sop_uid in sop_registry:
        entry = sop_registry[sop_uid]
        if isinstance(entry, dict) and entry.get("non_image"):
            return False
    # Fallback prefix heuristic
    _PFX = (
        "1.2.840.10008.5.1.4.1.1.88.",
        "1.2.840.10008.5.1.4.1.1.11.",
        "1.2.840.10008.5.1.4.1.1.104.",
        "1.2.840.10008.5.1.4.1.1.66.",
    )
    _EXACT = {
        "1.2.840.10008.5.1.4.1.1.481.3",
        "1.2.840.10008.5.1.4.1.1.481.4",
        "1.2.840.10008.5.1.4.1.1.481.5",
        "1.2.840.10008.5.1.4.1.1.481.6",
        "1.2.840.10008.5.1.4.1.1.481.7",
        "1.2.840.10008.5.1.4.1.1.481.8",
        "1.2.840.10008.5.1.4.1.1.481.9",
    }
    if sop_uid in _EXACT:
        return False
    return not sop_uid.startswith(_PFX)

def _proposed_ts_per_class(sop_registry):
    """Yield the storage SOP classes (as UIDs) this bridge will propose on a
    C-MOVE outbound association.

    PS3.8 7.1.1.13: a presentation context = one abstract syntax + a list of
    transfer syntaxes. Proposing the SAME abstract syntax several times, once
    per transfer syntax (the multi-context shape), is conformance-legal and is
    exactly the arrangement PS3.7 C.2.2.1.1 wants: the C-STORE dataset is
    encoded in the negotiated transfer syntax of the presentation context that
    is used, so per-TS contexts let the bridge pick the context whose transfer
    syntax equals the instance's stored transfer syntax.
    """
    if sop_registry is not None:
        return list(_get_sop_registry_uids(sop_registry))
    return list(_BUILTIN_SOP_CLASSES())

# Context-ID budget for one A-ASSOCIATE (PS3.8 7.1.1.13: Presentation Context
# IDs are the odd bytes 1..255, so at most 128 contexts). 1 is reserved for
# the Storage Commitment context proposed on the main association.
_MAX_CONTEXTS = 128

def _trim_optional_ts(num_classes, has_sc, optional_tokens):
    """Return the subset of optional tokens that fit the 128-context budget.

    optional_tokens: list of (sop_class_uid, ts_uid, kind) in canonical
    ascending order, where kind is 'stored' (a class's stored TS from
    pre-flight) or 'fixed' (the 4.80/4.70 extras of the pre-flight-less path).
    Each class always keeps its 2 baselines (EVRLE, IVRLE), which are never
    dropped (they are the refetch targets).

    The class is part of the token because the budget is shared: dropping a
    token identified only by its transfer syntax would remove that syntax from
    EVERY class, so one overfull class would cost another class a syntax it
    actually needed.

    Real studies propose far fewer than 128 contexts; this runs only as a
    defensive trim. Drop order (spec 12 / R2): stored extras first in
    reverse canonical priority (lowest-priority stored TS first), and the
    4.80/4.70 'fixed' extras only after every stored extra is gone.
    """
    fixed = 1 if has_sc else 0
    budget = _MAX_CONTEXTS - fixed - (2 * num_classes)
    if budget >= len(optional_tokens):
        return optional_tokens
    # Victim order: stored extras dropped from the LOWEST canonical priority
    # (largest canonical rank) upward first; fixed extras only after all
    # stored extras are gone. `stored` group sorts before `fixed` so the
    # fixed 4.80/4.70 extras survive longer.
    _group = {"stored": 0, "fixed": 1}

    def _victim_key(item):
        _sop_uid, ts_uid, kind = item
        # within stored: drop higher canonical index first (lower priority)
        rank = canonical_ts_sort_key(ts_uid)
        return (_group.get(kind, 1), -rank)

    victims = sorted(optional_tokens, key=_victim_key)
    drop_n = len(optional_tokens) - budget
    dropped = {tok for tok in victims[: max(0, drop_n)]}
    return [tok for tok in optional_tokens if tok not in dropped]

# ---------------------------------------------------------------------------
# Per-peer job gate
# ---------------------------------------------------------------------------
# Two jobs toward the SAME peer are serialized (busy exclusion): the second
# waits only while the first is actively running and then starts
# immediately. There is no post-job cooldown; the gate opens as soon
# as the peer is free.
# No client-specific logic involved - the gate applies equally to any peer.
_ASSOC_GATE_LOCK = threading.Lock()
_ASSOC_BUSY = set()  # peers with a job currently between gate-enter/exit
# Peer -> monotonic time of the LAST "busy - waiting" DEBUG line (throttled
# to at most one per _ASSOC_GATE_LOG_INTERVAL seconds, C3).
_ASSOC_GATE_LOG_LAST = {}
_ASSOC_GATE_LOG_INTERVAL = 10.0

def _job_gate_enter(host, port, ae_title):
    """Serialise concurrent jobs toward the same peer (busy exclusion).

    Waits until the peer has no actively running job, then marks it busy and
    returns; there is no post-job cooldown (immediate start once free).

    Logging: the per-tick "busy - waiting" DEBUG line is throttled to
    no more than one per _ASSOC_GATE_LOG_INTERVAL (default 10 s) seconds per
    peer, and exactly ONE line is emitted on entry carrying the total time
    the caller waited for the peer.
    """
    key = (host, port, ae_title)
    started = time.monotonic()
    waited_any = False
    while True:
        with _ASSOC_GATE_LOCK:
            if key not in _ASSOC_BUSY:
                _ASSOC_BUSY.add(key)
                if waited_any:
                    logging.info(
                        "[ASSOC-GATE] %s@%s:%s waited %.1fs for the peer",
                        ae_title,
                        host,
                        port,
                        time.monotonic() - started,
                    )
                return
            waited_any = True
        # Sleep OUTSIDE the lock so other workers can gate.
        now = time.monotonic()
        with _ASSOC_GATE_LOCK:
            last = _ASSOC_GATE_LOG_LAST.get(key, 0.0)
            if now - last >= _ASSOC_GATE_LOG_INTERVAL:
                _ASSOC_GATE_LOG_LAST[key] = now
                logging.debug(
                    "[ASSOC-GATE] %s@%s:%s busy - waiting for it to free",
                    ae_title,
                    host,
                    port,
                )
        time.sleep(0.05)

def _job_gate_exit(host, port, ae_title):
    """Release the peer so the next queued job to it can start."""
    key = (host, port, ae_title)
    with _ASSOC_GATE_LOCK:
        _ASSOC_BUSY.discard(key)
        # Drop the throttle timestamp so the next wait starts clean.
        _ASSOC_GATE_LOG_LAST.pop(key, None)

def _associate_for_move(
    move_dest_ae,
    bridge_ae_title,
    sop_registry,
    target_host,
    target_port,
    network_timeout=60,
    dimse_timeout=60,
    acse_timeout=15,
    outbound_assoc_attempts=3,
    study_ts_by_class=None,
):
    """Establish C-STORE association with target SCP (multi-context).

    Standard-shaped negotiation (PS3.8 7.1.1.13 +
    9.3.2.2, PS3.7 C.2.2.1.1): each SOP class is proposed as ONE presentation
    context per transfer syntax, in canonical order (uncompressed family
    first, then compressed). This lets the acceptor accept exactly the
    transfer syntaxes it supports and the SCU pick the context whose TS
    matches each instance's stored TS.

    Proposal per class:
    - WITH pre-flight (`study_ts_by_class` set): [EVRLE, IVRLE] + the class's
      stored TS set from the pre-flight (single-TS contexts, dedup).
    - WITHOUT pre-flight: [EVRLE, IVRLE, 4.80, 4.70] (today's IMAGE_TS as
      separate contexts - preserves the negotiated outcomes of 4.80-capable
      receivers; see test_bridge_ts_order.py).
    Non-image classes (SR/PR/RTSTRUCT) keep the uncompressed family plus any
    stored extras seen.

    Budget: total contexts + Storage Commitment <= 128 (PS3.8, PCID 1..255
    odd). Overflow trims stored extras in reverse canonical priority, then the
    4.80/4.70 extras; EVRLE/IVRLE are never trimmed (refetch targets).

    Args:
        move_dest_ae: AE Title of the move destination.
        bridge_ae_title: Bridge's own AE Title.
        sop_registry: SOP class registry dict.
        target_host: IP/hostname of the move destination.
        target_port: port of the move destination.
        network_timeout: socket-level (outbound, viewer may be slow).
        dimse_timeout: per C-STORE response (outbound).
        acse_timeout: A-ASSOCIATE negotiation.
        outbound_assoc_attempts: total A-ASSOCIATE attempts (main), immediate.
        study_ts_by_class: dict[sop_class -> set[ts]] from pre-flight, or None.

    Returns:
        (assoc, accepted_contexts_map) tuple.
        accepted_contexts_map: dict[sop_class_uid -> SET[ts]].

    Raises:
        RuntimeError if association fails after all attempts.
    """
    ae = AE(ae_title=bridge_ae_title)
    ae.network_timeout = network_timeout
    ae.acse_timeout = acse_timeout
    ae.dimse_timeout = dimse_timeout

    # Proposal is shaped from the canonical order: uncompressed family first,
    # then compressed in the taxonomy order (RLE, JPEG lossless, JPEG-LS,
    # JPEG lossy, JPEG 2000). Deterministic proposer order; a
    # conforming acceptor (PS3.8 9.3.2.2) accepts per-context by its own
    # support set, so proposer order is not a correctness input for standard
    # peers - only deterministic output for the bridge.
    # Field-observed: the registry-wide proposal
    # overflows the 128-context budget. With pre-flight knowledge the
    # proposal covers ONLY the classes the study actually contains
    # (PS3.18 10.4.4 metadata is per-instance, so its class map is the
    # study's real class set); the pre-flight-less legacy path keeps the
    # registry-wide proposal, subject to the whole-class budget drop
    # below.
    has_preflight = bool(study_ts_by_class)
    if has_preflight:
        class_uids = sorted(study_ts_by_class.keys())
    else:
        class_uids = _proposed_ts_per_class(sop_registry)
    # Per-class optional (non-baseline) TS, in canonical ascending order, each
    # tagged 'stored' (from pre-flight) or 'fixed' (4.80/4.70, no pre-flight).
    per_class_optional = {}
    for sop_uid in class_uids:
        is_image = _is_image_sop(sop_uid, sop_registry)
        if has_preflight:
            stored = set(study_ts_by_class.get(sop_uid, set()) or set())
            stored = {
                t
                for t in stored
                if t not in (ExplicitVRLittleEndian, ImplicitVRLittleEndian)
            }
            per_class_optional[sop_uid] = [
                (sop_uid, t, "stored")
                for t in sorted(stored, key=canonical_ts_sort_key)
            ]
        else:
            extra = [JPEGLS_LOSSLESS_TS, "1.2.840.10008.1.2.4.70"] if is_image else []
            per_class_optional[sop_uid] = [
                (sop_uid, t, "fixed")
                for t in extra
                if t not in (ExplicitVRLittleEndian, ImplicitVRLittleEndian)
            ]
    flat = [tok for cls in per_class_optional.values() for tok in cls]
    kept_tokens = set(_trim_optional_ts(len(class_uids), True, flat))
    proposals = {}
    for sop_uid in class_uids:
        ts_list = [ExplicitVRLittleEndian, ImplicitVRLittleEndian]
        for tok in per_class_optional[sop_uid]:
            if tok in kept_tokens and tok[1] not in ts_list:
                ts_list.append(tok[1])
        proposals[sop_uid] = ts_list

    # PS3.8 7.1.1.13: PCIDs are the odd bytes 1..255 -> at most 128
    # contexts, one reserved for Storage Commitment. Baselines alone can
    # overflow on the registry-wide (pre-flight-less) proposal: drop WHOLE
    # classes from the END of the list (reverse registry priority) until
    # the budget fits. Never truncate a class's own baseline pair -
    # EVRLE/IVRLE are the refetch targets (spec R2).
    budget = _MAX_CONTEXTS - 1  # Storage Commitment slot
    while sum(len(v) for v in proposals.values()) > budget:
        if not proposals:
            raise RuntimeError("presentation-context budget cannot fit")
        dropped_cls, dropped_ts = proposals.popitem()
        logging.info(
            "[C-MOVE] 128-context budget (PS3.8 7.1.1.13): dropped class "
            "%s (%d TS contexts) from the proposal",
            dropped_cls,
            len(dropped_ts),
        )

    # ----- add requested contexts -----
    contexts_req = 0
    for sop_uid in proposals:
        for ts_uid in proposals[sop_uid]:
            ae.add_requested_context(sop_uid, ts_uid)
            contexts_req += 1
    contexts_dropped = len(flat) - len(kept_tokens)

    # Storage Commitment on the main association, as today (a separate SC
    # association burned ACSE timeouts; see _send_storage_commitment).
    ae.add_requested_context(StorageCommitmentPushModel)

    # ----- main association with retries (single config knob) + outcome -----
    # Classify the associate() outcome. pynetdicom 3.0.4 returns a
    # non-established Association for TCP connect-refused/RST/timeout AND for
    # ACSE silence (the latter two are indistinguishable at the API boundary,
    # both `is_established == False`); it RAISES only for terminal local/
    # lookup/transport errors (e.g. socket.gaierror on DNS). Therefore:
    #   * an exception from associate()  -> TERMINAL transport -> NO retry
    #     (immediate failure; retrying a dead/unresolvable peer is only noise -
    #      PS3.8 9.1.4 Note 2: retry policy is implementation freedom);
    #   * a non-established return        -> ACSE-retry per outbound_assoc_attempts
    #     (a live peer whose ACSE is momentarily silent may come back, existing
    #      behaviour). Refused and silent are indistinguishable at this API
    #      boundary, so both take the retry path.
    attempts = max(1, int(outbound_assoc_attempts or 3))
    assoc = None
    outcome = None  # 'established' | 'acse-retry' | 'terminal' (last attempt)
    for attempt in range(1, attempts + 1):
        try:
            assoc = ae.associate(target_host, target_port, ae_title=move_dest_ae)
        except (OSError, RuntimeError) as _tcp_err:
            # Terminal transport: connection refused/RST/DNS/lookup surfaced as
            # an exception - no point retrying a peer/protocol that is down.
            outcome = "terminal"
            logging.error(
                "[C-MOVE] %s@%s:%s: terminal transport (attempt %d/%d) - "
                "not retrying: %s: %s",
                move_dest_ae,
                target_host,
                target_port,
                attempt,
                attempts,
                type(_tcp_err).__name__,
                _tcp_err,
            )
            raise RuntimeError(
                f"Cannot associate with {move_dest_ae} at "
                f"{target_host}:{target_port} - terminal transport "
                f"({type(_tcp_err).__name__}: {_tcp_err})"
            ) from _tcp_err
        if assoc.is_established:
            try:
                associations_total.labels(role="to", ae=ae_label(move_dest_ae)).inc()
            except Exception:
                pass
            outcome = "established"
            break
        # ACSE silence / refused-RST swallowed to a non-established return:
        # retry per the single knob (immediate), PS3.8 9.1.4 Note 2.
        logging.info(
            "[C-MOVE] %s@%s:%s main association not established "
            "(attempt %d/%d) - acse-retry immediately (PS3.8 9.1.4 Note 2: "
            "retry policy is implementation freedom)",
            move_dest_ae,
            target_host,
            target_port,
            attempt,
            attempts,
        )
        outcome = "acse-retry"
    if not assoc or not assoc.is_established:
        raise RuntimeError(
            f"Cannot associate with {move_dest_ae} at {target_host}:{target_port}"
        )

    # Build set-valued map: dict[sop_class_uid -> SET[ts]] - a rejected
    # context for one TS must not erase another accepted TS of the same class.
    accepted_contexts_map = {}
    for ctx in assoc.accepted_contexts:
        sop_uid = str(ctx.abstract_syntax)
        ts_uid = str(ctx.transfer_syntax[0]) if ctx.transfer_syntax else None
        if ts_uid:
            accepted_contexts_map.setdefault(sop_uid, set()).add(ts_uid)
    contexts_acc = sum(len(v) for v in accepted_contexts_map.values())
    logging.info(
        "[C-MOVE] Association with %s: contexts_req=%d contexts_acc=%d "
        "contexts_dropped=%d assocs=%d attempts[1/%d] outcome=%s",
        move_dest_ae,
        contexts_req,
        contexts_acc,
        contexts_dropped,
        1,
        attempts,
        outcome or "established",
    )
    return assoc, accepted_contexts_map

# ---------------------------------------------------------------------------
# _ensure_file_meta_bytes - synthesize/rewrite group 0002 (canonical trio)
# ---------------------------------------------------------------------------
_LONG_VRS = {
    b"OB",
    b"OD",
    b"OF",
    b"OL",
    b"OV",
    b"OW",
    b"SQ",
    b"UC",
    b"UN",
    b"UR",
    b"UT",
}

def _meta_data_start(dicom_bytes):
    """Preamble-aware start of the meta group: 132 (full preamble), 4
    (bare DICM) or 0 (no magic at all)."""
    if len(dicom_bytes) >= 132 and dicom_bytes[128:132] == b"DICM":
        return 132
    if len(dicom_bytes) >= 4 and dicom_bytes[:4] == b"DICM":
        return 4
    return 0

def _walk_meta(dicom_bytes):
    """Walk group 0002 (explicit VR LE); return (data_start, elements,
    meta_end). Reader-side tolerance: the value skip is vlen + (vlen % 2),
    so old externally-padded files keep parsing."""
    data_start = _meta_data_start(dicom_bytes)
    pos = data_start
    elems = []
    while pos + 8 <= len(dicom_bytes):
        group = struct.unpack_from("<H", dicom_bytes, pos)[0]
        if group != 0x0002:
            break
        elem = struct.unpack_from("<H", dicom_bytes, pos + 2)[0]
        vr = dicom_bytes[pos + 4 : pos + 6]
        if vr in _LONG_VRS:
            if pos + 12 > len(dicom_bytes):
                break
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
            vo = pos + 12
        else:
            vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
            vo = pos + 8
        if vo + vlen > len(dicom_bytes):
            break
        elems.append((elem, dicom_bytes[vo : vo + vlen]))
        pos = vo + vlen + (vlen % 2)
    return data_start, elems, pos

def _ui_elem(elem, value):
    """One canonical UI meta element (3008): even length with the trailing
    NULL INSIDE the length (PS3.5 sec 6.2), no external pad byte."""
    v = value.encode("ascii") if isinstance(value, str) else bytes(value)
    if len(v) % 2:
        v += b"\x00"
    return struct.pack("<HH2sH", 0x0002, elem, b"UI", len(v)) + v

def _extract_meta_ui(dicom_bytes, elem):
    """Byte-level read of the source meta group for (0002,elem), explicit
    VR LE, preamble-aware. Returns the UID string or None."""
    _, elems, _ = _walk_meta(dicom_bytes)
    for e, value in elems:
        if e == elem:
            raw = value.rstrip(b"\x00 ").decode("ascii", "replace")
            return raw if raw else None
    return None

def _skip_undefined_element(dicom_bytes, value_off, implicit_vr=False):
    """Skip an undefined-length body (SQ/UN element or item content):
    walks items AND raw dataset elements until the enclosing sequence
    delimitation item (FFFE,E0DD). Undefined-length items and elements
    recurse; an item delimitation item (FFFE,E00D) ends only the inner
    body, a sequence delimitation ends ALL enclosing bodies (the
    ZONARE 0109 shape omits E00D). implicit_vr: elements carry NO VR
    field (tag + 4-byte LE length); items and delimitation codes are
    identical in both encodings. Returns (offset, is_final): offset
    AFTER the terminator (None on malformed bytes), is_final=True when
    the terminator was E0DD."""
    p = value_off
    n = len(dicom_bytes)
    while p + 8 <= n:
        g = struct.unpack_from("<H", dicom_bytes, p)[0]
        e = struct.unpack_from("<H", dicom_bytes, p + 2)[0]
        if (g, e) == (0xFFFE, 0xE0DD):  # sequence delimitation
            return p + 8, True
        if (g, e) == (0xFFFE, 0xE00D):  # item delimitation
            return p + 8, False
        if (g, e) == (0xFFFE, 0xE000):  # item
            it_len = struct.unpack_from("<I", dicom_bytes, p + 4)[0]
            if it_len == 0xFFFFFFFF:
                p, final = _skip_undefined_element(
                    dicom_bytes,
                    p + 8,
                    implicit_vr,
                )
                if p is None:
                    return None, False
                if final:
                    return p, True  # E0DD closed this body too
                continue
            p = p + 8 + it_len + (it_len % 2)
            continue
        # Regular dataset element (explicit or implicit VR LE).
        if implicit_vr:
            if p + 8 > n:
                return None, False
            vlen = struct.unpack_from("<I", dicom_bytes, p + 4)[0]
            vo = p + 8
        else:
            vr = dicom_bytes[p + 4 : p + 6]
            if vr in _LONG_VRS:
                if p + 12 > n:
                    return None, False
                vlen = struct.unpack_from("<I", dicom_bytes, p + 8)[0]
                vo = p + 12
            else:
                vlen = struct.unpack_from("<H", dicom_bytes, p + 6)[0]
                vo = p + 8
        if vlen == 0xFFFFFFFF:
            p, final = _skip_undefined_element(dicom_bytes, vo, implicit_vr)
            if p is None:
                return None, False
            if final:
                return p, True
        else:
            if vo + vlen > n:
                return None, False
            p = vo + vlen + (vlen % 2)
    return None, False

def _extract_dataset_ui(dicom_bytes, elem, group=0x0008, implicit_vr=False):
    """Byte-level scan of the top-level dataset for (group,elem) - SOP
    Class UID (0x0008,0x0016) / SOP Instance UID (0x0008,0x0018) /
    Series UID (0x0020,0x000E). Explicit VR LE by default; implicit_vr
    reads elements WITHOUT the VR field (tag + 4-byte LE length - the
    stored IVRLE shape). Undefined-length elements
    (SQ/UN) are skipped over their item lists (0109 field: ZONARE
    (0008,2112) SQ stopped the scan before (0020,000E) and killed the
    C-MOVE refetch rescue)."""
    pos = _meta_data_start(dicom_bytes)
    # Skip the meta group (always explicit VR LE).
    while pos + 8 <= len(dicom_bytes):
        g = struct.unpack_from("<H", dicom_bytes, pos)[0]
        if g != 0x0002:
            break
        vr = dicom_bytes[pos + 4 : pos + 6]
        if vr in _LONG_VRS:
            if pos + 12 > len(dicom_bytes):
                return None
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
            vo = pos + 12
        else:
            vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
            vo = pos + 8
        pos = vo + vlen + (vlen % 2)
    # Walk the dataset (explicit or implicit VR LE).
    while pos + 8 <= len(dicom_bytes):
        g = struct.unpack_from("<H", dicom_bytes, pos)[0]
        e = struct.unpack_from("<H", dicom_bytes, pos + 2)[0]
        if implicit_vr:
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 4)[0]
            vo = pos + 8
        else:
            vr = dicom_bytes[pos + 4 : pos + 6]
            if vr in _LONG_VRS:
                if pos + 12 > len(dicom_bytes):
                    break
                vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
                vo = pos + 12
            else:
                vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
                vo = pos + 8
        if vlen == 0xFFFFFFFF:
            # Undefined-length element (SQ/UN): skip the item list to
            # the delimitation item - UIDs never live inside items.
            after, _final = _skip_undefined_element(
                dicom_bytes,
                vo,
                implicit_vr,
            )
            if after is None:
                break
            pos = after
            continue
        if vo + vlen > len(dicom_bytes):
            break
        if (g, e) == (group, elem):
            raw = dicom_bytes[vo : vo + vlen].rstrip(b"\x00 ")
            s = raw.decode("ascii", "replace")
            return s if s else None
        pos = vo + vlen + (vlen % 2)
    return None

def _ensure_file_meta_bytes(dicom_bytes, sop_class_uid, sop_uid, ts_uid):
    """Return bytes whose meta group is the canonical ascending trio -
    (0002,0002) MediaStorageSOPClassUID, (0002,0003)
    MediaStorageSOPInstanceUID, (0002,0010) TransferSyntaxUID LAST - each
    Explicit VR LE UI with an even value length and the trailing NULL
    INSIDE the length (PS3.5 sec 6.2).

    cltranscode-stored files have NO group 0002 at
    all, and the server's transcoded WADO response copies that gap.
    pynetdicom `send_c_store` then refuses the file and the whole C-MOVE
    dies with 0xB000.

    ONE canonical writer. UID resolution order: (a) byte-level meta
    group, (b) byte-level dataset scan for (0008,0016)/(0008,0018),
    (c) the pydicom-parsed value. A parser returning '' never suppresses
    (0002,0003). If the existing meta group is already byte-exactly the
    canonical trio, the input is returned unchanged; otherwise the WHOLE
    group is replaced (never spliced after non-ascending or
    externally-padded elements).
    """
    data_start = _meta_data_start(dicom_bytes)
    if len(dicom_bytes) >= 132 and dicom_bytes[128:132] == b"DICM":
        prefix = dicom_bytes[:132]
    elif len(dicom_bytes) >= 4 and dicom_bytes[:4] == b"DICM":
        prefix = dicom_bytes[:4]
    else:
        # No DICM magic at all: build a full preamble (pynetdicom reads
        # files, DICM expected).
        prefix = b"\x00" * 128 + b"DICM"

    _, existing, meta_end = _walk_meta(dicom_bytes)

    # 02.09 field Job #38: ts_uid==IVRLE means the dataset bytes are
    # implicit VR (no VR field). The meta group is ALWAYS explicit, so
    # only the dataset fallback scans switch encoding.
    _implicit = ts_uid == ImplicitVRLittleEndian
    resolved_sc = (
        _extract_meta_ui(dicom_bytes, 0x0002)
        or _extract_dataset_ui(dicom_bytes, 0x0016, implicit_vr=_implicit)
        or (sop_class_uid or None)
    )
    resolved_si = (
        _extract_meta_ui(dicom_bytes, 0x0003)
        or _extract_dataset_ui(dicom_bytes, 0x0018, implicit_vr=_implicit)
        or (sop_uid or None)
    )
    ts = ts_uid or "1.2.840.10008.1.2.1"

    trio = b""
    if resolved_sc:
        trio += _ui_elem(0x0002, resolved_sc)
    if resolved_si:
        trio += _ui_elem(0x0003, resolved_si)
    trio += _ui_elem(0x0010, ts)

    if dicom_bytes[data_start:meta_end] == trio:
        return dicom_bytes
    return prefix + trio + dicom_bytes[meta_end:]

def _pick_refetch_ts(accepted_ts_for_class, server_ts_list):
    """Choose the refetch transfer syntax for a stored-not-accepted instance.

    The bridge NEVER opens a second/probe association; a stored TS the viewer
    did not accept is delivered only if the server can produce an accepted TS.
    The refetch target is drawn from the intersection of the viewer's accepted
    set for the class and the server's producible set (caps). Priority within
    that intersection: EVRLE, then IVRLE, then any remaining accepted TS
    (deterministic order).

    The caps endpoint declares only the compressed transcode-target codecs and
    does NOT declare EVRLE/IVRLE, yet a server that serves `?transferSyntax=`
    (transcode-capable) requests is expected to be able to return an
    uncompressed form. PS3.18 8.7.3.1 (Table 8.7.3-2) makes Explicit VR Little
    Endian the Default (D) media-type transfer syntax for Image/Video/Text/Other
    instances and returns it "unless the origin server has only access to the
    pixel data in lossy compressed form or ... such length that it cannot be
    encoded in the Explicit VR Little Endian Transfer Syntax" - i.e. EVRLE is
    the standard default representation, not an optional transcode target, so a
    transcode-capable origin server can be expected to produce it.
    Therefore, when the server reports transcode capabilities
    (`server_ts_list` non-empty) EVRLE is treated as producible and added to
    the candidate set before the intersection - a transcode build has an EVRLE
    encoder. This is not inventing a capability. If the server in fact cannot
    produce EVRLE the refetch itself returns 406 and the instance fails
    honestly (the same outcome as before, so this cannot regress). When
    `server_ts_list` is EMPTY (a no-transcode server) EVRLE is NOT added -
    nothing can be transcoded, a refetch call would be wasted, and the
    instance fails honestly as today.

    Returns the chosen TS UID, or '' when no deliverable form exists (the
    caller must fail the instance honestly).
    """
    if isinstance(accepted_ts_for_class, str):
        acc = {accepted_ts_for_class} if accepted_ts_for_class else set()
    elif isinstance(accepted_ts_for_class, (list, tuple)):
        acc = set(accepted_ts_for_class)
    else:
        acc = set(accepted_ts_for_class or set())
    prod = set(server_ts_list or [])
    if prod:
        # A transcode-capable origin server is expected to be able to produce
        # EVRLE (PS3.18 8.7.3.1: EVRLE is the Default D transfer syntax for
        # image instances). EVRLE is never invented on a no-transcode server
        # (prod empty below).
        prod.add(ExplicitVRLittleEndian)
    cand = acc & prod
    if not cand:
        return ""
    for ts in (ExplicitVRLittleEndian, ImplicitVRLittleEndian):
        if ts in cand:
            return ts
    return sorted(cand)[0]

def _decide_send_path(accepted_ts_for_class, actual_ts, is_image):
    """Pure per-instance send-path decision (no probe is ever opened).

    Returns 'send_as_is' (C-STORE the stored bytes on the main association
    - the stored TS is accepted by the viewer, or it is a non-image SOP, or
    the stored TS is unknown) or 'needs_deliver' (a stored TS the viewer did
    NOT accept on the main association - the caller then chooses a
    deliverable refetch TS via `_pick_refetch_ts`, or fails the instance
    honestly when the server cannot produce one).

    obligation: the bridge NEVER opens a probe / second association to a
    C-MOVE destination. The fallback path is gone; the only outcomes per
    stored-not-accepted image are refetch on the MAIN association (if the
    server can produce an accepted TS) or an honest per-instance failure with
    reason (no silent drops).
    """
    if not is_image:
        return "send_as_is"
    if not actual_ts:
        return "send_as_is"
    accepted = accepted_ts_for_class
    if isinstance(accepted, str):
        accepted = {accepted} if accepted else set()
    elif isinstance(accepted, (list, tuple)):
        accepted = set(accepted)
    else:
        accepted = accepted or set()
    if accepted and actual_ts in accepted:
        return "send_as_is"
    return "needs_deliver"

def _pydicom_file_meta_ts(dicom_bytes):
    """Last-resort transfer-syntax read (pydicom). Used ONLY when neither
    the part Content-Type parameter nor the byte-level (0002,0010) read
    produced a TS. Returns '' on any failure."""
    try:
        ds = dcmread(io.BytesIO(dicom_bytes), stop_before_pixels=True)
        return str(
            getattr(getattr(ds, "file_meta", None), "TransferSyntaxUID", "") or ""
        )
    except Exception:
        return ""

# ---------------------------------------------------------------------------
# _stream_and_send_study  -  stream study from Clarus, send via C-STORE
# ---------------------------------------------------------------------------
def _stream_and_send_study(
    assoc,
    study_uid,
    clarus_url,
    http_timeout,
    move_jobs,
    job_id,
    accepted_contexts_map=None,
    server_ts_list=None,
    sop_registry=None,
    tls=None,
    spill_threshold=SPILL_THRESHOLD,
    peer_ae="",
    _skip_ids=None,
    _resumed=False,
    _report_lost=False,
    expose_rejected=False,
    qa_url="",
):
    """Stream study from Clarus via WADO-RS, send via C-STORE.

    stored-first: ONE study-level streaming multipart GET WITHOUT
    ?transferSyntax= (stored bytes, zero server CPU). Per instance the
    stored transfer syntax is decided byte-level.

    The bridge NEVER opens a probe / second association to a C-MOVE
    destination. Delivery per instance follows the negotiation result on the
    MAIN association:
    - stored TS accepted -> send_as_is (passthrough);
    - stored TS not accepted AND the server can produce an accepted TS (the
      intersection of the viewer's accepted set and the server caps) ->
      refetch the instance on the MAIN association with ?transferSyntax=
      (priority EVRLE -> IVRLE -> any);
    - otherwise -> an honest per-instance failure (the undelivered SOP UID
      lands in the (0008,0058) list of the final response).

    Resume: on an association loss the driver re-associates ONCE and calls
    this function a SECOND time with *_skip_ids* = the SOP UIDs already
    delivered on the first pass (they are refused a re-send, so every instance
    is delivered exactly once), *_resumed*=True (adds resumed=1 to the final
    INFO), and *_report_lost=True so this pass can report a further association
    loss via a trailing boolean. A resumed pass issues a FRESH study-level GET
    (a conformant continuation - PS3.7 9.1.4.2 (e) sub-operations may occur on
    a different Association than the C-MOVE; PS3.8 9.1.4 Note 2 + 9.1.5
    re-association freedom). When *_report_lost* is False the returned tuple
    has the historical 7 elements; when True an 8th element `lost` (0/1) is
    appended so the driver can tell "association lost again -> GIVE_UP".

    sop_registry: SOP class registry for image/non-image classification.
    spill_threshold: multipart parser spill threshold (W3); tests inject a
    small value, production uses the 16 MB default.

    Returns (completed, failed, total, sent_sop_uids, failed_sop_uids,
             cancelled, no_common_ts[, lost]). failed_sop_uids = the SOP
    instance UIDs that were seen and not delivered in THIS pass (PS3.4
    C.4.2.1.4.2 material); the driver reconciles the (0008,0058) tail across
    passes from the study-level list.
    """
    completed = 0
    failed = 0
    total = 0
    total_bytes = 0
    passthrough = 0
    transcoded = 0
    refetched = 0
    sent_sop_uids = []
    # 0709: every SOP instance UID this job attempted, so the failed set
    # (seen minus delivered) feeds the (0008,0058) Failed SOP Instance UID
    # List on the final C-MOVE-RSP (PS3.4 C.4.2.1.4.2).
    seen_sop_uids = set()

    def _out(cancelled=False, no_common=False, lost=False):
        """Assemble the return tuple; a `lost` element is appended ONLY when
        the driver requested it via `_report_lost` (test_spill unpacks the
        historical 7 elements and does not set `_report_lost`). The
        (0008,0058) tail is computed here from the current seen/delivered
        sets so the helper has no forward dependency."""
        _d = {u for _c, u in sent_sop_uids if u}
        _f = sorted(u for u in seen_sop_uids if u not in _d)
        base = (completed, failed, total, sent_sop_uids, _f, cancelled, no_common)
        if _report_lost:
            return base + (lost,)
        return base

    # Negotiate transfer syntax between viewer and server
    server_ts = server_ts_list if server_ts_list else []
    if accepted_contexts_map is not None and not accepted_contexts_map:
        # No accepted presentation context and therefore no refetch target.
        # The job finishes failed with zero slices delivered and the C-MOVE
        # generator reports a Failure (0xC000, PS3.4 Table C.4-2 "Failed:
        # Unable to process") - the wire status and this log agree. 0xC001
        # stayed a log-only claim in the past; it is NOT a response status.
        logging.warning(
            "[C-MOVE] Viewer accepted no presentation contexts - "
            "no common transfer syntax; job fails with 0 slices, "
            "C-MOVE-RSP is a Failure (0xC000)",
        )
        return _out(no_common=True)
    if server_ts:
        # Stored-first: the study-level GET NEVER carries
        # ?transferSyntax=. The server can transcode; per-instance
        # refetch picks a target from the accepted set.
        logging.info(
            "[C-MOVE] Server transcode available (%d TS); streams stored "
            "bytes; not-accepted instances refetch on the main association",
            len(server_ts),
        )
    else:
        # Passthrough mode: server has no transcode capabilities. Don't
        # request ?transferSyntax=. Server returns stored bytes as-is. The
        # bridge forwards whatever it receives; a stored TS the viewer did
        # not accept cannot be produced -> honest per-instance failure.
        logging.info(
            "[C-MOVE] Passthrough mode - server has no transcode; stored "
            "bytes only, not-accepted instances fail honestly",
        )

    # ONE study-level streaming GET WITHOUT ?transferSyntax=.
    accept_value = "multipart/related; type=application/dicom"
    # The study UID goes into the path through `_quote`: it is client input, and
    # `1.2?a=b` or `../x` in one would steer the GET at a different resource.
    url = (
        f"{service_base_url(clarus_url, qa_url, expose_rejected)}"
        f"/studies/{_quote(study_uid, safe='')}"
    )
    headers = {"Accept": accept_value}

    logging.info("[C-MOVE] Streaming study %s from DICOMweb server...", study_uid)
    resp = requests.get(
        url, headers=headers, timeout=http_timeout, stream=True, cert=tls
    )
    resp.raise_for_status()

    # B1 (2508): a reader thread prefetches the streamed multipart parts into a
    # bounded FIFO while this sender loop C-STORE-s them - the serial pipeline
    # left the Clarus server leg idle during each network C-STORE. Structural
    # backpressure is the bounded queue (4 parts ~ 20 MB, FIFO). The sender
    # loop below is unchanged; every early return must stop the reader thread.
    prefetch = PartPrefetcher(
        _stream_multipart_instances(resp, spill_threshold=spill_threshold)
    ).start()

    import os as _os
    import tempfile

    def _refetch_and_send(
        idx, sop_uid, sop_class_uid, actual_ts, refetch_ts, series_uid, peer_ae=""
    ):
        """Per-instance refetch + C-STORE on the MAIN association.

        Called when the stored TS is not accepted but a deliverable TS exists
        (the caller passes `refetch_ts` chosen from the accepted x server
        intersection via `_pick_refetch_ts` - never a probe/second
        association). A series UID is required to build the instance URL.
        Updates the refetched/failed counters and returns the C-STORE status
        (None = failure already counted).
        """
        nonlocal refetched, failed
        if not (refetch_ts and series_uid):
            reason = (
                "no series UID for the instance URL"
                if not series_uid
                else "no accepted refetch TS for this class"
            )
            logging.warning(
                "[C-MOVE] Instance %d (%s): stored TS %s not accepted "
                "and refetch impossible (%s) - counted failed",
                idx,
                sop_uid,
                actual_ts,
                reason,
            )
            failed += 1
            return None
        refetched += 1
        # Every UID goes into the path through `_quote`: a UID is not trusted
        # input just because it arrived over DIMSE, and `1.2?a=b` or `../x` in
        # one would steer the GET at a different resource than the instance the
        # peer asked for.
        inst_url = (
            f"{service_base_url(clarus_url, qa_url, expose_rejected)}"
            f"/studies/{_quote(study_uid, safe='')}"
            f"/series/{_quote(series_uid, safe='')}"
            f"/instances/{_quote(sop_uid, safe='')}"
            f"?transferSyntax={_quote(refetch_ts, safe='')}"
        )
        logging.info(
            "[C-MOVE] Instance %d (%s): stored TS %s not accepted; "
            "refetching on the MAIN association with transfer-syntax=%s",
            idx,
            sop_uid,
            actual_ts,
            refetch_ts,
        )
        try:
            r2 = requests.get(
                inst_url,
                headers={"Accept": f"application/dicom; transfer-syntax={refetch_ts}"},
                timeout=http_timeout,
                cert=tls,
            )
            r2.raise_for_status()
        except requests.RequestException as rf_err:
            logging.warning(
                "[C-MOVE] Instance %d (%s): refetch failed: %s",
                idx,
                sop_uid,
                rf_err,
            )
            failed += 1
            return None
        new_bytes = r2.content
        with tempfile.NamedTemporaryFile(suffix=".dcm", delete=False) as _f2:
            _f2.write(
                _ensure_file_meta_bytes(
                    new_bytes,
                    sop_class_uid,
                    sop_uid,
                    refetch_ts,
                )
            )
            _rtmp = _f2.name
        try:
            _t0 = time.perf_counter()
            status = assoc.send_c_store(_rtmp)
        except Exception as rs_err:
            logging.warning(
                "[C-MOVE] Instance %d (%s): C-STORE of refetched " "bytes failed: %s",
                idx,
                sop_uid,
                rs_err,
            )
            status = None
            _rtmp_size = None
        else:
            try:
                _rtmp_size = _os.path.getsize(_rtmp)
            except OSError:
                _rtmp_size = None
        finally:
            try:
                _os.unlink(_rtmp)
            except OSError:
                pass
        try:
            cstore_outbound_duration.labels(peer=ae_label(peer_ae)).observe(
                time.perf_counter() - _t0
            )
            if _rtmp_size is not None:
                bytes_total.labels(direction="tx", peer=ae_label(peer_ae)).inc(
                    _rtmp_size
                )
        except Exception:
            pass
        if status is None:
            failed += 1
        return status

    def _refetch_after_rejection(
        inst_idx, sop_uid, sop_class_uid, actual_ts, dicom_bytes, peer_ae=""
    ):
        """Refetch one not-accepted instance on the MAIN association.

        Refetch target = a TS the viewer accepts AND the server can produce,
        chosen by `_pick_refetch_ts` (EVRLE -> IVRLE -> any). No probe /
        second association is ever used. Returns the C-STORE status
        (None = failure already counted by _refetch_and_send; the caller then
        lets the undelivered SOP UID land in the (0008,0058) failed list).
        """
        _acc = (
            accepted_contexts_map.get(sop_class_uid) if accepted_contexts_map else None
        )
        refetch_ts = _pick_refetch_ts(_acc, server_ts)
        if not refetch_ts:
            # No deliverable form - honest per-instance failure. The SOP
            # UID stays in seen_sop_uids so the final (0008,0058) lists it.
            logging.warning(
                "[C-MOVE] Instance %d (%s): stored TS %s not accepted and "
                "no accepted TS the server can produce - counted failed",
                inst_idx,
                sop_uid,
                actual_ts,
            )
            return None
        # Field-observed: stored IVRLE bytes carry no VR field -
        # scan in implicit mode so the series UID (and the refetch URL)
        # survives the refetch rescue.
        series_uid = (
            _extract_dataset_ui(
                dicom_bytes,
                0x000E,
                group=0x0020,
                implicit_vr=(actual_ts == ImplicitVRLittleEndian),
            )
            or ""
        )
        return _refetch_and_send(
            inst_idx,
            sop_uid,
            sop_class_uid,
            actual_ts,
            refetch_ts,
            series_uid,
            peer_ae,
        )

    def _unlink_quiet(path):
        """Best-effort temp-file cleanup - cleanup must never fail the job."""
        try:
            _os.unlink(path)
        except OSError:
            pass

    def _failed_uids():
        """Sorted (0008,0058) material: seen-but-not-delivered SOP instance
        UIDs (PS3.4 C.4.2.1.4.2). Deterministic order for the wire list."""
        _delivered = {u for _c, u in sent_sop_uids if u}
        return sorted(u for u in seen_sop_uids if u not in _delivered)

    # The streamed response stays open for the whole loop; every exit
    # path must release it, early returns included, or the pooled
    # connection stays checked out for the life of the process.
    try:
        for part, idx, part_ts in prefetch:
            # A spilled part arrives as (head bytes, temp-file path).
            # The head carries the file meta group read below; the rest is
            # streamed from disk, never read whole into memory.
            spill_path = None
            if isinstance(part, SpilledPart):
                dicom_bytes = part.head
                spill_path = part.path
            else:
                dicom_bytes = part

            # Bridge: check C-MOVE-CANCEL before each C-STORE
            if move_jobs.is_job_cancelled(job_id):
                logging.warning(
                    "[C-MOVE] Job #%d cancelled by SCU after %d/%d instances",
                    job_id,
                    completed,
                    total if total else idx,
                )
                if spill_path is not None:
                    _unlink_quiet(spill_path)
                prefetch.stop()
                return _out(cancelled=True)

            # Bridge: check shutdown flag during long transfers
            if _shutdown_requested.is_set():
                logging.warning("[C-MOVE] Shutdown requested, aborting job #%d", job_id)
                if spill_path is not None:
                    _unlink_quiet(spill_path)
                prefetch.stop()
                return _out(cancelled=True)

            part_size = len(dicom_bytes)
            if spill_path is not None:
                part_size += _os.path.getsize(spill_path)
            total_bytes += part_size
            total = idx + 1  # Update total as we stream
            # DEBUG: log only every 50th part + first/last to avoid I/O spam
            if idx == 0 or idx % 50 == 0:
                logging.debug("[C-MOVE] Streamed part %d: %d bytes", idx + 1, part_size)

            # Stored-first hot loop: byte-level UIDs/TS, NO dcmread in the
            # send path (ap101 discipline - pydicom only as the TS last resort).
            sent_via_refetch = False
            try:
                # The transfer syntax decides how the dataset below must be
                # scanned, so it is resolved FIRST: an Implicit VR instance has no
                # VR field in any element, and reading it as explicit VR makes
                # every tag walk stop at the first element - the SOP UIDs then come
                # back empty and a delivered instance is counted failed.
                # Chain, PER PART:
                # 1) transfer-syntax= of the part Content-Type header;
                # 2) byte-level read of (0002,0010);
                # 3) pydicom - last resort only.
                actual_ts = (
                    part_ts
                    or _extract_meta_ui(dicom_bytes, 0x0010)
                    or _pydicom_file_meta_ts(dicom_bytes)
                )
                implicit_vr = actual_ts == ImplicitVRLittleEndian
                sop_class_uid = (
                    _extract_meta_ui(dicom_bytes, 0x0002)
                    or _extract_dataset_ui(dicom_bytes, 0x0016, implicit_vr=implicit_vr)
                    or ""
                )
                sop_uid = (
                    _extract_meta_ui(dicom_bytes, 0x0003)
                    or _extract_dataset_ui(dicom_bytes, 0x0018, implicit_vr=implicit_vr)
                    or ""
                )
                if sop_uid:
                    seen_sop_uids.add(str(sop_uid))
                # Resume: an instance already DELIVERED on the first pass
                # must not be re-sent or re-counted on the resumed pass. Skip it
                # (bytes were only fetched to identify it); exactly-once holds.
                if _skip_ids and sop_uid and str(sop_uid) in _skip_ids:
                    if spill_path is not None:
                        _unlink_quiet(spill_path)
                    logging.debug(
                        "[C-MOVE] Resume: skipping already-delivered instance %s "
                        "(part %d)",
                        sop_uid,
                        idx + 1,
                    )
                    continue
                # actual_ts was resolved before the byte scans above, because it
                # decides how those scans read the dataset.
                viewer_ts = accepted_contexts_map.get(sop_class_uid) or set()
                is_image = _is_image_sop(sop_class_uid, sop_registry)
                decision = _decide_send_path(viewer_ts, actual_ts, is_image)
                # The bridge NEVER opens a probe/second association.
                # A stored TS the viewer did NOT accept is either delivered on the
                # MAIN association by refetching in a producible accepted TS
                # (EVRLE -> IVRLE -> any from accepted x server intersection), or
                # - when the server cannot produce one - failed honestly.
                if decision == "needs_deliver":
                    refetch_ts = _pick_refetch_ts(viewer_ts, server_ts)
                    decision = "refetch_main" if refetch_ts else "fail"

                # Pass-through: raw bytes -> temp file -> pynetdicom reads directly.
                # No dcmread(), no write_dataset(). Bytes untouched.
                with tempfile.NamedTemporaryFile(suffix=".dcm", delete=False) as _f:
                    _f.write(
                        _ensure_file_meta_bytes(
                            dicom_bytes,
                            sop_class_uid,
                            sop_uid,
                            actual_ts,
                        )
                    )
                    if spill_path is not None:
                        # W3 (0209): append the spilled excess from disk in
                        # 1 MiB chunks - the spill file is never read whole.
                        with open(spill_path, "rb") as _src:
                            shutil.copyfileobj(_src, _f, 1024 * 1024)
                    _tmp_path = _f.name
                try:
                    if decision == "send_as_is":
                        # Stored TS accepted for this class -> main association.
                        _t0 = time.perf_counter()
                        status = assoc.send_c_store(_tmp_path)
                        try:
                            cstore_outbound_duration.labels(
                                peer=ae_label(peer_ae)
                            ).observe(time.perf_counter() - _t0)
                            bytes_total.labels(
                                direction="tx", peer=ae_label(peer_ae)
                            ).inc(part_size)
                        except Exception:
                            pass
                    elif decision == "refetch_main":
                        # Not accepted + a producible accepted TS exists ->
                        # refetch ON THE MAIN association in that TS. No fallback,
                        # no probe, no second association.
                        status = _refetch_after_rejection(
                            idx + 1,
                            sop_uid,
                            sop_class_uid,
                            actual_ts,
                            dicom_bytes,
                            peer_ae,
                        )
                        if status is None:
                            # _refetch_after_rejection returned ''-target or
                            # _refetch_and_send already counted the failure.
                            continue
                        sent_via_refetch = True
                    else:  # decision == "fail"
                        # Not accepted and no producible accepted TS (server lacks
                        # transcode or nothing in common): honest per-instance
                        # failure - the SOP UID stays in seen_sop_uids so the
                        # final (0008,0058) lists it. No silent drop (R3).
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): stored TS %s not accepted "
                            "and the server cannot produce an accepted TS - "
                            "counted failed",
                            idx + 1,
                            sop_uid,
                            actual_ts,
                        )
                        failed += 1
                        continue
                    if status is None:
                        failed += 1
                        continue
                except (TypeError, ValueError) as send_err:
                    err_msg = str(send_err)
                    if "presentation context" in err_msg.lower():
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): SOP class %s not negotiated "
                            "with viewer - viewer doesn't accept this class/TS. "
                            "Counted failed. Error: %s",
                            idx + 1,
                            sop_uid,
                            sop_class_uid,
                            send_err,
                        )
                        failed += 1
                        continue
                    else:
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): cannot encode for C-STORE - "
                            "corrupted DICOM metadata (tag encoding error). "
                            "Counted failed. Error: %s",
                            idx + 1,
                            sop_uid,
                            send_err,
                        )
                        failed += 1
                        continue
                except Exception as e:
                    # pynetdicom network_timeout false positive: timer fires
                    # even while data IS flowing (e.g. 432 slices, 45s).
                    # If association is alive and C-STORE succeeded before  -  ignore.
                    err_msg = str(e)
                    is_timeout = any(
                        kw in err_msg.lower()
                        for kw in ("timeout", "timed out", "network")
                    )
                    assoc_alive = getattr(assoc, "is_established", False)
                    if is_timeout and assoc_alive and completed > 0:
                        logging.warning(
                            "[DIMSE-OUT] %s:%d: network_timeout fired, "
                            "but association alive, %d C-STORE sent, "
                            "%d bytes transferred. Ignoring - data IS flowing. "
                            "Error: %s",
                            getattr(assoc, "ae_title", "?"),
                            getattr(assoc, "port", 0),
                            completed,
                            total_bytes,
                            err_msg,
                        )
                        failed += 1
                        continue
                    else:
                        # Association DEAD  -  viewer crashed or disconnected. The
                        # driver may resume ONCE. We stop this pass's
                        # stream and report `lost=True` (only when the driver
                        # requested it) so `_execute_cmove_job` can re-associate
                        # and run a skip-delivered second pass.
                        logging.warning(
                            "[DIMSE-OUT] %s:%d: association LOST after %d/%d "
                            "C-STORE sent (%d failed). %s Error: %s",
                            getattr(assoc, "ae_title", "?"),
                            getattr(assoc, "port", 0),
                            completed,
                            total if total else idx + 1,
                            failed + 1,
                            (
                                "Resuming once."
                                if _report_lost and not _resumed
                                else "Viewer must re-request or resume fails."
                            ),
                            err_msg,
                        )
                        prefetch.stop()
                        resp.close()
                        return _out(lost=True)
                finally:
                    _unlink_quiet(_tmp_path)
                    if spill_path is not None:
                        _unlink_quiet(spill_path)

                if status and status.Status == 0x0000:
                    completed += 1
                    if sent_via_refetch:
                        transcoded += 1
                    else:
                        passthrough += 1
                    # Bridge: track successfully sent SOPs for Storage Commitment
                    if sop_uid:
                        sent_sop_uids.append((sop_class_uid, sop_uid))
                else:
                    failed += 1
                    logging.warning(
                        "[C-MOVE] C-STORE failed for instance %d: status=%s",
                        idx + 1,
                        _dimse_status_name(status.Status if status else None),
                    )
            except (requests.RequestException, OSError, ValueError, KeyError) as e:
                failed += 1
                if spill_path is not None:
                    # W3: the send file was never handed to pynetdicom - drop
                    # the spill file right here (the inner finally is not hit).
                    _unlink_quiet(spill_path)
                logging.warning(
                    "[C-MOVE] C-STORE error for instance %d/%d: %s",
                    idx + 1,
                    total,
                    e,
                )
                logging.debug(
                    "[C-MOVE] C-STORE traceback for instance %d/%d:",
                    idx + 1,
                    total,
                    exc_info=True,
                )

            # Bridge: update job progress counters
            move_jobs.update_job_progress(job_id, completed, failed, total)

    finally:
        prefetch.stop()
        resp.close()

    if total == 0:
        logging.info(
            "[C-MOVE] Job #%d: study %s returned 0 instances", job_id, study_uid
        )

    logging.info(
        "[C-MOVE] Job #%d study %s: passthrough=%d transcoded=%d refetched=%d"
        " resumed=%d",
        job_id,
        study_uid,
        passthrough,
        transcoded,
        refetched,
        1 if _resumed else 0,
    )
    logging.info(
        "[C-MOVE] Streamed study %s: %d instances, %d bytes total",
        study_uid,
        total,
        total_bytes,
    )

    return _out()

# ---------------------------------------------------------------------------
# Bridge: A-RELEASE with A-ABORT fallback (polite first, then force)
# ---------------------------------------------------------------------------
def _release_or_abort(assoc, timeout=3.0):
    """Polite A-RELEASE, then A-ABORT if viewer doesn't respond.

    Release politely first, but do not wait forever.
    Data is already delivered (C-STORE-RSP status=0x0000 received
    for every instance). A-RELEASE is protocol courtesy, not data integrity.

    Orthanc/dcm4che: both try A-RELEASE with a timeout, then force-close.
    pynetdicom: release() blocks indefinitely if peer doesn't respond.
    This wrapper adds the missing timeout.
    """
    if assoc is None or not assoc.is_established:
        return

    released = threading.Event()

    def _do_release():
        try:
            assoc.release()
        except Exception:
            pass
        finally:
            released.set()

    t = threading.Thread(target=_do_release, daemon=True)
    t.start()

    if not released.wait(timeout=timeout):
        peer = getattr(assoc, "ae_title", "?")
        logging.warning(
            "[DIMSE] A-RELEASE timed out after %.0fs - " "sending A-ABORT to %s",
            timeout,
            peer,
        )
        try:
            assoc.abort()
        except Exception:
            pass

    t.join(timeout=1.0)

# ---------------------------------------------------------------------------
# Bridge: execute a single C-MOVE job: stream -> send -> finish
# ---------------------------------------------------------------------------
def _execute_cmove_job(
    job_id,
    study_uid,
    move_dest_ae,
    move_jobs,
    clarus_url,  # Clarus Server DICOMweb base URL (single knob, 2908)
    http_timeout,
    bridge_ae_title,  # Bridge: own AE Title for C-STORE associations
    target_host="",  # Resolved Move Destination host (subnet support)
    target_port=0,  # Resolved Move Destination port
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    peers_file=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    outbound_assoc_attempts=3,
    tls=None,
    spill_threshold=SPILL_THRESHOLD,
    expose_rejected=False,
    qa_url="",
):
    """Execute C-MOVE: stream study from Clarus, send instances to target SCP.

    Stage 1 (bridge-only): before the main A-ASSOCIATE a lightweight
    pre-flight learns each class's stored TS set from the standard metadata
    resource so the association proposal can carry per-TS contexts;
    delivery follows the negotiation result. Retry policy is the single
    outbound_assoc_attempts knob with immediate retries.

    1. Pre-flight stored TS - best effort, never fails the job.
    2. Stream study as multipart DICOM from Clarus (WADO-RS) - no temp file.
    3. Send each instance via C-STORE to move_dest_ae.
    4. Check C-MOVE-CANCEL before each C-STORE.
    5. Optionally send Storage Commitment N-ACTION after success.
    """
    # Bridge: target_host/target_port come from job (resolved in handle_c_move).
    # No re-lookup needed  -  subnet resolution happened at C-MOVE time.
    if not target_host or not target_port:
        # Legacy job without target info  -  fall back to lookup
        if peers_file:
            move_jobs.reload_peers_from_file(peers_file)
        target = move_jobs.lookup_scp(move_dest_ae)
        if target is None:
            logging.error(
                "[C-MOVE] Unknown Move Destination: %s",
                move_dest_ae,
            )
            move_jobs.finish_job(
                job_id,
                success=False,
                error_message=f"Unknown Move Destination: {move_dest_ae}",
            )
            move_jobs_counter.labels(status="failed").inc()
            return
        target_host, target_port = target

    assoc = None
    try:
        # Per-peer job gate: serialize jobs to the same peer (busy exclusion).
        # No post-job cooldown: the next job starts immediately once the
        # previous one to this peer ends. Taken inside the try so the
        # finally releases it on every path, including a pre-flight raise.
        _job_gate_enter(target_host, target_port, move_dest_ae)

        # -- Pre-flight: learn each class's stored TS BEFORE the association
        # (best effort - any failure degrades to the default proposal). --
        study_ts_by_class = _preflight_study_ts_by_class(
            study_uid,
            clarus_url,
            http_timeout=2.0,
            tls=tls,
            budget_s=4.0,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )

        try:
            assoc, accepted_contexts_map = _associate_for_move(
                move_dest_ae,
                bridge_ae_title,
                sop_registry,
                target_host,
                target_port,
                network_timeout=outbound_network_timeout,
                dimse_timeout=outbound_dimse_timeout,
                acse_timeout=outbound_acse_timeout,
                outbound_assoc_attempts=outbound_assoc_attempts,
                study_ts_by_class=study_ts_by_class,
            )
        except RuntimeError as e:
            logging.error("[C-MOVE] %s", e)
            logging.debug("[C-MOVE] Association traceback:", exc_info=True)
            move_jobs.record_scp_failure(move_dest_ae, host=target_host)
            move_jobs.finish_job(job_id, success=False, error_message=str(e))
            move_jobs_counter.labels(status="failed").inc()
            return

        server_ts_list = _get_clarus_transfer_syntaxes(clarus_url, tls=tls)

        global _suppress_pynetdicom
        _suppress_pynetdicom = True
        # -- Resume driver: at most ONE resume. The whole study is
        # re-streamed on a FRESH GET for the resumed pass (a conformant
        # continuation; PS3.7 9.1.4.2(e) / PS3.8 9.1.4 Note 2 + 9.1.5), and
        # only the SOP UIDs NOT yet delivered are re-sent, so each instance
        # is delivered at most once. Counters are reconciled by UNION of the
        # delivered sets at the end (never sum regression). --
        study_sop_uids = None
        try:
            # Authoritative study SOP list for the (0008,0058) tail ++ total.
            study_sop_uids = _study_sop_uids(
                study_uid,
                clarus_url,
                tls=tls,
                expose_rejected=expose_rejected,
                qa_url=qa_url,
            )
        except Exception:
            study_sop_uids = None
        sent_sop_uids = []  # union across passes (SC material)
        cancelled = False
        no_common_ts = False
        resumed_lost = False

        # Pass 1 (initial).
        try:
            r1 = _stream_and_send_study(
                assoc,
                study_uid,
                clarus_url,
                http_timeout,
                move_jobs,
                job_id,
                accepted_contexts_map=accepted_contexts_map,
                server_ts_list=server_ts_list,
                sop_registry=sop_registry,
                tls=tls,
                spill_threshold=spill_threshold,
                peer_ae=move_dest_ae,
                _skip_ids=None,
                _resumed=False,
                _report_lost=True,
                expose_rejected=expose_rejected,
                qa_url=qa_url,
            )
            _c1, _f1, _t1, _s1, _fs1, _ca1, _nc1, _lost1 = r1
            sent_sop_uids = list(_s1)
            cancelled = _ca1
            no_common_ts = _nc1
            resumed_lost = _lost1
        except Exception:
            sent_sop_uids = []
            cancelled = False
            no_common_ts = False
            resumed_lost = False
            raise

        # Resume ONCE on association loss (not on cancel/shutdown/no-common).
        if resumed_lost and not cancelled and not no_common_ts:
            delivered1 = {u for _c, u in sent_sop_uids if u}
            logging.info(
                "[C-MOVE] Job #%d: association lost after %d delivered - "
                "re-associating ONCE to resume (skip %d delivered)",
                job_id,
                len(delivered1),
                len(delivered1),
            )
            _release_or_abort(assoc)
            assoc = None
            try:
                assoc, accepted_contexts_map = _associate_for_move(
                    move_dest_ae,
                    bridge_ae_title,
                    sop_registry,
                    target_host,
                    target_port,
                    network_timeout=outbound_network_timeout,
                    dimse_timeout=outbound_dimse_timeout,
                    acse_timeout=outbound_acse_timeout,
                    outbound_assoc_attempts=outbound_assoc_attempts,
                    study_ts_by_class=study_ts_by_class,
                )
            except RuntimeError as e:
                # Resume's re-association failed -> GIVE_UP (honest partial).
                logging.error(
                    "[C-MOVE] Job #%d: resume re-association failed (%s) - "
                    "GIVE_UP with the delivered prefix",
                    job_id,
                    e,
                )
                resumed_lost = True
            else:
                # Pass 2 (resumed) - only the still-undelivered instances.
                try:
                    r2 = _stream_and_send_study(
                        assoc,
                        study_uid,
                        clarus_url,
                        http_timeout,
                        move_jobs,
                        job_id,
                        accepted_contexts_map=accepted_contexts_map,
                        server_ts_list=server_ts_list,
                        sop_registry=sop_registry,
                        tls=tls,
                        spill_threshold=spill_threshold,
                        peer_ae=move_dest_ae,
                        _skip_ids=delivered1,
                        _resumed=True,
                        _report_lost=True,
                        expose_rejected=expose_rejected,
                        qa_url=qa_url,
                    )
                    _c2, _f2, _t2, _s2, _fs2, _ca2, _nc2, _lost2 = r2
                    # Union the delivered sets.
                    sent_sop_uids = list(_s1) + list(_s2)
                    cancelled = cancelled or _ca2
                    no_common_ts = no_common_ts or _nc2
                    resumed_lost = _lost2  # second loss => GIVE_UP below
                except Exception:
                    resumed_lost = True

        if resumed_lost:
            logging.warning(
                "[C-MOVE] Job #%d: gave up after association failure or "
                "failed resume - finishing as a partial job",
                job_id,
            )

        # Reconcile the final counters by UNION of the delivered SOP UIDs.
        # Every instance is either delivered (its SOP uid is in sent_sop_uids)
        # or failed - never double counted, never a sum regression. The
        # authoritative study SOP list (when available) fixes
        # `total` and gives the honest (0008,0058) tail.
        delivered = {u for _c, u in sent_sop_uids if u}
        completed = len(delivered)
        _obs_total_p1 = _t1 if not no_common_ts else 0
        if study_sop_uids is not None and study_sop_uids:
            study_uids_set = set(study_sop_uids)
            total = len(study_uids_set)
            ordered_uids = study_sop_uids
        else:
            # No authoritative list (degradation): total = largest pass total.
            total = max(_obs_total_p1, completed)
            ordered_uids = None
        if study_sop_uids is not None and study_sop_uids:
            failed_sop_uids = [u for u in ordered_uids if u not in delivered]
        else:
            # Degrade to the per-attempt failed sets when present, else []. If
            # a single (non-resumed) pass ran, use its per-instance failed
            # list (exact); otherwise list nothing conclusive (honest).
            failed_sop_uids = sorted(_fs1) if not resumed_lost else []
        # PS3.4 C.4.2.1.4.2: the failure count is the number of instances that
        # were seen and NOT delivered, which is exactly the (0008,0058) list.
        # Deriving it as `total - completed` counted every instance that never
        # reached this pass at all as a failure, so a resumed job reported
        # failures it never observed.
        failed = len(failed_sop_uids)
        # Ensure total never falls below the delivered count.
        total = max(total, completed)

        # 0709: persist the (0008,0058) Failed SOP Instance UID List so the
        # C-MOVE generator can attach it to the final Failed/Warning/Cancel
        # status (PS3.4 C.4.2.1.4.2).
        try:
            move_jobs.set_job_failed_sops(job_id, failed_sop_uids)
        except Exception:
            # Best-effort: the progress/status path must not fail on logging.
            logging.debug("[C-MOVE] set_job_failed_sops failed for job #%d", job_id)

        if no_common_ts:
            # No common transfer syntax: the job ends failed with zero slices
            # delivered, so the C-MOVE generator emits a Failure (0xC000) -
            # not 0xC001 (which was a log-only claim; it is not a response
            # status). The viewer log and the wire now agree.
            logging.warning(
                "[C-MOVE] Job #%d: no common transfer syntax - "
                "job ends failed, 0 slices, C-MOVE-RSP is a Failure (0xC000)",
                job_id,
            )
            move_jobs.finish_job(
                job_id,
                success=False,
                error_message="No common transfer syntax between viewer and server",
            )
            move_jobs_counter.labels(status="failed").inc()
            return

        if cancelled:
            if move_jobs.is_job_cancelled(job_id):
                move_jobs.finish_job(
                    job_id, success=False, error_message="Cancelled by SCU"
                )
            else:
                move_jobs.finish_job(job_id, success=False, error_message="Shutdown")
            move_jobs_counter.labels(status="failed").inc()
            return

        # -- Storage Commitment after successful C-MOVE --
        # Controlled by [dimse] no_storage_commit config flag only.
        # The commit push is attempted only when Storage Commitment was
        # the commit push is attempted ONLY when Storage Commitment was
        # negotiated in the MAIN association (_associate_for_move requests
        # it). Viewers without SC (MicroDicom) burned ACSE timeouts when a
        # separate SC-only association was opened - skip instead of trying.
        if failed == 0 and total > 0:
            if storage_commit_after_move and sent_sop_uids:
                sc_negotiated = any(
                    str(ctx.abstract_syntax) == StorageCommitmentPushModel
                    for ctx in assoc.accepted_contexts
                )
                if not sc_negotiated:
                    logging.info(
                        "[C-MOVE] Job #%d: Storage Commitment not negotiated "
                        "in the main association - skipping SC push",
                        job_id,
                    )
                else:
                    try:
                        _send_storage_commitment(
                            move_dest_ae,
                            target_host,
                            target_port,
                            sent_sop_uids,
                            bridge_ae_title,
                        )
                    except Exception as e:
                        logging.warning(
                            "[C-MOVE] Job #%d: Storage Commitment push failed: %s",
                            job_id,
                            e,
                        )

        # -- Record SCP result  -  the peer is HEALTHY if the association was
        # established and (some or all) slices were delivered. A partial job
        # (failed > 0) is NOT a peer failure: a single bad minute must not
        # evict an alive peer, so only a MAIN-association failure (handled in
        # the RuntimeError catch above) touches the consecutive-failure
        # counter (D3, spec task #1).
        if failed == 0 and total > 0:
            move_jobs.record_scp_success(move_dest_ae, host=target_host)

        # -- Finish job --
        job_success = failed == 0 and total > 0
        move_jobs.finish_job(
            job_id,
            success=job_success,
            error_message=f"{completed} sent, {failed} failed" if failed > 0 else None,
        )
        move_jobs_counter.labels(status="completed" if job_success else "failed").inc()
        logging.info(
            "[C-MOVE] Job #%d finished: %d/%d success, %d failed",
            job_id,
            completed,
            total,
            failed,
        )

        if failed == 0 and total > 0:
            logging.debug("[C-MOVE] Job #%d: all %d instances succeeded", job_id, total)
        elif completed > 0 and failed > 0:
            logging.info(
                "[C-MOVE] Job #%d: partial - %d/%d succeeded, %d failed",
                job_id,
                completed,
                total,
                failed,
            )
        else:
            logging.info("[C-MOVE] Job #%d: no instances delivered", job_id)

    except requests.exceptions.RequestException as e:
        logging.error("[C-MOVE] Download/stream failed for job #%d: %s", job_id, e)
        logging.debug(
            "[C-MOVE] Download/stream traceback for job #%d:", job_id, exc_info=True
        )
        move_jobs.finish_job(
            job_id, success=False, error_message=f"Download failed: {e}"
        )
        move_jobs_counter.labels(status="failed").inc()
    finally:
        _suppress_pynetdicom = False
        _release_or_abort(assoc)
        # Release the peer gate so the next job to this peer can start.
        _job_gate_exit(target_host, target_port, move_dest_ae)

# ---------------------------------------------------------------------------
# Bridge: C-MOVE background worker pool  -  parallel execution
# ---------------------------------------------------------------------------
def _cmove_worker(
    move_jobs,
    clarus_url,  # Clarus Server DICOMweb base URL (single knob, 2908)
    http_timeout,
    bridge_ae_title,
    num_workers=2,
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    peers_file=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    outbound_assoc_attempts=3,
    tls=None,
    qa_url="",
):
    """Multi-threaded C-MOVE job executor.

    Spawns num_workers threads, each picking one pending job from queue.
    Executes: pre-flight -> stream -> send -> finish.
    Sleeps 5 seconds when queue is empty.
    Checks _shutdown_requested before each iteration.
    """

    def _worker_loop(worker_id):
        """Single worker thread: pick job, execute, repeat."""
        logging.info("[C-MOVE] Worker-%d started", worker_id)

        while not _shutdown_requested.is_set():
            # Bridge: pick next pending job, LIMIT 1
            job = move_jobs.pick_pending_job()
            if job is None:
                # pick_pending_job() already waited via Condition
                continue

            job_id = job["id"]
            study_uid = job["study_uid"]
            move_dest_ae = job["move_dest_ae"]
            attempt = job["attempts"]
            # Queued over the Expose Rejected Instances AE? Read from the job
            # row, not the event: the worker outlives the association.
            job_expose_rejected = bool(job.get("expose_rejected", 0))

            # Bridge: log retry attempts for recovery awareness
            if attempt > 0:
                logging.info(
                    "[C-MOVE] Worker-%d: Job #%d retry attempt %d (recovery)",
                    worker_id,
                    job_id,
                    attempt + 1,
                )

            logging.info(
                "[C-MOVE] Worker-%d picked job #%d: Study=%s -> %s (attempt %d)",
                worker_id,
                job_id,
                study_uid,
                move_dest_ae,
                attempt + 1,
            )

            try:
                # Bridge: execute C-MOVE job
                _execute_cmove_job(
                    job_id,
                    study_uid,
                    move_dest_ae,
                    move_jobs,
                    clarus_url,
                    http_timeout,
                    bridge_ae_title,
                    target_host=job.get("target_host", ""),
                    target_port=job.get("target_port", 0),
                    sop_registry=sop_registry,
                    storage_commit_after_move=storage_commit_after_move,
                    sop_index=sop_index,
                    peers_file=peers_file,
                    outbound_network_timeout=outbound_network_timeout,
                    outbound_dimse_timeout=outbound_dimse_timeout,
                    outbound_acse_timeout=outbound_acse_timeout,
                    outbound_assoc_attempts=outbound_assoc_attempts,
                    tls=tls,
                    expose_rejected=job_expose_rejected,
                    qa_url=qa_url,
                )
            except Exception as e:
                logging.error(
                    "[C-MOVE] Worker-%d: Job #%d failed with exception: %s",
                    worker_id,
                    job_id,
                    e,
                )
                move_jobs.finish_job(job_id, success=False, error_message=str(e))
                move_jobs_counter.labels(status="failed").inc()
            finally:
                # Bridge: clear cancel callback after job completes
                move_jobs.clear_job_callback(job_id)

        logging.info("[C-MOVE] Worker-%d stopped", worker_id)

    logging.info("[C-MOVE] Starting %d worker thread(s)", num_workers)
    workers = []
    for i in range(num_workers):
        t = threading.Thread(
            target=_worker_loop,
            args=(i,),
            name=f"cmove-worker-{i}",
            daemon=True,
        )
        t.start()
        workers.append(t)

    # Bridge: wait for all workers to finish (they stop when _shutdown_requested is set)
    for t in workers:
        t.join()

    logging.info("[C-MOVE] All worker threads stopped")

# ---------------------------------------------------------------------------
# Bridge: periodic cleanup of old C-MOVE jobs
# ---------------------------------------------------------------------------
def _cmove_cleanup_worker(move_jobs, max_age_hours=24):
    """Background thread: delete success/failed jobs older than max_age_hours.

    Runs once per hour. Stops when _shutdown_requested is set.
    """
    max_age_seconds = max_age_hours * 3600
    logging.info(
        "[C-MOVE] Cleanup worker started (max age: %dh)",
        max_age_hours,
    )

    while not _shutdown_requested.is_set():
        # Bridge: sleep 1 hour between cleanup cycles
        _shutdown_requested.wait(timeout=3600.0)
        if _shutdown_requested.is_set():
            break
        move_jobs.cleanup_old_jobs(max_age_seconds)
        logging.debug("[C-MOVE] Old job cleanup completed")

    logging.info("[C-MOVE] Cleanup worker stopped")

# ---------------------------------------------------------------------------
# Bridge: nevent
# ---------------------------------------------------------------------------

"""Clarus Bridge - N-EVENT-REPORT SCU (Storage Commitment push report).

Closes the RSP->report loop: after the
N-ACTION-RSP is returned, one N-EVENT-REPORT per batch is sent back to the
modality over a SEPARATE SCU association (PS3.4 Push Model).

EventTypeID (PS3.7 F.2 / table): 1 = "Storage Commitment Request Successful",
2 = "Storage Commitment Request Complete - Failures Exist". A failed SOP
carries a Failure Reason in its FailedSOPSequence item (PS3.3 C.14.1.1). The
modality keeps its local copy of any SOP it was NOT confirmed for.
"""

import logging
import threading
import time

from pydicom import Dataset
from pydicom.uid import ImplicitVRLittleEndian
from pynetdicom import AE
from pynetdicom.sop_class import StorageCommitmentPushModel

# EventTypeID (see module docstring).
EVENT_SUCCESS = 1
EVENT_FAILURE = 2

# PS3.4 J.3.2/J.3.3.1: an N-EVENT-REPORT on the Push Model addresses the SOP
# Instance this SOP Class defines as a constant, created conceptually at SCP
# startup. The Transaction UID is NOT the Affected SOP Instance UID - it travels
# inside the dataset as (0008,1195) and is how the SCU correlates the report with
# its request. Sending the UID as the instance makes a strict SCU drop the
# report: it does not recognise the affected instance as the commitment one.
WELL_KNOWN_SOP_INSTANCE_UID = "1.2.840.10008.1.20.1.1"

# The pynetdicom level is saved, raised and restored around `associate()`.
# That triple is not atomic, and two concurrent reports would interleave it:
# the second would save the ALREADY silenced level and restore that, leaving
# the library silenced for the life of the process.
_LEVEL_LOCK = threading.Lock()

# PS3.4 J.3.2 / J.3.3: a Storage Commitment transaction needs the requestor to
# receive the N-EVENT-REPORT the SCP pushes back, so the requestor must hold
# BOTH roles. PS3.7 D.3.3.4 spells the requestor's proposal as an SCP/SCU Role
# Selection item; pynetdicom exposes it per presentation context.

def _request_scp_role(ae, abstract_syntax):
    """Propose the SCU+SCP role for `abstract_syntax` on this association.

    Returns False when the installed pynetdicom cannot express the proposal,
    so the caller can report the resulting default-role association honestly
    instead of assuming the report can be pushed.
    """
    try:
        ae.requested_contexts[-1].requested_scp_role = True
        return True
    except (AttributeError, IndexError):
        logging.debug(
            "[N-EVENT] pynetdicom cannot propose the SCP role for %s",
            abstract_syntax,
        )
        return False

def send_n_event_report(
    host,
    port,
    calling_ae,
    tx_uid,
    event_type,
    success_sops,
    failed_sops,
    bridge_ae_title,
    max_retries=3,
    retry_delay=2.0,
):
    """Send ONE N-EVENT-REPORT-RQ to the modality (SCU role).

    Push model: a separate SCU association to (host, port). Retries with
    fixed backoff; on final failure only a WARN is logged (no persistence in
    v1 - the modality re-requests commitment, and we only confirm what is
    actually stored, so no data is at risk).

    Args:
        success_sops: list of (sop_class_uid, sop_instance_uid).
        failed_sops:  list of (sop_class_uid, sop_instance_uid, failure_reason).
        bridge_ae_title: Calling AE Title for this push - the configured
            [server] ae_title. A modality that knows the commitment-requestor
            AE rejects the report it did not expect, so this is required
            rather than defaulted here.
    """
    reported = False
    last_err = None

    for attempt in range(max_retries + 1):
        if attempt > 0:
            logging.warning(
                "[N-EVENT] Report attempt %d/%d after %.0fs (tx=%s)",
                attempt + 1,
                max_retries + 1,
                retry_delay,
                tx_uid,
            )
            time.sleep(retry_delay)

        ae = AE(ae_title=bridge_ae_title)
        ae.network_timeout = 5
        ae.acse_timeout = 3
        ae.dimse_timeout = 30
        # PS3.7 D.3.3.4: without a role item the requestor is SCU and the
        # acceptor is SCP, so the SCP could never send the N-EVENT-REPORT that
        # carries the Storage Commitment Result (PS3.4 J.3.3.1). The bridge
        # proposes the SCP role explicitly; a peer that declines it leaves the
        # default roles, which the response check below reports.
        ae.add_requested_context(StorageCommitmentPushModel, ImplicitVRLittleEndian)
        _request_scp_role(ae, StorageCommitmentPushModel)

        # "No accepted presentation contexts" is normal for SCPs that
        # do not implement the push model. Raise the pynetdicom level around
        # associate() so that expected ERROR does not spam the journal.
        _pn_logger = logging.getLogger("pynetdicom")
        with _LEVEL_LOCK:
            _prev = _pn_logger.level
            _pn_logger.setLevel(logging.CRITICAL + 1)
            try:
                assoc = ae.associate(host, port, ae_title=calling_ae)
                try:
                    associations_total.labels(role="to", ae=ae_label(calling_ae)).inc()
                except Exception:
                    pass
            finally:
                _pn_logger.setLevel(_prev)

        if not assoc.is_established:
            last_err = (
                f"SCP {calling_ae}@{host}:{port} unavailable (attempt {attempt + 1})"
            )
            logging.warning("[N-EVENT] %s", last_err)
            _release_or_abort(assoc, timeout=2.0)
            continue

        sc_accepted = any(
            str(ctx.abstract_syntax) == StorageCommitmentPushModel
            for ctx in assoc.accepted_contexts
        )
        if not sc_accepted:
            last_err = f"SCP {calling_ae} does not support push model"
            logging.warning("[N-EVENT] %s", last_err)
            _release_or_abort(assoc, timeout=2.0)
            continue

        try:
            ds = Dataset()
            ds.EventTypeID = event_type
            ds.TransactionUID = tx_uid

            if success_sops:
                seq = []
                for sop_class, sop_uid in success_sops:
                    item = Dataset()
                    item.ReferencedSOPClassUID = sop_class
                    item.ReferencedSOPInstanceUID = sop_uid
                    seq.append(item)
                ds.ReferencedSOPSequence = seq

            if failed_sops:
                fseq = []
                for sop_class, sop_uid, reason in failed_sops:
                    item = Dataset()
                    item.ReferencedSOPClassUID = sop_class
                    item.ReferencedSOPInstanceUID = sop_uid
                    item.FailureReason = reason
                    fseq.append(item)
                ds.FailedSOPSequence = fseq

            # pynetdicom 3.x signature: send_n_event_report(dataset, event_type,
            # class_uid, instance_uid) -> (status, response_dataset).
            # PS3.4 J.3.2: the Affected SOP Instance UID is the well-known
            # constant, not the Transaction UID (which is in the dataset).
            status, _resp = assoc.send_n_event_report(
                ds,
                ds.EventTypeID,
                StorageCommitmentPushModel,
                WELL_KNOWN_SOP_INSTANCE_UID,
            )
            if status is None or not hasattr(status, "Status"):
                # PS3.7 9.3: a response is mandatory. An empty one means the
                # association went away mid-request (timeout, abort), and the
                # modality was NOT told the outcome - treating it as delivered
                # stopped the retries and left the commitment never reported.
                last_err = "no N-EVENT-REPORT response"
                logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
                continue
            code = status.Status
            logging.info(
                "[N-EVENT] tx=%s type=%d sent to %s: %s (%d ok / %d failed)",
                tx_uid,
                event_type,
                calling_ae,
                _dimse_status_name(code),
                len(success_sops),
                len(failed_sops),
            )
            # PS3.7 9.1: only 0x0000 means the primitive succeeded. Any other
            # code says the SCP did not receive the report, so the modality was
            # never told the outcome - counting it as delivered stopped the
            # retries and left the commitment unreported for good.
            if code == 0x0000:
                reported = True
            else:
                last_err = f"N-EVENT-REPORT rejected with {_dimse_status_name(code)}"
                logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
        except Exception as e:
            last_err = f"send_n_event_report error: {e}"
            logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
        finally:
            _release_or_abort(assoc, timeout=2.0)

        if reported:
            try:
                nevent_delivered_total.inc()
            except Exception:
                pass
            return True

    logging.error(
        "[N-EVENT] Report NOT delivered for tx=%s after %d attempts: %s",
        tx_uid,
        max_retries + 1,
        last_err,
    )
    try:
        nevent_failed_total.inc()
    except Exception:
        pass
    return False

# ---------------------------------------------------------------------------
# Bridge: main
# ---------------------------------------------------------------------------

"""Clarus Bridge - DIMSE to DICOMweb adapter.

Configuration: clbridge.conf (nginx-style)
Sections: [server], [dicomweb], [dimse], [logging], [metrics], [advanced]

CLI:
  --config <path>   Path to config file (default: ./clbridge.conf)
  --version          Print version and exit
  --help             Print this help
"""

import ctypes
import functools
import logging
import os
import signal
import sys
import threading
import time

try:
    import yaml
except ImportError:
    yaml = None  # type: ignore

from http.server import ThreadingHTTPServer

from pydicom.uid import ImplicitVRLittleEndian
from pynetdicom import AE, _config, evt
from pynetdicom.sop_class import (
    ModalityWorklistInformationFind,
    PatientRootQueryRetrieveInformationModelFind,
    PatientRootQueryRetrieveInformationModelMove,
    StorageCommitmentPushModel,
    StudyRootQueryRetrieveInformationModelFind,
    StudyRootQueryRetrieveInformationModelMove,
)

# pass-through C-STORE - raw bytes from temp file.
# pynetdicom reads file_meta only, sends dataset bytes directly from disk.
# No dcmread(), no encode(), no re-serialization. One line.
_config.STORE_SEND_CHUNKED_DATASET = True

# TS-order constants (IMAGE_TS EVRLE-first etc.) live in clean_code.protocol
# (single definition - the bundle warns on duplicate module-level names).

# Bridge: C-PRINT driver framework - optional, graceful fallback
try:
    from drivers.base import AbstractPrintDriver, PrintResult
    from drivers.generic_dicom import GenericDicomPrintDriver

    _CPRINT_AVAILABLE = True
except ImportError:
    _CPRINT_AVAILABLE = False
    AbstractPrintDriver = None  # type: ignore
    PrintResult = None  # type: ignore
    GenericDicomPrintDriver = None  # type: ignore

import argparse

# SCP peer auto-remove threshold: an auto-registered move destination is
# dropped from the peer list after this many CONSECUTIVE association
# failures.
_SCP_FAILURES_BEFORE_REMOVE = 3

# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# _parse_args - CLI: only --version and --config
# ---------------------------------------------------------------------------
def _parse_args():
    """Parse CLI arguments. Returns argparse.Namespace with --config path only."""
    parser = argparse.ArgumentParser(
        description="Clarus Bridge - DICOM Bridge (C-STORE/C-FIND/C-MOVE/N-ACTION/C-PRINT)"
    )
    parser.add_argument("--version", action="version", version=f"clbridge v{VERSION}")
    # Default config path: next to the .exe (PyInstaller) or .py script.
    # PyInstaller one-file: sys.executable - actual .exe location.
    # Regular Python: __file__ - script location.
    if getattr(sys, "frozen", False):
        _script_dir = os.path.dirname(os.path.abspath(sys.executable))
    else:
        _script_dir = os.path.dirname(os.path.abspath(__file__))
    _default_config = os.path.join(_script_dir, "clbridge.conf")
    parser.add_argument(
        "--config",
        default=_default_config,
        help="Path to configuration file (default: clbridge.conf "
        "in script directory)",
    )
    # --regenerate-uids for tests/anonymization (NOT in config - too dangerous for prod)
    parser.add_argument(
        "--regenerate-uids",
        action="store_true",
        default=False,
        help="Regenerate Study/Series/SOP UIDs (tests/anonymization only)",
    )
    return parser.parse_args()

# ---------------------------------------------------------------------------
# CONFIG-DISCIPLINE: _populate_args - read ALL settings from clbridge.conf
# ---------------------------------------------------------------------------
def _populate_args(cfg):
    """Read all configuration values into a namespace. No CLI defaults - config is authoritative.

    Returns argparse.Namespace with all settings populated.
    """
    args = argparse.Namespace()

    # [server]
    args.bridge_host = cfg.get("server", "host", default="127.0.0.1")
    args.bridge_port = cfg.get_int("server", "port", default=8104)
    args.ae_title = cfg.get("server", "ae_title", default="CLARUS_BRIDGE")
    # QA / Expose Rejected Instances AE (AIRA 57.2.1). A DIMSE association has
    # no per-query "show rejected" flag, so the standard mechanism is a second
    # AE Title whose queries go to a separately configured QA webservice
    # endpoint. Empty port = off, which leaves the bridge with exactly one AE.
    args.expose_port = cfg.get_int("server", "expose_port", default=None)
    args.expose_ae_title = cfg.get("server", "expose_ae_title", default="CLBRIDGE_QA")

    # [dicomweb]
    # 2908: single clarus_url knob (replaces host/clarus_port, NO fallback).
    clarus_url, tls_cert, tls_key = validate_clarus_url(cfg)
    args.clarus_url = clarus_url
    # The QA webservice endpoint AIRA 57.2.1 calls "specifically configured to
    # provide access to hidden instances". It is a SEPARATE BASE URL, not a
    # query parameter: the bridge must work against any DICOMweb server, and a
    # Clarus-only parameter would make it useless elsewhere.
    args.qa_url = cfg.get("dicomweb", "qa_url", default="").strip().rstrip("/")
    args.tls_client_cert = tls_cert
    args.tls_client_key = tls_key
    args.tls_pair = (tls_cert, tls_key) if tls_cert and tls_key else None
    args.health_check_mode = cfg.get(
        "dicomweb", "health_check_mode", default="probe"
    ).lower()

    # [dicomweb] storage_commitment_presence: does the ORIGIN have a
    # Storage Commitment resource (PS3.18 13.4/13.5)? true => commitment
    # verdicts come from the origin's own honest check; false (default) =>
    # today's local heuristic. Unrelated to [dimse] no_storage_commit.
    args.storage_commitment_presence = cfg.get_bool(
        "dicomweb", "storage_commitment_presence", default=False
    )

    # [dimse]
    args.c_find_max_responses = cfg.get_int(
        "dimse", "c_find_max_responses", default=200
    )
    # c_move_workers: auto-scale - I/O-bound workers (TCP to viewer + HTTP from Clarus).
    # max(2, cpu_count()//2). 2-2, 4-2, 8-4, 16-8. Admin can override in config.
    _default_cmove = max(2, (os.cpu_count() or 2) // 2)
    args.c_move_workers = cfg.get_int("dimse", "c_move_workers", default=_default_cmove)
    args.no_storage_commit = cfg.get_bool("dimse", "no_storage_commit", default=False)
    # peers_file: path to peers.conf (chmod 644, public peer list)
    args.peers_file = cfg.get("peers", "peers_file", default="./peers.conf")
    # [peers] - peer auto-registration
    args.lazyload = cfg.get_bool("peers", "lazyload", default=True)
    args.lazyload_interval = cfg.get_int("peers", "lazyload_interval", default=30)
    # - DIMSE timeouts (inbound - outbound) -
    # Inbound: bridge as SCP (C-STORE from modality, C-FIND from viewer)
    args.inbound_dimse_timeout = cfg.get_int(
        "dimse", "inbound_dimse_timeout", default=60
    )
    # inbound_network_timeout: 0 = disabled (SCP waits for client - ).
    # Viewers keep associations open during C-MOVE (PS3.4 -C.4.2.2).
    # Non-zero: kill idle associations after N seconds.
    args.inbound_network_timeout = cfg.get_int(
        "dimse", "inbound_network_timeout", default=0
    )
    args.inbound_acse_timeout = cfg.get_int("dimse", "inbound_acse_timeout", default=15)
    # Outbound: bridge as SCU (C-MOVE - C-STORE to viewer)
    args.outbound_dimse_timeout = cfg.get_int(
        "dimse", "outbound_dimse_timeout", default=60
    )
    args.outbound_network_timeout = cfg.get_int(
        "dimse", "outbound_network_timeout", default=60
    )
    args.outbound_acse_timeout = cfg.get_int(
        "dimse", "outbound_acse_timeout", default=15
    )
    # Total outbound A-ASSOCIATE attempts (main AND fallback) with
    # immediate retries, default 3, range 1..5 (spec sec.12.2 single knob).
    args.outbound_assoc_attempts = cfg.get_int(
        "dimse", "outbound_assoc_attempts", default=3
    )
    # C-MOVE progress poll timeout (2608): the bridge holds the viewer's
    # association and polls job progress in the DB. If a worker dies mid-job
    # the poll must not run forever - on expiry unfinished jobs are failed
    # and 0xB000 is returned. Range: 30..3600.
    args.move_poll_timeout = cfg.get_int("dimse", "move_poll_timeout", default=600)
    # [dimse] inbound association cap (0509 capacity): pynetdicom default
    # is 8 simultaneous inbound associations per AE. One C-MOVE holds its
    # association for the whole study transfer, and TS-fallback opens a
    # SECOND association, so 8 caps concurrent C-MOVE viewers at ~5
    # (measured 05.09: "Local limit exceeded" at step 6). Each held
    # association costs one pynetdicom thread, idle while the study
    # transfers. Default is DELIBERATELY 8 (pynetdicom parity): on weak
    # boxes the bridge then fails SOFT at the cap instead of going deep
    # into memory pressure (05.09 zram RCA: small hosts die of memory,
    # not of thread count). The bench measured 6-7 viewers clean at 32
    # with c_move_workers=2 - raise deliberately. Admin rule:
    # max_associations >= 2 x concurrent C-MOVE viewers + 4 headroom.
    # Range: 4..256.
    args.max_associations = cfg.get_int("dimse", "max_associations", default=16)

    # [bridge] - DICOM field coercion
    args.fix_empty_patient_id = cfg.get_bool(
        "bridge", "fix_empty_patient_id", default=True
    )
    args.fix_empty_patient_name = cfg.get_bool(
        "bridge", "fix_empty_patient_name", default=True
    )
    args.bridge_id_prefix = cfg.get("bridge", "id_prefix", default="AUTOPAT_")
    args.bridge_name_prefix = cfg.get("bridge", "name_prefix", default="Anonymous^")

    # [logging]
    args.log_level = cfg.get("logging", "log_level", default="INFO").upper()
    args.log_file = cfg.get("logging", "log_file", default=None)

    # [metrics]
    args.http_port = cfg.get_int("metrics", "health_port", default=8105)
    args.http_print_bind = cfg.get("metrics", "http_bind", default="127.0.0.1")

    # [advanced]
    args.sop_registry = cfg.get(
        "advanced", "sop_registry", default="clbridge/sop_classes.yaml"
    )
    args.printers_yaml = cfg.get(
        "advanced", "printers_yaml", default="clbridge/printers.yaml"
    )
    args.sop_index_dir = cfg.get(
        "advanced", "sop_index_dir", default="./clbridge/sop_index"
    )
    args.max_store_mb = cfg.get_int("advanced", "max_store_mb", default=0)
    args.http_timeout = cfg.get_int("advanced", "http_timeout", default=30)
    args.health_check_interval = cfg.get_float(
        "advanced", "health_check_interval_sec", default=5.0
    )
    args.stow_queue_max_mb = cfg.get_int("advanced", "stow_queue_max_mb", default=500)
    args.stow_queue_size = cfg.get_int("advanced", "stow_queue_size", default=20000)
    args.outbox_dir = cfg.get("outbox", "outbox_dir", default="clbridge/outbox")
    args.outbox_cleanup = cfg.get_bool("outbox", "cleanup", default=True)
    args.outbox_max_retries = cfg.get_int("outbox", "max_retries", default=10)
    args.outbox_retry_interval = cfg.get_int("outbox", "retry_interval", default=0)
    # Outbox STOW batching: flush a study-batch when any trigger fires.
    args.outbox_batch_max_sop = cfg.get_int("outbox", "batch_max_sop", default=100)
    args.outbox_batch_max_bytes = cfg.get_int(
        "outbox", "batch_max_bytes", default=96 * 1024 * 1024
    )
    args.outbox_batch_idle_sec = cfg.get_float("outbox", "batch_idle_sec", default=5.0)
    # STORE-FORWARD: when on, a C-STORE against a dead server (>=30s)
    # is PARKED (0x0000; blob already atomically on disk) instead of 0xC000.
    args.outbox_store_forward = cfg.get_bool("outbox", "store_forward", default=False)

    # [forward] - 0409: best-effort DIMSE->DIMSE mirror to a second archive.
    # Absent or enabled=false keeps behaviour byte-identical to pre-0409.
    args.forward_enabled = cfg.get_bool("forward", "enabled", default=False)
    args.forward_dest_ae = cfg.get("forward", "dest_ae", default=None)
    args.forward_dest_host = cfg.get("forward", "dest_host", default=None)
    args.forward_dest_port = cfg.get_int("forward", "dest_port", default=0)
    args.forward_max_queue = cfg.get_int("forward", "forward_max_queue", default=20000)

    # Backpressure: max concurrent C-STORE handlers
    max_cstore = cfg.get_int("advanced", "max_concurrent_cstore", default=None)
    if max_cstore is not None:
        max_cstore = max(1, min(50, max_cstore))
        set_max_concurrent_cstore(max_cstore)
        logging.info("[CONFIG] max_concurrent_cstore = %d", max_cstore)

    return args

# ---------------------------------------------------------------------------
# CONFIG-DISCIPLINE: _validate_config - validate all config values
# ---------------------------------------------------------------------------
def _validate_config(cfg):
    """Validate config values are within allowed ranges. Raises ValueError on violation."""
    errors = []

    def check(cond, msg):
        if not cond:
            errors.append(msg)

    # Server
    port = cfg.get_int("server", "port", default=8104)
    check(1 <= port <= 65535, f"server.port {port} out of range [1..65535]")

    # DICOMweb
    # 2908: clarus_url validated fail-fast (scheme, host, legacy-key removal,
    # mTLS pair symmetry). Raises ValueError with a clear message.
    validate_clarus_url(cfg)

    # Dimse
    cmove = cfg.get_int("dimse", "c_move_workers", default=2)
    check(0 <= cmove <= 16, f"dimse.c_move_workers {cmove} out of range [0..16]")
    cfind = cfg.get_int("dimse", "c_find_max_responses", default=200)
    check(
        0 <= cfind <= 10000,
        f"dimse.c_find_max_responses {cfind} out of range [0..10000]",
    )
    # Inbound DIMSE timeouts (bridge as SCP)
    idt = cfg.get_int("dimse", "inbound_dimse_timeout", default=60)
    check(10 <= idt <= 300, f"dimse.inbound_dimse_timeout {idt} out of range [10..300]")
    int_ = cfg.get_int("dimse", "inbound_network_timeout", default=0)
    check(
        int_ == 0 or (10 <= int_ <= 600),
        f"dimse.inbound_network_timeout {int_} out of range [0 or 10..600]",
    )
    iat = cfg.get_int("dimse", "inbound_acse_timeout", default=15)
    check(5 <= iat <= 60, f"dimse.inbound_acse_timeout {iat} out of range [5..60]")
    # Outbound DIMSE timeouts (bridge as SCU, C-MOVE)
    odt = cfg.get_int("dimse", "outbound_dimse_timeout", default=60)
    check(
        10 <= odt <= 600, f"dimse.outbound_dimse_timeout {odt} out of range [10..600]"
    )
    ont = cfg.get_int("dimse", "outbound_network_timeout", default=60)
    check(
        10 <= ont <= 600, f"dimse.outbound_network_timeout {ont} out of range [10..600]"
    )
    oat = cfg.get_int("dimse", "outbound_acse_timeout", default=15)
    check(5 <= oat <= 60, f"dimse.outbound_acse_timeout {oat} out of range [5..60]")
    # Outbound association attempts (main + fallback), range 1..5.
    oaa = cfg.get_int("dimse", "outbound_assoc_attempts", default=3)
    check(1 <= oaa <= 5, f"dimse.outbound_assoc_attempts {oaa} out of range [1..5]")
    # C-MOVE progress poll timeout (2608): bounds the held reactor's poll of
    # job progress. On expiry unfinished jobs are failed and 0xB000 returned.
    mpt = cfg.get_int("dimse", "move_poll_timeout", default=600)
    check(30 <= mpt <= 3600, f"dimse.move_poll_timeout {mpt} out of range [30..3600]")
    mas = cfg.get_int("dimse", "max_associations", default=16)
    check(4 <= mas <= 256, f"dimse.max_associations {mas} out of range [4..256]")

    # Logging
    level = cfg.get("logging", "log_level", default="INFO").upper()
    check(
        level in ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"),
        f"logging.log_level '{level}' must be DEBUG|INFO|WARNING|ERROR|CRITICAL",
    )

    # Metrics
    hp = cfg.get_int("metrics", "health_port", default=8105)
    check(1 <= hp <= 65535, f"metrics.health_port {hp} out of range [1..65535]")

    # Advanced
    ms = cfg.get_int("advanced", "max_store_mb", default=0)
    check(ms >= 0, f"advanced.max_store_mb {ms} must be >= 0")
    ht = cfg.get_int("advanced", "http_timeout", default=30)
    check(1 <= ht <= 300, f"advanced.http_timeout {ht} out of range [1..300]")
    sqm = cfg.get_int("advanced", "stow_queue_max_mb", default=500)
    check(
        10 <= sqm <= 2000, f"advanced.stow_queue_max_mb {sqm} out of range [10..2000]"
    )
    sqs = cfg.get_int("advanced", "stow_queue_size", default=20000)
    check(
        100 <= sqs <= 100000,
        f"advanced.stow_queue_size {sqs} out of range [100..100000]",
    )
    hi = cfg.get_float("advanced", "health_check_interval_sec", default=5.0)
    check(
        1.0 <= hi <= 60.0,
        f"advanced.health_check_interval_sec {hi} out of range [1.0..60.0]",
    )

    # DICOMweb health check mode
    hcm = cfg.get("dicomweb", "health_check_mode", default="probe").lower()
    check(
        hcm in ("probe", "always", "never"),
        f"dicomweb.health_check_mode '{hcm}' must be probe|always|never",
    )

    # Outbox STOW batching
    bs = cfg.get_int("outbox", "batch_max_sop", default=100)
    check(1 <= bs <= 500, f"outbox.batch_max_sop {bs} out of range [1..500]")
    bb = cfg.get_int("outbox", "batch_max_bytes", default=96 * 1024 * 1024)
    check(
        1 <= bb <= 2048 * 1024 * 1024,
        f"outbox.batch_max_bytes {bb} out of range [1..2048MB]",
    )
    bi = cfg.get_float("outbox", "batch_idle_sec", default=5.0)
    check(0.1 <= bi <= 60.0, f"outbox.batch_idle_sec {bi} out of range [0.1..60]")

    # [forward] - 0409: best-effort DIMSE->DIMSE second-archive mirror.
    # When enabled, the destination modality/host/port are REQUIRED and the
    # port/queue-size ranges are enforced. When disabled (or the section
    # absent), nothing is required - an upgrade changes no behaviour.
    if cfg.get_bool("forward", "enabled", default=False):
        if not cfg.get("forward", "dest_ae", default=None):
            errors.append("forward.dest_ae is required when forward.enabled=true")
        if not cfg.get("forward", "dest_host", default=None):
            errors.append("forward.dest_host is required when forward.enabled=true")
        fdp = cfg.get_int("forward", "dest_port", default=0)
        check(1 <= fdp <= 65535, f"forward.dest_port {fdp} out of range [1..65535]")
        fqm = cfg.get_int("forward", "forward_max_queue", default=20000)
        check(
            1 <= fqm <= 100000,
            f"forward.forward_max_queue {fqm} out of range [1..100000]",
        )

    if errors:
        raise ValueError("Configuration errors:\n  " + "\n  ".join(errors))

    logging.info("[CONFIG] All values validated - OK")

# _init_components - initialize managers and registries
# ---------------------------------------------------------------------------
class _LockedDb:
    """The `SharedDb.locked()` context: one connection, one lock."""

    def __init__(self, lock, conn):
        self._lock = lock
        self._conn = conn

    def __enter__(self):
        self._lock.acquire()
        return self._conn

    def __exit__(self, *args):
        self._lock.release()

class _MoveJobsDb:
    """Minimal SharedDb-compatible wrapper.

    One file, one connection, one lock. Two consumers share the shape - the
    C-MOVE state machine (`move_jobs.db`) and the Storage Commitment
    tracker's outstanding batches (`commit_jobs.db`) - and a single
    serialized writer is what keeps both free of SQLite busy-handler
    tuning. They get separate FILES, not separate classes: a tracker write
    that cannot proceed must not be able to block a C-MOVE claim.
    """

    def __init__(self, path):
        import sqlite3 as _sqlite3

        self._conn = _sqlite3.connect(path, check_same_thread=False)
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._lock = threading.Lock()

    def locked(self):
        return _LockedDb(self._lock, self._conn)

    def close(self):
        with self._lock:
            try:
                self._conn.close()
            except Exception:
                pass

def _init_components(args):
    """Initialize SopIndexManager, MoveJobManager, printer_registry, driver_registry.

    Returns (sop_index, move_jobs, printer_registry, driver_registry).
    """
    sop_index = SopIndexManager(index_dir=args.sop_index_dir)
    # move_jobs keeps its own SQLite - it's the right tool for state machine + multi-worker claim.
    move_jobs_db_path = os.path.join(
        os.path.dirname(args.sop_index_dir), "move_jobs.db"
    )
    # SCP peer auto-remove threshold is a fixed constant.
    move_jobs = MoveJobManager(
        shared_db=_MoveJobsDb(move_jobs_db_path),
        max_workers=args.c_move_workers,
        scp_remove_failures=_SCP_FAILURES_BEFORE_REMOVE,
    )
    move_jobs.lazyload_peers_interval = args.lazyload_interval if args.lazyload else 0

    # Bridge: recover in-progress jobs from previous crash
    recovered = move_jobs.recover_in_progress_jobs()
    if recovered > 0:
        logging.warning(
            "[C-MOVE] Recovered %d in-progress job(s) from previous session. "
            "They are now available for retry by the C-MOVE worker.",
            recovered,
        )

    # Bridge: peers are loaded on first C-MOVE, not at startup.
    # Weasis/OHIF/modality will NEVER be running before the bridge.
    # Lazy registration via lookup_scp miss - reload_peers_from_file.

    # Bridge: load printer registry
    printer_registry = _load_printer_registry(args.printers_yaml)

    # Bridge: register C-PRINT drivers - only if drivers/ folder is present
    driver_registry = {}
    if _CPRINT_AVAILABLE:
        driver_registry["generic_dicom"] = GenericDicomPrintDriver()
        logging.info("[C-PRINT] Generic DICOM Print driver loaded")
    else:
        logging.info(
            "[C-PRINT] drivers/ folder not found - print support disabled. "
            "Download drivers/ from https://github.com/clarus-pacs/clarus to enable."
        )

    return sop_index, move_jobs, printer_registry, driver_registry

# ---------------------------------------------------------------------------
# BR-P31: SOP index periodic cleanup worker - prevents unbounded :memory: growth
# ---------------------------------------------------------------------------
def _sop_index_cleanup_worker(sop_index, max_age_hours=24):
    """Background thread: remove SOP index entries older than max_age_hours.

    Without periodic cleanup, the SopIndexManager's :memory: SQLite B-tree grows
    unbounded - 55K objects = ~15-25 MB, millions of objects after weeks of 24/7
    operation = hundreds of MB of RSS - Python GC gen2 pauses - GIL stalls.

    Runs once per hour. Stops when _shutdown_requested is set.
    """

    max_age_seconds = max_age_hours * 3600
    logging.info(
        "[SOP-INDEX] Cleanup worker started (max age: %dh)",
        max_age_hours,
    )

    while not _shutdown_requested.is_set():
        _shutdown_requested.wait(timeout=3600.0)  # Every hour
        if _shutdown_requested.is_set():
            break
        try:
            before = sop_index.count()
            sop_index.cleanup(max_age_seconds)
            after = sop_index.count()
            if before != after:
                logging.info(
                    "[SOP-INDEX] Cleanup: %d entries removed, %d remain",
                    before - after,
                    after,
                )
        except Exception as e:
            logging.error("[SOP-INDEX] Cleanup error: %s", e)

    logging.info("[SOP-INDEX] Cleanup worker stopped")

# ---------------------------------------------------------------------------
# Duplicate instance detection - three layers
# ---------------------------------------------------------------------------

def _check_port_available(port: int, bind_addr: str, name: str) -> None:
    """Layer 1: TCP bind() with the listener's own reuse semantics.

    The check must match how the real listeners bind, or it reports a free
    port as taken: a listener that closes leaves the port in TIME_WAIT for
    about a minute on Linux, and a probe without SO_REUSEADDR fails with
    EADDRINUSE for that whole window - which turns an ordinary restart into a
    manual wait.

    Windows is the exception in the other direction: there SO_REUSEADDR lets a
    second socket bind a port that is ACTIVELY listening, so it would weaken
    exactly the duplicate-instance guard this function exists for.
    SO_EXCLUSIVEADDRUSE is its counterpart - it refuses a port another socket
    holds, including one in TIME_WAIT.
    """
    import socket

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        if sys.platform == "win32":
            exclusive = getattr(socket, "SO_EXCLUSIVEADDRUSE", None)
            if exclusive is not None:
                sock.setsockopt(socket.SOL_SOCKET, exclusive, 1)
        else:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.bind((bind_addr, port))
    except OSError as e:
        logging.error(
            "[FATAL] bind() to %s:%d (%s) failed: %s - "
            "another process may be using this port. Refusing to start.",
            bind_addr,
            port,
            name,
            e,
        )
        sys.exit(1)
    finally:
        sock.close()

def _check_dimse_unique(host: str, port: int, my_ae_title: str) -> None:
    """Layer 2: C-ECHO probe against the DICOMweb server via pynetdicom.

    Probes the Clarus Bridge AE over DIMSE; a live association proves
    the configured server address and AE settings are reachable.
    - AE Title is echoed back by the server (Clarus Bridge).
    - AE Title mismatch is reported without aborting the DICOMweb path.
    """
    from pynetdicom import AE as ProbeAE
    from pynetdicom.sop_class import Verification

    # Resolve 0.0.0.0 / :: to loopback - can't connect to bind-any address.
    probe_host = host
    if host in ("0.0.0.0", "::"):
        probe_host = "127.0.0.1"

    probe_ae_title = (f"{my_ae_title}_PROBE")[:16]  # DICOM AE: max 16 chars
    probe_ae = ProbeAE(ae_title=probe_ae_title)
    probe_ae.add_requested_context(Verification)
    probe_ae.network_timeout = 2
    probe_ae.acse_timeout = 2

    # Suppress pynetdicom internal logging during probe - connection
    # refusal is expected (means we're the only process on this port).
    _probe_logger = logging.getLogger("pynetdicom")
    _probe_prev_level = _probe_logger.level
    _probe_logger.setLevel(logging.CRITICAL + 1)

    assoc = None
    try:
        # Call as the bridge's own AE title - with require_called_aet=True a
        # running bridge instance rejects the generic probe title.
        assoc = probe_ae.associate(probe_host, port, ae_title=my_ae_title)
        if assoc.is_established:
            remote_ae = (
                assoc.acceptor.ae_title
                if hasattr(assoc, "acceptor") and assoc.acceptor
                else "unknown"
            )
            if remote_ae == my_ae_title:
                logging.error(
                    "[FATAL] C-ECHO: another Clarus Bridge (AE=%s) already "
                    "listening on %s:%d. Refusing to start.",
                    remote_ae,
                    host,
                    port,
                )
            else:
                logging.error(
                    "[FATAL] C-ECHO: DIMSE port %s:%d already in use "
                    "by AE=%s. Refusing to start.",
                    host,
                    port,
                    remote_ae,
                )
            sys.exit(1)
    except Exception:
        # - - - - -. -.
        pass
    finally:
        _probe_logger.setLevel(_probe_prev_level)
        try:
            if assoc is not None and assoc.is_established:
                assoc.release()
        except Exception:
            pass

def _default_pid_path(port: int) -> str:
    """Platform default path for the bridge PID file.

    Linux: `/var/run/clbridge-{port}.pid`. A PID file is a system-level
    thing on Unix; the FHS location is what an operator's init scripts
    expect. It is NOT guaranteed writable (that needs root), which is
    exactly why `_write_pid_file` degrades instead of dying - see below.

    Elsewhere (Windows, macOS): next to the executable/script, which is
    the historical location and always writable by the user who can start
    the process in the first place.
    """
    if sys.platform.startswith("linux"):
        return os.path.join("/var/run", f"clbridge-{port}.pid")
    script_dir = os.path.dirname(
        os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)
    )
    return os.path.join(script_dir, f"clbridge-{port}.pid")

def _fallback_pid_path(port: int) -> str:
    """Fallback PID path when the default is not writable.

    Next to the script/executable. This is the pre-04.09 behaviour and it
    worked everywhere except when the install directory itself was read-only.
    """
    script_dir = os.path.dirname(
        os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)
    )
    return os.path.join(script_dir, f"clbridge-{port}.pid")

def _pid_is_alive(pid: int) -> bool:
    """True when `pid` names a running process.

    `os.kill(pid, 0)` is the POSIX idiom, but on Windows it does NOT probe:
    CPython implements it with TerminateProcess, so signal 0 KILLS the process
    it was asked to check. The bridge's own PID file then took down whatever
    held that pid - which on a recycled pid is an unrelated program.
    """
    if pid <= 0:
        return False
    if os.name == "nt":
        # Windows: ask for the process handle and its exit code instead.
        import ctypes
        from ctypes import wintypes

        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        handle = kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if not handle:
            err = ctypes.get_last_error()
            # 5 = ACCESS_DENIED: the process exists but is not ours to inspect.
            return err == 5
        try:
            code = wintypes.DWORD()
            if not kernel32.GetExitCodeProcess(handle, ctypes.byref(code)):
                return True  # cannot tell: assume alive and refuse to steal
            return code.value == STILL_ACTIVE
        finally:
            kernel32.CloseHandle(handle)
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        # The process exists but belongs to another user.
        return True

def _write_pid_file(path: str) -> None:
    """Layer 3: atomic PID file via O_EXCL.

    Order: platform default (/var/run on Linux, next to the script
    elsewhere); if not writable, fall back next to the script; if
    neither is writable, WARN and run WITHOUT a PID file. FATAL only
    when a live foreign pid occupies the path.

    The FATAL path exits via os._exit(1) because _write_pid_file is
    called from _fatal_pid_error.
    """
    pid = str(os.getpid())
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    except FileExistsError:
        with open(path) as f:
            old_pid = f.read().strip()
        try:
            alive = _pid_is_alive(int(old_pid))
        except ValueError:
            alive = False
        if alive:
            logging.error(
                "[FATAL] PID file %s exists and pid=%s is ALIVE. "
                "Another instance is running. Remove %s manually if stale.",
                path,
                old_pid,
                path,
            )
            # os._exit: immediate process termination, works on Win+*nix.
            # sys.exit only raises SystemExit - non-daemon threads prevent exit.
            os._exit(1)
        else:
            logging.warning(
                "[WARN] Stale PID file %s (pid=%s is dead). Overwriting.",
                path,
                old_pid,
            )
            try:
                os.remove(path)
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
            except OSError as e:
                logging.warning(
                    "[WARN] Cannot rewrite stale PID file %s: %s. Continuing without it.",
                    path,
                    e,
                )
                return
    except OSError as e:
        # PermissionError is an OSError. NOT fatal: the service must start.
        logging.warning(
            "[WARN] Cannot create PID file %s: %s. Continuing without it.",
            path,
            e,
        )
        return
    with os.fdopen(fd, "w") as f:
        f.write(pid)
    logging.info("[PID] %s written (pid=%s)", path, pid)

def _acquire_pid_file(port: int) -> str:
    """Resolve, write and register the PID file. Returns the path in use.

    There is deliberately NO configuration for this: no config key, no CLI
    flag, no environment variable. The PID file is an internal artefact and
    the operator never needs to know about it.

    Order (owner directive, incident 04.09):
      1. platform default (`/var/run/...` on Linux, next to the script
         elsewhere);
      2. if that is not writable - fall back next to the script;
      3. if neither is writable - WARN and run WITHOUT a PID file.

    A live foreign pid is fatal, because two instances must not silently
    coexist.
    """
    candidates = []
    default = _default_pid_path(port)
    fallback = _fallback_pid_path(port)
    candidates.append(default)
    if fallback != default:
        candidates.append(fallback)

    for candidate in candidates:
        directory = os.path.dirname(candidate) or "."
        if not os.path.isdir(directory):
            logging.warning(
                "[WARN] PID directory %s does not exist; skipping %s.",
                directory,
                candidate,
            )
            continue
        if not os.access(directory, os.W_OK):
            logging.warning(
                "[WARN] PID directory %s is not writable; skipping %s.",
                directory,
                candidate,
            )
            continue
        # A live foreign pid inside _write_pid_file exits the process; a
        # stale one is overwritten and we return that same path.
        _write_pid_file(candidate)
        return candidate

    logging.warning(
        "[WARN] No writable PID file location found (tried: %s). "
        "Continuing without a PID file.",
        ", ".join(candidates),
    )
    return ""

# ---------------------------------------------------------------------------
# _start_background_services - HTTP server, C-MOVE workers, cleanup
# ---------------------------------------------------------------------------
def _start_background_services(
    args, driver_registry, printer_registry, move_jobs, sop_index, sop_registry
):
    """Start HTTP server, C-MOVE workers, cleanup thread.

    Returns (http_server, http_thread, cmove_thread, cleanup_thread, sop_cleanup_thread,
             outbox, outbox_workers, health_checker, commit_tracker, commit_thread,
             forward_outbox, forward_worker_thread).
    """
    # Outbox Queue - filesystem-backed reliable DICOM persistence + delivery
    max_queue = args.stow_queue_size
    outbox = OutboxQueue(
        outbox_dir=args.outbox_dir,
        max_queue=max_queue,
        max_retries=args.outbox_max_retries,
        cleanup=args.outbox_cleanup,
        retry_interval=args.outbox_retry_interval,
    )
    recovered, undelivered = outbox.recover_stuck()
    outbox_pending.set(outbox.pending_count())
    if recovered > 0:
        outbox_recovery_total.inc(recovered)
    # Update disk bytes metric
    try:
        total = sum(
            os.path.getsize(os.path.join(root, f))
            for root, _, files in os.walk(args.outbox_dir)
            for f in files
        )
        outbox_disk_bytes.set(total)
    except OSError:
        pass

    # Forwarder: SECOND OutboxQueue instance pointed at its own
    # directory (<outbox_dir>/forward). Only constructed when forward is
    # enabled - an upgrade without the config block creates NO new dirs and
    # changes NO metric behaviour. Feeding it forward_pending (not
    # outbox_pending) keeps the two queues' gauges isolated. The drain worker
    # that consumes this queue is the drain worker; reception-only wiring lives here.
    forward_outbox = None
    if getattr(args, "forward_enabled", False):
        forward_dir = os.path.join(args.outbox_dir, "forward")
        forward_outbox = OutboxQueue(
            outbox_dir=forward_dir,
            max_queue=args.forward_max_queue,
            max_retries=10,  # 0409: forward-queue retry budget (like outbox)
            cleanup=args.outbox_cleanup,
            pending_gauge=forward_pending,
            undelivered_total=forward_undelivered_total,
        )
        logging.info(
            "[FORWARD] secondary queue enabled -> %s (max_queue=%d, max_retries=10)",
            forward_dir,
            args.forward_max_queue,
        )

    # HealthChecker - background poller + pre-flight gate
    hc_mode = getattr(args, "health_check_mode", "probe")
    hc_interval = getattr(args, "health_check_interval", 5.0)
    health_checker = HealthChecker(
        clarus_url=args.clarus_url,
        mode=hc_mode,
        interval=hc_interval,
        http_timeout=args.http_timeout,
        tls=args.tls_pair,
    )
    health_checker.start()

    # Bridge: start HTTP server in daemon thread
    bridge_up.set(1)  # mark bridge as running

    # P2.10: ThreadingHTTPServer - each request handled in its own thread.
    # Single-threaded HTTPServer serialized /health behind heavy /metrics
    # (Prometheus rendering), causing >5s response times under load.
    HandlerCls = make_bridge_handler(
        driver_registry,
        printer_registry,
        args.ae_title,
        outbox=outbox,
        health_checker=health_checker,
        move_jobs=move_jobs,
    )
    http_server = ThreadingHTTPServer(
        (args.http_print_bind, args.http_port),
        HandlerCls,
    )
    http_thread = threading.Thread(
        target=http_server.serve_forever,
        name="http-bridge-server",
        daemon=False,
    )
    http_thread.start()
    logging.info(
        "[HTTP] Bridge server listening on %s:%d (/print, /metrics, /health)",
        args.http_print_bind,
        args.http_port,
    )

    # Start single outbox background worker (KISS: one worker, N SOPs per STOW-RS)
    outbox_workers = _start_outbox_workers(
        outbox,
        args.clarus_url,
        args.http_timeout,
        sop_index,
        move_jobs,
        batch_max_sop=args.outbox_batch_max_sop,
        batch_max_bytes=args.outbox_batch_max_bytes,
        batch_idle_sec=args.outbox_batch_idle_sec,
        health_checker=health_checker,
        tls=args.tls_pair,
        bridge_ae_title=args.ae_title,
    )
    logging.info(
        "[OUTBOX-WORKER] Started 1 worker, outbox: %s "
        "(batch: sop<=%d bytes<=%d idle<=%.0fs)",
        args.outbox_dir,
        args.outbox_batch_max_sop,
        args.outbox_batch_max_bytes,
        args.outbox_batch_idle_sec,
    )

    # Bridge: start C-MOVE background worker pool
    cmove_thread = threading.Thread(
        target=_cmove_worker,
        args=(
            move_jobs,
            args.clarus_url,
            args.http_timeout,
            args.ae_title,
        ),
        kwargs={
            "num_workers": args.c_move_workers,
            "sop_registry": sop_registry,
            "storage_commit_after_move": not args.no_storage_commit,
            "sop_index": sop_index,
            "peers_file": args.peers_file,
            "outbound_network_timeout": args.outbound_network_timeout,
            "outbound_dimse_timeout": args.outbound_dimse_timeout,
            "outbound_acse_timeout": args.outbound_acse_timeout,
            "outbound_assoc_attempts": args.outbound_assoc_attempts,
            "tls": args.tls_pair,
            "qa_url": args.qa_url,
        },
        name="cmove-worker-pool",
        daemon=False,
    )
    cmove_thread.start()
    logging.info(
        "[C-MOVE] Background worker pool started (%d workers)", args.c_move_workers
    )

    # Bridge: start C-MOVE cleanup worker
    cleanup_thread = threading.Thread(
        target=_cmove_cleanup_worker,
        args=(move_jobs, 24),
        name="cmove-cleanup",
        daemon=False,
    )
    cleanup_thread.start()

    # BR-P31: start SOP index cleanup worker - prevents unbounded :memory: growth
    sop_cleanup_thread = threading.Thread(
        target=_sop_index_cleanup_worker,
        args=(sop_index, 24),
        name="sop-index-cleanup",
        daemon=False,
    )
    sop_cleanup_thread.start()

    # Async Storage Commitment report loop (N-EVENT-REPORT). Fire-and-
    # forget: N-ACTION registers a batch; this worker resolves it and sends
    # ONE report back.
    #
    # Two modes (2409), selected once here by storage_commitment_presence:
    #   false (default) - the readiness gate is the local probe: all SOPs
    #     confirmed via WADO-RS, or the 300s deadline, then the local
    #     heuristic's verdict (unconfirmed -> 0x0110).
    #   true - the readiness gate is the bridge's OWN outbox delivery state
    #     (a C-STORE returns before its STOW completes, so an immediate
    #     origin-side ask would report false "not stored" verdicts), then
    #     ONE POST to the origin's Commit resource and its verdict verbatim.
    def _verify_cb(sop_class, sop_uid):
        return (
            _sop_confirm(
                sop_uid,
                sop_index,
                args.clarus_url,
                args.http_timeout,
                tls=args.tls_pair,
            )
            == 0
        )

    stc_presence = bool(getattr(args, "storage_commitment_presence", False))

    def _resolve_stc(job):
        """Ask the origin ONCE and report its verdict verbatim (true-mode).

        Only wired in true-mode; false-mode leaves `resolve` unset so the
        tracker runs its own heuristic, byte-for-byte as before.
        """
        committed, failed, sentinel = _stc_commit_request(
            args.clarus_url,
            job.tx_uid,
            job.sops,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
        )
        if sentinel == STC_NO_RESOURCE:
            # The WARN already named the misconfiguration; there is
            # deliberately no fallback to the local path.
            logging.warning(
                "[N-EVENT] tx=%s: origin has no Commit resource - reporting "
                "every SOP failed (0x0110)",
                job.tx_uid,
            )
        event_type = 1 if not failed else 2
        send_n_event_report(
            job.host,
            job.port,
            job.calling_ae,
            job.tx_uid,
            event_type,
            committed,
            failed,
            args.ae_title,
        )

    # Storage Commitment batches are a promise to the modality (PS3.4
    # J.3.3.1: the N-EVENT-REPORT IS the result), so an outstanding batch has
    # to survive a restart. It gets its OWN database file rather than a table
    # alongside move_jobs: a tracker write must not contend with a C-MOVE
    # claim, and the two have nothing to join on.
    commit_db_path = os.path.join(os.path.dirname(args.sop_index_dir), "commit_jobs.db")

    if stc_presence:
        # Origin-owned commitment: the readiness signal is the bridge's OWN
        # delivery state, not a probe (a C-STORE returns before its STOW
        # completes, so an immediate origin-side ask would report false "not
        # stored" verdicts). `delivered` is the outbox's read-side query.
        commit_tracker = CommitTracker(
            verify=lambda sop_class, sop_uid: outbox.delivered(sop_uid),
            report=functools.partial(
                send_n_event_report, bridge_ae_title=args.ae_title
            ),
            resolve=_resolve_stc,
            deadline_sec=300.0,
            db=_MoveJobsDb(commit_db_path),
        )
    else:
        # Unchanged local heuristic: the tracker's own _resolve owns it.
        commit_tracker = CommitTracker(
            verify=_verify_cb,
            report=functools.partial(
                send_n_event_report, bridge_ae_title=args.ae_title
            ),
            deadline_sec=300.0,
            db=_MoveJobsDb(commit_db_path),
        )
    commit_thread = threading.Thread(
        target=commit_tracker.run,
        name="commit-tracker",
        daemon=False,
    )
    commit_thread.start()
    # Expose the tracker to the /metrics scrape (pending-batch gauges). The
    # HTTP server is already serving, so the ref is attached to its handler
    # class once the tracker exists.
    try:
        HandlerCls._commit_tracker_ref = commit_tracker
    except Exception:
        pass
    logging.info(
        "Storage Commitment: %s",
        "origin STC" if stc_presence else "local heuristic",
    )

    # Forwarder: separate DIMSE drain thread for the second,
    # NON-authoritative archive. Started ONLY when the forward queue exists
    # (enabled). It shares NO state with the primary STOW drain thread and
    # runs on its own queue, so a dead second server can only pause its own
    # batch - never the primary reception/delivery (isolation).
    forward_worker_thread = None
    if forward_outbox is not None:
        forward_worker_thread = threading.Thread(
            target=_forward_worker,
            args=(
                forward_outbox,
                args.forward_dest_ae,
                args.ae_title,
                args.forward_dest_host,
                args.forward_dest_port,
            ),
            kwargs={
                "network_timeout": args.outbound_network_timeout,
                "dimse_timeout": args.outbound_dimse_timeout,
                "acse_timeout": args.outbound_acse_timeout,
            },
            name="forward-worker",
            daemon=False,
        )
        forward_worker_thread.start()
        logging.info(
            "[FORWARD] drain worker started: %s@%s:%d (best-effort DIMSE mirror)",
            args.forward_dest_ae,
            args.forward_dest_host,
            args.forward_dest_port,
        )

    return (
        http_server,
        http_thread,
        cmove_thread,
        cleanup_thread,
        sop_cleanup_thread,
        outbox,
        outbox_workers,
        health_checker,
        commit_tracker,
        commit_thread,
        forward_outbox,
        forward_worker_thread,
    )

# ---------------------------------------------------------------------------
# Outbox Queue: background STOW workers (replaces sync STOW-RS in handler)
# ---------------------------------------------------------------------------

def _outbox_worker(
    outbox,
    clarus_url,
    http_timeout,
    sop_index,
    move_jobs,
    batch_max_sop=100,
    batch_max_bytes=96 * 1024 * 1024,
    batch_idle_sec=5.0,
    health_checker=None,
    tls=None,
    bridge_ae_title="CLARUS_BRIDGE",
):
    """Background worker: drains outbox, batches same-study SOPs into one STOW-RS.

    Fieldtest: 1 SLICE = 1 POST -> N SLICES = 1 POST (1063 -> ~20).
    Flush triggers, whoever fires first:
      - count  >= batch_max_sop
      - bytes  >= batch_max_bytes (buffer cap; on-disk blob size as proxy)
      - idle   >= batch_idle_sec  (study tail, non-empty buffer)
      - study boundary: SWITCH to another study flushes the tail IMMEDIATELY.
    Studies never mix in one batch. Single worker drains sequentially; each
    flush is independent (no cross-study waiting). P8 raw pass-through kept
    per part (byte-identical content for CAS dedup).

    Stage 5 (store_forward): while the server is down (health_checker reports
    unhealthy), the worker PAUSES instead of burning STOW retries
    (MAX_RETRIES=10 -> undelivered -> manual intervention). No HTTP on this
    hot path - it only reads the health checker's cached event.

    nginx-way: one worker drains STOW. Outbox decouples C-STORE from
    delivery: C-STORE ACKs once the blob is on disk, worker forwards later.
    """
    import os

    import httpx

    # P30: persistent HTTP client -- Keep-Alive. One handshake for the whole
    # queue drain instead of one per instance (x2 throughput).
    # 2908: cert=tls enables mTLS when configured; verify is ALWAYS on
    # (httpx default) - there is no knob to disable it.
    _http = httpx.Client(
        timeout=httpx.Timeout(http_timeout + 10),
        limits=httpx.Limits(max_keepalive_connections=1, max_connections=1),
        cert=tls,
    )

    _last_stuck_check = time.time()  # periodic reaper timer
    # P8: watchdog -- last successful delivery for liveness monitoring
    _last_progress = time.time()
    _progress_lock = threading.Lock()
    # Log "paused"/"resumed" once per transition, not every 5s poll.
    _was_paused = False
    # 2908: 507 backpressure state (Retry-After pause, files stay pending).
    _pause_until = 0.0
    _was_507_paused = False

    # Delivery summary ("432/432 delivered", not 432 "201 Created").
    _delivered_total = 0
    _delivered_failed = 0
    _last_summary_log = time.time()  # throttle progress logs to every 30s
    _queue_was_empty = True  # detect queue-empty -> summary transition
    # Per-study tracking: {study_uid -> {delivered, failed, patient, modalities}}
    _study_stats: dict[str, dict] = {}
    _current_study: str | None = None

    # Batching state: current same-study buffer + its byte total.
    _batch: list = []  # (sop_uid, ds, blob_path, raw_bytes, dataset_modified)
    _batch_study: str | None = None
    _batch_bytes = 0

    def _log_study_start(sop_uid, ds, study_uid):
        """First SOP of a study: log and seed per-study stats."""
        if study_uid not in _study_stats:
            try:
                _patient_id = mask_patient_id(str(getattr(ds, "PatientID", "?")))
            except Exception:
                _patient_id = "?"
            try:
                _modality = str(getattr(ds, "Modality", "??"))
            except Exception:
                _modality = "??"
            _study_stats[study_uid] = {
                "delivered": 0,
                "failed": 0,
                "patient": _patient_id,
                "modalities": {_modality} if _modality and _modality != "??" else set(),
            }
        else:
            # Track all modalities seen (studies often mix DX + SR etc.)
            try:
                _modality = str(getattr(ds, "Modality", "??"))
                if _modality and _modality != "??":
                    _study_stats[study_uid].setdefault("modalities", set()).add(
                        _modality
                    )
            except Exception:
                pass

    def _deliver_batch():
        """Send the accumulated same-study batch, mark per-SOP outcomes."""
        nonlocal _batch, _batch_study, _batch_bytes
        nonlocal _delivered_total, _delivered_failed, _last_summary_log
        nonlocal _queue_was_empty, _current_study
        nonlocal _pause_until
        if not _batch:
            return
        batch_study = _batch_study
        mods = (
            ", ".join(
                sorted(_study_stats.get(batch_study, {}).get("modalities", set()))
            )
            or "??"
        )
        logging.info(
            "[OUTBOX] Flushing batch: study=%s %d SOP(s) %d bytes %s",
            (batch_study or "")[:50],
            len(_batch),
            _batch_bytes,
            mods,
        )
        payloads = [
            (uid, ds, (None if modified else raw))
            for uid, ds, _bp, raw, modified in _batch  # P8: raw stays as-is unless modified
        ]
        try:
            results, backoff = stow_batch_instances(
                payloads,
                clarus_url,
                http_timeout=http_timeout,
                client=_http,
                tls=tls,
            )
        except Exception as e:
            logging.error("[OUTBOX-WORKER] stow_batch_instances raised: %s", e)
            logging.debug("[OUTBOX-WORKER] traceback:", exc_info=True)
            results, backoff = None, None

        if results is None:
            # Total transport failure not mapped per-SOP: fail the whole batch.
            for uid, ds, blob_path, raw_bytes, modified in _batch:
                outbox.mark_failed(uid, "Batch transport error")
            _batch = []
            _batch_study = None
            _batch_bytes = 0
            with _progress_lock:
                _last_progress = time.time()
            return

        # 2908: 507 Insufficient Storage -> backpressure, NOT a failure.
        # Files go back to pending without a retry bump; the worker pauses
        # for Retry-After seconds (clamped 5..300, default 30).
        if backoff is not None:
            batch_len = len(_batch)
            for uid, ds, blob_path, raw_bytes, modified in _batch:
                outbox.requeue(uid, f"Server 507 - retry after {backoff}s")
            _batch = []
            _batch_study = None
            _batch_bytes = 0
            with _progress_lock:
                _last_progress = time.time()
            outbox_pending_files.set(outbox.pending_count())
            logging.warning(
                "[OUTBOX-WORKER] Server 507 - %d SOP(s) returned to pending, "
                "pausing %.0fs (Retry-After)",
                batch_len,
                backoff,
            )
            _pause_until = time.time() + backoff
            return

        results_by_uid = {uid: (st, hs, msg) for uid, st, hs, msg in results}
        batch_ok = 0

        for uid, ds, blob_path, raw_bytes, modified in _batch:
            status, http_status, msg = results_by_uid.get(
                uid, (0xC000, None, "No outcome")
            )
            # P1-4: watchdog heartbeat after each STOW round.
            with _progress_lock:
                _last_progress = time.time()

            study_uid = str(getattr(ds, "StudyInstanceUID", "")) or ""
            if status == 0x0000:
                # sidecar no longer needed (audit trail embedded in
                # payload). Delete BEFORE mark_delivered so retry keeps it.
                if modified:
                    outbox.delete_mods_sidecar(blob_path)
                outbox.mark_delivered(uid)
                batch_ok += 1
                _delivered_total += 1
                if study_uid and study_uid in _study_stats:
                    _study_stats[study_uid]["delivered"] += 1
                if sop_index is not None:
                    try:
                        series_uid = str(getattr(ds, "SeriesInstanceUID", ""))
                        if uid and study_uid and series_uid:
                            sop_index.insert_sop(uid, study_uid, series_uid)
                    except Exception:
                        pass
            else:
                outbox.mark_failed(uid, msg or "Unknown error")
                _delivered_total += 1
                _delivered_failed += 1
                if study_uid and study_uid in _study_stats:
                    _study_stats[study_uid]["delivered"] += 1
                    _study_stats[study_uid]["failed"] += 1
                retries = outbox._get_retry_count(uid)
                if retries >= outbox.MAX_RETRIES:
                    outbox.move_to_undelivered(uid)

        logging.info(
            "[OUTBOX] Batch delivered %d/%d OK",
            batch_ok,
            len(_batch),
        )
        _batch = []
        _batch_study = None
        _batch_bytes = 0

        # 2908: observability - last successful STOW flush (unix time).
        if batch_ok > 0:
            outbox_last_success_timestamp.set(time.time())
        outbox_pending_files.set(outbox.pending_count())

        # P30: delivery summary -- progress every 100 SOPs or 30s.
        _now = time.time()
        pending = outbox.pending_count()
        if _delivered_total > 0 and (
            _delivered_total % 100 == 0 or _now - _last_summary_log >= 30.0
        ):
            _last_summary_log = _now
            _study_label = f"study={_current_study[:40]}" if _current_study else ""
            logging.info(
                "[OUTBOX] %d delivered, %d failed - %s",
                _delivered_total - _delivered_failed,
                _delivered_failed,
                _study_label,
            )

        # Queue drained: log per-study summaries and reset counters.
        if pending == 0 and not _queue_was_empty:
            _queue_was_empty = True
            _last_summary_log = _now
            for study_uid, s in list(_study_stats.items()):
                mods = ", ".join(sorted(s.get("modalities", set()))) or "??"
                logging.info(
                    "[OUTBOX] Study delivered: study=%s patient=%s modality=%s %d/%d OK",
                    study_uid[:50],
                    s.get("patient", "?"),
                    mods,
                    s.get("delivered", 0) - s.get("failed", 0),
                    s.get("delivered", 0),
                )
            _study_stats.clear()
            _current_study = None
            _delivered_total = 0
            _delivered_failed = 0
        elif pending > 0:
            _queue_was_empty = False

    def _dequeue_safe():
        try:
            return outbox.dequeue()
        except Exception as e:
            logging.error("[OUTBOX-WORKER] dequeue() failed: %s", e)
            logging.debug("[OUTBOX-WORKER] dequeue traceback:", exc_info=True)
            _shutdown_requested.wait(timeout=1.0)
            return (None, None, None, None)

    while not _shutdown_requested.is_set():
        # STORE-FORWARD: if the server is down, pause instead of
        # burning STOW retries (MAX_RETRIES=10 -> undelivered -> manual).
        # Reads the health checker's cached event - no HTTP on the hot path.
        if health_checker is not None and not health_checker.is_healthy():
            if not _was_paused:
                _was_paused = True
                logging.warning(
                    "[OUTBOX-WORKER] Server down - worker paused "
                    "(no STOW, no HTTP); will resume on recovery"
                )
            _shutdown_requested.wait(5.0)
            with _progress_lock:
                _last_progress = time.time()
            continue
        elif _was_paused:
            _was_paused = False
            logging.info("[OUTBOX-WORKER] Server up - delivery resumed")

        # 2908: 507 backpressure - pause for Retry-After seconds (clamped
        # 5..300 by retry_after_seconds, default 30). Files stay pending.
        # WARN once per paused/resumed transition.
        if _pause_until > time.time():
            if not _was_507_paused:
                _was_507_paused = True
                logging.warning(
                    "[OUTBOX-WORKER] Server 507 - paused %.0fs (Retry-After); "
                    "files stay pending",
                    _pause_until - time.time(),
                )
            outbox_pending_files.set(outbox.pending_count())
            with _progress_lock:
                _last_progress = time.time()
            _shutdown_requested.wait(5.0)
            continue
        elif _was_507_paused:
            _was_507_paused = False
            logging.warning("[OUTBOX-WORKER] 507 pause over - delivery resumed")

        # 2908: live pending-count gauge (outbox worker view).
        outbox_pending_files.set(outbox.pending_count())

        # periodic stuck-item reaper -- every 60s, reset in_progress
        # items stuck too long (crashed worker, hung HTTP) or max-retry blobs
        # still on disk so they can be retried.
        _now = time.time()
        if _now - _last_stuck_check >= STUCK_ITEM_CHECK_INTERVAL:
            _last_stuck_check = _now
            outbox.recover_stuck()

        result = _dequeue_safe()

        if result[0] is None:
            # Nothing ready now. If a study tail is buffered, wait up to
            # batch_idle_sec for a same-study item; if none arrives, flush.
            if _batch:
                _shutdown_requested.wait(timeout=batch_idle_sec)
                with _progress_lock:
                    _last_progress = time.time()
                result = _dequeue_safe()
                if result[0] is None:
                    _deliver_batch()
                    continue
            else:
                # P8 + retry: sleep until next_retry_at (bounded by 5s).
                wait = outbox.next_retry_wait_sec()
                _shutdown_requested.wait(timeout=wait)
                # P30/P1-4: watchdog heartbeat -- worker is alive and waiting.
                with _progress_lock:
                    _last_progress = time.time()
                with _progress_lock:
                    dead_sec = time.time() - _last_progress
                if dead_sec > 120 and outbox.pending_count() > 0:
                    logging.warning(
                        "[OUTBOX-WATCHDOG] Worker stalled %.0fs with %d pending - "
                        "running recovery",
                        dead_sec,
                        outbox.pending_count(),
                    )
                    reset_p, reset_r = outbox.recover_stuck()
                    if reset_p > 0 or reset_r > 0:
                        logging.warning(
                            "[OUTBOX-WATCHDOG] Recovery done: %d stuck in_progress, "
                            "%d moved to undelivered",
                            reset_p,
                            reset_r,
                        )
                    with _progress_lock:
                        _last_progress = time.time()
                        _last_stuck_check = time.time()
                continue

        sop_uid, ds, blob_path, raw_bytes = result
        # ds is already a pydicom Dataset from dequeue() -- no dcmread needed.

        # Study context for batching + INFO-level delivery logging.
        try:
            _study_uid = str(getattr(ds, "StudyInstanceUID", ""))
        except Exception:
            _study_uid = ""

        # Study boundary HARD: never mix studies in one batch. Switch flushes.
        if _batch and _study_uid != _batch_study:
            _deliver_batch()

        if _study_uid and _study_uid != _current_study:
            _current_study = _study_uid
            _log_study_start(sop_uid, ds, _study_uid)
            mods_display = (
                ", ".join(sorted(_study_stats[_study_uid].get("modalities", set())))
                or "??"
            )
            logging.info(
                "[OUTBOX] Delivering: study=%s patient=%s modality=%s - %d SOP(s) pending",
                _study_uid[:50],
                _study_stats[_study_uid]["patient"],
                mods_display,
                outbox.pending_count() + 1,
            )

        # apply deferred audit trail (off hot-path). C-STORE handler
        # generated PatientID/Name but skipped (0400,0561); now we apply
        # record_modification() from the .mods sidecar written by enqueue().
        mods_json = outbox.read_mods_sidecar(blob_path)
        dataset_modified = False
        if mods_json:

            try:
                for entry in mods_json:
                    tag = tuple(entry["tag"])
                    record_modification(
                        ds,
                        tag,
                        entry["old"],
                        modifying_operator="DIMSE",
                        modifying_system=bridge_ae_title,
                    )
                dataset_modified = True
                logging.debug(
                    "[OUTBOX-WORKER] Applied %d audit trail entries for SOP %s",
                    len(mods_json),
                    sop_uid,
                )
            except Exception as e:
                logging.warning(
                    "[OUTBOX-WORKER] Failed to apply audit trail for SOP %s: %s",
                    sop_uid,
                    e,
                )
                # Continue delivery -- blob is valid even without audit trail

        # P8: raw pass-through for CAS dedup. Modified instances (raw=None)
        # are re-serialized by stow_batch_instances via dcmwrite.
        _batch.append(
            (
                sop_uid,
                ds,
                blob_path,
                (None if dataset_modified else raw_bytes),
                dataset_modified,
            )
        )
        try:
            _batch_bytes += os.path.getsize(blob_path)  # on-disk size = payload proxy
        except OSError:
            _batch_bytes += len(raw_bytes) if raw_bytes else 0
        _batch_study = _study_uid

        # Flush when count or bytes trigger fires.
        if len(_batch) >= batch_max_sop or _batch_bytes >= batch_max_bytes:
            _deliver_batch()

    if _batch:
        _deliver_batch()  # shutdown: drain any remaining tail first
    _http.close()  # P30: clean up persistent HTTP client
    logging.info("[OUTBOX-WORKER] Worker stopped")

def _start_outbox_workers(
    outbox,
    clarus_url,
    http_timeout,
    sop_index,
    move_jobs,
    batch_max_sop=100,
    batch_max_bytes=96 * 1024 * 1024,
    batch_idle_sec=5.0,
    health_checker=None,
    tls=None,
    bridge_ae_title="CLARUS_BRIDGE",
):
    """Start single background outbox worker thread. KISS."""
    t = threading.Thread(
        target=_outbox_worker,
        args=(
            outbox,
            clarus_url,
            http_timeout,
            sop_index,
            move_jobs,
            batch_max_sop,
            batch_max_bytes,
            batch_idle_sec,
            health_checker,
            tls,
            bridge_ae_title,
        ),
        name="outbox-worker",
        daemon=False,
    )
    t.start()
    logging.info("[OUTBOX-WORKER] Started 1 worker")
    return [t]

def _drain_outbox(outbox):
    """Wait for outbox to empty, then close (graceful shutdown)."""
    pending = outbox.pending_count()
    if pending > 0:
        logging.info("[OUTBOX] Waiting for %d pending SOPs to be delivered...", pending)
        # Poll until empty or shutdown
        while outbox.pending_count() > 0 and not _shutdown_requested.is_set():
            _shutdown_requested.wait(timeout=0.5)
        remaining = outbox.pending_count()
        if remaining > 0:
            logging.warning(
                "[OUTBOX] %d SOPs remain undelivered - will survive restart",
                remaining,
            )
    outbox.close()
    logging.info("[OUTBOX] Closed")

# ---------------------------------------------------------------------------
# Forwarder: _forward_worker - best-effort DIMSE drain of the
# SECOND (non-authoritative) outbox into the second DIMSE server.
#
# The forward channel is fully isolated from the primary STOW drain: it holds
# its own OutboxQueue instance (clean_code/outbox.py, the same class), runs on
# its own thread, and pauses rather than burning retries when the second server
# is unreachable. Whatever happens here NEVER backpressures primary reception.
#
# Reuses the byte-level meta helpers from handlers/cmove.py (import only, no
# edits) to read each stored blob's (sop_class, transfer_syntax) without a full
# pydicom parse. The blob is sent as stored bytes (its own Transfer Syntax).
# ---------------------------------------------------------------------------

# Forward batching: up to 20 SOPs per association (a widely interoperable
# ceiling), drained over a short 0.5 s window to fill each association, then a
# 5 s pause before retrying after an association failure so a dead peer is not
# hammered.
_FORWARD_BATCH_MAX_SOP = 20
_FORWARD_BATCH_WINDOW_S = 0.5
_FORWARD_PAUSE_S = 5.0

def _forward_blob_pair(raw_bytes):
    """Read (sop_class_uid, stored_ts_uid) from a stored DICOM file's meta.

    Uses the byte-level helpers from handlers/cmove.py:805-987 (import, no
    edits). Reads (0002,0002) MediaStorageSOPClassUID and (0002,0010)
    TransferSyntaxUID straight from the preamble-aware meta group, so a
    forward blob is identified WITHOUT a pydicom dataset parse.
    """
    sop_class = _extract_meta_ui(raw_bytes, 0x0002)
    stored_ts = _extract_meta_ui(raw_bytes, 0x0010)
    if sop_class is None:
        # Meta MS SOP class absent - fall back to dataset (0008,0016).
        sop_class = _extract_dataset_ui(raw_bytes, 0x0016, group=0x0008)
    return sop_class, stored_ts

def _forward_blob_size(blob_path):
    """Size in bytes of a forward blob, 0 when it cannot be stat'ed.

    Metrics must never break the drain, so a vanished/renamed blob degrades
    to 0 rather than raising.
    """
    try:
        return os.path.getsize(blob_path)
    except OSError:
        return 0

def _forward_open_assoc(
    calling_ae, dest_ae, host, port, pairs, network_timeout, dimse_timeout, acse_timeout
):
    """Open ONE association carrying one requested context per distinct
    (sop_class, stored_ts) pair of the batch. Returns an
    established association or None on any failure."""
    ae = AE(ae_title=calling_ae)
    ae.network_timeout = network_timeout
    ae.acse_timeout = acse_timeout
    ae.dimse_timeout = dimse_timeout
    for sop_class, ts_uid in sorted(pairs):
        if sop_class and ts_uid:
            ae.add_requested_context(sop_class, ts_uid)
    try:
        assoc = ae.associate(host, port, ae_title=dest_ae)
    except Exception:
        return None
    if not assoc.is_established:
        try:
            assoc.release()
        except Exception:
            pass
        return None
    # Counted only once the association is actually established: a refused
    # association is not an association made.
    try:
        associations_total.labels(role="to", ae=ae_label(dest_ae)).inc()
    except Exception:
        pass
    return assoc

def _forward_process_batch(
    forward_outbox,
    items,
    dest_ae,
    calling_ae,
    host,
    port,
    network_timeout,
    dimse_timeout,
    acse_timeout,
):
    """Deliver ONE already-claimed batch of forward items over a single
    association.

    Args:
        forward_outbox: the forward OutboxQueue.
        items: list of claimed tuples (uid, sop_class, stored_ts, blob_path),
               each ALREADY atomically claimed into forward/in_progress via
               dequeue() (so mark_delivered/mark_failed/requeue know the mover).
        dest_ae/host/port/calling_ae/timeouts: association parameters.

    Returns True if the association was usable (even if individual RSPs were
    non-zero); False if the association could NOT be established at all, in
    which case the CALLER requeues the whole batch (no retry burn) and pauses.

    Per instance it READS every C-STORE-RSP: 0x0000 -> mark_delivered;
    a non-zero RSP -> mark_failed (backoff, then undelivered at max retries);
    a lost/None RSP or an unasendable context mismatch -> requeued without a
    retry burn (association transport issue, not a per-instance failure).

    Items are sent in deterministic uid order: dequeue() claims files in
    os.listdir order, which differs across filesystems (CI failure on Linux
    ext4 vs local NTFS) - sorting here makes delivery order stable and
    reproducible everywhere, and keeps the wire test's exact-order pin valid.
    """
    items = sorted(items, key=lambda item: item[0])
    pairs = sorted({(sop, ts) for (_, sop, ts, _) in items if sop and ts})
    assoc = _forward_open_assoc(
        calling_ae,
        dest_ae,
        host,
        port,
        pairs,
        network_timeout,
        dimse_timeout,
        acse_timeout,
    )
    if assoc is None:
        logging.warning(
            "[FORWARD] Cannot associate with %s at %s:%s - batch %d requeued, "
            "pause %.0fs (no retry burn)",
            dest_ae,
            host,
            port,
            len(items),
            _FORWARD_PAUSE_S,
        )
        return False

    try:
        # accepted = {sop_class: {ts,...}} from the negotiated contexts.
        accepted = {}
        for ctx in assoc.accepted_contexts:
            ts_list = [str(t) for t in (ctx.transfer_syntax or [])]
            accepted.setdefault(str(ctx.abstract_syntax), set()).update(ts_list)

        delivered_any = False
        for uid, sop_class, stored_ts, blob_path in items:
            # Only send when the negotiated context actually covers this
            # sop_class and stored TS; sending stored bytes as-is over a
            # foreign/absent TS would corrupt them. A peer that cannot accept
            # this SOP class / TS is a PEER CAPABILITY RESULT, so it burns a
            # retry (mark_failed -> at max retries -> undelivered), exactly like
            # a non-zero RSP. It is NOT a transient transport condition, so it
            # must NOT requeue-no-burn (which would otherwise spin forever).
            negotiated_ts = accepted.get(sop_class, set())
            if not sop_class or stored_ts not in negotiated_ts:
                logging.warning(
                    "[FORWARD] SOP %s %s@%s context not negotiated - "
                    "mark_failed (capability verdict, retry budget applied "
                    "then undelivered)",
                    uid,
                    sop_class,
                    stored_ts,
                )
                forward_failed_total.inc()
                try:
                    forward_outbox.mark_failed(uid, "context not covered")
                except Exception:
                    pass
                continue

            # Size is read BEFORE the send: mark_delivered removes the blob,
            # so measuring afterwards always yields 0.
            _blob_size = _forward_blob_size(blob_path)
            try:
                _t0 = time.perf_counter()
                status = assoc.send_c_store(blob_path)
                try:
                    cstore_outbound_duration.labels(peer=ae_label(dest_ae)).observe(
                        time.perf_counter() - _t0
                    )
                except Exception:
                    pass
            except Exception as fwd_err:
                logging.warning(
                    "[FORWARD] SOP %s C-STORE raised %s - requeued (no burn)",
                    uid,
                    type(fwd_err).__name__,
                )
                try:
                    forward_outbox.requeue(
                        uid, f"send exception: {type(fwd_err).__name__}"
                    )
                except Exception:
                    pass
                continue

            # READ every C-STORE-RSP.
            if status is not None and status.Status == 0x0000:
                forward_outbox.mark_delivered(uid)
                forward_delivered_total.inc()
                try:
                    bytes_total.labels(direction="tx", peer=ae_label(dest_ae)).inc(
                        _blob_size
                    )
                except Exception:
                    pass
                delivered_any = True
                logging.debug("[FORWARD] SOP %s delivered (0x0000)", uid)
            elif status is None:
                # Lost/aborted association transport - requeue, no retry burn.
                logging.warning(
                    "[FORWARD] SOP %s: no C-STORE-RSP read - requeued (no burn)",
                    uid,
                )
                try:
                    forward_outbox.requeue(uid, "no RSP")
                except Exception:
                    pass
            else:
                # A real non-zero RSP (0xC000/0xA7xx/etc) - a per-instance status.
                # mark_failed bumps the retry counter and (at MAX_RETRIES) calls
                # move_to_undelivered internally (outbox.py semantics).
                msg = str(getattr(status, "Status", status))
                forward_failed_total.inc()
                forward_outbox.mark_failed(uid, f"C-STORE {msg}")
                logging.warning("[FORWARD] SOP %s rejected: %s", uid, msg)
        if delivered_any:
            try:
                forward_last_success_timestamp.set(time.time())
            except Exception:
                pass
        return True
    finally:
        try:
            assoc.release()
        except Exception:
            pass

def _forward_worker(
    forward_outbox,
    dest_ae,
    calling_ae,
    host,
    port,
    network_timeout=30,
    dimse_timeout=30,
    acse_timeout=15,
):
    """Background thread loop: drain forward/pending into the second DIMSE
    server. Runs independently of _outbox_worker; the two queues/threads are
    isolated, so a slow/dead second server CANNOT stall the primary drain."""
    _last_stuck = 0.0
    while not _shutdown_requested.is_set():
        # Periodic stuck recovery (restart replay / crash recovery) - same
        # recover_stuck semantics as the primary outbox (outbox.py).
        now = time.time()
        if now - _last_stuck >= 60.0:
            _last_stuck = now
            try:
                forward_outbox.recover_stuck()
            except Exception:
                pass
        try:
            forward_pending_files.set(forward_outbox.pending_count())
        except Exception:
            pass

        # Drain one batch (up to _FORWARD_BATCH_MAX_SOP within a small window).
        items = []
        window_end = time.time() + _FORWARD_BATCH_WINDOW_S
        while not _shutdown_requested.is_set() and len(items) < _FORWARD_BATCH_MAX_SOP:
            try:
                res = forward_outbox.dequeue()
            except Exception:
                res = (None, None, None, None)
            uid, _ds, blob_path, raw_bytes = res
            if uid is None:
                break
            sop_class, stored_ts = _forward_blob_pair(raw_bytes)
            items.append((uid, sop_class, stored_ts, blob_path))
            if time.time() >= window_end:
                break

        if not items:
            # Empty / nothing ready - sleep until the next retry is due.
            try:
                wait = forward_outbox.next_retry_wait_sec()
            except Exception:
                wait = 1.0
            _shutdown_requested.wait(timeout=max(0.1, wait))
            continue

        assoc_ok = _forward_process_batch(
            forward_outbox,
            items,
            dest_ae,
            calling_ae,
            host,
            port,
            network_timeout,
            dimse_timeout,
            acse_timeout,
        )
        if not assoc_ok:
            # Association-level failure: requeue the WHOLE already-claimed
            # batch without burning retries, then pause (destination probe).
            for uid, _sop, _ts, _bp in items:
                try:
                    forward_outbox.requeue(uid, "association failed")
                except Exception:
                    pass
            _shutdown_requested.wait(timeout=_FORWARD_PAUSE_S)
        try:
            forward_pending_files.set(forward_outbox.pending_count())
        except Exception:
            pass

# ---------------------------------------------------------------------------
# _register_handlers - DIMSE event handler registration
# ---------------------------------------------------------------------------
def _register_handlers(
    args,
    sop_index,
    move_jobs,
    sop_registry,
    outbox,
    health_checker,
    commit_tracker=None,
    forward_outbox=None,
    expose_rejected=False,
):
    """Register DIMSE event handlers. Returns list of (event, handler) tuples.

    `expose_rejected` is bound to the AE this set is registered on: the Expose
    Rejected Instances AE builds its own set with the flag on, every other AE
    uses the default. It only affects the QIDO/WADO query the C-FIND and
    C-MOVE handlers issue - the DIMSE behaviour is identical.
    """
    # Bridge: verbose HTTP logging when DEBUG level is active
    verbose = args.log_level == "DEBUG"

    # Storage Commitment presence, read here rather than threaded in as a
    # parameter: it is consumed by on_n_action below, and the same one-line
    # formula already appears in _start_background_services (which selects the
    # readiness-gate mode). A parameter would add an argument for a single
    # read of a single config flag.
    stc_presence = bool(getattr(args, "storage_commitment_presence", False))

    # P1-3: C-STORE, C-FIND, C-MOVE share the httpx.Client for connection reuse.
    # C-MOVE uses HTTP WADO-RS via httpx.Client for instance retrieval.

    # C-STORE wrapper with pynetdicom error isolation.
    # 0xC001 (CannotUnderstand) is generated by pynetdicom BEFORE our handler
    # when it fails to decode the dataset or negotiate the presentation context.
    # This wrapper catches any Exception that manages to reach our handler,
    # logging the Transfer Syntax and SOP Class UID for root cause analysis.
    def on_c_store(event):
        try:
            return handle_c_store(
                event,
                args.clarus_url,
                verbose,
                sop_index,
                max_store_bytes=(
                    args.max_store_mb * 1024 * 1024 if args.max_store_mb > 0 else 0
                ),
                http_timeout=args.http_timeout,
                sop_registry=sop_registry,
                outbox=outbox,
                health_checker=health_checker,
                store_forward=args.outbox_store_forward,
                fix_empty_patient_id=args.fix_empty_patient_id,
                fix_empty_patient_name=args.fix_empty_patient_name,
                bridge_id_prefix=args.bridge_id_prefix,
                bridge_name_prefix=args.bridge_name_prefix,
                tls=args.tls_pair,
                forward_outbox=forward_outbox,
                bridge_ae_title=args.ae_title,
            )
        except Exception:
            # Catch ALL exceptions to prevent pynetdicom association abort.
            # Log enough context to identify root cause (Transfer Syntax, SOP Class,
            # presentation context) without relying on event.dataset (may be None).
            ctx_uid = "?"
            ts_uid = "?"
            sop_uid = "?"
            try:
                ctx_uid = str(event.context.abstract_syntax) if event.context else "?"
            except Exception:
                pass
            try:
                ts_uid = str(event.context.transfer_syntax) if event.context else "?"
            except Exception:
                pass
            try:
                sop_uid = str(getattr(event.dataset, "SOPInstanceUID", "?"))
            except Exception:
                pass
            logging.error(
                "[BUG-005] C-STORE handler crashed - "
                "AbstractSyntax=%s TransferSyntax=%s SOP=%s",
                ctx_uid,
                ts_uid,
                sop_uid,
            )
            logging.debug(
                "[BUG-005] Full traceback follows:",
                exc_info=True,
            )
            return 0xC000  # Processing Failure - association survives

    def on_c_echo(event):
        return handle_c_echo(event)

    def on_c_find(event):
        yield from handle_c_find(
            event,
            args.clarus_url,
            verbose,
            args.c_find_max_responses,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
            expose_rejected=expose_rejected,
            qa_url=args.qa_url,
        )

    def on_c_move(event):
        yield from handle_c_move(
            event,
            move_jobs,
            args.peers_file,
            args.clarus_url,
            bridge_ae_title=args.ae_title,
            http_timeout=args.http_timeout,
            sop_registry=sop_registry,
            storage_commit_after_move=not args.no_storage_commit,
            sop_index=sop_index,
            outbound_network_timeout=args.outbound_network_timeout,
            outbound_dimse_timeout=args.outbound_dimse_timeout,
            outbound_acse_timeout=args.outbound_acse_timeout,
            bridge_dimse_host=args.bridge_host,
            bridge_dimse_port=args.bridge_port,
            move_poll_timeout=args.move_poll_timeout,
            tls=args.tls_pair,
            expose_rejected=expose_rejected,
            qa_url=args.qa_url,
        )

    def on_n_action(event):
        yield from handle_n_action(
            event,
            args.clarus_url,
            verbose,
            sop_index,
            http_timeout=args.http_timeout,
            commit_tracker=commit_tracker,
            resolve_scp=lambda ae_title, client_ip: move_jobs.lookup_scp(
                ae_title, client_ip=client_ip
            ),
            tls=args.tls_pair,
            stc_presence=stc_presence,
        )

    # DIMSE association lifecycle handlers.
    # Log association open/close at INFO - admin sees who connected and what they sent.
    def on_assoc_accepted(event):
        # Use id(event.assoc) as unique key - same as C-STORE handler.
        # Python object ID is unique per DICOM connection, available before negotiation.
        ae_title = "?"
        address = "?"
        assoc_id = 0
        try:
            assoc = event.assoc
            assoc_id = id(assoc)
            req = getattr(assoc, "requestor", None)
            if req is not None:
                ae = getattr(req, "ae_title", None)
                if ae and str(ae).strip():
                    ae_title = str(ae).strip()
                addr = getattr(req, "address", None)
                if addr and str(addr).strip():
                    address = str(addr).strip()
        except Exception as e:
            logging.debug("[DIMSE] Failed to extract AE/address: %s", e)
        register_assoc_accepted(assoc_id, ae_title, address)
        return 0x0000  # Always accept

    def on_assoc_released(event):
        assoc_id = 0
        try:
            assoc_id = id(event.assoc)
        except Exception:
            pass
        register_assoc_released(assoc_id)

    handlers = [
        (evt.EVT_C_STORE, on_c_store),
        (evt.EVT_C_ECHO, on_c_echo),
        (evt.EVT_C_FIND, on_c_find),
        (evt.EVT_C_MOVE, on_c_move),
        (evt.EVT_N_ACTION, on_n_action),
        (evt.EVT_ACCEPTED, on_assoc_accepted),
        (evt.EVT_RELEASED, on_assoc_released),
        (evt.EVT_ABORTED, on_assoc_released),  # Same cleanup as release
    ]

    return handlers

# ---------------------------------------------------------------------------
# Main entry point
# ---------------------------------------------------------------------------
def main():
    # - Windows: disable Quick Edit mode (console Mark mode) -
    # On Windows, clicking in a console window pauses ALL output
    # (ENABLE_QUICK_EDIT_MODE). PyInstaller .exe has no Properties dialog
    # to disable it manually, so we do it programmatically at startup.
    # Without this, a single accidental click freezes the bridge.
    if sys.platform == "win32" and sys.stdout is not None:
        try:
            kernel32 = ctypes.windll.kernel32
            ENABLE_QUICK_EDIT_MODE = 0x0040
            ENABLE_EXTENDED_FLAGS = 0x0080
            STD_INPUT_HANDLE = -10
            handle = kernel32.GetStdHandle(STD_INPUT_HANDLE)
            mode = ctypes.c_uint32()
            if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                new_mode = (
                    mode.value & ~ENABLE_QUICK_EDIT_MODE
                ) | ENABLE_EXTENDED_FLAGS
                kernel32.SetConsoleMode(handle, new_mode)
        except Exception:
            pass  # Not a console (redirected output, no-pty, etc.)

    cli = _parse_args()

    # CONFIG-DISCIPLINE: config file is the sole source of settings.
    if not os.path.exists(cli.config):
        logging.basicConfig(level=logging.INFO)
        logging.error("Config file not found: %s", cli.config)
        sys.exit(1)

    cfg = ConfParser(cli.config)

    # Validate before populating - fail fast on bad config.
    try:
        _validate_config(cfg)
    except ValueError as e:
        logging.basicConfig(level=logging.INFO)
        logging.error("%s", e)
        logging.debug("Config validation traceback:", exc_info=True)
        sys.exit(1)

    args = _populate_args(cfg)

    # - Resolve relative paths against config file directory -
    # Same as nginx: all relative paths in config are relative to the
    # config file, NOT the CWD. Makes the entire folder portable.
    _config_dir = os.path.dirname(os.path.abspath(cli.config))
    # peers_file and printers_yaml are read by the C-MOVE peer lookup and the
    # print registry; resolved from the CWD they point nowhere under a service
    # manager, and both lookups then silently return nothing.
    _path_keys = [
        "log_file",
        "sop_registry",
        "sop_index_dir",
        "outbox_dir",
        "peers_file",
        "printers_yaml",
    ]
    for key in _path_keys:
        val = getattr(args, key, None)
        if val and not os.path.isabs(val):
            setattr(args, key, os.path.join(_config_dir, val))

    # The patient-id masking key lives beside the outbox: the same directory
    # the data it labels is written to, so moving the outbox moves the
    # correlation with it. Set before the first log line that masks an id.
    set_mask_key_dir(os.path.join(args.outbox_dir, "forward"))

    # Bridge: initialize logging before any output
    _setup_logging(args.log_level, args.log_file)

    # Startup WARN: if worst-case association retry time (attempts x
    # outbound_acse_timeout) reaches into the C-MOVE poll budget, the reactor
    # could hit 0xB000 before a job finishes its association attempts. The
    # standard (PS3.8 9.1.4 Note 2) gives no retry-count guidance, so surface
    # the risk at config load - not at 0xB000 time.
    _retry_total = args.outbound_assoc_attempts * args.outbound_acse_timeout
    if args.move_poll_timeout and _retry_total >= args.move_poll_timeout:
        logging.warning(
            "[CONFIG-WARN] dimse.outbound_assoc_attempts=%d x "
            "outbound_acse_timeout=%d = %ds reaches into "
            "move_poll_timeout=%ds - a wedged target could exhaust the "
            "C-MOVE poll budget across association retries (0xB000 before "
            "delivery). Tune the attempts/timeouts down if this bites.",
            args.outbound_assoc_attempts,
            args.outbound_acse_timeout,
            _retry_total,
            args.move_poll_timeout,
        )

    # Bridge: load SOP class registry
    sop_registry = _load_sop_registry(args.sop_registry)

    # - Duplicate-instance and port checks BEFORE any component starts -
    # `_init_components` calls `move_jobs.recover_in_progress_jobs()`, which
    # resets every in-progress C-MOVE job in the shared database back to
    # pending. A second instance would therefore steal the live first
    # instance's running jobs and only afterwards discover that the ports are
    # taken - the first instance's workers then re-claim the same jobs and
    # both C-STORE them. Refusing before that write is what keeps the guard
    # free of side effects.
    _check_port_available(args.http_port, args.http_print_bind, "metrics HTTP")
    _check_port_available(args.bridge_port, args.bridge_host, "DIMSE")
    _check_dimse_unique(args.bridge_host, args.bridge_port, args.ae_title)

    # PID file: `/var/run/clbridge-{port}.pid` on Linux, next to the script
    # elsewhere, falling back to the script directory when the system
    # location is not writable. Never fatal on a write error - see
    # `_acquire_pid_file`. Named by DIMSE port so multiple bridge instances
    # on the same machine don't clash.
    _pid_path = _acquire_pid_file(args.bridge_port)
    if _pid_path:
        set_pid_path(_pid_path)

    # initialize components
    sop_index, move_jobs, printer_registry, driver_registry = _init_components(args)

    # - Startup summary (INFO: key params; DEBUG: tuning) -
    logging.info("clbridge v%s", VERSION)
    logging.info("[CONFIG] file: %s", cli.config)
    logging.info(
        "[DIMSE] %s:%d AE=%s", args.bridge_host, args.bridge_port, args.ae_title
    )
    logging.info("[DICOMWEB] %s", args.clarus_url)
    logging.info("[OUTBOX] dir=%s cleanup=%s", args.outbox_dir, args.outbox_cleanup)
    # The patient-id masking key is a SECRET that lives on this host's file
    # system: an operator who does not know it exists cannot back it up, and
    # restoring an outbox without it silently breaks the correlation between
    # old and new log tokens. Named here, at startup, next to the directory
    # it sits in.
    logging.info(
        "[MASK] patient-id key: %s",
        os.path.join(args.outbox_dir, "forward", ".patient_id_mask.key"),
    )
    logging.info("[SOP-INDEX] dir=%s", args.sop_index_dir)
    logging.info("[METRICS] %s:%d", args.http_print_bind, args.http_port)
    logging.info(
        "[COERCION] fix_patient_id=%s fix_patient_name=%s id_prefix=%s",
        args.fix_empty_patient_id,
        args.fix_empty_patient_name,
        args.bridge_id_prefix,
    )
    # - Tuning params (DEBUG only) -
    logging.debug(
        "[TUNING] c_find_max=%d c_move_workers=%d http_timeout=%ds "
        "stow_queue_size=%d max_assoc=%d",
        args.c_find_max_responses,
        args.c_move_workers,
        args.http_timeout,
        args.stow_queue_size,
        args.max_associations,
    )
    mx_cstore = getattr(args, "max_concurrent_cstore", None)
    logging.debug(
        "[TUNING] max_concurrent_cstore=%s",
        str(mx_cstore) if mx_cstore else "unlimited",
    )
    # - SOP registry info (DEBUG) -
    logging.debug("SOP registry: %s (%d classes)", args.sop_registry, len(sop_registry))
    mx_store = f"{args.max_store_mb} MB" if args.max_store_mb > 0 else "unlimited"
    logging.debug("C-STORE size limit: %s", mx_store)

    # start background services (HTTP server, workers, cleanup)
    (
        http_server,
        http_thread,
        cmove_thread,
        cleanup_thread,
        sop_cleanup_thread,
        outbox,
        outbox_workers,
        health_checker,
        commit_tracker,
        commit_thread,
        forward_outbox,
        forward_worker_thread,
    ) = _start_background_services(
        args,
        driver_registry,
        printer_registry,
        move_jobs,
        sop_index,
        sop_registry,
    )

    ae = AE(ae_title=args.ae_title)
    # P1 (2608): answer associations ONLY for our own AE title. pynetdicom
    # default is False - any Called AE Title would be accepted, which let a
    # misconfigured peers.conf loop C-MOVE back into the bridge's own SCP.
    ae.require_called_aet = True
    # DIMSE timeouts - from config [dimse] (inbound - outbound).
    # Inbound: bridge as SCP - C-STORE from modality, C-FIND from viewer.
    # inbound_network_timeout: 0 = disabled (SCP should wait for client, ).
    # None tells pynetdicom "never kill idle associations" - viewers hold
    # associations open during C-MOVE (PS3.4 C.4.2.2), sometimes for minutes.
    ae.network_timeout = (
        args.inbound_network_timeout if args.inbound_network_timeout > 0 else None
    )
    ae.acse_timeout = args.inbound_acse_timeout
    ae.dimse_timeout = args.inbound_dimse_timeout
    # [dimse] max_associations: explicit inbound association cap.
    ae.maximum_associations = args.max_associations
    nw = ae.network_timeout
    logging.debug(
        "[DIMSE] Inbound: network=%s acse=%ds dimse=%ds",
        nw if nw is not None else "off",
        ae.acse_timeout,
        ae.dimse_timeout,
    )
    # Bridge: register supported SOP classes from YAML registry
    accepted_uids = _get_sop_registry_uids(sop_registry)

    def _register_contexts(target_ae):
        """Add every SOP class and query/retrieve context to `target_ae`.

        Shared by the ordinary AE and the Expose Rejected Instances AE: the
        second AE exposes the SAME objects with a different QIDO view, so a
        differing context set would make it answer a strictly narrower set
        of requests for no reason.
        """
        # EVRLE is proposed FIRST for image SOP classes (see the module-level
        # IMAGE_TS constant in clean_code.protocol): a native-only viewer
        # accepts the (DX, 4.70) fallback association only with EVRLE first.
        # Negotiation is acceptor-driven, so a 4.80-capable viewer still
        # negotiates 4.80 and a stored 4.80 instance sends as-is. JPEG
        # Lossless 4.57 and Baseline 4.50 are dropped from the proposal -
        # never stored, never produced, and no viewer ever selected them.
        # Non-image SOPs (SR, PR, RTSTRUCT) get uncompressed-only lists.
        _NON_IMAGE_PFX = (
            "1.2.840.10008.5.1.4.1.1.88.",
            "1.2.840.10008.5.1.4.1.1.11.",
            "1.2.840.10008.5.1.4.1.1.104.",
            "1.2.840.10008.5.1.4.1.1.66.",
        )
        _NON_IMAGE_EXACT = {
            "1.2.840.10008.5.1.4.1.1.481.3",
            "1.2.840.10008.5.1.4.1.1.481.4",
            "1.2.840.10008.5.1.4.1.1.481.5",
            "1.2.840.10008.5.1.4.1.1.481.6",
            "1.2.840.10008.5.1.4.1.1.481.7",
            "1.2.840.10008.5.1.4.1.1.481.8",
            "1.2.840.10008.5.1.4.1.1.481.9",
        }
        for sop_uid in accepted_uids:
            entry = (
                sop_registry.get(sop_uid, {}) if isinstance(sop_registry, dict) else {}
            )
            non_image = (
                bool(entry.get("non_image")) if isinstance(entry, dict) else False
            )
            if (
                non_image
                or sop_uid in _NON_IMAGE_EXACT
                or sop_uid.startswith(_NON_IMAGE_PFX)
            ):
                ts_list = NON_IMAGE_TS
            else:
                ts_list = IMAGE_TS
            # The SCP side (incoming C-STORE from viewers and modalities)
            # accepts the broad IMAGE_TS_INCOMING set - local files arrive in
            # their original TS, and a sender whose context is rejected
            # reports a failed export. The SCU proposal keeps IMAGE_TS.
            target_ae.add_supported_context(
                sop_uid, IMAGE_TS_INCOMING if ts_list is IMAGE_TS else NON_IMAGE_TS
            )
            target_ae.add_requested_context(sop_uid, ts_list)
        target_ae.add_supported_context(
            PatientRootQueryRetrieveInformationModelFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StudyRootQueryRetrieveInformationModelFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            ModalityWorklistInformationFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StorageCommitmentPushModel, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StudyRootQueryRetrieveInformationModelMove, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            PatientRootQueryRetrieveInformationModelMove, ImplicitVRLittleEndian
        )

    _register_contexts(ae)
    logging.info(
        "Registered %d SOP classes for C-STORE (from registry)", len(accepted_uids)
    )

    # register handlers
    handlers = _register_handlers(
        args,
        sop_index,
        move_jobs,
        sop_registry,
        outbox,
        health_checker,
        commit_tracker=commit_tracker,
        forward_outbox=forward_outbox,
    )

    # QA AE (AIRA 57.2.1 Expose Rejected Instances). A DIMSE association has
    # no per-query "show rejected" flag, so a designated AE Title is the
    # standard mechanism, and its queries go to a separately configured QA
    # webservice endpoint. It runs on its OWN port with its OWN handler set:
    # the endpoint choice is a property of the AE that accepted the
    # association, so the ordinary AE cannot inherit it.
    #
    # BOTH keys are required. A port without a URL would accept associations
    # and then query the ordinary endpoint, silently returning the hidden
    # view to a QA user; a URL without a port is dead config. Either half
    # alone is a configuration mistake, so it is reported and the second AE
    # is not started.
    expose_ae = None
    expose_handlers = None
    if args.expose_port and args.qa_url:
        expose_ae = AE(ae_title=args.expose_ae_title)
        expose_ae.require_called_aet = True
        expose_ae.network_timeout = ae.network_timeout
        expose_ae.acse_timeout = ae.acse_timeout
        expose_ae.dimse_timeout = ae.dimse_timeout
        expose_ae.maximum_associations = args.max_associations
        _register_contexts(expose_ae)
        expose_handlers = _register_handlers(
            args,
            sop_index,
            move_jobs,
            sop_registry,
            outbox,
            health_checker,
            commit_tracker=commit_tracker,
            forward_outbox=forward_outbox,
            expose_rejected=True,
        )
    elif args.expose_port:
        logging.warning(
            "[DIMSE] [server] expose_port is set but [dicomweb] qa_url is "
            "empty - the QA AE is NOT started; the bridge stays single-AE. "
            "Set qa_url to the backend QA webservice endpoint."
        )
    elif args.qa_url:
        logging.warning(
            "[DIMSE] [dicomweb] qa_url is set but [server] expose_port is "
            "empty - the QA AE is NOT started; the bridge stays single-AE. "
            "Set expose_port to the port the QA workstation will connect to."
        )

    # - Shutdown Monitor Thread -
    # Bridges the async-signal-safe shutdown flag to pynetdicom's event loop.
    # On Windows, select() does NOT wake up on signals (no EINTR).
    # The monitor waits for _shutdown_requested in a regular thread and calls
    # ae.shutdown() - which closes the listening socket - select() wakes up
    # - start_server() returns - main thread proceeds with graceful shutdown.
    shutdown_monitor = threading.Thread(
        target=lambda: (_shutdown_requested.wait(), ae.shutdown()),
        name="shutdown-monitor",
        daemon=True,
    )
    shutdown_monitor.start()

    if expose_ae is not None:
        # Both AEs answer from their own listener thread. The expose server is
        # non-blocking so the main thread can keep serving the ordinary AE;
        # the shutdown monitor above still governs the process.
        logging.info(
            "[DIMSE] Expose Rejected Instances AE '%s' on %s:%d",
            args.expose_ae_title,
            args.bridge_host,
            args.expose_port,
        )

        def _serve_expose():
            try:
                expose_ae.start_server(
                    (args.bridge_host, args.expose_port),
                    block=True,
                    evt_handlers=expose_handlers,
                )
            except Exception as exc:
                logging.error("[DIMSE] Expose AE stopped: %s", exc)
                _shutdown_requested.set()

        threading.Thread(target=_serve_expose, name="dimse-expose", daemon=True).start()

    # Bridge: register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)
    # Windows: Ctrl+Break - graceful shutdown (SIGBREAK)
    if hasattr(signal, "SIGBREAK"):
        signal.signal(signal.SIGBREAK, _signal_handler)

    logging.info("Waiting for DICOM connections...")

    try:
        # Bridge: start_server blocks, but signal handlers will trigger shutdown
        ae.start_server(
            (args.bridge_host, args.bridge_port), block=True, evt_handlers=handlers
        )
    except KeyboardInterrupt:
        # Bridge: Ctrl+C in terminal
        logging.info("KeyboardInterrupt received")
        _shutdown_requested.set()
    finally:
        # Bridge: graceful shutdown sequence
        logging.info("Shutting down DICOM server...")
        if not _shutdown_requested.is_set():
            _shutdown_requested.set()

        # Bridge: allow in-flight operations to complete (30s grace period)
        logging.info("Waiting up to 30s for in-flight operations to complete...")
        ae.shutdown()  # Idempotent - monitor may have already called it
        if expose_ae is not None:
            expose_ae.shutdown()
        logging.info("DICOM server stopped")

        # Bridge: stop HTTP server - before joining threads
        http_server.shutdown()
        logging.info("[HTTP] Bridge server stopped")

        # - stop the producers before draining their queues -
        # The outbox workers exit on `_shutdown_requested`, so joining them
        # FIRST lets each one push its tail batch. Draining and then closing
        # the queue while a worker was still alive made `mark_delivered` /
        # `mark_failed` run against a closed queue, which turned a delivered
        # instance into a logged error.
        _fwd = [forward_worker_thread] if forward_worker_thread is not None else []
        for t in list(outbox_workers) + _fwd:
            if t.is_alive():
                logging.info("[SHUTDOWN] Waiting for thread %s (up to 30s)...", t.name)
                t.join(timeout=30.0)
                if t.is_alive():
                    logging.warning("[SHUTDOWN] Thread %s did not stop in time", t.name)

        # Bridge: drain outbox (graceful shutdown), then close the queues.
        # The forward queue exists only with `[forward] enabled=true`; the
        # default leaves it None and an unguarded close aborts the whole
        # shutdown sequence on the way out.
        _drain_outbox(outbox)
        if forward_outbox is not None:
            forward_outbox.close()

        # Stop the async Storage Commitment resolver.
        commit_tracker.close()

        # - join the remaining background threads -
        # Join C-MOVE workers FIRST - they use move_jobs DB which must stay open.
        _all_threads = [
            cmove_thread,
            cleanup_thread,
            sop_cleanup_thread,
            http_thread,
            commit_thread,
        ]
        for t in _all_threads:
            if t.is_alive():
                logging.info("[SHUTDOWN] Waiting for thread %s (up to 30s)...", t.name)
                t.join(timeout=30.0)
                if t.is_alive():
                    logging.warning("[SHUTDOWN] Thread %s did not stop in time", t.name)

        # Bridge: cleanup resources AFTER threads are done
        sop_index.close()
        move_jobs.close()

        # clean up PID file in normal shutdown sequence
        # (NOT in signal handler - unsafe on Windows)
        if _pid_path and os.path.exists(_pid_path):
            try:
                os.unlink(_pid_path)
                logging.info("Removed PID file %s", _pid_path)
            except OSError:
                pass

        logging.info("Bridge shutdown complete")

if __name__ == "__main__":
    main()

